	public void CreateControls(bool Preview, bool ToolPreview)
	{
		EyeCreateProps eyeCreateProps = null;
		if (Preview)
		{
			clsItem.FrmPreview = new F_Preview();
			eyeCreateProps = new EyeCreateProps();
			ProgramParsToCreateModelProps(clsVar.varPreviewViewport, clsVar.varMouse, ref eyeCreateProps);
			clsItem.FrmPreview.viewportLayout = buEyeShotFunctions.CreateControlsTool(FirstCreate: true, eyeCreateProps);
			clsItem.FrmPreview.Controls.Add(clsItem.FrmPreview.viewportLayout);
		}
		if (clsItem.FrmTempLayers == null)
		{
		}
		if (clsItem.FrmTempTools != null && ToolPreview)
		{
			eyeCreateProps = new EyeCreateProps();
			eyeCreateProps.ShowOriginCaption = false;
			eyeCreateProps.ShowOrigin = false;
			eyeCreateProps.ShowToolBar = false;
			eyeCreateProps.ShowViewCube = false;
			eyeCreateProps.ShowCoordinateArrow = false;
			eyeCreateProps.BottomColor = clsVar.varToolViewport.BottomColor;
			eyeCreateProps.IntermediateColor = clsVar.varToolViewport.IntermediateColor;
			eyeCreateProps.ShowCoordinateArrow = clsVar.varToolViewport.ShowCoordinateSystemIcon;
			eyeCreateProps.ZoomMouseButton = new MouseButton(buConversion5.MouseButtonConv(clsVar.varMouse.ZoomConfigration.Button), buConversion5.KeyConv(clsVar.varMouse.ZoomConfigration.Key));
			eyeCreateProps.PanMouseButton = new MouseButton(buConversion5.MouseButtonConv(clsVar.varMouse.PanConfigration.Button), buConversion5.KeyConv(clsVar.varMouse.PanConfigration.Key));
			eyeCreateProps.RotateMouseButton = new MouseButton(buConversion5.MouseButtonConv(clsVar.varMouse.RotateConfigration.Button), buConversion5.KeyConv(clsVar.varMouse.RotateConfigration.Key));
			eyeCreateProps.ZoomMouseButton = new MouseButton(buConversion5.MouseButtonConv(clsVar.varMouse.ZoomConfigration.Button), buConversion5.KeyConv(clsVar.varMouse.ZoomConfigration.Key));
			clsItem.ModelToolPreview = buEyeShotFunctions.CreateControlsTool(FirstCreate: true, eyeCreateProps);
			clsItem.FrmTempTools.pnl_model.Controls.Add(clsItem.ModelToolPreview);
		}
		eyeCreateProps = new EyeCreateProps(Visible: false);
		eyeCreateProps.Width = clsInit.appCommand.openDialogCtrlPreview.picture_preview.Width;
		eyeCreateProps.Height = clsInit.appCommand.openDialogCtrlPreview.picture_preview.Height;
		clsItem.ModelOpenPreview = buEyeShotFunctions.CreateControlsTool(FirstCreate: true, eyeCreateProps);
		clsItem.ModelOpenPreview.WorkCompleted += clsInit.appCommand.ModelOpenPreview_WorkCompleted;
		clsItem.ModelOpenPreview.WorkCancelled += clsInit.appCommand.ModelOpenPreview_WorkCancelled;
