	public void cmdFileNewPage()
	{
		try
		{
			if (!clsVar.appModes_0.NoValidLicense)
			{
				if (!clsVar.appModes_0.TimePeriodExpire)
				{
					if (ccVars.Pages.Count < clsVar.varProgram.MaxPageCount)
					{
						Pages page = new Pages();
						NewPage(page, NewPageEnable: true, "", "");
						if (formUpdate_0 != null)
						{
							formUpdate_0(MenuUpdate: false, SettingUpdate: false, ControlsUpdate: true);
						}
						clsVar.NewCount++;
					}
					else
					{
						buString.MessageBoxWarning(AppLanguage.CadCamMessages[3]);
