	public void NewPage(Pages Page, bool NewPageEnable, string PageName, string FileName)
	{
		if (!clsVar.appModes_0.TuftingMode.Enable || ccVars.Pages.Count <= 0)
		{
			if (clsVar.SingleNewPage && ccVars.Pages.Count > 0)
			{
				for (int num = ccVars.Pages.Count - 1; num >= 0; num--)
				{
					clsInit.appCommand.PageClose(num);
				}
			}
			F_Drawing f_Drawing = (Page.Form = new F_Drawing
			{
				WindowState = FormWindowState.Maximized,
				MdiParent = clsItem.FrmMain
			});
			Page.FileName = FileName;
			Page.PageName = AppLanguage.CadCamDynamic[37] + "-" + (ccVars.Pages.Count + 1);
			FileInfo fileInfo = new FileInfo(Application.StartupPath + "\\Undo" + Page.PageName + ".und");
			if (fileInfo.Exists)
			{
				fileInfo.Delete();
			}
			if (Page.Layers.Count <= 0)
			{
				LayerBase5 layerBase = new LayerBase5(AppLanguage.CadCamDynamic[24] + " 1");
				layerBase.LayerColor = Color.Black;
				Page.Layers.Add(layerBase);
				layerBase = new LayerBase5(AppLanguage.CadCamDynamic[24] + " 2");
				layerBase.LayerColor = Color.Red;
				Page.Layers.Add(layerBase);
				layerBase = new LayerBase5(AppLanguage.CadCamDynamic[24] + " 3");
				layerBase.LayerColor = Color.Gold;
				Page.Layers.Add(layerBase);
			}
			PageScene pageScene = new PageScene();
			pageScene.ScenePlane = Plane.XY;
			pageScene.SceneName = AppLanguage.CadCamDynamic[38] + (Page.Scene.Count + 1);
			Page.Scene.Add(pageScene);
			Page.Form.viewportcad.WorkCompleted += ModelOpenFile_WorkCompleted;
			Page.Form.viewportcad.WorkFailed += ModelOpenFile_WorkFailed;
			Page.Form.viewportcad.WorkCancelled += ModelOpenFile_WorkCancelled;
			ccVars.Pages.Add(Page);
			ccVars.PageIndex = ccVars.Pages.Count - 1;
			ccVars.Pages[ccVars.PageIndex].SceneIndex = 0;
			ccVars.Pages[ccVars.PageIndex].SceneName = ccVars.Pages[ccVars.PageIndex].Scene[ccVars.Pages[ccVars.PageIndex].SceneIndex].SceneName;
			ccVars.Pages[ccVars.PageIndex].Form.Tag = ccVars.PageIndex;
			ccVars.Pages[ccVars.PageIndex].Form.Text = buFile.getFileName(FileName);
			ccVars.Pages[ccVars.PageIndex].LayerName = Page.Layers[0].Name;
			if (clsVar.appModes_0.ProfileMode.Enable && FileName.Length == 0)
			{
				clsInit.appProfile.NewPageExtension();
			}
			if (clsVar.appModes_0.DrillMode.Enable && FileName.Length == 0)
			{
				clsInit.appDrill.NewPageExtension();
			}
			if (clsVar.appModes_0.FoamCuttingMode.Enable && FileName.Length == 0)
			{
				clsInit.appFoamCutting.doNewPage();
			}
			if (clsVar.appModes_0.MarbleMode.Enable && FileName.Length == 0)
			{
				clsInit.appMarble.doNewPage();
			}
			if (clsVar.appModes_0.CompositeMode.Enable && FileName.Length == 0)
			{
				clsInit.appRouter3AX.doNewPage();
			}
			if (clsVar.appModes_0.NestingMode.PanelMode && FileName.Length == 0)
			{
				clsInit.appPanelCut.doNewPage();
			}
			if (clsVar.appModes_0.Printer3DMode.Enable && FileName.Length == 0)
			{
				clsInit.appPrinter3D.NewPageExtension();
			}
			if (clsVar.appModes_0.WoodMode.Enable && FileName.Length == 0)
			{
				clsInit.appWood.NewPageExtension();
			}
			if (clsVar.appModes_0.DoorMode.Enable && FileName.Length == 0)
			{
				clsInit.appDoor.NewPageExtension();
			}
			if (clsVar.appModes_0.CutterMode.Enable && FileName.Length == 0)
			{
				clsInit.appCutter.doNewExtension();
			}
			if (NewPageEnable)
			{
				MacroExecute(clsVar.macroNewPage);
			}
			if (clsItem.FrmTempMisc != null)
			{
				clsItem.FrmTempMisc.txt_notes.Text = "";
			}
			if (clsItem.FrmTempMaterial != null)
			{
				clsItem.FrmTempMaterial.txt_notes.Text = "";
			}
			f_Drawing.Init();
			f_Drawing.Show();
			ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Layers = LayerConvertFromBuLayerToEyeLayer(ccVars.Pages[ccVars.PageIndex].Layers);
			if (formUpdate_0 != null)
			{
				formUpdate_0(MenuUpdate: true, SettingUpdate: false, ControlsUpdate: false);
			}
			ccVars.Pages[ccVars.PageIndex].LayerIndex = 0;
			ccVars.Pages[ccVars.PageIndex].LayerName = ccVars.Pages[ccVars.PageIndex].Layers[ccVars.Pages[ccVars.PageIndex].LayerIndex].Name;
			PagesUpdate(FillPages: true, "");
			LayersUpdate(ccVars.Pages[ccVars.PageIndex].Layers, FillLayer: true, 0);
			undoBuffer();
			PageInfo(ccVars.Pages[ccVars.PageIndex], clsVar.varProgram.PagePanelSettings);
			MaterialUpdate(FillMaterial: true, clsVar.varInterface.MaterialIndex);
			if (clsVar.appModes_0.TuftingMode.Enable)
			{
				clsInit.appTufting.NewPageTuftingExtension();
			}
			ccVars.Pages[ccVars.PageIndex].Changed = false;
		}
		else
		{
			buString5.MessageBoxWarning(AppLanguage.CadCamMessages[95]);
		}
	}

