	public void NewScene(bool NewSceneEnable, string SceneName, string FileName)
	{
		PageScene pageScene = new PageScene();
		pageScene.ScenePlane = Plane.XY;
		pageScene.SceneFileName = FileName;
		if (SceneName.Length <= 0)
		{
			pageScene.SceneName = "Scene" + (ccVars.Pages[ccVars.PageIndex].Scene.Count + 1);
		}
		else
		{
			pageScene.SceneName = SceneName;
		}
		ccVars.Pages[ccVars.PageIndex].Scene.Add(pageScene);
		ccVars.Pages[ccVars.PageIndex].SceneIndex = ccVars.Pages[ccVars.PageIndex].Scene.Count - 1;
		if (NewSceneEnable)
		{
			MacroExecute(clsVar.macroNewScene);
		}
		ccVars.Pages[ccVars.PageIndex].Changed = true;
	}

	public bool cmdFileOpenPreview(FileOpenType Type, string InitPath = "")
	{
		try
		{
			if (!clsVar.appModes_0.NoValidLicense)
			{
				if (!clsVar.appModes_0.TimePeriodExpire)
				{
					if (ccVars.Pages.Count < clsVar.varProgram.MaxPageCount)
					{
						if (!clsVar.appModes_0.TuftingMode.Enable || ccVars.Pages.Count <= 0)
						{
							openFileDialog_0 = new OpenFileDialog();
							openDialogCtrlPreview.Extensions.Clear();
							if (!(Type == FileOpenType.ImportAsPage || Type == FileOpenType.ImportAsScene))
							{
								for (int i = 0; i <= AppExtension.OpenFileExtension.Count - 1; i++)
								{
									if (i != 0)
									{
										openFileDialog_0.Filter = openFileDialog_0.Filter + "|" + AppExtension.OpenFileExtension[i].ToString();
									}
									else
									{
										openFileDialog_0.Filter = AppExtension.OpenFileExtension[i].ToString();
									}
									openDialogCtrlPreview.Extensions.Add(AppExtension.OpenFileExtension[i].ToString());
								}
							}
							else
							{
								for (int j = 0; j <= AppExtension.ImportFileExtension.Count - 1; j++)
								{
									if (j != 0)
									{
										openFileDialog_0.Filter = openFileDialog_0.Filter + "|" + AppExtension.ImportFileExtension[j].ToString();
									}
									else
									{
										openFileDialog_0.Filter = AppExtension.ImportFileExtension[j].ToString();
									}
									openDialogCtrlPreview.Extensions.Add(AppExtension.ImportFileExtension[j].ToString());
								}
							}
							string Path = clsVar.varFile.FileOpenMode.InitPath;
							int fileFilterIndex = clsVar.varFile.FileOpenMode.FileFilterIndex;
							bool previewEnable = clsVar.varFile.FileOpenMode.PreviewEnable;
							if (Type == FileOpenType.OpenAsPage || Type == FileOpenType.OpenAsScene)
							{
								buFile.GetFileInitPathByType(AppExtension.OpenFileExtension, fileFilterIndex - 1, clsVar.varFile.FileOpenMode, ref Path);
								openDialogCtrlPreview.Properties = new FileOpenModes(clsVar.varFile.FileOpenMode);
							}
							if (Type == FileOpenType.ImportAsPage || Type == FileOpenType.ImportAsScene)
							{
								Path = clsVar.varFile.FileImportMode.InitPath;
								fileFilterIndex = clsVar.varFile.FileImportMode.FileFilterIndex;
								previewEnable = clsVar.varFile.FileImportMode.PreviewEnable;
								ccVars.Action = actionTypeBU.fileImportAsPage;
								buFile.GetFileInitPathByType(AppExtension.ImportFileExtension, fileFilterIndex - 1, clsVar.varFile.FileImportMode, ref Path);
								openDialogCtrlPreview.Properties = new FileOpenModes(clsVar.varFile.FileImportMode);
							}
							if (Type == FileOpenType.Add)
							{
								Path = clsVar.varFile.FileAddMode.InitPath;
								fileFilterIndex = clsVar.varFile.FileAddMode.FileFilterIndex;
								previewEnable = clsVar.varFile.FileAddMode.PreviewEnable;
								ccVars.Action = actionTypeBU.fileAdd;
								buFile.GetFileInitPathByType(AppExtension.OpenFileExtension, fileFilterIndex - 1, clsVar.varFile.FileAddMode, ref Path);
								openDialogCtrlPreview.Properties = new FileOpenModes(clsVar.varFile.FileAddMode);
							}
							if (Type == FileOpenType.Insert)
							{
								Path = clsVar.varFile.FileInsertMode.InitPath;
								fileFilterIndex = clsVar.varFile.FileInsertMode.FileFilterIndex;
								previewEnable = clsVar.varFile.FileInsertMode.PreviewEnable;
								ccVars.Action = actionTypeBU.fileInsert;
								buFile.GetFileInitPathByType(AppExtension.OpenFileExtension, fileFilterIndex - 1, clsVar.varFile.FileInsertMode, ref Path);
								openDialogCtrlPreview.Properties = new FileOpenModes(clsVar.varFile.FileInsertMode);
							}
							clsVar.PreviewLoaded = true;
							openDialogCtrlPreview.SubFolder = true;
							openDialogCtrlPreview.FileDlgCaption = AppLanguage.CadCamDynamic[32] + " " + AppLanguage.CadCamDynamic[31];
							openDialogCtrlPreview.FileDlgOkCaption = AppLanguage.CadCamDynamic[31];
							openDialogCtrlPreview.FileDlgInitialDirectory = Environment.GetFolderPath(Environment.SpecialFolder.MyPictures);
							openDialogCtrlPreview.SubFolder = clsVar.varFile.FileOpenMode.SubFolder;
							openDialogCtrlPreview.ShowInfoButton = clsVar.varFile.FileOpenMode.ShowInfoButton;
							openDialogCtrlPreview.ShowPreviewDisable = clsVar.varFile.FileOpenMode.ShowDisablePreview;
							openDialogCtrlPreview.ShowLoading(Show: false);
							openDialogCtrlPreview.Init();
							openFileDialog_0.AddExtension = true;
							openDialogCtrlPreview.PreviewEnable = previewEnable;
							openFileDialog_0.InitialDirectory = Path;
							if (InitPath.Trim().Length > 0)
							{
								openFileDialog_0.InitialDirectory = InitPath;
							}
							openFileDialog_0.FilterIndex = fileFilterIndex;
							openFileDialog_0.CheckFileExists = true;
							openFileDialog_0.DefaultExt = "bucad";
							openFileDialog_0.FileName = "";
							openFileDialog_0.DereferenceLinks = true;
							DialogResult dialogResult = openFileDialog_0.ShowDialog(openDialogCtrlPreview, clsItem.FrmMain);
							if (dialogResult != DialogResult.OK)
							{
								return false;
							}
							if (!(Type == FileOpenType.OpenAsPage || Type == FileOpenType.OpenAsScene))
							{
								if (!(Type == FileOpenType.ImportAsPage || Type == FileOpenType.ImportAsScene))
								{
									switch (Type)
									{
									case FileOpenType.Add:
										OpenPage(openFileDialog_0.FileNames);
										clsVar.varFile.FileAddMode.PreviewEnable = openDialogCtrlPreview.chk_preview.Checked;
										clsVar.varFile.FileAddMode.InitPath = buFile.GetPath(openFileDialog_0.FileName);
										clsVar.varFile.FileAddMode.FileFilterIndex = openFileDialog_0.FilterIndex;
										buFile.SetFileInitPathByType(AppExtension.OpenFileExtension, clsVar.varFile.FileAddMode.FileFilterIndex - 1, clsVar.varFile.FileAddMode.InitPath, ref clsVar.varFile.FileAddMode);
										break;
									case FileOpenType.Insert:
										OpenPage(openFileDialog_0.FileNames);
										clsVar.varFile.FileInsertMode.PreviewEnable = openDialogCtrlPreview.chk_preview.Checked;
										clsVar.varFile.FileInsertMode.InitPath = buFile.GetPath(openFileDialog_0.FileName);
										clsVar.varFile.FileInsertMode.FileFilterIndex = openFileDialog_0.FilterIndex;
										buFile.SetFileInitPathByType(AppExtension.OpenFileExtension, clsVar.varFile.FileInsertMode.FileFilterIndex - 1, clsVar.varFile.FileInsertMode.InitPath, ref clsVar.varFile.FileInsertMode);
										break;
									case FileOpenType.ProfileDrawImport:
										clsInit.appProfile.fileNameOperation = openFileDialog_0.FileNames[0];
										break;
									}
								}
								else
								{
									OpenPage(openFileDialog_0.FileNames);
									clsVar.varFile.FileImportMode.PreviewEnable = openDialogCtrlPreview.chk_preview.Checked;
									clsVar.varFile.FileImportMode.InitPath = buFile.GetPath(openFileDialog_0.FileName);
									clsVar.varFile.FileImportMode.FileFilterIndex = openFileDialog_0.FilterIndex;
									buFile.SetFileInitPathByType(AppExtension.ImportFileExtension, clsVar.varFile.FileImportMode.FileFilterIndex - 1, clsVar.varFile.FileImportMode.InitPath, ref clsVar.varFile.FileImportMode);
								}
							}
							else
							{
								OpenPage(openFileDialog_0.FileNames);
								clsVar.varFile.FileOpenMode.PreviewEnable = openDialogCtrlPreview.chk_preview.Checked;
								clsVar.varFile.FileOpenMode.InitPath = buFile.GetPath(openFileDialog_0.FileName);
								clsVar.varFile.FileOpenMode.FileFilterIndex = openFileDialog_0.FilterIndex;
								buFile.SetFileInitPathByType(AppExtension.OpenFileExtension, clsVar.varFile.FileOpenMode.FileFilterIndex - 1, clsVar.varFile.FileOpenMode.InitPath, ref clsVar.varFile.FileOpenMode);
							}
							clsFiles.SaveParameter();
							return true;
						}
						buString5.MessageBoxWarning(AppLanguage.CadCamMessages[95]);
						return false;
					}
					buString.MessageBoxWarning(AppLanguage.CadCamMessages[3] + " - " + clsVar.varProgram.MaxPageCount);
					return false;
				}
				buString5.MessageBoxError(AppLanguage.CadCamMessages[84]);
				return false;
			}
			buString5.MessageBoxError(AppLanguage.CadCamMessages[83]);
			return false;
		}
		catch (Exception mSException)
		{
			buLog.addLog("", "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: true, "");
			return false;
		}
	}

	public void cmdFileOpen(FileOpenType Type)
	{
		try
		{
			if (!clsVar.appModes_0.NoValidLicense)
			{
				if (!clsVar.appModes_0.TimePeriodExpire)
				{
					if (ccVars.Pages.Count < clsVar.varProgram.MaxPageCount)
					{
						if (!clsVar.appModes_0.TuftingMode.Enable || ccVars.Pages.Count <= 0)
						{
							string initPath = clsVar.varFile.FileOpenMode.InitPath;
							int fileFilterIndex = clsVar.varFile.FileOpenMode.FileFilterIndex;
							if (Type == FileOpenType.ImportAsPage || Type == FileOpenType.ImportAsScene)
							{
								initPath = clsVar.varFile.FileImportMode.InitPath;
								fileFilterIndex = clsVar.varFile.FileImportMode.FileFilterIndex;
								ccVars.Action = actionTypeBU.fileImportAsPage;
							}
							if (Type == FileOpenType.Add)
							{
								initPath = clsVar.varFile.FileAddMode.InitPath;
								fileFilterIndex = clsVar.varFile.FileAddMode.FileFilterIndex;
								ccVars.Action = actionTypeBU.fileAdd;
							}
							if (Type == FileOpenType.Insert)
							{
								initPath = clsVar.varFile.FileInsertMode.InitPath;
								fileFilterIndex = clsVar.varFile.FileInsertMode.FileFilterIndex;
								ccVars.Action = actionTypeBU.fileInsert;
							}
							OpenFileDialog openFileDialog = new OpenFileDialog();
							openFileDialog.InitialDirectory = initPath;
							if (AppExtension.OpenFileExtension.Count != 0)
							{
								for (int i = 0; i <= AppExtension.OpenFileExtension.Count - 1; i++)
								{
									if (i != 0)
									{
										openFileDialog.Filter = openFileDialog.Filter + "|" + AppExtension.OpenFileExtension[i].ToString();
									}
									else
									{
										openFileDialog.Filter = AppExtension.OpenFileExtension[i].ToString();
									}
								}
							}
							else
							{
								openFileDialog.Filter = "buCad Cad/Cam Files (*.bucad)|*.bucad";
							}
							openFileDialog.FilterIndex = fileFilterIndex;
							openFileDialog.FileName = "";
							if (openFileDialog.ShowDialog() != DialogResult.OK)
							{
								return;
							}
							OpenPage(openFileDialog.FileNames);
							if (!(Type == FileOpenType.OpenAsPage || Type == FileOpenType.OpenAsScene))
							{
								if (!(Type == FileOpenType.ImportAsPage || Type == FileOpenType.ImportAsScene))
								{
									if (Type != FileOpenType.Add)
									{
										if (Type == FileOpenType.Insert)
										{
											clsVar.varFile.FileInsertMode.InitPath = buFile.GetPath(openFileDialog.FileName);
											clsVar.varFile.FileInsertMode.FileFilterIndex = openFileDialog.FilterIndex;
										}
									}
									else
									{
										clsVar.varFile.FileAddMode.InitPath = buFile.GetPath(openFileDialog.FileName);
										clsVar.varFile.FileAddMode.FileFilterIndex = openFileDialog.FilterIndex;
									}
								}
								else
								{
									clsVar.varFile.FileImportMode.InitPath = buFile.GetPath(openFileDialog.FileName);
									clsVar.varFile.FileImportMode.FileFilterIndex = openFileDialog.FilterIndex;
								}
							}
							else
							{
								clsVar.varFile.FileOpenMode.InitPath = buFile.GetPath(openFileDialog.FileName);
								clsVar.varFile.FileOpenMode.FileFilterIndex = openFileDialog.FilterIndex;
							}
							clsFiles.SaveParameter();
						}
						else
						{
							buString5.MessageBoxWarning(AppLanguage.CadCamMessages[95]);
						}
					}
					else
					{
						buString.MessageBoxWarning(AppLanguage.CadCamMessages[3] + " - " + clsVar.varProgram.MaxPageCount);
					}
				}
				else
				{
					buString5.MessageBoxError(AppLanguage.CadCamMessages[84]);
				}
			}
			else
			{
				buString5.MessageBoxError(AppLanguage.CadCamMessages[83]);
			}
		}
		catch (Exception mSException)
		{
			buLog.addLog("", "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: true, "");
		}
	}

