	public void SetPreviewImage()
	{
		clsItem.ModelOpenPreview.Invalidate();
		clsItem.ModelOpenPreview.Entities.RegenAllCurved();
		clsItem.ModelOpenPreview.SetView(buConversion5.buViewTypeToEyeViewType(openDialogCtrlPreview.ViewType), fit: true, animate: false);
		clsItem.ModelOpenPreview.Invalidate();
		clsItem.ModelOpenPreview.CopyToClipboardRaster(new Size(openDialogCtrlPreview.picture_preview.Width, openDialogCtrlPreview.picture_preview.Height));
		Image image = Clipboard.GetImage();
		openDialogCtrlPreview.DrawPreviewImage(image);
		openDialogCtrlPreview.ShowLoading(Show: false);
		clsVar.PreviewLoaded = true;
	}

	public void OpenPage(string[] FileNames)
	{
		if (FileNames.Length == 0)
		{
			return;
		}
		FileInfo fileInfo = new FileInfo(FileNames[0]);
		if (!((fileInfo.Extension.ToLower() == ".buprofile") & clsVar.appModes_0.ProfileMode.Enable))
		{
			clsVar.OpeningFileName = FileNames[0];
			bool clearEntities = false;
			if ((ccVars.Action == actionTypeBU.fileOpenAsPage) | (ccVars.Action == actionTypeBU.fileImportAsPage))
			{
				Pages page = new Pages();
				if (clsVar.NewPageViewportMode)
				{
					NewViewport(page, NewPageEnable: true, "", FileNames[0]);
				}
				else
				{
					NewPage(page, NewPageEnable: true, "", FileNames[0]);
				}
				clearEntities = true;
			}
			if ((ccVars.Action == actionTypeBU.fileOpenAsScene) | (ccVars.Action == actionTypeBU.fileImportAsScene))
			{
				NewScene(NewSceneEnable: true, "", FileNames[0]);
			}
			Design model = null;
			if (ccVars.Action != actionTypeBU.fileInsert)
			{
				clsInit.appFiles.OpenCadFiles(FileNames[0], clearEntities, ref model);
			}
			else
			{
				clsInit.appFiles.OpenCadFiles(FileNames[0], clearEntities, ref clsItem.ModelOpenInsert);
			}
			if ((fileInfo.Extension.ToLower() == ".bucadv5") | (fileInfo.Extension.ToLower() == ".bucad") | (fileInfo.Extension.ToLower() == ".ply") | (fileInfo.Extension.ToLower() == ".cf2"))
			{
				clsInit.appFiles.CommonOperationAfterFileLoading();
			}
			if ((ccVars.Action == actionTypeBU.fileOpenAsPage) | (ccVars.Action == actionTypeBU.fileOpenAsScene))
			{
				buString.AddFileToRecentFileList(FileNames[0], 10, ref clsVar.varInterface.LastLoadedFiles);
			}
			if ((ccVars.Action == actionTypeBU.fileImportAsPage) | (ccVars.Action == actionTypeBU.fileImportAsScene))
			{
				buString.AddFileToRecentFileList(FileNames[0], 10, ref clsVar.varInterface.LastImportedFiles);
			}
			if (ccVars.Action == actionTypeBU.fileOpenAsPage)
			{
				MacroExecute(clsVar.macroOpen);
			}
			if (ccVars.Action == actionTypeBU.fileImportAsPage)
			{
				MacroExecute(clsVar.macroImport);
			}
			if (formUpdate_0 != null)
			{
				formUpdate_0(MenuUpdate: true, SettingUpdate: false, ControlsUpdate: false);
			}
			if (((ccVars.Action == actionTypeBU.fileImportAsPage) | (ccVars.Action == actionTypeBU.fileOpenAsPage)) && ((fileInfo.Extension.ToLower() == ".bucadv5") | (fileInfo.Extension.ToLower() == ".bucad") | (fileInfo.Extension.ToLower() == ".ply") | (fileInfo.Extension.ToLower() == ".cf2") | (fileInfo.Extension.ToLower() == ".cnc") | (fileInfo.Extension.ToLower() == ".nc") | (fileInfo.Extension.ToLower() == ".mpf")))
			{
				MaterialUpdate(FillMaterial: true, clsVar.varInterface.MaterialIndex);
			}
			if (clsVar.appModes_0.FoamCuttingMode.Enable)
			{
				clsInit.appFoamCutting.doOpenPage();
			}
			if (clsVar.appModes_0.MarbleMode.Enable)
			{
				clsInit.appMarble.doOpenPage();
			}
			if (clsVar.appModes_0.CutterMode.Enable)
			{
				clsInit.appCutter.doOpenPage();
			}
			if (clsVar.appModes_0.CompositeMode.Enable)
			{
				clsInit.appRouter3AX.doOpenPage();
			}
			if (clsVar.appModes_0.NestingMode.PanelMode)
			{
				clsInit.appPanelCut.doOpenPage();
			}
			if (clsVar.appModes_0.DrillMode.Enable)
			{
				clsInit.appDrill.OpenExtension();
			}
			Reset(ClearSelection: false);
		}
		else
		{
			clsInit.appProfile.OpenProfileJobFile(fileInfo.FullName, AddOperations: true, CreateProfile: true, OnlyDrawing: false, ref clsInit.appProfile.activeProfile, AddRecent: true);
			clsInit.appProfile.FileOpenCommonCommands();
		}
	}

	public void SavePage(string FileName)
	{
		string text = "";
		try
		{
			if (FileName.Length <= 0)
			{
				return;
			}
			FileInfo fileInfo = new FileInfo(FileName);
			string fileNameWithoutExtension = buFile.getFileNameWithoutExtension(fileInfo.FullName);
			if (!((fileInfo.Extension.ToLower() == ".buprofile") & clsVar.appModes_0.ProfileMode.Enable))
			{
				if (fileInfo.Extension.ToLower() == ".bucadv5")
				{
					DirectoryInfo directoryInfo = new DirectoryInfo(fileInfo.DirectoryName + "\\" + fileNameWithoutExtension);
					if (directoryInfo.Exists)
					{
						directoryInfo.Delete(recursive: true);
					}
					Directory.CreateDirectory(directoryInfo.FullName);
					text = directoryInfo.FullName;
					ArrayList arrayList = new ArrayList();
					buCadCamFileInfo buCadCamFileInfo2 = new buCadCamFileInfo();
					buCadCamFileInfo2.ProgramVersionNo = Application.ProductVersion;
					string text2 = clsItem.FrmTempMisc.txt_notes.Text;
					text2 = text2 + Environment.NewLine + clsItem.FrmTempMaterial.txt_notes.Text;
					buCadCamFileInfo2.Notes = text2;
					buCadCamFileInfo2.Notes = buCadCamFileInfo2.Notes.Replace("\r\n", "{[NewLine]}");
					arrayList.AddRange(buCadCamFileInfo2.ToDefAll("", 2, SerilizationMode.MultiLine).ToArray());
					for (int i = 0; i <= ccVars.Pages[ccVars.PageIndex].Layers.Count - 1; i++)
					{
						arrayList.AddRange(ccVars.Pages[ccVars.PageIndex].Layers[i].ToDefAll("", 2, SerilizationMode5.MultiLine).ToArray());
					}
					for (int j = 0; j <= ccVars.Pages[ccVars.PageIndex].Scene.Count - 1; j++)
					{
						arrayList.AddRange(ccVars.Pages[ccVars.PageIndex].Scene[j].ToDef("", 2).ToArray());
					}
					for (int k = 0; k <= ccVars.Pages[ccVars.PageIndex].Cams.Count - 1; k++)
					{
						arrayList.AddRange(ccVars.Pages[ccVars.PageIndex].Cams[k].ToDefAll("", 2, SerilizationMode5.MultiLine).ToArray());
					}
					List<Entity> list = new List<Entity>();
					for (int num = ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Count - 1; num >= 0; num--)
					{
						if (ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[num].GetType() == typeof(buMaterial))
						{
							Entity item = buVector5.CopyEntities(ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[num]);
							list.Add(item);
							ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.RemoveAt(num);
						}
					}
					buFile.SaveToFile(arrayList, directoryInfo.FullName + "\\" + fileNameWithoutExtension + ".busets");
					WriteFileParams writeFileParams = new WriteFileParams(ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Document);
					writeFileParams.Content = contentType.GeometryAndTessellation;
					writeFileParams.SerializationMode = serializationType.Uncompressed;
					writeFileParams.SelectedOnly = false;
					writeFileParams.Purge = false;
					writeFileParams.Tag = MyFileSerializer.CustomTag;
					int SelectedCount = 0;
					clsInit.cVector5.getSelectedEntitiesCount(ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities, ref SelectedCount);
					if ((SelectedCount > 0) & clsVar.varFile.IfSelectedAvailableSaveOnlySelected)
					{
						writeFileParams.SelectedOnly = true;
					}
					WriteFile writeFile = new WriteFile(writeFileParams, directoryInfo.FullName + "\\" + fileNameWithoutExtension + ".bupage", new MyFileSerializer());
					writeFile.DoWork();
					FileInfo fileInfo2 = new FileInfo(FileName);
					if (fileInfo2.Exists)
					{
						fileInfo2.Delete();
					}
					buFile.ZipFolderToFile(directoryInfo.FullName, FileName);
					directoryInfo.Delete(recursive: true);
					for (int l = 0; l <= list.Count - 1; l++)
					{
						ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Add(buVector5.CopyEntities(list[l]));
					}
					clsFiles.SaveParameter();
					ccVars.Pages[ccVars.PageIndex].FileName = fileInfo.FullName;
					ccVars.Pages[ccVars.PageIndex].Changed = false;
				}
				if (fileInfo.Extension.ToLower() == ".dxf")
				{
					WriteFileAsync writeFileAsync = null;
					for (int m = 0; m <= ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Count - 1; m++)
					{
						if (ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[m] is LinearPath && ((ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[m].Vertices.Length == 2) & clsVar.varAutoCadFileProps.Convert2PointLinearPathToLine))
						{
							Line line = new Line(ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[m].Vertices[0], ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[m].Vertices[1]);
							line.LayerName = ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[m].LayerName;
							line.Color = ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[m].Color;
							line.ColorMethod = ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[m].ColorMethod;
							line.LineWeight = ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[m].LineWeight;
							line.LineWeightMethod = ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[m].LineWeightMethod;
							ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[m] = line;
						}
					}
					WriteAutodeskParams writeAutodeskParams = new WriteAutodeskParams(ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Document);
					writeAutodeskParams.Version = clsVar.varAutoCadFileProps.Version;
					writeAutodeskParams.AciColors = clsVar.varAutoCadFileProps.AciColors;
					writeAutodeskParams.CurveAsFitSpline = clsVar.varAutoCadFileProps.CurveAsFitSpline;
					writeAutodeskParams.Deviation = clsVar.varAutoCadFileProps.Deviation;
					writeAutodeskParams.ExplodeViews = clsVar.varAutoCadFileProps.ExplodeViews;
					writeAutodeskParams.Password = clsVar.varAutoCadFileProps.Password;
					writeAutodeskParams.Purge = clsVar.varAutoCadFileProps.Purge;
					writeAutodeskParams.SelectedOnly = clsVar.varAutoCadFileProps.SelectedOnly;
					writeAutodeskParams.Format = WriteAutodesk.formatType.DXF;
					int SelectedCount2 = 0;
					clsInit.cVector5.getSelectedEntitiesCount(ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities, ref SelectedCount2);
					if ((SelectedCount2 > 0) & clsVar.varFile.IfSelectedAvailableSaveOnlySelected)
					{
						writeAutodeskParams.SelectedOnly = true;
					}
					if (!clsVar.varFile.SaveOnlyCurveAndTextEntities)
					{
						if (clsVar.varFile.SaveOnlyCurveEntities)
						{
							for (int n = 0; n <= ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Count - 1; n++)
							{
								if (ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[n] is ICurve)
								{
									ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[n].Selected = true;
								}
							}
							writeAutodeskParams.SelectedOnly = true;
						}
					}
					else
					{
						for (int num2 = 0; num2 <= ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Count - 1; num2++)
						{
							if ((ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[num2] is ICurve) | (ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[num2] is Text))
							{
								ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[num2].Selected = true;
							}
						}
						writeAutodeskParams.SelectedOnly = true;
					}
					writeFileAsync = new WriteAutodesk(writeAutodeskParams, fileInfo.FullName);
					ccVars.Pages[ccVars.PageIndex].Form.viewportcad.StartWork(writeFileAsync);
				}
				if (fileInfo.Extension.ToLower() == ".dwg")
				{
					WriteFileAsync writeFileAsync2 = null;
					WriteAutodeskParams writeAutodeskParams2 = new WriteAutodeskParams(ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Document);
					writeAutodeskParams2.Version = clsVar.varAutoCadFileProps.Version;
					writeAutodeskParams2.AciColors = clsVar.varAutoCadFileProps.AciColors;
					writeAutodeskParams2.CurveAsFitSpline = clsVar.varAutoCadFileProps.CurveAsFitSpline;
					writeAutodeskParams2.Deviation = clsVar.varAutoCadFileProps.Deviation;
					writeAutodeskParams2.ExplodeViews = clsVar.varAutoCadFileProps.ExplodeViews;
					writeAutodeskParams2.Password = clsVar.varAutoCadFileProps.Password;
					writeAutodeskParams2.Purge = clsVar.varAutoCadFileProps.Purge;
					writeAutodeskParams2.SelectedOnly = clsVar.varAutoCadFileProps.SelectedOnly;
					writeAutodeskParams2.Format = WriteAutodesk.formatType.DWG;
					int SelectedCount3 = 0;
					clsInit.cVector5.getSelectedEntitiesCount(ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities, ref SelectedCount3);
					if ((SelectedCount3 > 0) & clsVar.varFile.IfSelectedAvailableSaveOnlySelected)
					{
						writeAutodeskParams2.SelectedOnly = true;
