	public void cmdFileSave()
	{
		try
		{
			if (!clsVar.appModes_0.DemoMode)
			{
				if (ccVars.Pages.Count <= 0)
				{
					return;
				}
				if (ccVars.Pages[ccVars.PageIndex].FileName.Length >= 2)
				{
					try
					{
						FileInfo fileInfo = new FileInfo(ccVars.Pages[ccVars.PageIndex].FileName);
						if (!fileInfo.Exists)
						{
							cmdFileSaveAs();
						}
						else
						{
							clsVar.varFile.FileSaveMode.InitPath = buFile.GetPath(fileInfo.FullName);
							SavePage(fileInfo.FullName);
							clsFiles.SaveParameter();
						}
						return;
					}
					catch (Exception)
					{
						cmdFileSaveAs();
						return;
					}
				}
				cmdFileSaveAs();
			}
			else
			{
				MessageBox.Show("You can't save in Demo Mode");
			}
		}
		catch (Exception mSException)
		{
			buLog.addLog("", "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: true, "");
		}
	}

	public void cmdFileSaveAs()
	{
		try
		{
			if (!clsVar.appModes_0.DemoMode)
			{
				if (ccVars.Pages.Count <= 0)
				{
					return;
				}
				string initPath = clsVar.varFile.FileSaveMode.InitPath;
				int fileFilterIndex = clsVar.varFile.FileSaveMode.FileFilterIndex;
				saveDialogCtrlOption.SubFolder = true;
				saveDialogCtrlOption.FileDlgCaption = AppLanguage.CadCamDynamic[32] + " " + AppLanguage.CadCamDynamic[36];
				saveDialogCtrlOption.FileDlgOkCaption = AppLanguage.CadCamDynamic[36];
				saveDialogCtrlOption.FileDlgInitialDirectory = Environment.GetFolderPath(Environment.SpecialFolder.MyPictures);
				saveDialogCtrlOption.SubFolder = clsVar.varFile.FileOpenMode.SubFolder;
				saveDialogCtrlOption.Init();
				saveFileDialog_0 = new SaveFileDialog();
				saveFileDialog_0.InitialDirectory = initPath;
				saveFileDialog_0.AddExtension = true;
				if (AppExtension.SaveFileExtension.Count != 0)
				{
					for (int i = 0; i <= AppExtension.SaveFileExtension.Count - 1; i++)
					{
						if (i != 0)
						{
							saveFileDialog_0.Filter = saveFileDialog_0.Filter + "|" + AppExtension.SaveFileExtension[i].ToString();
						}
						else
						{
							saveFileDialog_0.Filter = AppExtension.SaveFileExtension[i].ToString();
						}
					}
				}
				else
				{
					saveFileDialog_0.Filter = "buCad Cad/Cam Files (*.bucad)|*.bucad";
				}
				saveFileDialog_0.FilterIndex = fileFilterIndex;
				if (clsVar.appModes_0.ProfileMode.Enable)
				{
					saveFileDialog_0.FilterIndex = 1;
				}
				saveFileDialog_0.CheckFileExists = false;
				saveFileDialog_0.DefaultExt = "bucadv5";
				saveFileDialog_0.FileName = "";
				saveFileDialog_0.DereferenceLinks = true;
				DialogResult dialogResult = saveFileDialog_0.ShowDialog(saveDialogCtrlOption, clsItem.FrmMain);
				if (dialogResult == DialogResult.OK)
				{
					SavePage(saveFileDialog_0.FileName);
					ccVars.Pages[ccVars.PageIndex].Form.Text = buFile.getFileName(saveFileDialog_0.FileName);
					clsVar.varFile.FileSaveMode.InitPath = buFile.GetPath(saveFileDialog_0.FileName);
					clsVar.varFile.FileSaveMode.FileFilterIndex = saveFileDialog_0.FilterIndex;
					clsVar.varFile.FileSaveMode.SaveGeometry = saveDialogCtrlOption.Properties.SaveGeometry;
					clsVar.varFile.FileSaveMode.SaveTessellation = saveDialogCtrlOption.Properties.SaveTessellation;
					clsVar.varFile.FileSaveMode.SaveSelected = saveDialogCtrlOption.Properties.SaveSelected;
					clsVar.varFile.FileSaveMode.SaveTools = saveDialogCtrlOption.Properties.SaveTools;
					clsFiles.SaveParameter();
				}
			}
			else
			{
				MessageBox.Show("You can't save in Demo Mode");
			}
		}
		catch (Exception mSException)
		{
			buLog.addLog("", "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: true, "");
		}
	}

	public void cmdFileRecentOpen(string fileName)
	{
		try
		{
			if (!clsVar.appModes_0.NoValidLicense)
			{
				if (!clsVar.appModes_0.TimePeriodExpire)
				{
					if (!clsVar.appModes_0.TuftingMode.Enable || ccVars.Pages.Count <= 0)
					{
						FileInfo fileInfo = new FileInfo(fileName);
						if (!fileInfo.Exists)
						{
							buString.MessageBoxError(AppLanguage.CadCamMessages[5]);
							return;
						}
						string[] fileNames = new string[1] { fileInfo.FullName };
						ccVars.Action = actionTypeBU.fileOpenAsPage;
						OpenPage(fileNames);
