	public void ModelOpenPreview_WorkCancelled(object sender, EventArgs e)
	{
		openDialogCtrlPreview.ShowLoading(Show: false);
		clsVar.PreviewLoaded = true;
	}

	public void ModelOpenPreview_WorkCompleted(object sender, WorkCompletedEventArgs e)
	{
		try
		{
			bool flag = false;
			bool flag2 = false;
			if (!(e.WorkUnit is BallPivoting))
			{
				if (!(e.WorkUnit is ReadFileAsync))
				{
					if (e.WorkUnit is Regeneration)
					{
						clsItem.ModelOpenPreview.UpdateBoundingBox();
						if (!flag)
						{
							clsItem.ModelOpenPreview.ZoomFit();
						}
						clsItem.ModelOpenPreview.Invalidate();
						flag = false;
					}
				}
				else
				{
					ReadFileAsync readFileAsync = (ReadFileAsync)e.WorkUnit;
					RegenOptions ro = new RegenOptions();
					flag = e.WorkUnit is ReadFile readFile && readFile.Camera != null;
					clsItem.ModelOpenPreview.Shaded.ShadowMode = shadowType.None;
					clsItem.ModelOpenPreview.Rendered.ShadowMode = shadowType.None;
					clsItem.ModelOpenPreview.Rendered.SilhouettesDrawingMode = silhouettesDrawingType.Never;
					clsItem.ModelOpenPreview.Rendered.PlanarReflections = false;
					readFileAsync.OpenTo(clsItem.ModelOpenPreview, ro);
					FileInfo fileInfo = new FileInfo(readFileAsync.FilePath);
					if (((clsItem.ModelOpenPreview.Layers.Count == 1) & (fileInfo.Extension.ToLower() == ".stl")) && clsItem.ModelOpenPreview.Layers[0].Color == Color.Black)
					{
						clsItem.ModelOpenPreview.Layers[0].Color = Color.LightSeaGreen;
					}
					if (!flag2 && !flag)
					{
						clsItem.ModelOpenPreview.SetView(viewType.Top, fit: true, animate: false);
					}
					clsItem.ModelOpenPreview.CopyToClipboardRaster(new Size(openDialogCtrlPreview.picture_preview.Width, openDialogCtrlPreview.picture_preview.Height), drawBackground: true);
					Image image = Clipboard.GetImage();
					openDialogCtrlPreview.picture_preview.Image = image;
					openDialogCtrlPreview.ShowLoading(Show: false);
				}
			}
			else
			{
				BallPivoting ballPivoting = (BallPivoting)e.WorkUnit;
				Mesh result = ballPivoting.Result;
				result.EdgeStyle = Mesh.edgeStyleType.Free;
				clsItem.ModelOpenPreview.Entities.Clear();
				clsItem.ModelOpenPreview.Entities.Add(result, "Default", Color.Beige);
			}
			clsVar.PreviewLoaded = true;
		}
		catch (Exception)
		{
			clsVar.PreviewLoaded = true;
		}
	}

	public void ModelOpenPreview_WorkFailed(object sender, WorkFailedEventArgs e)
	{
		openDialogCtrlPreview.ShowLoading(Show: false);
		MessageBox.Show("Error");
		clsVar.PreviewLoaded = true;
	}

