	public void ModelOpenFile_WorkCompleted(object sender, WorkCompletedEventArgs e)
	{
		try
		{
			if (clsInit.appPrinter3D != null)
			{
				if (e.WorkUnit is Slicing)
				{
					clsInit.appPrinter3D.doSlicing(e);
					return;
				}
				if (e.WorkUnit is buCadCamResVer5.Printer3D.Simulation)
				{
					clsInit.appPrinter3D.doSimulation(e);
					return;
				}
				if (e.WorkUnit is SimulationRender)
				{
					clsInit.appPrinter3D.doSimulationRender(e);
					return;
				}
			}
			if (!(e.WorkUnit is BallPivoting))
			{
				if (!(e.WorkUnit is ReadFileAsync))
				{
					if (e.WorkUnit is Regeneration || !(e.WorkUnit is WriteAutodesk))
					{
						return;
					}
					if (!clsVar.varFile.SaveOnlyCurveAndTextEntities)
					{
						if (!clsVar.varFile.SaveOnlyCurveEntities)
						{
							return;
						}
						for (int i = 0; i <= ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Count - 1; i++)
						{
							if (ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[i] is ICurve)
							{
								ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[i].Selected = false;
							}
						}
						return;
					}
					for (int j = 0; j <= ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Count - 1; j++)
					{
						if ((ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[j] is ICurve) | (ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[j] is Text))
						{
							ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[j].Selected = false;
						}
					}
					return;
				}
				ReadFileAsync readFileAsync = (ReadFileAsync)e.WorkUnit;
				RegenOptions ro = new RegenOptions();
				if (e.WorkUnit is ReadFile readFile)
				{
					_ = readFile.Camera != null;
				}
				shadowType shadowMode = ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Shaded.ShadowMode;
				shadowType shadowMode2 = ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Rendered.ShadowMode;
				_ = ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Rendered.SilhouettesDrawingMode;
				bool planarReflections = ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Rendered.PlanarReflections;
				ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Shaded.ShadowMode = shadowType.None;
				ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Rendered.ShadowMode = shadowType.None;
				ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Rendered.SilhouettesDrawingMode = silhouettesDrawingType.Never;
				ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Rendered.PlanarReflections = false;
				FileInfo fileInfo = new FileInfo(clsVar.OpeningFileName);
				_ = ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Count;
				if (!((fileInfo.Extension.ToLower() == ".dxf") | (fileInfo.Extension.ToLower() == ".dwg")))
				{
					readFileAsync.OpenTo(ccVars.Pages[ccVars.PageIndex].Form.viewportcad, ro);
				}
				else
				{
					Design viewport = new Design();
					clsInit.cVector5.CreateModelControl(ref viewport, clsVar.UnlockKey, new CreateModelProperties());
					ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Layers.Clear();
					readFileAsync.OpenTo(ccVars.Pages[ccVars.PageIndex].Form.viewportcad, ro);
				}
				List<List<Entity>> list = new List<List<Entity>>();
				if (clsVar.varFile.ExplodeBlockReferanceWhenOpenFile)
				{
					for (int k = 0; k <= 10; k++)
					{
						List<int> list2 = new List<int>();
						list = new List<List<Entity>>();
						for (int l = 0; l <= ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Count - 1; l++)
						{
							if (!(ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[l] is BlockReference))
							{
								continue;
							}
							Entity[] array = ((BlockReference)ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[l]).Explode(ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Blocks);
							if (array != null && array.Length != 0)
							{
								List<Entity> list3 = new List<Entity>();
								for (int m = 0; m <= array.Length - 1; m++)
								{
									if (!(array[m] is LinearPathEx))
									{
										if (!(array[m].GetType() == typeof(devDept.Eyeshot.Entities.Point)))
										{
											if (!(array[m].GetType() == typeof(Text)))
											{
												list3.Add(array[m]);
											}
											else if (!clsVar.varFile.DontAddTextFromDxfFile)
											{
												list3.Add(array[m]);
											}
										}
										else if (!clsVar.varFile.DontAddPointFromDxfFile)
										{
											list3.Add(array[m]);
										}
									}
									else
									{
										LinearPath linearPath = new LinearPath(array[m].Vertices);
										linearPath.LayerName = array[m].LayerName;
										linearPath.Color = array[m].Color;
										list3.Add(linearPath);
									}
								}
								list.Add(list3);
							}
							list2.Add(l);
						}
						if (list2.Count <= 0)
						{
							k = 11;
						}
						else
						{
							list2.Sort();
							list2.Reverse();
							for (int n = 0; n <= list2.Count - 1; n++)
							{
								ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.RemoveAt(list2[n]);
							}
						}
						for (int num = 0; num <= list.Count - 1; num++)
						{
							for (int num2 = 0; num2 <= list[num].Count - 1; num2++)
							{
								ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Add((Entity)list[num][num2].Clone());
							}
						}
					}
				}
				Point3D MinPoint = new Point3D();
				Point3D MidPoint = new Point3D();
				Point3D MaxPoint = new Point3D();
				clsInit.cVector5.BoxSizeCalculate(ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities, ref MinPoint, ref MidPoint, ref MaxPoint);
				ccVars.Pages[ccVars.PageIndex].Info.EntitiesBoxSize = new Point3D(Math.Round(MaxPoint.X - MinPoint.X, 5), Math.Round(MaxPoint.Y - MinPoint.Y, 5), Math.Round(MaxPoint.Z - MinPoint.Z, 5));
				if (clsVar.varFile.MoveOpenEntitiesToZeroPointAuto)
				{
					ccVars.Pages[ccVars.PageIndex].MovedDistanceWhenImport = new Vec3D(0.0 - MinPoint.X, 0.0 - MinPoint.Y, 0.0 - MinPoint.Z);
					ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Translate(0.0 - MinPoint.X, 0.0 - MinPoint.Y, 0.0 - MinPoint.Z);
				}
				double num3 = 0.0;
				double num4 = 0.0;
				double num5 = 0.0;
				if (clsVar.varFile.ConvertDxfTextToVector)
				{
					for (int num6 = 0; num6 <= ccVars.CharLibList.Count - 1; num6++)
					{
						if ((ccVars.CharLibList[num6].Char == "A") | (ccVars.CharLibList[num6].Char == "O") | (ccVars.CharLibList[num6].Char == "M"))
						{
							Point3D MinPoint2 = new Point3D();
							Point3D MidPoint2 = new Point3D();
							Point3D MaxPoint2 = new Point3D();
							clsInit.cVector5.BoxSizeCalculate(ccVars.CharLibList[num6].CharEntities, ref MinPoint2, ref MidPoint2, ref MaxPoint2);
							num3 = MaxPoint2.Y - MinPoint2.Y;
							num4 = MaxPoint2.X - MinPoint2.X;
							num5 = num4 / 5.0;
						}
					}
				}
				for (int num7 = 0; num7 <= ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Count - 1; num7++)
				{
					if (ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[num7] is Circle)
					{
						_ = ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[num7];
					}
					if (!(clsVar.varFile.ConvertDxfTextToVector && num3 > 0.0 && num4 > 0.0) || !((ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[num7] is Text) & (ccVars.CharLibList.Count > 0)))
					{
						continue;
					}
					Text text = ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[num7] as Text;
					text.Selected = true;
					Point3D point3D = buVector5.ToPoint3D(text.InsertionPoint);
					Point3D MinPoint3 = new Point3D();
					Point3D MidPoint3 = new Point3D();
					Point3D MaxPoint3 = new Point3D();
					clsInit.cVector5.BoxSizeCalculate(ccVars.CharLibList[0].CharEntities, ref MinPoint3, ref MidPoint3, ref MaxPoint3);
					double num8 = text.Height / num3;
					double num9 = num5 * num8;
					for (int num10 = 0; num10 <= text.TextString.Length - 1; num10++)
					{
						string text2 = text.TextString.Substring(num10, 1);
						double height = text.Height;
						for (int num11 = 0; num11 <= ccVars.CharLibList.Count - 1; num11++)
						{
							if (ccVars.CharLibList[num11].Char == text2)
							{
