	public void cmdInternalEntitiesToLayer()
	{
		try
		{
			if (ccVars.Pages.Count <= 0)
			{
				return;
			}
			Reset();
			List<EntitiesGroup> Groups = new List<EntitiesGroup>();
			for (int i = 0; i <= ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Count - 1; i++)
			{
				if (ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[i].EntityData != null)
				{
					if (!(ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[i].EntityData is CustomData))
					{
						CustomData customData = new CustomData();
						customData.RefIndex = i;
						ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[i].EntityData = customData;
					}
					else
					{
						((CustomData)ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[i].EntityData).RefIndex = i;
					}
				}
				else
				{
					CustomData customData2 = new CustomData();
					customData2.RefIndex = i;
					ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[i].EntityData = customData2;
				}
			}
			clsInit.cVector5.FindEntitiesGroupFromEntities(new Point3D(), ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.ToList(), ccVars.planeActive, ref Groups);
			if (Groups.Count <= 0)
			{
				return;
			}
			DialogBoxList dialogBoxList = new DialogBoxList();
			for (int j = 0; j <= ccVars.Pages[ccVars.PageIndex].Layers.Count - 1; j++)
			{
				LayerBase5 layerBase = new LayerBase5(ccVars.Pages[ccVars.PageIndex].Layers[j]);
				List<string> items = dialogBoxList.Items;
				string[] obj = new string[6]
				{
					"[",
					(j + 1).ToString(),
					"] ",
					layerBase.Name,
					" - ",
					null
				};
				Color layerColor = layerBase.LayerColor;
				obj[5] = layerColor.ToString();
				items.Add(string.Concat(obj));
			}
			dialogBoxList.Init();
			dialogBoxList.ShowDialog();
			if (dialogBoxList.Result != DialogResult.OK)
			{
				return;
			}
			if ((dialogBoxList.SelectedIndex >= 0) & (dialogBoxList.SelectedIndex <= ccVars.Pages[ccVars.PageIndex].Layers.Count - 1))
			{
				string text = "";
				if ((dialogBoxList.SelectedIndex >= 0) & (dialogBoxList.SelectedIndex <= ccVars.Pages[ccVars.PageIndex].Layers.Count - 1))
				{
					text = ccVars.Pages[ccVars.PageIndex].Layers[dialogBoxList.SelectedIndex].Name;
				}
				for (int k = 0; k <= Groups.Count - 1; k++)
				{
					if (!((Groups[k].Inside != null) & (text.Trim().Length > 0)))
					{
						continue;
					}
					for (int l = 0; l <= Groups[k].Inside.Count - 1; l++)
					{
						for (int m = 0; m <= Groups[k].Inside[l].Count - 1; m++)
						{
							if (Groups[k].Inside[l][m].EntityData != null && Groups[k].Inside[l][m].EntityData is CustomData)
							{
								CustomData customData3 = Groups[k].Inside[l][m].EntityData as CustomData;
								if ((customData3.RefIndex >= 0) & (customData3.RefIndex <= ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Count - 1))
								{
									ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[customData3.RefIndex].LayerName = text;
								}
							}
						}
					}
				}
			}
			Reset(ClearSelection: true, ReDraw: true);
		}
		catch (Exception mSException)
		{
			buLog.addLog("", "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: true, "");
		}
	}

