	public void cmdEntitiesProperties()
	{
		F_EntitiesProps f_EntitiesProps = new F_EntitiesProps();
		for (int i = 0; i <= ccVars.SelectionOP.Selections.Count - 1; i++)
		{
			int index = ccVars.SelectionOP.Selections[i].Index;
			if ((index >= 0) & (index <= ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Count - 1))
			{
				Entity item = buVector5.CopyEntities(ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index]);
				f_EntitiesProps.Entities.Add(item);
			}
		}
		ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.RegenAllCurved();
		f_EntitiesProps.Layers.Clear();
		f_EntitiesProps.InitViewport();
		f_EntitiesProps.viewportPort.Layers = clsInit.cVector5.LayerCopy(ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Layers);
		f_EntitiesProps.viewportPort.TextStyles = clsInit.cVector5.TextStyleCopy(ccVars.Pages[ccVars.PageIndex].Form.viewportcad.TextStyles);
		f_EntitiesProps.viewportPort.HatchPatterns = clsInit.cVector5.HatchPatternCopy(ccVars.Pages[ccVars.PageIndex].Form.viewportcad.HatchPatterns);
		f_EntitiesProps.viewportPort.Materials = clsInit.cVector5.MaterialCopy(ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Materials);
		f_EntitiesProps.Init();
		f_EntitiesProps.ShowDialog();
		f_EntitiesProps.Entities.Clear();
		f_EntitiesProps.Dispose();
	}

