	public void doMeshRemoveTrianlge(Plane refPlane, Point3D pntLeftBottom, Point3D pntRigthTop)
	{
		for (int num = ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Count - 1; num >= 0; num--)
		{
			if (ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[num] is Mesh)
			{
				Mesh mesh = ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[num] as Mesh;
				MeshEditor meshEditor = new MeshEditor(mesh.Vertices, mesh.Triangles);
				int num2 = 0;
				for (int num3 = mesh.Triangles.Length - 1; num3 >= 0; num3--)
				{
					if (clsInit.cVector5.IsPointInsideBoxsize(mesh.Vertices[mesh.Triangles[num3].V1], pntLeftBottom, pntRigthTop, refPlane))
					{
						meshEditor.DeleteTriangle(num3);
						num2++;
					}
				}
				meshEditor.Apply();
				if (num2 > 0 && meshEditor.Vertices.Length > 1 && meshEditor.Triangles.Length > 1)
				{
					Mesh mesh2 = new Mesh(meshEditor.Vertices, meshEditor.Triangles);
					mesh2.Color = mesh.Color;
					mesh2.ColorMethod = mesh.ColorMethod;
					mesh2.LayerName = mesh.LayerName;
					ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[num] = mesh2;
					ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[num].Regen(0.1);
				}
			}
		}
		ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Invalidate();
	}

