	public void CamDraw(camTp cam, string LayerName = "")
	{
		bool flag = false;
		if (LayerName.Trim().Length > 0)
		{
			for (int i = 0; i <= ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Layers.Count - 1; i++)
			{
				if (ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Layers[i].Name == LayerName)
				{
					flag = true;
				}
			}
		}
		if (clsVar.varCam.ShowCamG0Drawings)
		{
			for (int j = 0; j <= cam.EntitiesG0.Count - 1; j++)
			{
				ccVars.UndoDont = true;
				Entity Ent = null;
				CreateEntity(cam.EntitiesG0[j], ref Ent);
				if (Ent != null)
				{
					Ent.Color = clsVar.varCam.CamG0Draw.Color;
					Ent.LineWeight = clsVar.varCam.CamG0Draw.Thickness;
					Ent.ColorMethod = colorMethodType.byEntity;
					Ent.LineWeightMethod = colorMethodType.byEntity;
					if (flag)
					{
						Ent.LineTypeMethod = colorMethodType.byLayer;
						Ent.ColorMethod = colorMethodType.byLayer;
						Ent.LineWeightMethod = colorMethodType.byLayer;
						Ent.LayerName = LayerName;
					}
					Ent.Selectable = false;
					if (Ent.EntityData != null && Ent.EntityData is CustomData)
					{
						((CustomData)Ent.EntityData).typeDefination = entityTypeDefination.CamG0;
					}
					AddEntity(Ent);
				}
			}
		}
		if (clsVar.varCam.ShowCamG1Drawings)
		{
			for (int k = 0; k <= cam.EntitiesG1.Count - 1; k++)
			{
				ccVars.UndoDont = true;
