		}
		for (int num3 = 0; num3 <= cam.EntitiesOther.Count - 1; num3++)
		{
			Entity Ent8 = null;
			CreateEntity(cam.EntitiesOther[num3], ref Ent8);
			if (Ent8 != null)
			{
				ccVars.UndoDont = true;
				Ent8.Color = clsVar.varCam.CamOtherDraw.Color;
				Ent8.LineWeight = clsVar.varCam.CamOtherDraw.Thickness;
				Ent8.ColorMethod = colorMethodType.byEntity;
				Ent8.LineWeightMethod = colorMethodType.byEntity;
				Ent8.Selectable = false;
				if (flag)
				{
					Ent8.LineTypeMethod = colorMethodType.byLayer;
					Ent8.ColorMethod = colorMethodType.byLayer;
					Ent8.LineWeightMethod = colorMethodType.byLayer;
					Ent8.LayerName = LayerName;
				}
				if (Ent8.EntityData != null && Ent8.EntityData is CustomData)
				{
					((CustomData)Ent8.EntityData).typeDefination = entityTypeDefination.CamOther;
				}
				AddEntity(Ent8);
			}
		}
	}

	public void CamsUpdate(bool FillCam, int SelectedIndex)
	{
		try
		{
			if (clsItem.FrmTempCams == null)
			{
				return;
			}
			CamUpdating = true;
			if (ccVars.Pages[ccVars.PageIndex].Cams.Count != clsItem.FrmTempCams.tree_cam.Nodes.Count)
			{
				FillCam = true;
			}
			if ((SelectedIndex >= 0) & (SelectedIndex <= ccVars.Pages[ccVars.PageIndex].CamIndex))
			{
				ccVars.Pages[ccVars.PageIndex].CamIndex = SelectedIndex;
			}
			if (ccVars.Pages[ccVars.PageIndex].CamIndex >= ccVars.Pages[ccVars.PageIndex].Cams.Count)
			{
				ccVars.Pages[ccVars.PageIndex].CamIndex = ccVars.Pages[ccVars.PageIndex].Cams.Count - 1;
			}
			int num = Convert.ToInt32(CamType.Drill4X) + Convert.ToInt32(ToolType.Laser) + 3;
			int num2 = Convert.ToInt32(CamType.Drill4X) + Convert.ToInt32(ToolType.Laser) + 4;
			if (!FillCam)
			{
				for (int i = 0; i <= ccVars.Pages[ccVars.PageIndex].Cams.Count - 1; i++)
				{
					clsItem.FrmTempCams.tree_cam.Nodes[i].Text = CamToName(ccVars.Pages[ccVars.PageIndex].Cams[i]);
					clsItem.FrmTempCams.tree_cam.Nodes[i].Nodes[0].Text = ToolToName(ccVars.Pages[ccVars.PageIndex].Cams[i].Tool);
					if (ccVars.Pages[ccVars.PageIndex].Cams[i].Visible)
					{
						clsItem.FrmTempCams.tree_cam.Nodes[i].Nodes[2].ImageIndex = num2;
						clsItem.FrmTempCams.tree_cam.Nodes[i].Nodes[2].SelectedImageIndex = num2;
					}
					else
					{
						clsItem.FrmTempCams.tree_cam.Nodes[i].Nodes[2].ImageIndex = num;
						clsItem.FrmTempCams.tree_cam.Nodes[i].Nodes[2].SelectedImageIndex = num;
					}
				}
			}
			else
			{
				clsItem.FrmTempCams.tree_cam.Nodes.Clear();
				TreeNodeSettings treeNodeSettings = null;
				TreeNodeSettings treeNodeSettings2 = null;
				TreeNodeSettings treeNodeSettings3 = null;
				TreeNodeSettings treeNodeSettings4 = null;
				for (int j = 0; j <= ccVars.Pages[ccVars.PageIndex].Cams.Count - 1; j++)
				{
					treeNodeSettings = new TreeNodeSettings(CamToName(ccVars.Pages[ccVars.PageIndex].Cams[j]))
					{
						ImageIndex = Convert.ToInt32(ccVars.Pages[ccVars.PageIndex].Cams[j].TypeCam),
						SelectedImageIndex = Convert.ToInt32(ccVars.Pages[ccVars.PageIndex].Cams[j].TypeCam),
						Tag = j.ToString(),
						ClassIndex = j,
						ClassSubIndex = -1,
						ClassSubSubIndex = -1,
						Command = "cam",
						Checked = ccVars.Pages[ccVars.PageIndex].Cams[j].Enable
					};
					string nodeText = "No Tool";
					int num3 = Convert.ToInt32(CamType.Drill4X) - Convert.ToInt32(CamType.None) + 1;
					if (ccVars.Pages[ccVars.PageIndex].Cams[j].Tool != null)
					{
						nodeText = ToolToName(ccVars.Pages[ccVars.PageIndex].Cams[j].Tool);
					}
					treeNodeSettings2 = new TreeNodeSettings(nodeText)
					{
						ImageIndex = Convert.ToInt32(ccVars.Pages[ccVars.PageIndex].Cams[j].Tool.Geometry.GeometryType) + num3,
						SelectedImageIndex = Convert.ToInt32(ccVars.Pages[ccVars.PageIndex].Cams[j].Tool.Geometry.GeometryType) + num3,
						Tag = j.ToString(),
						ClassIndex = j,
						ClassSubIndex = j,
						ClassSubSubIndex = -1,
						Command = "tool",
						Checked = ccVars.Pages[ccVars.PageIndex].Cams[j].Enable
					};
					treeNodeSettings.Nodes.Add(treeNodeSettings2);
					string nodeText2 = "Parameter";
					int num4 = Convert.ToInt32(ToolType.Laser) + num3;
					treeNodeSettings3 = new TreeNodeSettings(nodeText2)
					{
						ImageIndex = num4 + 1,
						SelectedImageIndex = num4 + 1,
						Tag = j.ToString(),
						ClassIndex = j,
						ClassSubIndex = j,
						ClassSubSubIndex = -1,
						Command = "parameter",
						Checked = ccVars.Pages[ccVars.PageIndex].Cams[j].Enable
					};
					treeNodeSettings.Nodes.Add(treeNodeSettings3);
					string nodeText3 = "Toolpath Draw";
					treeNodeSettings4 = new TreeNodeSettings(nodeText3)
					{
						ImageIndex = num2,
						SelectedImageIndex = num2,
						Tag = j.ToString(),
						ClassIndex = j,
						ClassSubIndex = j,
						ClassSubSubIndex = -1,
						Command = "toolpathvisible",
						Checked = ccVars.Pages[ccVars.PageIndex].Cams[j].Enable
					};
					if (!ccVars.Pages[ccVars.PageIndex].Cams[j].Visible)
					{
						treeNodeSettings4.ImageIndex = num;
						treeNodeSettings4.SelectedImageIndex = num;
					}
					treeNodeSettings.Nodes.Add(treeNodeSettings4);
					clsItem.FrmTempCams.tree_cam.Nodes.Add(treeNodeSettings);
				}
			}
			for (int k = 0; k <= ccVars.Pages[ccVars.PageIndex].CamIndex - 1; k++)
			{
				clsItem.FrmTempCams.tree_cam.Nodes[k].ForeColor = Color.Black;
			}
			for (int l = ccVars.Pages[ccVars.PageIndex].CamIndex + 1; l <= clsItem.FrmTempCams.tree_cam.Nodes.Count - 1; l++)
			{
				clsItem.FrmTempCams.tree_cam.Nodes[l].ForeColor = Color.Black;
			}
			if ((ccVars.Pages[ccVars.PageIndex].CamIndex >= 0) & (ccVars.Pages[ccVars.PageIndex].CamIndex <= clsItem.FrmTempCams.tree_cam.Nodes.Count - 1))
			{
				clsItem.FrmTempCams.tree_cam.Nodes[ccVars.Pages[ccVars.PageIndex].CamIndex].ForeColor = Color.Red;
			}
			CamUpdating = false;
		}
		catch (Exception mSException)
		{
			CamUpdating = false;
			buLog.addLog("", "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: true, "");
		}
	}

	public string CamToName(camTp Cam)
	{
		string text = "";
		if (Cam.Name.Trim().Length > 0)
		{
			text = Cam.Name + " ";
		}
		return text + Cam.TypeCam;
	}

	public void CamControlResize(bool Vertical, bool Horizontal)
	{
		try
		{
			int height = clsItem.tabcontrolLeft.Height;
			int width = clsItem.tabcontrolLeft.Width;
			if (clsVar.varProgram.ToolLocation == LeftRightAlignment.Right)
			{
				height = clsItem.tabcontrolRight.Height;
				width = clsItem.tabcontrolRight.Width;
			}
			if (Vertical)
			{
				clsItem.FrmTempCams.pnl_controls.Height = height;
			}
			if (Horizontal)
			{
				clsItem.FrmTempCams.pnl_controls.Width = width - 50;
			}
			if (clsVar.varProgram.CamLocation == LeftRightAlignment.Right)
			{
				height = clsItem.tabcontrolRight.Height;
				width = clsItem.tabcontrolRight.Width;
			}
		}
		catch (Exception value)
		{
			Console.WriteLine(value);
			throw;
		}
	}

	public void Cam_AfterSelect(object sender, TreeViewEventArgs e)
	{
		TreeNodeSettings treeNodeSettings = (TreeNodeSettings)e.Node;
		if ((treeNodeSettings.ClassIndex >= 0) & (treeNodeSettings.ClassIndex <= ccVars.Pages[ccVars.PageIndex].Cams.Count - 1))
		{
			ccVars.Pages[ccVars.PageIndex].CamIndex = treeNodeSettings.ClassIndex;
			CamsUpdate(FillCam: false, ccVars.Pages[ccVars.PageIndex].CamIndex);
			CamInfo(ccVars.Pages[ccVars.PageIndex].Cams[ccVars.Pages[ccVars.PageIndex].CamIndex], clsVar.varProgram.CamPanelSettings);
		}
	}

	public void Cam_DoubleClick(object sender, EventArgs e)
	{
		if (clsItem.FrmTempCams.tree_cam.SelectedNode == null || !(clsItem.FrmTempCams.tree_cam.SelectedNode.GetType() == typeof(TreeNodeSettings)))
		{
			return;
		}
		TreeNodeSettings treeNodeSettings = new TreeNodeSettings();
		treeNodeSettings = (TreeNodeSettings)clsItem.FrmTempCams.tree_cam.SelectedNode;
		if (!((treeNodeSettings.ClassSubIndex >= 0) & (treeNodeSettings.ClassSubIndex <= ccVars.Pages[ccVars.PageIndex].Cams.Count - 1)))
		{
			return;
		}
		if (treeNodeSettings.Command == "toolpathvisible")
		{
			if (!ccVars.Pages[ccVars.PageIndex].Cams[treeNodeSettings.ClassSubIndex].Visible)
			{
				ccVars.Pages[ccVars.PageIndex].Cams[treeNodeSettings.ClassSubIndex].Visible = true;
			}
			else
			{
				ccVars.Pages[ccVars.PageIndex].Cams[treeNodeSettings.ClassSubIndex].Visible = false;
			}
			CamsUpdate(FillCam: false, ccVars.Pages[ccVars.PageIndex].CamIndex);
			CamEntitiesSetVisibily(ccVars.Pages[ccVars.PageIndex].Cams[treeNodeSettings.ClassSubIndex].CamID, ccVars.Pages[ccVars.PageIndex].Cams[treeNodeSettings.ClassSubIndex].Visible);
		}
		if (!(treeNodeSettings.Command == "tool"))
		{
			return;
		}
		F_ToolList f_ToolList = new F_ToolList();
		for (int i = 0; i <= ccVars.Tools.Count - 1; i++)
		{
			for (int j = 0; j <= ccVars.Tools[i].Tools.Count - 1; j++)
			{
				f_ToolList.Tools.Add(new ToolBase5(ccVars.Tools[i].Tools[j]));
			}
		}
		f_ToolList.SelectedTool = new ToolBase5(ccVars.Pages[ccVars.PageIndex].Cams[treeNodeSettings.ClassSubIndex].Tool);
		f_ToolList.Init();
		f_ToolList.ShowDialog();
		if (f_ToolList.PropertiesForm.Result == DialogResult.OK)
		{
			CamsUpdate(FillCam: false, ccVars.Pages[ccVars.PageIndex].CamIndex);
			CamEntitiesSetVisibily(ccVars.Pages[ccVars.PageIndex].Cams[treeNodeSettings.ClassSubIndex].CamID, ccVars.Pages[ccVars.PageIndex].Cams[treeNodeSettings.ClassSubIndex].Visible);
		}
	}

