	public void CamRemoveEntities(int CamID)
	{
		try
		{
			for (int num = ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Count - 1; num >= 0; num--)
			{
				Entity entity = ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[num];
				int camID = clsInit.cVector5.GetCamID(ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[num]);
				if (CamID < 0)
				{
					if (!((ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[num] is buLineCam) | (ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[num] is buArcCam) | (ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[num] is buLinearPathCam) | (ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[num] is buCompositeCurveCam)))
					{
						if (entity.EntityData != null && entity.EntityData is CustomData && clsInit.cVector5.isEntityCamEntity(entity))
						{
							ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.RemoveAt(num);
						}
					}
					else
					{
						ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.RemoveAt(num);
					}
				}
				else if (camID == CamID)
				{
					if (!((ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[num] is buLineCam) | (ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[num] is buArcCam) | (ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[num] is buLinearPathCam) | (ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[num] is buCompositeCurveCam)))
					{
						if (entity.EntityData != null && entity.EntityData is CustomData && clsInit.cVector5.isEntityCamEntity(entity))
						{
							ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.RemoveAt(num);
						}
					}
					else
					{
						ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.RemoveAt(num);
					}
				}
			}
		}
		catch (Exception)
		{
		}
	}

	public void CamAvailableIDGet(ref int AvailableCamID)
	{
		if (ccVars.Pages.Count > 0)
		{
			AvailableCamID = 1;
			List<int> list = new List<int>();
			for (int i = 0; i <= ccVars.Pages[ccVars.PageIndex].Cams.Count - 1; i++)
			{
				list.Add(ccVars.Pages[ccVars.PageIndex].Cams[i].CamID);
			}
			if (list.Count <= 0)
			{
				AvailableCamID = ccVars.Pages[ccVars.PageIndex].Cams.Count + 1;
				return;
			}
			int num = list.Max();
			AvailableCamID = num + 1;
		}
	}

	public void CamInfo(camTp cam, CamPanelSetting Settings)
	{
		if (clsItem.FrmTempCams != null)
		{
			clsItem.FrmTempCams.txt_camexplanatiom.Text = "";
			if (Settings.ShowCamName)
			{
				clsItem.FrmTempCams.txt_camexplanatiom.Text = clsItem.FrmTempCams.txt_camexplanatiom.Text + AppLanguage.CadCamDynamic[40] + " : " + cam.Name + Environment.NewLine;
			}
			if (Settings.ShowCamType)
			{
				clsItem.FrmTempCams.txt_camexplanatiom.Text = clsItem.FrmTempCams.txt_camexplanatiom.Text + AppLanguage.CadCamDynamic[84] + " : " + cam.TypeCam.ToString() + Environment.NewLine;
			}
			if (Settings.ShowTool)
			{
				clsItem.FrmTempCams.txt_camexplanatiom.Text = clsItem.FrmTempCams.txt_camexplanatiom.Text + AppLanguage.CadCamDynamic[25] + " : " + cam.Tool.Data.Name + " | " + AppLanguage.CadCamDynamic[84] + ": " + cam.Tool.Geometry.GeometryType.ToString() + Environment.NewLine;
			}
			if (Settings.ShowProcessTime)
			{
				clsItem.FrmTempCams.txt_camexplanatiom.Text = clsItem.FrmTempCams.txt_camexplanatiom.Text + AppLanguage.CadCamDynamic[85] + " : " + cam.Information.AllProcessTime + Environment.NewLine;
			}
			if (Settings.ShowTotalLength)
			{
				clsItem.FrmTempCams.txt_camexplanatiom.Text = clsItem.FrmTempCams.txt_camexplanatiom.Text + AppLanguage.CadCamDynamic[0] + " : " + cam.Information.TotalLength + Environment.NewLine;
			}
		}
	}

	public void CamReCalculate()
	{
		camTp camTp2 = new camTp(ccVars.Pages[ccVars.PageIndex].Cams[ccVars.Pages[ccVars.PageIndex].CamIndex]);
		if ((camTp2.Action == actionTypeBU.camJewel3AXContour) | (camTp2.Action == actionTypeBU.camJewel3AXPocket) | (camTp2.Action == actionTypeBU.camJewel4AXContour) | (camTp2.Action == actionTypeBU.camJewel4AXSpinRamp) | (camTp2.Action == actionTypeBU.camJewel3AXSpinConstant) | (camTp2.Action == actionTypeBU.camJewel3AXPunch) | (camTp2.Action == actionTypeBU.camJewel4AXPunch) | (camTp2.Action == actionTypeBU.camJewel4AXPointRotation) | (camTp2.Action == actionTypeBU.camJewel3AXTriMeshRough) | (camTp2.Action == actionTypeBU.camJewel3AXTriMeshParalelCut) | (camTp2.Action == actionTypeBU.camJewel3AXTriMeshConstantZ))
		{
			camTp NewCam = new camTp();
			int num = clsInit.appJewel.cmdCamContourReCalculate(ccVars.Pages[ccVars.PageIndex].Cams[ccVars.Pages[ccVars.PageIndex].CamIndex], ref NewCam);
			if (num >= 1)
			{
				CamRemoveEntities(ccVars.Pages[ccVars.PageIndex].Cams[ccVars.Pages[ccVars.PageIndex].CamIndex].CamID);
				ccVars.Pages[ccVars.PageIndex].Cams[ccVars.Pages[ccVars.PageIndex].CamIndex] = NewCam;
				CamInfo(NewCam, clsVar.varProgram.CamPanelSettings);
				CamDraw(NewCam);
				CamsUpdate(FillCam: true, ccVars.Pages[ccVars.PageIndex].CamIndex);
			}
		}
		if ((camTp2.Action == actionTypeBU.camContours) | (camTp2.Action == actionTypeBU.camContours4AX) | (camTp2.Action == actionTypeBU.camPocketing) | (camTp2.Action == actionTypeBU.camDrill) | (camTp2.Action == actionTypeBU.camTriangularMesh3DRough) | (camTp2.Action == actionTypeBU.camTriangularMesh3DParalelCut) | (camTp2.Action == actionTypeBU.camTriangularMesh3DConstantZ))
		{
			camTp NewCam2 = new camTp();
			int num2 = CamCalcReCalculate(ccVars.Pages[ccVars.PageIndex].Cams[ccVars.Pages[ccVars.PageIndex].CamIndex], ref NewCam2);
			if (num2 >= 1)
			{
				CamRemoveEntities(ccVars.Pages[ccVars.PageIndex].Cams[ccVars.Pages[ccVars.PageIndex].CamIndex].CamID);
				ccVars.Pages[ccVars.PageIndex].Cams[ccVars.Pages[ccVars.PageIndex].CamIndex] = NewCam2;
				CamInfo(NewCam2, clsVar.varProgram.CamPanelSettings);
				CamDraw(NewCam2);
				CamsUpdate(FillCam: true, ccVars.Pages[ccVars.PageIndex].CamIndex);
			}
		}
	}

	public int CamCalcReCalculate(camTp OldCam, ref camTp NewCam)
	{
		//IL_00a9: Unknown result type (might be due to invalid IL or missing references)
		//IL_00b3: Expected O, but got Unknown
		//IL_00ae: Unknown result type (might be due to invalid IL or missing references)
		//IL_00b8: Expected O, but got Unknown
		//IL_0128: Unknown result type (might be due to invalid IL or missing references)
		//IL_0132: Expected O, but got Unknown
		//IL_012d: Unknown result type (might be due to invalid IL or missing references)
		//IL_0137: Expected O, but got Unknown
		//IL_01a7: Unknown result type (might be due to invalid IL or missing references)
		//IL_01b1: Expected O, but got Unknown
		//IL_01ac: Unknown result type (might be due to invalid IL or missing references)
		//IL_01b6: Expected O, but got Unknown
		//IL_0226: Unknown result type (might be due to invalid IL or missing references)
		//IL_0230: Expected O, but got Unknown
		//IL_022b: Unknown result type (might be due to invalid IL or missing references)
		//IL_0235: Expected O, but got Unknown
		//IL_02a5: Unknown result type (might be due to invalid IL or missing references)
		//IL_02af: Expected O, but got Unknown
		//IL_02aa: Unknown result type (might be due to invalid IL or missing references)
		//IL_02b4: Expected O, but got Unknown
		//IL_0324: Unknown result type (might be due to invalid IL or missing references)
		//IL_032e: Expected O, but got Unknown
		//IL_0329: Unknown result type (might be due to invalid IL or missing references)
		//IL_0333: Expected O, but got Unknown
		//IL_03a3: Unknown result type (might be due to invalid IL or missing references)
		//IL_03ad: Expected O, but got Unknown
		//IL_03a8: Unknown result type (might be due to invalid IL or missing references)
		//IL_03b2: Expected O, but got Unknown
		try
		{
			MWCalculationOptions mWCalculationOptions = new MWCalculationOptions(OldCam.MWCalcOptions);
			clsMW.CamEntities.Clear();
			if (OldCam.Action != actionTypeBU.camContours)
			{
				if (OldCam.Action != actionTypeBU.camPocketing)
				{
					if (OldCam.Action != actionTypeBU.camContours4AX)
					{
						if (OldCam.Action != actionTypeBU.camDrill)
						{
							if (OldCam.Action != actionTypeBU.camTriangularMesh3DRough)
							{
								if (OldCam.Action != actionTypeBU.camTriangularMesh3DParalelCut)
								{
									if (OldCam.Action != actionTypeBU.camTriangularMesh3DConstantZ)
									{
										return -1;
									}
									clsVar.varCamMeshConstantZPars.mwPar.MachParam = new MachiningParams((MachiningParams)OldCam.mwParameter);
									clsVar.varCamMeshConstantZPars.buPar = new camParameters5(OldCam.Parameter);
									clsMW.CamEntities.Clear();
									clsMW.CamEntities = new List<Entity>();
									buVector5.CopyEntities(OldCam.RefEntities, ref clsMW.CamEntities);
									mWCalculationOptions.AddToCamListInLocalCalculation = false;
									NewCam = new camTp();
									return doTriangleMesh(mWCalculationOptions, ccVars.toolActive, OldCam.Action, ref NewCam);
								}
								clsVar.varCamMeshParallelPars.mwPar.MachParam = new MachiningParams((MachiningParams)OldCam.mwParameter);
								clsVar.varCamMeshParallelPars.buPar = new camParameters5(OldCam.Parameter);
								clsMW.CamEntities.Clear();
								clsMW.CamEntities = new List<Entity>();
								buVector5.CopyEntities(OldCam.RefEntities, ref clsMW.CamEntities);
								mWCalculationOptions.AddToCamListInLocalCalculation = false;
								NewCam = new camTp();
								return doTriangleMesh(mWCalculationOptions, ccVars.toolActive, OldCam.Action, ref NewCam);
							}
							clsVar.varCamMeshRoughPars.mwPar.MachParam = new MachiningParams((MachiningParams)OldCam.mwParameter);
							clsVar.varCamMeshRoughPars.buPar = new camParameters5(OldCam.Parameter);
							clsMW.CamEntities.Clear();
							clsMW.CamEntities = new List<Entity>();
							buVector5.CopyEntities(OldCam.RefEntities, ref clsMW.CamEntities);
							mWCalculationOptions.AddToCamListInLocalCalculation = false;
							NewCam = new camTp();
							return doTriangleMesh(mWCalculationOptions, ccVars.toolActive, OldCam.Action, ref NewCam);
						}
						clsVar.varCamDrillPars.mwPar.MachParam = new MachiningParams((MachiningParams)OldCam.mwParameter);
						clsVar.varCamDrillPars.buPar = new camParameters5(OldCam.Parameter);
						clsMW.CamEntities.Clear();
						clsMW.CamEntities = new List<Entity>();
						buVector5.CopyEntities(OldCam.RefEntities, ref clsMW.CamEntities);
						mWCalculationOptions.AddToCamListInLocalCalculation = false;
						NewCam = new camTp();
						return doDrill(mWCalculationOptions, ccVars.toolActive, OldCam.Action, ref NewCam);
					}
					clsVar.varCamWFContour4XPars.mwPar.MachParam = new MachiningParams((MachiningParams)OldCam.mwParameter);
					clsVar.varCamWFContour4XPars.buPar = new camParameters5(OldCam.Parameter);
					clsMW.CamEntities.Clear();
					clsMW.CamEntities = new List<Entity>();
					buVector5.CopyEntities(OldCam.RefEntities, ref clsMW.CamEntities);
					mWCalculationOptions.AddToCamListInLocalCalculation = false;
					NewCam = new camTp();
					return doWireframeContour(mWCalculationOptions, ccVars.toolActive, OldCam.Action, ref NewCam);
				}
				clsVar.varCamWFPocketPars.mwPar.MachParam = new MachiningParams((MachiningParams)OldCam.mwParameter);
				clsVar.varCamWFPocketPars.buPar = new camParameters5(OldCam.Parameter);
				clsMW.CamEntities.Clear();
				clsMW.CamEntities = new List<Entity>();
				buVector5.CopyEntities(OldCam.RefEntities, ref clsMW.CamEntities);
				mWCalculationOptions.AddToCamListInLocalCalculation = false;
				NewCam = new camTp();
				return doWireframeContour(mWCalculationOptions, ccVars.toolActive, OldCam.Action, ref NewCam);
			}
			clsVar.varCamWFContourPars.mwPar.MachParam = new MachiningParams((MachiningParams)OldCam.mwParameter);
			clsVar.varCamWFContourPars.buPar = new camParameters5(OldCam.Parameter);
			clsMW.CamEntities.Clear();
			clsMW.CamEntities = new List<Entity>();
			buVector5.CopyEntities(OldCam.RefEntities, ref clsMW.CamEntities);
			mWCalculationOptions.AddToCamListInLocalCalculation = false;
			NewCam = new camTp();
			return doWireframeContour(mWCalculationOptions, ccVars.toolActive, OldCam.Action, ref NewCam);
		}
		catch (Exception mSException)
		{
			buLog.addLog("", "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: true, "");
			return -1;
		}
	}

	public void CamEntitiesSetVisibily(int CamID, bool Visible)
	{
		for (int i = 0; i <= ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Count - 1; i++)
		{
			if (ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[i].GetType() == typeof(buLinearPathCam) && ((buLinearPathCam)ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[i]).CamID == CamID)
			{
				ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[i].Visible = Visible;
			}
		}
		ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Invalidate();
	}

	public void simStart()
	{
		if (ccVars.Pages.Count <= 0)
		{
			return;
		}
		if (!((ccVars.SimCamBaseIndex >= 0) & (ccVars.SimCamBaseIndex <= ccVars.Pages[ccVars.PageIndex].Cams.Count - 1)))
		{
			if (ccVars.Pages[ccVars.PageIndex].Cams.Count != 0 && ((ccVars.SimCamBaseIndex < 0) & (ccVars.SimCamBaseIndex <= ccVars.Pages[ccVars.PageIndex].Cams.Count - 1)))
			{
				ccVars.SimCamBaseIndex = 0;
				if (ccVars.Pages[ccVars.PageIndex].Cams[ccVars.SimCamBaseIndex].Tool == null)
				{
					ccVars.Pages[ccVars.PageIndex].Cams[ccVars.SimCamBaseIndex].Tool = new ToolBase5();
				}
				if (ccVars.Pages[ccVars.PageIndex].Cams[ccVars.SimCamBaseIndex].Kinematic == null)
				{
					ccVars.Pages[ccVars.PageIndex].Cams[ccVars.SimCamBaseIndex].Kinematic = new KinematicBase5();
				}
				SimMachinePartAdd(ccVars.Pages[ccVars.PageIndex].Cams[ccVars.SimCamBaseIndex].Tool, ccVars.Pages[ccVars.PageIndex].Cams[ccVars.SimCamBaseIndex].Kinematic);
				ccVars.Pages[ccVars.PageIndex].Form.viewportcad.StartAnimation(clsVar.varSimulation.SimulationInterval);
				clsItem.timSim.Enabled = true;
				clsFiles.SaveParameter();
			}
		}
		else
		{
			clsItem.timSim.Enabled = true;
		}
	}

	public void simToolCreate(ToolBase5 Tool, KinematicBase5 Kinematic)
	{
		if (ccVars.Pages.Count > 0)
		{
			SimMachinePartAdd(Tool, Kinematic);
			ccVars.Pages[ccVars.PageIndex].Form.viewportcad.StartAnimation(clsVar.varSimulation.SimulationInterval);
		}
	}

