			((buTool)ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[ccVars.SimToolEntityIndex]).zPos = Position.Z;
			((buTool)ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[ccVars.SimToolEntityIndex]).aPos = Position.A;
			((buTool)ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[ccVars.SimToolEntityIndex]).bPos = Position.B;
			((buTool)ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[ccVars.SimToolEntityIndex]).cPos = Position.C;
