	public void simPre()
	{
		if (ccVars.Pages.Count > 0 && ccVars.SimCamBaseIndex >= 0 && ((ccVars.SimCamBaseIndex >= 0) & (ccVars.SimCamBaseIndex <= ccVars.Pages[ccVars.PageIndex].Cams.Count - 1)))
		{
			ccVars.SimCamPointIndex -= clsVar.varInterface.CamSimulationStep * 2;
