		}
	}

	public void SimMachinePartAdd(ToolBase5 Tool, KinematicBase5 Kinematic)
	{
		List<Mesh> refMeshes = new List<Mesh>();
		if (Tool.Geometry.FromFileEnable)
		{
			FileInfo fileInfo = new FileInfo(Tool.Geometry.FromFileFileName);
			if (fileInfo.Exists)
			{
				Design design = new Design();
				ReadSTL readSTL = new ReadSTL(fileInfo.FullName);
				readSTL.DoWork();
				readSTL.OpenTo(design);
				if (design.Entities.Count > 0)
				{
					for (int i = 0; i <= design.Entities.Count - 1; i++)
					{
						if (design.Entities[i] is Mesh)
						{
							Mesh mesh = (Mesh)design.Entities[i].Clone();
							mesh.ColorMethod = colorMethodType.byEntity;
							if (mesh.Color == Color.Black)
							{
								mesh.Color = Color.DarkGray;
							}
							mesh.Rotate(buConversion5.DegreeToRadian(Tool.Geometry.FromFileAngle), new Vector3D(0.0, 0.0, 1.0));
							refMeshes.Add(mesh);
						}
					}
				}
			}
		}
		else if (!((Tool.Geometry.ToolDirection.X != 0.0) | (Tool.Geometry.ToolDirection.Y != 0.0)))
		{
			clsInit.appMW.CreateTool(Tool, ToolCut: true, Tool.Geometry.DrawLength, Tool.Geometry.DrawArbor, Tool.Geometry.DrawHolder, ref refMeshes);
		}
		else
		{
			clsInit.appMW.CreateToolWithToolDirection(Tool, ToolCut: true, Tool.Geometry.DrawLength, Tool.Geometry.DrawArbor, Tool.Geometry.DrawHolder, ZeroIsMachineSide: false, ref refMeshes);
		}
		SimToolRemove();
		Block block = new Block("Tool");
		new Mesh();
		if (refMeshes.Count != 1)
		{
			for (int j = 0; j <= refMeshes.Count - 1; j++)
			{
				refMeshes[j].ColorMethod = colorMethodType.byEntity;
				if (Tool.Geometry.GeometryType == ToolType.Saw)
				{
					refMeshes[j].Rotate(Utility.DegToRad(90.0), new Vector3D(0.0, 1.0, 0.0), new Point3D(0.0, 0.0, 0.0));
					refMeshes[j].Rotate(Utility.DegToRad(90.0), new Vector3D(0.0, 0.0, 1.0), new Point3D(0.0, 0.0, 0.0));
					refMeshes[j].Translate(0.0 + Kinematic.MovePartRuntimeOffset.X, 0.0 + Kinematic.MovePartRuntimeOffset.Y, 0.0 - Tool.Geometry.Thickness / 1.0 + Kinematic.MovePartRuntimeOffset.Z);
				}
				block.Entities.Add(refMeshes[j]);
			}
		}
		else
		{
			for (int k = 0; k <= refMeshes.Count - 1; k++)
			{
				refMeshes[k].ColorMethod = colorMethodType.byEntity;
				if (Tool.Geometry.GeometryType == ToolType.Saw)
				{
					refMeshes[k].Rotate(Utility.DegToRad(90.0), new Vector3D(0.0, 1.0, 0.0), new Point3D(0.0, 0.0, 0.0));
					refMeshes[k].Rotate(Utility.DegToRad(90.0), new Vector3D(0.0, 0.0, 1.0), new Point3D(0.0, 0.0, 0.0));
					refMeshes[k].Translate(0.0 + Kinematic.MovePartRuntimeOffset.X, 0.0 + Kinematic.MovePartRuntimeOffset.Y, 0.0 - Tool.Geometry.Thickness / 1.0 + Kinematic.MovePartRuntimeOffset.Z);
				}
				block.Entities.Add(refMeshes[k]);
			}
		}
		ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Blocks.Add(block);
		buTool buTool2 = new buTool("Tool");
		buTool2.CRotation = Tool.Limits.RotationC;
		buTool2.BRotation = Tool.Limits.RotationB;
		buTool2.ARotation = Tool.Limits.RotationA;
		ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Add(buTool2);
		ccVars.SimToolEntityIndex = ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Count - 1;
	}

	public void SimToolRemove()
	{
		if (((ccVars.SimToolEntityIndex >= 0) & (ccVars.SimToolEntityIndex <= ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Count - 1)) && ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[ccVars.SimToolEntityIndex] is buTool)
		{
			ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.RemoveAt(ccVars.SimToolEntityIndex);
		}
		ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Blocks.Remove("Tool");
		ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Invalidate();
	}

	public void Sim_Tick(object sender, EventArgs e)
	{
		if (ccVars.Pages.Count <= 0)
		{
			return;
		}
		if (ccVars.SimCamBaseIndex <= ccVars.Pages[ccVars.PageIndex].Cams.Count - 1)
		{
			if (ccVars.SimCamBaseIndex > ccVars.Pages[ccVars.PageIndex].Cams.Count - 1)
			{
				ccVars.SimCamBaseIndex = -1;
				ccVars.SimCamPointIndex = 0;
				clsItem.timSim.Enabled = false;
				simStop();
			}
			else if (!ccVars.Pages[ccVars.PageIndex].Cams[ccVars.SimCamBaseIndex].Enable)
			{
				ccVars.SimCamBaseIndex++;
			}
			else if (!((ccVars.SimCamPointIndex >= 0) & (ccVars.SimCamPointIndex <= ccVars.Pages[ccVars.PageIndex].Cams[ccVars.SimCamBaseIndex].SimilationPoint.SimMove.Count - 1)))
			{
				ccVars.SimCamBaseIndex++;
				ccVars.SimCamPointIndex = 0;
				if (!((ccVars.SimCamBaseIndex >= 0) & (ccVars.SimCamBaseIndex <= ccVars.Pages[ccVars.PageIndex].Cams.Count - 1)))
				{
					ccVars.SimCamBaseIndex = -1;
					ccVars.SimCamPointIndex = 0;
					clsItem.timSim.Enabled = false;
					simStop();
				}
				else
				{
					clsInit.appCommand.SimMachinePartAdd(ccVars.Pages[ccVars.PageIndex].Cams[ccVars.SimCamBaseIndex].Tool, ccVars.Pages[ccVars.PageIndex].Cams[ccVars.SimCamBaseIndex].Kinematic);
				}
			}
			else
			{
				ccVars.pntSimulation = new Pnt6DSimMove(ccVars.Pages[ccVars.PageIndex].Cams[ccVars.SimCamBaseIndex].SimilationPoint.SimMove[ccVars.SimCamPointIndex]);
				new Pnt3D(ccVars.Pages[ccVars.PageIndex].Cams[ccVars.SimCamBaseIndex].Tool.CamData.SimMoveOffset);
				if (clsItem.FrmTempCams != null)
				{
					clsItem.FrmTempCams.txt_simx.Text = Math.Round(ccVars.pntSimulation.X, 3).ToString();
					clsItem.FrmTempCams.txt_simy.Text = Math.Round(ccVars.pntSimulation.Y, 3).ToString();
					clsItem.FrmTempCams.txt_simz.Text = Math.Round(ccVars.pntSimulation.Z, 3).ToString();
					clsItem.FrmTempCams.txt_sima.Text = Math.Round(ccVars.pntSimulation.A, 3).ToString();
					clsItem.FrmTempCams.txt_simb.Text = Math.Round(ccVars.pntSimulation.B, 3).ToString();
					clsItem.FrmTempCams.txt_simc.Text = Math.Round(ccVars.pntSimulation.C, 3).ToString();
				}
				Pnt3D pnt3D = new Pnt3D(ccVars.Pages[ccVars.PageIndex].Cams[ccVars.SimCamBaseIndex].Kinematic.RotateCenterOffsetOfA.X - ccVars.Pages[ccVars.PageIndex].Cams[ccVars.SimCamBaseIndex].Kinematic.RotateCenterOffsetOfC.X, ccVars.Pages[ccVars.PageIndex].Cams[ccVars.SimCamBaseIndex].Kinematic.RotateCenterOffsetOfA.Y - ccVars.Pages[ccVars.PageIndex].Cams[ccVars.SimCamBaseIndex].Kinematic.RotateCenterOffsetOfC.Y, ccVars.Pages[ccVars.PageIndex].Cams[ccVars.SimCamBaseIndex].Kinematic.RotateCenterOffsetOfA.Z - ccVars.Pages[ccVars.PageIndex].Cams[ccVars.SimCamBaseIndex].Kinematic.RotateCenterOffsetOfC.Z);
				if ((ccVars.SimToolEntityIndex >= 0) & (ccVars.SimToolEntityIndex <= ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Count - 1))
				{
					_ = ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[ccVars.SimToolEntityIndex] is buTool;
					((buTool)ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[ccVars.SimToolEntityIndex]).xRot = pnt3D.X;
					((buTool)ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[ccVars.SimToolEntityIndex]).yRot = pnt3D.Y;
					((buTool)ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[ccVars.SimToolEntityIndex]).zRot = pnt3D.Z;
					_ = (buTool)ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[ccVars.SimToolEntityIndex];
					((buTool)ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[ccVars.SimToolEntityIndex]).xPos = ccVars.pntSimulation.X + ccVars.Pages[ccVars.PageIndex].Cams[ccVars.SimCamBaseIndex].SimilationToolOffset.X;
					((buTool)ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[ccVars.SimToolEntityIndex]).yPos = ccVars.pntSimulation.Y + ccVars.Pages[ccVars.PageIndex].Cams[ccVars.SimCamBaseIndex].SimilationToolOffset.Y;
					((buTool)ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[ccVars.SimToolEntityIndex]).zPos = ccVars.pntSimulation.Z + ccVars.Pages[ccVars.PageIndex].Cams[ccVars.SimCamBaseIndex].SimilationToolOffset.Z;
					((buTool)ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[ccVars.SimToolEntityIndex]).aPos = ccVars.pntSimulation.A;
					((buTool)ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[ccVars.SimToolEntityIndex]).bPos = ccVars.pntSimulation.B;
					((buTool)ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[ccVars.SimToolEntityIndex]).cPos = ccVars.pntSimulation.C;
				}
				ccVars.SimCamPointIndex += clsVar.varInterface.CamSimulationStep;
			}
			if (clsInit.appPrinter3D != null)
			{
				clsInit.appPrinter3D.Sim_Tick(null, null);
			}
			ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Invalidate();
			if (ccVars.SimStopAfterExecute)
			{
				simStop();
				ccVars.SimStopAfterExecute = false;
			}
		}
		else
		{
			ccVars.SimCamBaseIndex = -1;
			ccVars.SimCamPointIndex = 0;
			clsItem.timSim.Enabled = false;
			simStop();
		}
	}

	public void GetSimPointFromReverseKinematic(Pnt6D RefPoint, ToolBase5 Tool, KinematicBase Kinematic, ref Pnt6D CalcPoint)
	{
		try
		{
			if (Kinematic == null)
			{
				CalcPoint = new Pnt6D(RefPoint);
			}
			else if (Kinematic.Type != KinemeticType.CartezianXYZ_3Axis)
			{
				double toolLength = Tool.Geometry.Length;
				if (Tool.Geometry.GeometryType == ToolType.Saw)
				{
					toolLength = Tool.Geometry.Diameter / 2.0;
				}
				clsInit.cKinematic.ReverseKinematix5Ax(toolLength, Kinematic, new OrientationAngle(RefPoint), new Pnt3D(RefPoint), ref CalcPoint);
				CalcPoint.Z = CalcPoint.Z - Kinematic.RotateCenterOffsetOfC.Z + Kinematic.RotateCenterOffsetOfA.Z;
			}
			else
			{
				CalcPoint = new Pnt6D(RefPoint);
			}
		}
		catch (Exception mSException)
		{
			string text = "RefPoint: " + RefPoint.ToString();
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
		}
	}

