	public void cmdAnalyseEntities()
	{
		try
		{
			AnalyseEntitiesResult Result = new AnalyseEntitiesResult();
			List<Entity> copiedEnt = new List<Entity>();
			buVector5.CopyEntities(ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities, ref copiedEnt);
			clsInit.cVector5.AnalyseEntities(copiedEnt, clsVar.varInterface5.AnalyseEntitySetting, ref Result);
			if (!Result.isError)
			{
				buString5.MessageBoxInfo(AppLanguage.CadCamMessages[89]);
				return;
			}
			for (int i = 0; i <= copiedEnt.Count - 1; i++)
			{
				ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[i].Selected = copiedEnt[i].Selected;
			}
			ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Invalidate();
			F_AnalyseResult f_AnalyseResult = new F_AnalyseResult();
			f_AnalyseResult.Result = new AnalyseEntitiesResult(Result);
			f_AnalyseResult.Init();
			f_AnalyseResult.ShowDialog();
			if (f_AnalyseResult.PropertiesForm.Result != DialogResult.OK)
			{
				return;
			}
			for (int j = 0; j <= copiedEnt.Count - 1; j++)
			{
				ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[j].Selected = false;
			}
			for (int k = 0; k <= f_AnalyseResult.Result.ErrorList.Count - 1; k++)
			{
				int indexEntity = f_AnalyseResult.Result.ErrorList[k].IndexEntity;
				if (((indexEntity >= 0) & (indexEntity <= ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Count - 1)) && ((f_AnalyseResult.Result.ErrorList[k].Action == AnalyseEntitiesActionType.Delete) & f_AnalyseResult.Result.ErrorList[k].Enable))
				{
					ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[indexEntity].Selected = true;
				}
			}
			ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.DeleteSelected();
		}
		catch (Exception mSException)
		{
			buLog.addLog("", "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: true, "");
		}
	}

