	public void cmdMaterialAdd()
	{
		try
		{
			MaterialBase5 materialBase = null;
			materialBase = (((clsVar.varInterface.MaterialIndex >= 0) & (clsVar.varInterface.MaterialIndex <= ccVars.MaterialList.Count - 1)) ? new MaterialBase5(ccVars.MaterialList[clsVar.varInterface.MaterialIndex]) : new MaterialBase5());
			clsItem.FrmMaterial = new F_Material();
			CreateModelProperties createModelProperties = new CreateModelProperties();
			createModelProperties.CoordinateSystemIconVisible = false;
			createModelProperties.ViewCubeIconVisible = false;
			createModelProperties.OrigineCaptionVisible = false;
			createModelProperties.ToolBorVisible = false;
			clsInit.cVector5.CreateModelControl(ref clsItem.FrmMaterial.viewportLayout, clsVar.UnlockKey, createModelProperties);
			clsItem.FrmMaterial.pnl_model.Controls.Add(clsItem.FrmMaterial.viewportLayout);
			clsItem.FrmMaterial.viewportLayout.Entities.Clear();
			clsItem.FrmMaterial.Properties.FormCloseMode = FormCloseModeType.Invisible;
			clsItem.FrmMaterial.Material = new MaterialBase5(materialBase);
			clsItem.FrmMaterial.Init();
			clsItem.FrmMaterial.StartPosition = FormStartPosition.CenterParent;
			clsItem.FrmMaterial.ShowDialog();
			if (clsItem.FrmMaterial.Properties.Result != DialogResult.OK)
			{
				return;
			}
			bool flag = false;
			for (int i = 0; i <= ccVars.MaterialList.Count - 1; i++)
			{
				if (ccVars.MaterialList[i].Name.Trim().ToLower() == clsItem.FrmMaterial.Material.Name.Trim().ToLower())
				{
					flag = true;
				}
			}
			if (!flag)
			{
				ccVars.MaterialList.Add(new MaterialBase5(clsItem.FrmMaterial.Material));
				MaterialUpdate(FillMaterial: true, clsVar.varInterface.MaterialIndex);
				DrawingPropertiesUpdate();
				clsFiles.SaveParameter();
			}
			else
			{
				buString.MessageBoxWarning(AppLanguage.CadCamMessages[87] + Environment.NewLine + Environment.NewLine + "[ " + clsItem.FrmMaterial.Material.Name + " ]");
			}
		}
		catch (Exception mSException)
		{
			buLog.addLog("", "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: true, "");
		}
	}

