	public void MaterialInfo(MaterialBase5 Mat)
	{
		clsItem.FrmTempMaterial.txt_materialexplanatiom.Text = "";
		clsItem.FrmTempMaterial.txt_materialexplanatiom.Text = clsItem.FrmTempMaterial.txt_materialexplanatiom.Text + AppLanguage.CadCamDynamic[40] + " : " + Mat.Name + Environment.NewLine;
		clsItem.FrmTempMaterial.txt_materialexplanatiom.Text = clsItem.FrmTempMaterial.txt_materialexplanatiom.Text + AppLanguage.CadCamDynamic[84] + " : " + Mat.Shapes.ToString() + Environment.NewLine;
		if (Mat.Shapes == MaterialShapes.Rectangle)
		{
			clsItem.FrmTempMaterial.txt_materialexplanatiom.Text = clsItem.FrmTempMaterial.txt_materialexplanatiom.Text + AppLanguage.CadCamDynamic[15] + " : " + Mat.Size.Width + Environment.NewLine;
			clsItem.FrmTempMaterial.txt_materialexplanatiom.Text = clsItem.FrmTempMaterial.txt_materialexplanatiom.Text + AppLanguage.CadCamDynamic[16] + " : " + Mat.Size.Height + Environment.NewLine;
		}
		if (Mat.Shapes == MaterialShapes.Circle)
		{
			clsItem.FrmTempMaterial.txt_materialexplanatiom.Text = clsItem.FrmTempMaterial.txt_materialexplanatiom.Text + AppLanguage.CadCamDynamic[19] + " : " + Mat.Radius + Environment.NewLine;
		}
		if (Mat.Shapes == MaterialShapes.Ellipse)
		{
			clsItem.FrmTempMaterial.txt_materialexplanatiom.Text = clsItem.FrmTempMaterial.txt_materialexplanatiom.Text + AppLanguage.CadCamDynamic[15] + " : " + Mat.MajorRadius + Environment.NewLine;
			clsItem.FrmTempMaterial.txt_materialexplanatiom.Text = clsItem.FrmTempMaterial.txt_materialexplanatiom.Text + AppLanguage.CadCamDynamic[16] + " : " + Mat.MinorRadius + Environment.NewLine;
		}
		if (Mat.Shapes == MaterialShapes.Irregular)
		{
			clsItem.FrmTempMaterial.txt_materialexplanatiom.Text = clsItem.FrmTempMaterial.txt_materialexplanatiom.Text + AppLanguage.CadCamDynamic[15] + " : " + Mat.Size.Width + Environment.NewLine;
			clsItem.FrmTempMaterial.txt_materialexplanatiom.Text = clsItem.FrmTempMaterial.txt_materialexplanatiom.Text + AppLanguage.CadCamDynamic[16] + " : " + Mat.Size.Height + Environment.NewLine;
		}
		clsItem.FrmTempMaterial.txt_materialexplanatiom.Text = clsItem.FrmTempMaterial.txt_materialexplanatiom.Text + AppLanguage.CadCamDynamic[42] + " : " + Mat.Size.Depth + Environment.NewLine;
	}

	public void MaterialUpdate(bool FillMaterial, int SelectedIndex)
	{
		try
		{
			if (clsItem.FrmTempMaterial == null)
			{
				return;
			}
			MaterialUpdating = true;
			if (!FillMaterial)
			{
				for (int i = 0; i <= ccVars.MaterialList.Count - 1; i++)
				{
					if (i > clsItem.FrmTempMaterial.tree_mats.Nodes.Count - 1)
					{
						continue;
					}
					clsItem.FrmTempMaterial.tree_mats.Nodes[i].Text = ccVars.MaterialList[i].Name;
					if (ccVars.MaterialList[i].Shapes != MaterialShapes.Rectangle)
					{
						if (ccVars.MaterialList[i].Shapes != MaterialShapes.Circle)
						{
							if (ccVars.MaterialList[i].Shapes != MaterialShapes.Ellipse)
							{
								if (ccVars.MaterialList[i].Shapes != MaterialShapes.Irregular)
								{
									if (ccVars.MaterialList[i].Shapes == MaterialShapes.FromFile)
									{
										if (ccVars.MaterialList[i].Enable)
										{
											clsItem.FrmTempMaterial.tree_mats.Nodes[i].ImageIndex = 9;
											clsItem.FrmTempMaterial.tree_mats.Nodes[i].SelectedImageIndex = 9;
										}
										else
										{
											clsItem.FrmTempMaterial.tree_mats.Nodes[i].ImageIndex = 8;
											clsItem.FrmTempMaterial.tree_mats.Nodes[i].SelectedImageIndex = 8;
										}
									}
								}
								else if (ccVars.MaterialList[i].Enable)
								{
									clsItem.FrmTempMaterial.tree_mats.Nodes[i].ImageIndex = 7;
									clsItem.FrmTempMaterial.tree_mats.Nodes[i].SelectedImageIndex = 7;
								}
								else
								{
									clsItem.FrmTempMaterial.tree_mats.Nodes[i].ImageIndex = 6;
									clsItem.FrmTempMaterial.tree_mats.Nodes[i].SelectedImageIndex = 6;
								}
							}
							else if (ccVars.MaterialList[i].Enable)
							{
								clsItem.FrmTempMaterial.tree_mats.Nodes[i].ImageIndex = 5;
								clsItem.FrmTempMaterial.tree_mats.Nodes[i].SelectedImageIndex = 5;
							}
							else
							{
								clsItem.FrmTempMaterial.tree_mats.Nodes[i].ImageIndex = 4;
								clsItem.FrmTempMaterial.tree_mats.Nodes[i].SelectedImageIndex = 4;
							}
						}
						else if (ccVars.MaterialList[i].Enable)
						{
							clsItem.FrmTempMaterial.tree_mats.Nodes[i].ImageIndex = 3;
							clsItem.FrmTempMaterial.tree_mats.Nodes[i].SelectedImageIndex = 3;
						}
						else
						{
							clsItem.FrmTempMaterial.tree_mats.Nodes[i].ImageIndex = 2;
							clsItem.FrmTempMaterial.tree_mats.Nodes[i].SelectedImageIndex = 2;
						}
					}
					else if (ccVars.MaterialList[i].Enable)
					{
						clsItem.FrmTempMaterial.tree_mats.Nodes[i].ImageIndex = 1;
						clsItem.FrmTempMaterial.tree_mats.Nodes[i].SelectedImageIndex = 1;
					}
					else
					{
						clsItem.FrmTempMaterial.tree_mats.Nodes[i].ImageIndex = 0;
						clsItem.FrmTempMaterial.tree_mats.Nodes[i].SelectedImageIndex = 0;
					}
				}
			}
			else
			{
				clsItem.FrmTempMaterial.tree_mats.Nodes.Clear();
				TreeNodeSettings treeNodeSettings = null;
				for (int j = 0; j <= ccVars.MaterialList.Count - 1; j++)
				{
					treeNodeSettings = new TreeNodeSettings(ccVars.MaterialList[j].Name)
					{
						Tag = j.ToString(),
						ClassIndex = j,
						ClassSubIndex = -1,
						ClassSubSubIndex = -1,
						Command = "matitem",
						Checked = true
					};
					if (ccVars.MaterialList[j].Shapes != MaterialShapes.Rectangle)
					{
						if (ccVars.MaterialList[j].Shapes != MaterialShapes.Circle)
						{
							if (ccVars.MaterialList[j].Shapes != MaterialShapes.Ellipse)
							{
								if (ccVars.MaterialList[j].Shapes != MaterialShapes.Irregular)
								{
									if (ccVars.MaterialList[j].Shapes == MaterialShapes.FromFile)
									{
										if (ccVars.MaterialList[j].Enable)
										{
											treeNodeSettings.ImageIndex = 9;
											treeNodeSettings.SelectedImageIndex = 9;
										}
										else
										{
											treeNodeSettings.ImageIndex = 8;
											treeNodeSettings.SelectedImageIndex = 8;
										}
									}
								}
								else if (ccVars.MaterialList[j].Enable)
								{
									treeNodeSettings.ImageIndex = 7;
									treeNodeSettings.SelectedImageIndex = 7;
								}
								else
								{
									treeNodeSettings.ImageIndex = 6;
									treeNodeSettings.SelectedImageIndex = 6;
								}
							}
							else if (ccVars.MaterialList[j].Enable)
							{
								treeNodeSettings.ImageIndex = 5;
								treeNodeSettings.SelectedImageIndex = 5;
							}
							else
							{
								treeNodeSettings.ImageIndex = 4;
								treeNodeSettings.SelectedImageIndex = 4;
							}
						}
						else if (ccVars.MaterialList[j].Enable)
						{
							treeNodeSettings.ImageIndex = 3;
							treeNodeSettings.SelectedImageIndex = 3;
						}
						else
						{
							treeNodeSettings.ImageIndex = 2;
							treeNodeSettings.SelectedImageIndex = 2;
						}
					}
					else if (ccVars.MaterialList[j].Enable)
					{
						treeNodeSettings.ImageIndex = 1;
						treeNodeSettings.SelectedImageIndex = 1;
					}
					else
					{
						treeNodeSettings.ImageIndex = 0;
						treeNodeSettings.SelectedImageIndex = 0;
					}
					if (treeNodeSettings != null)
					{
						clsItem.FrmTempMaterial.tree_mats.Nodes.Add(treeNodeSettings);
					}
				}
			}
			clsItem.FrmTempMaterial.tree_mats.ExpandAll();
			for (int k = 0; k <= clsVar.varInterface.MaterialIndex - 1; k++)
			{
				clsItem.FrmTempMaterial.tree_mats.Nodes[k].ForeColor = Color.Black;
			}
			for (int l = clsVar.varInterface.MaterialIndex + 1; l <= clsItem.FrmTempMaterial.tree_mats.Nodes.Count - 1; l++)
			{
				clsItem.FrmTempMaterial.tree_mats.Nodes[l].ForeColor = Color.Black;
			}
			if ((clsItem.FrmTempMaterial.tree_mats.Nodes.Count > 0) & (clsVar.varInterface.MaterialIndex <= clsItem.FrmTempMaterial.tree_mats.Nodes.Count - 1))
			{
				clsItem.FrmTempMaterial.tree_mats.Nodes[clsVar.varInterface.MaterialIndex].ForeColor = Color.Red;
			}
			if (ccVars.Pages.Count > 0)
			{
				for (int num = ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Count - 1; num >= 0; num--)
				{
					if (ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[num].GetType() == typeof(buMaterial))
					{
						ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[num].Selected = true;
					}
					if (ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[num].GetType() == typeof(Brep) && ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[num].EntityData != null && ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[num].EntityData is CustomData)
					{
						CustomData customData = ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[num].EntityData as CustomData;
						if (customData.typeDefination == entityTypeDefination.Material)
						{
							ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[num].Selected = true;
						}
					}
					if (ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[num].GetType() == typeof(Text) && ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[num].EntityData != null && ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[num].EntityData is CustomData)
					{
						CustomData customData2 = ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[num].EntityData as CustomData;
						if (customData2.typeDefination == entityTypeDefination.Material)
						{
							ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[num].Selected = true;
						}
					}
				}
				ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.DeleteSelected();
				for (int m = 0; m <= ccVars.MaterialList.Count - 1; m++)
				{
					if (ccVars.MaterialList[m].Enable)
					{
						Entity entSurface = null;
						clsInit.cVector5.MaterialToSurface(ccVars.MaterialList[m], ref entSurface);
						entSurface.Translate(ccVars.MaterialList[m].dX, ccVars.MaterialList[m].dY, ccVars.MaterialList[m].dZ);
						entSurface.ColorMethod = colorMethodType.byEntity;
						if (entSurface.BoxMin == null)
						{
							entSurface.Regen(0.01);
						}
						CustomData customData3 = new CustomData();
						customData3.typeDefination = entityTypeDefination.Material;
						entSurface.EntityData = customData3;
						ccVars.MaterialList[m].BoxMinPoint = new Point3D(entSurface.BoxMin.X, entSurface.BoxMin.Y, entSurface.BoxMin.Z);
						ccVars.MaterialList[m].BoxMaxPoint = new Point3D(entSurface.BoxMax.X, entSurface.BoxMax.Y, entSurface.BoxMax.Z);
						if (entSurface != null)
						{
							entSurface.Selectable = false;
							ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Add(entSurface);
							double num2 = Math.Round(entSurface.BoxMax.Y * 0.05, 3);
							Text text = new Text(Plane.XY, (m + 1).ToString(), num2);
							double dx = entSurface.BoxMin.X + (entSurface.BoxMax.X - entSurface.BoxMin.X) / 2.0;
							text.Translate(dx, 0.0 - (num2 + 10.0));
							customData3 = new CustomData();
							customData3.typeDefination = entityTypeDefination.Material;
							text.EntityData = customData3;
							ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Add(text);
						}
					}
				}
				ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Invalidate();
			}
			MaterialUpdating = false;
		}
		catch (Exception mSException)
		{
			MaterialUpdating = false;
			buLog.addLog("", "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: true, "");
		}
	}

	public void MaterialControlResize(bool Vertical, bool Horizontal)
	{
		try
		{
			int height = clsItem.tabcontrolLeft.Height;
			int width = clsItem.tabcontrolLeft.Width;
			if (clsVar.varProgram.MaterialLocation == LeftRightAlignment.Right)
			{
				height = clsItem.tabcontrolRight.Height;
				width = clsItem.tabcontrolRight.Width;
			}
			if (Vertical)
			{
				clsItem.FrmTempMaterial.pnl_controls.Height = height;
			}
			if (Horizontal)
			{
				clsItem.FrmTempMaterial.pnl_controls.Width = width - 50;
			}
		}
		catch (Exception mSException)
		{
			string text = "";
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: true, text);
		}
	}

	public void Material_AfterSelect(object sender, TreeViewEventArgs e)
	{
		TreeNodeSettings treeNodeSettings = (TreeNodeSettings)e.Node;
		if ((treeNodeSettings.ClassIndex >= 0) & (treeNodeSettings.ClassIndex <= ccVars.MaterialList.Count - 1))
		{
			clsVar.varInterface.MaterialIndex = treeNodeSettings.ClassIndex;
			MaterialInfo(ccVars.MaterialList[clsVar.varInterface.MaterialIndex]);
			MaterialUpdate(FillMaterial: false, clsVar.varInterface.MaterialIndex);
