	public void Material_DoubleClick(object sender, EventArgs e)
	{
		if ((clsVar.varInterface.MaterialIndex >= 0) & (clsVar.varInterface.MaterialIndex <= ccVars.MaterialList.Count - 1))
		{
			if (!ccVars.MaterialList[clsVar.varInterface.MaterialIndex].Enable)
			{
				ccVars.MaterialList[clsVar.varInterface.MaterialIndex].Enable = true;
