	public void cmdToolAdd(ToolProgramType Type)
	{
		try
		{
			if (ccVars.Pages.Count <= 0)
			{
				return;
			}
			ToolBase5 tool = new ToolBase5(ccVars.toolActive);
			if (ccVars.ToolIndex == -1)
			{
				tool = new ToolBase5();
			}
			clsItem.FrmTool = new F_Tool();
			CreateModelProperties createModelProperties = new CreateModelProperties();
			createModelProperties.CoordinateSystemIconVisible = false;
			createModelProperties.ViewCubeIconVisible = false;
			createModelProperties.OrigineCaptionVisible = false;
			createModelProperties.ToolBorVisible = false;
			clsInit.cVector5.CreateModelControl(ref clsItem.FrmTool.viewportLayout, clsVar.UnlockKey, createModelProperties);
			clsItem.FrmTool.viewportLayout.Entities.Clear();
			clsItem.FrmTool.Properties.FormCloseMode = FormCloseModeType.Invisible;
			clsItem.FrmTool.Tool = new ToolBase5(tool);
			clsItem.FrmTool.Init();
			clsItem.FrmTool.StartPosition = FormStartPosition.CenterParent;
			clsItem.FrmTool.ShowDialog();
			if (clsItem.FrmTool.Properties.Result == DialogResult.OK)
			{
				if (ccVars.Tools.Count <= 0)
				{
					ToolGroup5 toolGroup = new ToolGroup5();
					toolGroup.Tools.Add(new ToolBase5(clsItem.FrmTool.Tool));
					ccVars.Tools.Add(toolGroup);
				}
				else
				{
					ccVars.Tools[ccVars.ToolGroupIndex].Tools.Add(new ToolBase5(clsItem.FrmTool.Tool));
				}
				ToolUpdate(FillTool: true, ccVars.ToolGroupIndex, ccVars.ToolIndex);
				DrawingPropertiesUpdate();
				clsVar.varInterface.pathTool = AppPath.Tool;
				clsVar.varInterface.pathToolHolder = AppPath.ToolHolder;
				clsFiles.SaveParameter();
			}
		}
		catch (Exception mSException)
		{
			buLog.addLog("", "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: true, "");
		}
	}

	public void cmdToolCopy()
	{
		try
		{
			if (ccVars.Pages.Count <= 0 || !((ccVars.ToolGroupIndex >= 0) & (ccVars.ToolGroupIndex <= ccVars.Tools.Count - 1)))
			{
				return;
			}
			if (!((ccVars.ToolIndex >= 0) & (ccVars.ToolIndex <= ccVars.Tools[ccVars.ToolGroupIndex].Tools.Count - 1)))
			{
				if (ccVars.ToolIndex != -1)
				{
					return;
				}
				ToolGroup5 toolGroup = new ToolGroup5();
				toolGroup.GroupName = ccVars.Tools[ccVars.ToolGroupIndex].GroupName + " - Copy";
				if (buString.MessageBoxQuestionYesNoCancel(AppLanguage.CadCamMessages[75] + Environment.NewLine + Environment.NewLine + "[ " + AppLanguage.CadCamDynamic[69] + " =  " + toolGroup.GroupName + " ]") == DialogResult.Yes)
				{
					for (int i = 0; i <= ccVars.Tools[ccVars.ToolGroupIndex].Tools.Count - 1; i++)
					{
						ToolBase5 item = new ToolBase5(ccVars.Tools[ccVars.ToolGroupIndex].Tools[i]);
						toolGroup.Tools.Add(item);
					}
					ccVars.Tools.Add(toolGroup);
					ToolUpdate(FillTool: true, ccVars.ToolGroupIndex, ccVars.ToolIndex);
					DrawingPropertiesUpdate();
					clsFiles.SaveParameter();
				}
			}
			else
			{
				ToolBase5 toolBase = new ToolBase5(ccVars.Tools[ccVars.ToolGroupIndex].Tools[ccVars.ToolIndex]);
				if (buString.MessageBoxQuestionYesNoCancel(AppLanguage.CadCamMessages[12] + Environment.NewLine + Environment.NewLine + "[ " + AppLanguage.CadCamDynamic[25] + " =  " + toolBase.Data.Name + " ]") == DialogResult.Yes)
				{
					ToolBase5 toolBase2 = new ToolBase5(ccVars.Tools[ccVars.ToolGroupIndex].Tools[ccVars.ToolIndex]);
					toolBase2.Data.Name = toolBase2.Data.Name + " - Copy";
					ccVars.Tools[ccVars.ToolGroupIndex].Tools.Add(toolBase2);
					ToolUpdate(FillTool: true, ccVars.ToolGroupIndex, ccVars.ToolIndex);
					DrawingPropertiesUpdate();
					clsFiles.SaveParameter();
				}
			}
		}
		catch (Exception mSException)
		{
			buLog.addLog("", "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: true, "");
		}
	}

	public void cmdToolRemove()
	{
		try
		{
			if (ccVars.Pages.Count <= 0 || !((ccVars.Tools.Count >= 0) & (ccVars.ToolGroupIndex >= 0) & (ccVars.ToolGroupIndex <= ccVars.Tools.Count - 1)))
			{
				return;
			}
			if (!((ccVars.Tools[ccVars.ToolGroupIndex].Tools.Count > 0) & (ccVars.ToolIndex >= 0) & (ccVars.ToolIndex <= ccVars.Tools[ccVars.ToolGroupIndex].Tools.Count - 1)))
			{
				if (ccVars.ToolIndex != -1)
				{
					return;
				}
				if (ccVars.Tools.Count <= 1)
				{
					buString.MessageBoxWarning(AppLanguage.CadCamMessages[76]);
					return;
				}
				string groupName = ccVars.Tools[ccVars.ToolGroupIndex].GroupName;
				if (buString.MessageBoxQuestionYesNoCancel(AppLanguage.CadCamMessages[74] + Environment.NewLine + Environment.NewLine + "[ " + AppLanguage.CadCamDynamic[69] + " =  " + groupName + " ]") == DialogResult.Yes)
				{
					ccVars.Tools.RemoveAt(ccVars.ToolGroupIndex);
					if (ccVars.Tools.Count <= 0)
					{
						ccVars.ToolGroupIndex = -1;
					}
					if (ccVars.ToolGroupIndex >= ccVars.Tools.Count - 1)
					{
						ccVars.ToolGroupIndex = ccVars.Tools.Count - 1;
					}
					ToolUpdate(FillTool: true, ccVars.ToolGroupIndex, ccVars.ToolIndex);
					clsFiles.SaveParameter();
				}
				return;
			}
			ToolBase5 toolBase = new ToolBase5(ccVars.Tools[ccVars.ToolGroupIndex].Tools[ccVars.ToolIndex]);
			if (buString.MessageBoxQuestionYesNoCancel(AppLanguage.CadCamMessages[10] + Environment.NewLine + Environment.NewLine + "[ " + AppLanguage.CadCamDynamic[25] + " =  " + toolBase.Data.Name + " ]") == DialogResult.Yes)
			{
				ccVars.Tools[ccVars.ToolGroupIndex].Tools.RemoveAt(ccVars.ToolIndex);
				if (ccVars.Tools[ccVars.ToolGroupIndex].Tools.Count <= 0)
				{
					ccVars.ToolIndex = -1;
				}
				if (ccVars.ToolIndex >= ccVars.Tools[ccVars.ToolGroupIndex].Tools.Count - 1)
				{
					ccVars.ToolIndex = ccVars.Tools[ccVars.ToolGroupIndex].Tools.Count - 1;
				}
				ToolUpdate(FillTool: true, ccVars.ToolGroupIndex, ccVars.ToolIndex);
				clsFiles.SaveParameter();
			}
		}
		catch (Exception mSException)
		{
			buLog.addLog("", "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: true, "");
		}
	}

