			if (ccVars.Pages.Count > 0 && ((ccVars.ToolGroupIndex >= 0) & (ccVars.ToolGroupIndex <= ccVars.Tools.Count - 1)) && ccVars.Tools[ccVars.ToolGroupIndex].Tools.Count >= 0 && buString.MessageBoxQuestionYesNoCancel(AppLanguage.CadCamMessages[11]) == DialogResult.Yes)
