	public void cmdToolMoveUp()
	{
		try
		{
			if (ccVars.Pages.Count <= 0)
			{
				return;
			}
			if (ccVars.ToolIndex != -1)
			{
				if ((ccVars.Tools[ccVars.ToolGroupIndex].Tools.Count >= 0) & (ccVars.ToolIndex > 0) & (ccVars.ToolIndex <= ccVars.Tools[ccVars.ToolGroupIndex].Tools.Count - 1))
				{
					ToolBase5 item = new ToolBase5(ccVars.Tools[ccVars.ToolGroupIndex].Tools[ccVars.ToolIndex]);
					ccVars.Tools[ccVars.ToolGroupIndex].Tools.RemoveAt(ccVars.ToolIndex);
					ccVars.ToolIndex--;
					ccVars.Tools[ccVars.ToolGroupIndex].Tools.Insert(ccVars.ToolIndex, item);
					if (!((clsItem.FrmToolList != null) & clsItem.FrmToolList.Visible))
					{
						ToolUpdate(FillTool: true, ccVars.ToolGroupIndex, ccVars.ToolIndex);
					}
					else
					{
						ToolUpdate(FillTool: true, ccVars.ToolGroupIndex, ccVars.ToolIndex, ref clsItem.FrmToolList.tree_tools);
					}
				}
			}
			else if ((ccVars.Tools.Count >= 0) & (ccVars.ToolGroupIndex > 0) & (ccVars.ToolGroupIndex <= ccVars.Tools.Count - 1))
			{
				ToolGroup5 item2 = new ToolGroup5(ccVars.Tools[ccVars.ToolGroupIndex]);
				ccVars.Tools.RemoveAt(ccVars.ToolGroupIndex);
				ccVars.ToolGroupIndex--;
				ccVars.Tools.Insert(ccVars.ToolGroupIndex, item2);
				if (!((clsItem.FrmToolList != null) & clsItem.FrmToolList.Visible))
				{
					ToolUpdate(FillTool: true, ccVars.ToolGroupIndex, ccVars.ToolIndex);
				}
				else
				{
					ToolUpdate(FillTool: true, ccVars.ToolGroupIndex, ccVars.ToolIndex, ref clsItem.FrmToolList.tree_tools);
				}
			}
		}
		catch (Exception mSException)
		{
			buLog.addLog("", "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: true, "");
		}
	}

	public void cmdToolMoveDown()
	{
		try
		{
			if (ccVars.Pages.Count <= 0)
			{
				return;
			}
			if (ccVars.ToolIndex != -1)
			{
				if ((ccVars.Tools[ccVars.ToolGroupIndex].Tools.Count >= 0) & (ccVars.ToolIndex <= ccVars.Tools[ccVars.ToolGroupIndex].Tools.Count - 2) & (ccVars.ToolIndex <= ccVars.Tools[ccVars.ToolGroupIndex].Tools.Count - 1))
				{
					ToolBase5 item = new ToolBase5(ccVars.Tools[ccVars.ToolGroupIndex].Tools[ccVars.ToolIndex]);
					ccVars.Tools[ccVars.ToolGroupIndex].Tools.RemoveAt(ccVars.ToolIndex);
					ccVars.ToolIndex++;
					ccVars.Tools[ccVars.ToolGroupIndex].Tools.Insert(ccVars.ToolIndex, item);
					if (!((clsItem.FrmToolList != null) & clsItem.FrmToolList.Visible))
					{
						ToolUpdate(FillTool: true, ccVars.ToolGroupIndex, ccVars.ToolIndex);
					}
					else
					{
						ToolUpdate(FillTool: true, ccVars.ToolGroupIndex, ccVars.ToolIndex, ref clsItem.FrmToolList.tree_tools);
					}
				}
			}
			else if ((ccVars.Tools.Count >= 0) & (ccVars.ToolGroupIndex <= ccVars.Tools.Count - 2) & (ccVars.ToolGroupIndex <= ccVars.Tools.Count - 1))
			{
				ToolGroup5 item2 = new ToolGroup5(ccVars.Tools[ccVars.ToolGroupIndex]);
				ccVars.Tools.RemoveAt(ccVars.ToolGroupIndex);
				ccVars.ToolGroupIndex++;
				ccVars.Tools.Insert(ccVars.ToolGroupIndex, item2);
				if (!((clsItem.FrmToolList != null) & clsItem.FrmToolList.Visible))
				{
					ToolUpdate(FillTool: true, ccVars.ToolGroupIndex, ccVars.ToolIndex);
				}
				else
				{
					ToolUpdate(FillTool: true, ccVars.ToolGroupIndex, ccVars.ToolIndex, ref clsItem.FrmToolList.tree_tools);
				}
			}
		}
		catch (Exception mSException)
		{
			buLog.addLog("", "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: true, "");
		}
	}

	public void cmdToolSort()
	{
		for (int i = 0; i <= ccVars.Tools.Count - 1; i++)
		{
			ccVars.Tools[i].Tools = ToolSortByNo(ccVars.Tools[i].Tools, SortDirection.LowerToBigger);
