			}
			if (clsItem.FrmToolList.Viewport == null)
			{
				EyeCreateProps eyeCreateProps = new EyeCreateProps();
				eyeCreateProps.ShowToolBar = false;
				eyeCreateProps.ShowViewCube = false;
				eyeCreateProps.ShowCoordinateArrow = false;
				eyeCreateProps.ShowOrigin = false;
				eyeCreateProps.ShowOriginCaption = false;
				eyeCreateProps.PanMouseButton.Button = mouseButtonsZPR.Middle;
				eyeCreateProps.PanMouseButton.ModifierKey = devDept.Eyeshot.Control.modifierKeys.None;
				eyeCreateProps.RotateMouseButton.Button = mouseButtonsZPR.Middle;
				eyeCreateProps.RotateMouseButton.ModifierKey = devDept.Eyeshot.Control.modifierKeys.Ctrl;
				eyeCreateProps.ZoomMouseButton.Button = mouseButtonsZPR.Middle;
				eyeCreateProps.ZoomMouseButton.ModifierKey = devDept.Eyeshot.Control.modifierKeys.Shift;
				clsItem.FrmToolList.Viewport = buEyeShotFunctions.CreateControlsTool(FirstCreate: true, eyeCreateProps);
				clsItem.FrmToolList.Viewport.Dock = DockStyle.Fill;
				clsItem.FrmToolList.pnl_viewport.Controls.Clear();
				clsItem.FrmToolList.pnl_viewport.Controls.Add(clsItem.FrmToolList.Viewport);
			}
			ToolUpdate(FillTool: true, ccVars.ToolGroupIndex, ccVars.ToolIndex, ref clsItem.FrmToolList.tree_tools);
			clsItem.FrmToolList.SelectedTool = new ToolBase5(ccVars.toolActive);
			clsItem.FrmToolList.SelectedIndex = ccVars.ToolIndex;
			int toolGroupIndex = ccVars.ToolGroupIndex;
			int toolIndex = ccVars.ToolIndex;
			clsItem.FrmToolList.PropertiesForm.FormCloseMode = FormCloseModeType.Invisible;
			clsItem.FrmToolList.ShowCommand = true;
			clsItem.FrmToolList.Init();
			clsItem.FrmToolList.ShowDialog();
			if (clsItem.FrmToolList.PropertiesForm.Result != DialogResult.OK)
			{
				ccVars.ToolGroupIndex = toolGroupIndex;
				ccVars.ToolIndex = toolIndex;
				ccVars.toolActive = new ToolBase5(ccVars.Tools[ccVars.ToolGroupIndex].Tools[ccVars.ToolIndex]);
				return false;
			}
			ccVars.ToolGroupIndex = 0;
			ccVars.ToolIndex = clsItem.FrmToolList.SelectedIndex;
			ccVars.toolActive = new ToolBase5(ccVars.Tools[ccVars.ToolGroupIndex].Tools[ccVars.ToolIndex]);
			clsFiles.SaveParameter();
			return true;
		}
		catch (Exception mSException)
		{
			buLog.addLog("", "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: true, "");
			return false;
		}
	}

