	public void DrawTool(ToolBase5 Tool, bool DrawArbor, bool DrawHolder, ref Design viewportLayout)
	{
		viewportLayout.Entities.Clear();
		List<Mesh> refMeshes = new List<Mesh>();
		viewportLayout.Viewports.Count.ToString();
		if (viewportLayout.Viewports.Count == 0)
		{
			CreateModelProperties createModelProperties = new CreateModelProperties();
			createModelProperties.CoordinateSystemIconVisible = false;
			createModelProperties.ViewCubeIconVisible = false;
			createModelProperties.OrigineCaptionVisible = true;
			createModelProperties.ToolBorVisible = false;
			clsInit.cVector5.CreateModelControl(ref viewportLayout, clsVar.UnlockKey, createModelProperties);
		}
		viewportLayout.ActiveViewport.CoordinateSystemIcon.Visible = false;
		if (Tool.Geometry.FromFileEnable)
		{
			FileInfo fileInfo = new FileInfo(Tool.Geometry.FromFileFileName);
			if (fileInfo.Exists)
			{
				ReadSTL readSTL = new ReadSTL(fileInfo.FullName);
				readSTL.DoWork();
				readSTL.OpenTo(viewportLayout);
				if (viewportLayout.Entities.Count > 0)
				{
					for (int i = 0; i <= viewportLayout.Entities.Count - 1; i++)
					{
						if (viewportLayout.Entities[i] is Mesh)
						{
							viewportLayout.Entities[i].ColorMethod = colorMethodType.byEntity;
							if (viewportLayout.Entities[i].Color == Color.Black)
							{
								viewportLayout.Entities[i].Color = Color.DarkGray;
							}
							viewportLayout.Entities[i].Rotate(buConversion5.DegreeToRadian(Tool.Geometry.FromFileAngle), new Vector3D(0.0, 0.0, 1.0));
						}
					}
					viewportLayout.Entities.Regen();
					viewportLayout.ActiveViewport.ViewCubeIcon.Visible = false;
					viewportLayout.ActiveViewport.Camera.ProjectionMode = projectionType.Orthographic;
					viewportLayout.SetView(viewType.Top, fit: true, animate: false);
					viewportLayout.ZoomOut(2);
				}
			}
		}
		else
		{
			if (clsInit.appMW != null)
			{
				if (Tool.Geometry.GeometryType != ToolType.Saw)
				{
					clsInit.appMW.CreateTool(Tool, ToolCut: true, Tool.Geometry.DrawLength, DrawArbor & Tool.Geometry.DrawArbor, DrawHolder & Tool.Geometry.DrawHolder, ref refMeshes);
				}
				else
				{
					clsInit.appMW.CreateTool(Tool, ToolCut: true, Tool.Geometry.DrawLength, Arbor: false, Holder: false, ref refMeshes);
				}
			}
			for (int j = 0; j <= refMeshes.Count - 1; j++)
			{
				if (refMeshes[j].Vertices.Length != 0)
				{
					viewportLayout.Entities.Add(refMeshes[j]);
				}
			}
			List<Entity> dimEntities = new List<Entity>();
			clsInit.cVector5.ToolDimensionEntities(Tool, ref dimEntities);
			for (int k = 0; k <= dimEntities.Count - 1; k++)
			{
				viewportLayout.Entities.Add(dimEntities[k]);
			}
			if (Tool.Geometry.GeometryType != ToolType.Saw)
			{
				viewportLayout.SetView(viewType.Front, fit: true, animate: false);
				viewportLayout.ZoomOut(2);
			}
			else
			{
				viewportLayout.SetView(viewType.Front, fit: true, animate: false);
				viewportLayout.ZoomOut(2);
			}
		}
		viewportLayout.Invalidate();
	}

	public void DrawTool(ToolBase5 Tool, bool DrawArbor, bool DrawHolder, ref List<Mesh> ToolMeshes)
	{
		ToolMeshes = new List<Mesh>();
		if (!Tool.Geometry.FromFileEnable)
		{
			if (Tool.Geometry.GeometryType != ToolType.Saw)
			{
				clsInit.appMW.CreateTool(Tool, ToolCut: true, Tool.Geometry.DrawLength, DrawArbor & Tool.Geometry.DrawArbor, DrawHolder & Tool.Geometry.DrawHolder, ref ToolMeshes);
			}
			else
			{
				clsInit.appMW.CreateTool(Tool, ToolCut: true, Tool.Geometry.DrawLength, Arbor: false, Holder: false, ref ToolMeshes);
			}
		}
	}

	public void ToolUpdate(bool FillTool, int SelectedGroupIndex, int SelectedIndex)
	{
		try
		{
			ToolUpdating = true;
			if (clsItem.FrmTempTools != null)
			{
				if (!FillTool)
				{
					for (int i = 0; i <= ccVars.Tools.Count - 1; i++)
					{
						clsItem.FrmTempTools.tree_tools.Nodes[i].Text = ccVars.Tools[i].GroupName;
						for (int j = 0; j <= ccVars.Tools[i].Tools.Count - 1; j++)
						{
							if (j <= clsItem.FrmTempTools.tree_tools.Nodes[i].Nodes.Count - 1)
							{
								clsItem.FrmTempTools.tree_tools.Nodes[i].Nodes[j].Text = ToolToName(ccVars.Tools[i].Tools[j]);
							}
						}
					}
				}
				else
				{
					clsItem.FrmTempTools.tree_tools.Nodes.Clear();
					TreeNodeSettings treeNodeSettings = null;
					TreeNodeSettings treeNodeSettings2 = null;
					for (int k = 0; k <= ccVars.Tools.Count - 1; k++)
					{
						treeNodeSettings = new TreeNodeSettings(ccVars.Tools[k].GroupName)
						{
							ImageIndex = 13,
							SelectedImageIndex = 13,
							Tag = k.ToString(),
							ClassIndex = k,
							ClassSubIndex = -1,
							ClassSubSubIndex = -1,
							Command = "toolgroup",
							Checked = true
						};
						for (int l = 0; l <= ccVars.Tools[k].Tools.Count - 1; l++)
						{
							treeNodeSettings2 = new TreeNodeSettings(ToolToName(ccVars.Tools[k].Tools[l]))
							{
								ImageIndex = Convert.ToInt32(ccVars.Tools[k].Tools[l].Geometry.GeometryType),
								SelectedImageIndex = Convert.ToInt32(ccVars.Tools[k].Tools[l].Geometry.GeometryType),
								Tag = l.ToString(),
								ClassIndex = k,
								ClassSubIndex = l,
								ClassSubSubIndex = -1,
								Command = "tool",
								Checked = true
							};
							treeNodeSettings.Nodes.Add(treeNodeSettings2);
						}
						if (treeNodeSettings != null)
						{
							clsItem.FrmTempTools.tree_tools.Nodes.Add(treeNodeSettings);
						}
					}
				}
				clsItem.FrmTempTools.tree_tools.ExpandAll();
				for (int m = 0; m <= ccVars.ToolGroupIndex - 1; m++)
				{
					clsItem.FrmTempTools.tree_tools.Nodes[m].ForeColor = Color.Black;
					for (int n = 0; n <= clsItem.FrmTempTools.tree_tools.Nodes[m].Nodes.Count - 1; n++)
					{
						clsItem.FrmTempTools.tree_tools.Nodes[m].Nodes[n].ForeColor = Color.Black;
					}
				}
				for (int num = ccVars.ToolGroupIndex + 1; num <= clsItem.FrmTempTools.tree_tools.Nodes.Count - 1; num++)
				{
					clsItem.FrmTempTools.tree_tools.Nodes[num].ForeColor = Color.Black;
					for (int num2 = 0; num2 <= clsItem.FrmTempTools.tree_tools.Nodes[num].Nodes.Count - 1; num2++)
					{
						clsItem.FrmTempTools.tree_tools.Nodes[num].Nodes[num2].ForeColor = Color.Black;
					}
				}
				clsItem.FrmTempTools.tree_tools.Nodes[ccVars.ToolGroupIndex].ForeColor = Color.Black;
				for (int num3 = 0; num3 <= clsItem.FrmTempTools.tree_tools.Nodes[ccVars.ToolGroupIndex].Nodes.Count - 1; num3++)
				{
					if (num3 != ccVars.ToolIndex)
					{
						clsItem.FrmTempTools.tree_tools.Nodes[ccVars.ToolGroupIndex].Nodes[num3].ForeColor = Color.Black;
					}
					else
					{
						clsItem.FrmTempTools.tree_tools.Nodes[ccVars.ToolGroupIndex].Nodes[num3].ForeColor = Color.Red;
					}
				}
			}
			ToolUpdating = false;
			if (clsInit.appMarble != null)
			{
				clsInit.appMarble.doToolUpdate(SelectedGroupIndex, SelectedIndex);
			}
		}
		catch (Exception mSException)
		{
			ToolUpdating = false;
			buLog.addLog("", "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: true, "");
		}
	}

	public void ToolUpdate(bool FillTool, int SelectedGroupIndex, int SelectedIndex, ref TreeView Tree)
	{
