			{
				if (ccVars.Tools.Count <= 1)
				{
					if (ccVars.Tools.Count == 1)
					{
						for (int i = 0; i <= ccVars.Tools[0].Tools.Count - 1; i++)
						{
							Tree.Nodes[i].Text = ToolToName(ccVars.Tools[0].Tools[i]);
						}
