				}
				else
				{
					for (int j = 0; j <= ccVars.Tools.Count - 1; j++)
					{
						Tree.Nodes[j].Text = ccVars.Tools[j].GroupName;
						for (int k = 0; k <= ccVars.Tools[j].Tools.Count - 1; k++)
						{
							Tree.Nodes[j].Nodes[k].Text = ToolToName(ccVars.Tools[j].Tools[k]);
						}
					}
				}
			}
			else
			{
				Tree.Nodes.Clear();
