								Tag = l.ToString(),
								ClassIndex = 0,
								ClassSubIndex = l,
								ClassSubSubIndex = -1,
								Command = "tool",
								Checked = true
							};
							Tree.Nodes.Add(treeNodeSettings2);
						}
					}
				}
				else
				{
					for (int m = 0; m <= ccVars.Tools.Count - 1; m++)
