							Tree.Nodes.Add(treeNodeSettings);
						}
					}
				}
			}
			Tree.ExpandAll();
			if (ccVars.Tools.Count <= 1)
			{
				if (ccVars.Tools.Count == 1)
				{
					for (int num = 0; num <= Tree.Nodes[0].Nodes.Count - 1; num++)
