	public void Tool_AfterSelect(object sender, TreeViewEventArgs e)
	{
		TreeNodeSettings treeNodeSettings = (TreeNodeSettings)e.Node;
		if (clsItem.FrmToolList != null && clsItem.FrmToolList.Visible)
		{
			clsItem.FrmToolList.Viewport.Entities.Clear();
			if ((treeNodeSettings.ClassIndex >= 0) & (treeNodeSettings.ClassIndex <= ccVars.Tools.Count - 1))
			{
				ccVars.ToolGroupIndex = treeNodeSettings.ClassIndex;
				if (!((treeNodeSettings.ClassSubIndex >= 0) & (treeNodeSettings.ClassSubIndex <= ccVars.Tools[treeNodeSettings.ClassIndex].Tools.Count - 1)))
				{
					if (treeNodeSettings.ClassSubIndex == -1)
					{
						ccVars.ToolIndex = -1;
						clsItem.FrmToolList.SelectedIndex = treeNodeSettings.ClassSubIndex;
					}
				}
				else
				{
					ccVars.ToolIndex = treeNodeSettings.ClassSubIndex;
					ccVars.ToolGroupIndex = treeNodeSettings.ClassIndex;
					clsItem.FrmToolList.SelectedIndex = treeNodeSettings.ClassSubIndex;
					clsVar.varInterface.ToolIndex = ccVars.ToolIndex;
					clsVar.varInterface.ToolGroupIndex = ccVars.ToolGroupIndex;
					ccVars.toolActive = new ToolBase5(ccVars.Tools[ccVars.ToolGroupIndex].Tools[ccVars.ToolIndex]);
					clsItem.FrmToolList.txt_detail.Text = ToolInfo(ccVars.toolActive, clsVar.varProgram.ToolPanelSettings);
					ToolUpdate(FillTool: false, ccVars.ToolGroupIndex, ccVars.ToolIndex, ref clsItem.FrmToolList.tree_tools);
					DrawTool(ccVars.toolActive, clsVar.varDisplay.ToolPreviewDrawArbor, clsVar.varDisplay.ToolPreviewDrawHolder, ref clsItem.FrmToolList.Viewport);
				}
				clsItem.FrmToolList.Viewport.Invalidate();
				return;
			}
		}
		if (!((treeNodeSettings.ClassIndex >= 0) & (treeNodeSettings.ClassIndex <= ccVars.Tools.Count - 1)))
		{
			return;
		}
		ccVars.ToolGroupIndex = treeNodeSettings.ClassIndex;
		if (!((treeNodeSettings.ClassSubIndex >= 0) & (treeNodeSettings.ClassSubIndex <= ccVars.Tools[treeNodeSettings.ClassIndex].Tools.Count - 1)))
		{
			if (treeNodeSettings.ClassSubIndex == -1)
			{
				ccVars.ToolIndex = -1;
			}
			return;
		}
		ccVars.ToolIndex = treeNodeSettings.ClassSubIndex;
		ccVars.ToolGroupIndex = treeNodeSettings.ClassIndex;
		clsVar.varInterface.ToolIndex = ccVars.ToolIndex;
		clsVar.varInterface.ToolGroupIndex = ccVars.ToolGroupIndex;
		ccVars.toolActive = new ToolBase5(ccVars.Tools[ccVars.ToolGroupIndex].Tools[ccVars.ToolIndex]);
		if (clsItem.FrmTempTools != null)
		{
			clsItem.FrmTempTools.txt_toolexplanatiom.Text = ToolInfo(ccVars.toolActive, clsVar.varProgram.ToolPanelSettings);
		}
		ToolUpdate(FillTool: false, ccVars.ToolGroupIndex, ccVars.ToolIndex);
		DrawTool(ccVars.toolActive, clsVar.varDisplay.ToolPreviewDrawArbor, clsVar.varDisplay.ToolPreviewDrawHolder, ref clsItem.ModelToolPreview);
		if (clsInit.appMarble != null)
		{
			clsInit.appMarble.doToolSelected(ccVars.toolActive);
		}
	}

