	public string ToolInfo(ToolBase5 tool, ToolPanelSetting Settings)
	{
		string text = "";
		text = text + "T" + tool.Data.No;
		if (Settings.ShowToolName)
		{
			text = text + " - " + AppLanguage.CadCamDynamic[40] + " : " + tool.Data.Name + Environment.NewLine;
		}
		if (Settings.ShowToolType)
		{
			text = text + AppLanguage.CadCamDynamic[84] + " : " + tool.Geometry.GeometryType.ToString() + Environment.NewLine;
		}
		if (Settings.ShowDiameter)
		{
			text = text + AppLanguage.CadCamDynamic[57] + " : " + tool.Geometry.Diameter + Environment.NewLine;
		}
		if (Settings.ShowLength)
		{
			text = text + AppLanguage.CadCamDynamic[0] + " : " + tool.Geometry.Length + Environment.NewLine;
		}
		if (Settings.ShowPurpose)
		{
			text = text + AppLanguage.CadCamDynamic[86] + " : " + tool.Purpose.ToString() + Environment.NewLine;
		}
		if (Settings.ShowSpindleSpeed)
		{
			text = text + AppLanguage.CadCamDynamic[87] + " : " + tool.CamData.SpindleSpeed + Environment.NewLine;
		}
		if (Settings.ShowFeed)
		{
			text = text + AppLanguage.CadCamDynamic[88] + " : " + tool.CamData.FeedSpeed + Environment.NewLine;
		}
		if (Settings.ShowSafeDistance)
		{
			text = text + AppLanguage.CadCamDynamic[89] + " : " + tool.CamData.SafeDistance + Environment.NewLine;
		}
		return text;
	}

	public List<ToolBase5> ToolSortByNo(List<ToolBase5> lst, SortDirection Direction)
	{
		List<ToolBase5> list = new List<ToolBase5>();
		if (lst.Count > 0)
		{
			ToolBase5 toolBase = new ToolBase5();
			toolBase.Data.No = 0;
			list.Add(lst[NearestToolNo(toolBase, lst)]);
			lst.Remove(list[0]);
			int num = 0;
			for (int i = 0; i < lst.Count + num; i++)
			{
				list.Add(lst[NearestToolNo(list[list.Count - 1], lst)]);
				lst.Remove(list[list.Count - 1]);
				num++;
			}
			if (Direction == SortDirection.LowerToBigger)
			{
				list.Reverse();
			}
		}
		return list;
	}

	public int NearestToolNo(ToolBase5 srcPt, List<ToolBase5> lookIn)
	{
		KeyValuePair<int, int> keyValuePair = default(KeyValuePair<int, int>);
		for (int i = 0; i < lookIn.Count; i++)
		{
			int num = srcPt.Data.No - lookIn[i].Data.No;
			if (i != 0)
			{
				if (num < keyValuePair.Key)
				{
					keyValuePair = new KeyValuePair<int, int>(num, i);
				}
			}
			else
			{
				keyValuePair = new KeyValuePair<int, int>(num, i);
			}
		}
		return keyValuePair.Value;
	}

	public void cmdToolProperties()
	{
		try
		{
			if (!((ccVars.ToolIndex >= 0) & (ccVars.ToolGroupIndex >= 0)))
			{
				return;
			}
			ToolBase5 tool = new ToolBase5(ccVars.toolActive);
			clsItem.FrmTool = new F_Tool();
			CreateModelProperties createModelProperties = new CreateModelProperties();
			createModelProperties.CoordinateSystemIconVisible = false;
			createModelProperties.ViewCubeIconVisible = false;
			createModelProperties.OrigineCaptionVisible = false;
			createModelProperties.ToolBorVisible = false;
			clsInit.cVector5.CreateModelControl(ref clsItem.FrmTool.viewportLayout, clsVar.UnlockKey, createModelProperties);
			clsItem.FrmTool.viewportLayout.Entities.Clear();
			clsItem.FrmTool.Properties.FormCloseMode = FormCloseModeType.Invisible;
			clsItem.FrmTool.Tool = new ToolBase5(tool);
			clsItem.FrmTool.Init();
			clsItem.FrmTool.StartPosition = FormStartPosition.CenterParent;
			clsItem.FrmTool.ShowDialog();
			if (clsItem.FrmTool.Properties.Result == DialogResult.OK)
			{
				ccVars.Tools[ccVars.ToolGroupIndex].Tools[ccVars.ToolIndex] = new ToolBase5(clsItem.FrmTool.Tool);
				ccVars.toolActive = new ToolBase5(clsItem.FrmTool.Tool);
				ToolUpdate(FillTool: false, ccVars.ToolGroupIndex, ccVars.ToolIndex);
				if (ccVars.Pages.Count > 0)
				{
					DrawingPropertiesUpdate();
				}
				if (clsInit.appMarble != null)
				{
					clsInit.appMarble.doToolUpdate(ccVars.ToolGroupIndex, ccVars.ToolIndex);
				}
				clsVar.varInterface.pathTool = AppPath.Tool;
				clsVar.varInterface.pathToolHolder = AppPath.ToolHolder;
				clsFiles.SaveParameter();
			}
		}
		catch (Exception mSException)
		{
			buLog.addLog("", "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: true, "");
		}
	}

