	public void GetToolIndexWithToolName(ToolBase5 refTool, ref int ToolGroupIndex, ref int ToolIndex)
	{
		for (int i = 0; i <= ccVars.Tools.Count - 1; i++)
		{
			for (int j = 0; j <= ccVars.Tools[i].Tools.Count - 1; j++)
			{
				if (refTool.Data.Name == ccVars.Tools[i].Tools[j].Data.Name)
				{
					ToolGroupIndex = i;
					ToolIndex = j;
					return;
				}
			}
		}
	}

