	public void cmdFilePagePreview()
	{
		if (clsItem.FrmPreview == null)
		{
			clsItem.FrmPreview = new F_Preview();
			CreateModelProperties Properties = new CreateModelProperties();
			EyeParameterToCreateModelProperties(clsVar.varPreviewViewport, clsVar.varMouse, ref Properties);
			clsInit.cVector5.CreateModelControl(ref clsItem.FrmPreview.viewportLayout, clsVar.UnlockKey, Properties);
			clsItem.FrmPreview.Controls.Add(clsItem.FrmPreview.viewportLayout);
		}
		clsItem.FrmPreview.viewportLayout.Entities.Clear();
		clsItem.FrmPreview.viewportLayout.Layers = buConversion5.CopyEyeLayerToEyeLayer(ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Layers);
		for (int num = clsItem.FrmPreview.viewportLayout.Blocks.Count - 1; num >= 1; num--)
		{
			clsItem.FrmPreview.viewportLayout.Blocks.RemoveAt(num);
		}
		clsItem.FrmPreview.viewportLayout.Blocks.AddRange(clsInit.cVector5.CopyEyeBlockToEyeBlock(clsItem.FrmPreview.viewportLayout.Blocks, ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Blocks));
		if (ccVars.SelectedPageItem.Mode != PageModes.Scene)
		{
			if (ccVars.SelectedPageItem.Mode != PageModes.BlockItem)
			{
				if (ccVars.SelectedPageItem.Mode == PageModes.EntityItem)
				{
					int entityIndex = ccVars.SelectedPageItem.EntityIndex;
					if ((entityIndex >= 0) & (entityIndex <= ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Count - 1))
					{
						_ = (Entity)ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[entityIndex].Clone();
						Line line = new Line(new Point3D(), new Point3D(100.0, 100.0, 0.0));
						line.Color = Color.Red;
						line.ColorMethod = colorMethodType.byEntity;
						line.LineWeightMethod = colorMethodType.byEntity;
						line.LineWeight = 2f;
						clsItem.FrmPreview.viewportLayout.Entities.Add(line);
					}
				}
			}
			else
			{
				string blockName = ccVars.SelectedPageItem.BlockName;
				for (int i = 0; i <= ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Blocks.Count - 1; i++)
				{
					if (blockName == ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Blocks[i].Name)
					{
						for (int j = 0; j <= ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Blocks[i].Entities.Count - 1; j++)
						{
							Entity item = (Entity)ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Blocks[i].Entities[j].Clone();
							clsItem.FrmPreview.viewportLayout.Entities.Add(item);
						}
					}
				}
			}
		}
		else
		{
			string sceneName = ccVars.Pages[ccVars.PageIndex].Scene[ccVars.Pages[ccVars.PageIndex].SceneIndex].SceneName;
			for (int k = 0; k <= ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Count - 1; k++)
			{
				string sceneName2 = clsInit.cVector5.GetSceneName(ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[k]);
				if (!(sceneName == sceneName2))
				{
					if (sceneName2.Length == 0)
					{
						Entity item2 = (Entity)ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[k].Clone();
						clsItem.FrmPreview.viewportLayout.Entities.Add(item2);
					}
				}
				else
				{
					Entity item3 = (Entity)ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[k].Clone();
					clsItem.FrmPreview.viewportLayout.Entities.Add(item3);
				}
			}
		}
		clsItem.FrmPreview.Init(viewType.Trimetric, zoomFit: true, zoomAnimation: true);
		clsItem.FrmPreview.Show();
	}

