	public void PagesUpdate(bool FillPages, string Command)
	{
		try
		{
			if (clsItem.FrmTempPages == null)
			{
				return;
			}
			PageUpdating = true;
			if (ccVars.Pages.Count != clsItem.FrmTempPages.tree_pages.Nodes.Count)
			{
				FillPages = true;
			}
			string text = AppLanguage.CadCamDynamic[109];
			string nodeText = AppLanguage.CadCamDynamic[108];
			string text2 = AppLanguage.CadCamDynamic[107] + " - ";
			string nodeText2 = AppLanguage.CadCamDynamic[106];
			_ = AppLanguage.CadCamDynamic[112];
			if (!FillPages)
			{
				for (int i = 0; i <= ccVars.Pages.Count - 1; i++)
				{
					clsItem.FrmTempPages.tree_pages.Nodes[i].Text = ccVars.Pages[i].PageName;
					for (int j = 0; j <= ccVars.Pages[i].Scene.Count - 1; j++)
					{
						clsItem.FrmTempPages.tree_pages.Nodes[i].Nodes[j].Text = ccVars.Pages[i].Scene[j].SceneName;
						if (!ccVars.Pages[i].Scene[j].Visible)
						{
							clsItem.FrmTempPages.tree_pages.Nodes[i].Nodes[j].ImageIndex = 6;
							clsItem.FrmTempPages.tree_pages.Nodes[i].Nodes[j].SelectedImageIndex = 6;
						}
						else
						{
							clsItem.FrmTempPages.tree_pages.Nodes[i].Nodes[j].ImageIndex = 1;
							clsItem.FrmTempPages.tree_pages.Nodes[i].Nodes[j].SelectedImageIndex = 1;
						}
						clsItem.FrmTempPages.tree_pages.Nodes[i].Nodes[j].Nodes[0].Text = buVector5.PlaneToString(ccVars.Pages[i].Scene[j].ScenePlane);
						clsItem.FrmTempPages.tree_pages.Nodes[i].Nodes[j].Nodes[1].Text = text + " [" + ccVars.Pages[i].Scene[j].EntitiesCount + "]";
						int num = 0;
						clsItem.FrmTempPages.tree_pages.Nodes[i].Nodes[j].Nodes[2].Nodes.Clear();
						for (int k = 0; k <= ccVars.Pages[i].Cams.Count - 1; k++)
						{
