	public void Pages_Click(object sender, EventArgs e)
	{
		if (!AppBool.ShiftKeyPressed || clsItem.FrmTempPages.tree_pages.SelectedNode == null)
		{
			return;
		}
		TreeNodeSettings treeNodeSettings = new TreeNodeSettings();
		treeNodeSettings = (TreeNodeSettings)clsItem.FrmTempPages.tree_pages.SelectedNode;
		if (((treeNodeSettings.ClassIndex == ccVars.PageIndex) & (treeNodeSettings.ClassSubIndex == ccVars.Pages[ccVars.PageIndex].SceneIndex)) && ((ccVars.Pages[ccVars.PageIndex].SceneIndex >= 0) & (ccVars.Pages[ccVars.PageIndex].SceneIndex <= ccVars.Pages[ccVars.PageIndex].Scene.Count - 1)))
		{
			if (!ccVars.Pages[ccVars.PageIndex].Scene[ccVars.Pages[ccVars.PageIndex].SceneIndex].Visible)
			{
				ccVars.Pages[ccVars.PageIndex].Scene[ccVars.Pages[ccVars.PageIndex].SceneIndex].Visible = true;
				clsItem.FrmTempPages.tree_pages.Nodes[treeNodeSettings.ClassIndex].Nodes[treeNodeSettings.ClassSubIndex].ImageIndex = 1;
				clsItem.FrmTempPages.tree_pages.Nodes[treeNodeSettings.ClassIndex].Nodes[treeNodeSettings.ClassSubIndex].SelectedImageIndex = 1;
				clsInit.appCommand.DrawingPropertiesUpdate();
			}
			else
			{
				ccVars.Pages[ccVars.PageIndex].Scene[ccVars.Pages[ccVars.PageIndex].SceneIndex].Visible = false;
