	public void PageInfo(Pages page, PagePanelSetting Settings)
	{
		if (clsItem.FrmTempPages != null)
		{
			clsItem.FrmTempPages.txt_pageexplanatiom.Text = "";
			if (Settings.ShowPageName)
			{
				clsItem.FrmTempPages.txt_pageexplanatiom.Text = clsItem.FrmTempPages.txt_pageexplanatiom.Text + AppLanguage.CadCamDynamic[37] + " " + AppLanguage.CadCamDynamic[40] + " : " + page.PageName + Environment.NewLine;
			}
			if (Settings.ShowSceneName)
			{
				clsItem.FrmTempPages.txt_pageexplanatiom.Text = clsItem.FrmTempPages.txt_pageexplanatiom.Text + AppLanguage.CadCamDynamic[38] + " " + AppLanguage.CadCamDynamic[40] + " : " + page.SceneName + Environment.NewLine;
			}
			if (Settings.ShowEntityCount)
			{
				clsItem.FrmTempPages.txt_pageexplanatiom.Text = clsItem.FrmTempPages.txt_pageexplanatiom.Text + AppLanguage.CadCamDynamic[90] + " : " + page.Form.viewportcad.Entities.Count + Environment.NewLine;
			}
			if (Settings.ShowPlane)
			{
				WorkPlane workPlane = buVector5.PlaneToWorkPlane(page.Scene[page.SceneIndex].ScenePlane);
				clsItem.FrmTempPages.txt_pageexplanatiom.Text = clsItem.FrmTempPages.txt_pageexplanatiom.Text + AppLanguage.CadCamDynamic[43] + " : " + workPlane.PlaneName.ToString() + Environment.NewLine;
			}
		}
	}

	public void SceneGetByName(List<PageScene> Scenes, string SceneName, ref PageScene FoundScene)
	{
		FoundScene = null;
		for (int i = 0; i <= Scenes.Count - 1; i++)
		{
			if (Scenes[i].SceneName == SceneName)
			{
				FoundScene = new PageScene(Scenes[i]);
			}
		}
	}

	public Plane GetPlaneFromSceneName(string sceneName)
	{
		for (int i = 0; i <= ccVars.Pages[ccVars.PageIndex].Scene.Count - 1; i++)
		{
			if (ccVars.Pages[ccVars.PageIndex].Scene[i].SceneName == sceneName)
			{
				return ccVars.Pages[ccVars.PageIndex].Scene[i].ScenePlane;
			}
		}
		return Plane.XY;
	}

	public void SetViewAccordingToPlane(Plane plane)
	{
		if (!buVector5.isPlaneXY(plane))
		{
			if (!buVector5.isPlaneYX(plane))
			{
				if (!buVector5.isPlaneXZ(plane))
				{
					if (!buVector5.isPlaneZX(plane))
					{
						if (!buVector5.isPlaneYZ(plane))
						{
							if (!buVector5.isPlaneZY(plane))
							{
								ccVars.Pages[ccVars.PageIndex].Form.viewportcad.SetView(viewType.Top);
								ccVars.Pages[ccVars.PageIndex].Form.viewportcad.SetView(ccVars.Pages[ccVars.PageIndex].Scene[ccVars.Pages[ccVars.PageIndex].SceneIndex].ScenePlane.AxisZ, fit: false);
								ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Invalidate();
							}
							else
							{
								cmdViewLeft(ZoomFit: false, AtPlane: false);
							}
						}
						else
						{
							cmdViewRight(ZoomFit: false, AtPlane: false);
						}
					}
					else
					{
						cmdViewRear(ZoomFit: false, AtPlane: false);
					}
				}
				else
				{
					cmdViewFront(ZoomFit: false, AtPlane: false);
				}
			}
			else
			{
				cmdViewBottom(ZoomFit: false, AtPlane: false);
			}
		}
		else
		{
			cmdViewTop(ZoomFit: false, AtPlane: false);
		}
	}

