	public void cmdLayerRemove()
	{
		try
		{
			if (ccVars.Pages.Count <= 0 || !((ccVars.Pages[ccVars.PageIndex].Layers.Count >= 0) & (ccVars.Pages[ccVars.PageIndex].LayerIndex >= 0) & (ccVars.Pages[ccVars.PageIndex].LayerIndex <= ccVars.Pages[ccVars.PageIndex].Layers.Count - 1)))
			{
				return;
			}
			LayerBase5 layerBase = new LayerBase5(ccVars.Pages[ccVars.PageIndex].Layers[ccVars.Pages[ccVars.PageIndex].LayerIndex]);
			if (ccVars.Pages[ccVars.PageIndex].Layers.Count != 1)
			{
				if (buString.MessageBoxQuestionYesNoCancel(AppLanguage.CadCamMessages[0] + Environment.NewLine + Environment.NewLine + "[ " + AppLanguage.CadCamDynamic[24] + " =  " + layerBase.Name + " ]") != DialogResult.Yes)
				{
					return;
				}
				bool flag = false;
				for (int i = 0; i <= ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Count - 1; i++)
				{
					if (ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[i].LayerName == ccVars.Pages[ccVars.PageIndex].Layers[ccVars.Pages[ccVars.PageIndex].LayerIndex].Name)
					{
						flag = true;
						i = 2147483645;
					}
				}
				if (!flag)
				{
					LayerDelete(ccVars.Pages[ccVars.PageIndex].LayerIndex, DeleteEntities: false);
					ccVars.Pages[ccVars.PageIndex].LayerIndex--;
					if (ccVars.Pages[ccVars.PageIndex].LayerIndex < 0)
					{
						ccVars.Pages[ccVars.PageIndex].LayerIndex = 0;
					}
					if (ccVars.Pages[ccVars.PageIndex].LayerIndex > ccVars.Pages[ccVars.PageIndex].Layers.Count - 1)
					{
						ccVars.Pages[ccVars.PageIndex].LayerIndex = ccVars.Pages[ccVars.PageIndex].Layers.Count - 1;
					}
					LayersUpdate(ccVars.Pages[ccVars.PageIndex].Layers, FillLayer: true, ccVars.Pages[ccVars.PageIndex].LayerIndex);
				}
				else if (buString.MessageBoxQuestionYesNoCancel(AppLanguage.CadCamMessages[1] + Environment.NewLine + Environment.NewLine + "[ " + AppLanguage.CadCamDynamic[24] + " =  " + layerBase.Name + " ]") == DialogResult.Yes)
				{
					LayerDelete(ccVars.Pages[ccVars.PageIndex].LayerIndex, DeleteEntities: true);
					ccVars.Pages[ccVars.PageIndex].LayerIndex--;
					if (ccVars.Pages[ccVars.PageIndex].LayerIndex < 0)
					{
						ccVars.Pages[ccVars.PageIndex].LayerIndex = 0;
					}
					if (ccVars.Pages[ccVars.PageIndex].LayerIndex > ccVars.Pages[ccVars.PageIndex].Layers.Count - 1)
					{
						ccVars.Pages[ccVars.PageIndex].LayerIndex = ccVars.Pages[ccVars.PageIndex].Layers.Count - 1;
					}
					LayersUpdate(ccVars.Pages[ccVars.PageIndex].Layers, FillLayer: true, ccVars.Pages[ccVars.PageIndex].LayerIndex);
				}
			}
			else
			{
				buString.MessageBoxInfo(AppLanguage.CadCamMessages[2] + Environment.NewLine + Environment.NewLine + "[ " + AppLanguage.CadCamDynamic[24] + " =  " + layerBase.Name + " ]");
			}
		}
		catch (Exception mSException)
		{
			buLog.addLog("", "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: true, "");
		}
