	public void cmdLayerHideUnused()
	{
		List<string> list = new List<string>();
		for (int i = 0; i <= ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Count - 1; i++)
		{
			if (list.Count != 0)
			{
				if (ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[i].LayerName.Length <= 0)
				{
					continue;
				}
				bool flag = true;
				for (int j = 0; j <= list.Count - 1; j++)
				{
					if (ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[i].LayerName == list[j])
					{
						flag = false;
					}
				}
				if (flag)
				{
					list.Add(ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[i].LayerName);
				}
			}
			else if (ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[i].LayerName.Length > 0)
			{
				list.Add(ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[i].LayerName);
			}
		}
		LayerHideUnused(list);
	}

