	public void SelectedEntitiesToLayerByName(string LayerName)
	{
		int num = -1;
		for (int i = 0; i <= ccVars.Pages[ccVars.PageIndex].Layers.Count - 1; i++)
		{
			if (ccVars.Pages[ccVars.PageIndex].Layers[i].Name.Trim() == LayerName.Trim())
			{
				num = i;
			}
		}
		if ((num >= 0) & (num <= ccVars.Pages[ccVars.PageIndex].Layers.Count - 1))
		{
			for (int j = 0; j <= ccVars.SelectionOP.Selections.Count - 1; j++)
			{
				int index = ccVars.SelectionOP.Selections[j].Index;
				ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index].ColorMethod = colorMethodType.byLayer;
				ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index].LineWeightMethod = colorMethodType.byLayer;
				ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index].LineTypeMethod = colorMethodType.byLayer;
				ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index].LayerName = ccVars.Pages[ccVars.PageIndex].Layers[num].Name;
			}
		}
		Reset(ClearSelection: true, ReDraw: true);
	}

