	public void EntitiesToLayer()
	{
		if (ccVars.Pages.Count <= 0)
		{
			return;
		}
		Reset(ClearSelection: false);
		if (ccVars.SelectionOP.Selections.Count <= 0)
		{
			return;
		}
		DialogBoxList dialogBoxList = new DialogBoxList();
		for (int i = 0; i <= ccVars.Pages[ccVars.PageIndex].Layers.Count - 1; i++)
		{
			LayerBase5 layerBase = new LayerBase5(ccVars.Pages[ccVars.PageIndex].Layers[i]);
			List<string> items = dialogBoxList.Items;
			string[] obj = new string[6]
			{
				"[",
				(i + 1).ToString(),
				"] ",
				layerBase.Name,
				" - ",
				null
			};
			Color layerColor = layerBase.LayerColor;
			obj[5] = layerColor.ToString();
			items.Add(string.Concat(obj));
		}
		dialogBoxList.Init();
		dialogBoxList.ShowDialog();
		if (dialogBoxList.Result != DialogResult.OK)
		{
			return;
		}
		for (int j = 0; j <= ccVars.SelectionOP.Selections.Count - 1; j++)
		{
			int index = ccVars.SelectionOP.Selections[j].Index;
			if ((dialogBoxList.SelectedIndex >= 0) & (dialogBoxList.SelectedIndex <= ccVars.Pages[ccVars.PageIndex].Layers.Count - 1))
			{
				ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index].ColorMethod = colorMethodType.byLayer;
				ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index].LineWeightMethod = colorMethodType.byLayer;
				ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index].LineTypeMethod = colorMethodType.byLayer;
				ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index].LayerName = ccVars.Pages[ccVars.PageIndex].Layers[dialogBoxList.SelectedIndex].Name;
			}
		}
		Reset(ClearSelection: true, ReDraw: true);
	}

