	public void LayerCreate(LayerBase5 Layer)
	{
		if (clsVar.appModes_0.CompositeMode.Enable)
		{
			Layer.Router3AX = new LayerRouter3XProps();
		}
		ccVars.Pages[ccVars.PageIndex].Layers.Add(Layer);
		Layer eyeLayer = null;
		buConversion5.buLayerToeyeLayer(Layer, ref eyeLayer);
		if (eyeLayer != null)
		{
			ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Layers.Add(eyeLayer);
		}
	}

	public void LayerDelete(int LayerIndex, bool DeleteEntities)
	{
		for (int num = ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Layers.Count - 1; num >= 0; num--)
		{
			if (ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Layers[num].Name == ccVars.Pages[ccVars.PageIndex].Layers[LayerIndex].Name)
			{
				ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Layers.RemoveAt(num);
			}
		}
		ccVars.Pages[ccVars.PageIndex].Layers.RemoveAt(LayerIndex);
	}

	public void LayerConvertFromEyeLayerToBuLayer(LayerKeyedCollection eyeLayers, ref List<LayerBase5> buLayers)
	{
		try
		{
			if (eyeLayers.Count == buLayers.Count)
			{
				for (int i = 0; i <= eyeLayers.Count - 1; i++)
				{
					if (eyeLayers[i].Name != buLayers[i].Name)
					{
						LayerBase5 buLayer = null;
						buConversion5.eyeLayerTobuLayer(eyeLayers[i], ref buLayer);
						if (clsVar.appModes_0.CompositeMode.Enable)
						{
							buLayer.Router3AX = new LayerRouter3XProps();
						}
						if (clsVar.appModes_0.TuftingMode.Enable)
						{
							buLayer.Tufting = new LayerTuftingProps();
						}
						buLayers[i] = buLayer;
					}
				}
			}
			else
			{
				buLayers.Clear();
				for (int j = 0; j <= eyeLayers.Count - 1; j++)
				{
					LayerBase5 buLayer2 = null;
					buConversion5.eyeLayerTobuLayer(eyeLayers[j], ref buLayer2);
					if (clsVar.appModes_0.CompositeMode.Enable)
					{
						buLayer2.Router3AX = new LayerRouter3XProps();
					}
					if (clsVar.appModes_0.TuftingMode.Enable)
					{
						buLayer2.Tufting = new LayerTuftingProps();
					}
					buLayers.Add(buLayer2);
				}
			}
			for (int k = 0; k <= ccVars.LayerOptions.Count - 1; k++)
			{
				for (int l = 0; l <= buLayers.Count - 1; l++)
				{
					if (ccVars.LayerOptions[k].LayerNewName == buLayers[l].Name)
					{
						buLayers[l].NameExtra = ccVars.LayerOptions[k].LayerExtraName;
					}
				}
			}
		}
		catch (Exception mSException)
		{
			LayerUpdating = false;
			buLog.addLog("", "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: true, "");
		}
	}

