	public void LayersUpdate(List<LayerBase5> Layers, bool FillLayer, int SelectedIndex)
	{
		try
		{
			if (clsItem.FrmTempLayers == null)
			{
				return;
			}
			LayerUpdating = true;
			if (Layers.Count != clsItem.FrmTempLayers.buLayerList1.LayerList.Count)
			{
				FillLayer = true;
			}
			if (!FillLayer)
			{
				for (int i = 0; i <= Layers.Count - 1; i++)
				{
					Layers[i].LayerColor.ToString();
					if (Layers[i].LayerColor.IsKnownColor)
					{
						Layers[i].LayerColor.ToKnownColor().ToString();
					}
					string text = Layers[i].Name;
					if (clsVar.varProgram.LayerDefinationShow && Layers[i].Defination.Length > 0)
					{
						text = text + " - " + Layers[i].Defination;
					}
					if (clsVar.appModes_0.TuftingMode.Enable && Layers[i].Tufting != null)
					{
						text = text + " , " + Layers[i].Tufting.StitchMode.ToString() + " , P: " + Layers[i].Tufting.PileHeight.ToString("f1") + " , S: " + Layers[i].Tufting.StitchLength.ToString("f1");
					}
					if (clsVar.varProgram.LayerColorNameShow)
					{
					}
				}
			}
			else
			{
				clsItem.FrmTempLayers.buLayerList1.RemoveAll();
				for (int j = 0; j <= Layers.Count - 1; j++)
				{
					Layers[j].LayerColor.ToString();
					if (Layers[j].LayerColor.IsKnownColor)
					{
						Layers[j].LayerColor.ToKnownColor().ToString();
					}
					string text2 = Layers[j].Name;
					if (Layers[j].NameExtra.Length > 0)
					{
						text2 = text2 + " " + Layers[j].NameExtra;
					}
					if (clsVar.varProgram.LayerDefinationShow && Layers[j].Defination.Length > 0)
					{
						text2 = text2 + " - " + Layers[j].Defination;
					}
					if (clsVar.appModes_0.TuftingMode.Enable && Layers[j].Tufting != null)
					{
						text2 = text2 + " , " + Layers[j].Tufting.StitchMode.ToString() + " , P: " + Layers[j].Tufting.PileHeight.ToString("f1") + " , S: " + Layers[j].Tufting.StitchLength.ToString("f1");
					}
					if (clsVar.varProgram.LayerColorNameShow)
					{
					}
					LayerData layer = new LayerData(text2, Layers[j].Lock, Layers[j].Enable, Layers[j].LayerColor);
					clsItem.FrmTempLayers.buLayerList1.Add(layer, Draw: false);
				}
				clsItem.FrmTempLayers.buLayerList1.DrawControls();
			}
			for (int k = 0; k <= Layers.Count - 1; k++)
			{
			}
			if ((SelectedIndex >= 0) & (SelectedIndex <= ccVars.Pages[ccVars.PageIndex].Layers.Count - 1))
			{
				LayerInfo(ccVars.Pages[ccVars.PageIndex].Layers[SelectedIndex], clsVar.varProgram.LayerPanelSettings);
			}
			DrawingPropertiesUpdate();
			LayerUpdating = false;
		}
		catch (Exception mSException)
		{
			LayerUpdating = false;
			buLog.addLog("", "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: true, "");
		}
	}

	public void LayerDGV_CellClick(object sender, EventArgs e)
	{
		int selectedLayer = clsItem.FrmTempLayers.buLayerList1.SelectedLayer;
		if ((selectedLayer >= 0) & (selectedLayer <= ccVars.Pages[ccVars.PageIndex].Layers.Count - 1))
		{
			ccVars.Pages[ccVars.PageIndex].LayerName = ccVars.Pages[ccVars.PageIndex].Layers[selectedLayer].Name;
			ccVars.Pages[ccVars.PageIndex].LayerIndex = selectedLayer;
