	public LayerKeyedCollection LayerConvertFromBuLayerToEyeLayer(List<LayerBase5> buLayers)
	{
		try
		{
			LayerKeyedCollection layerKeyedCollection = new LayerKeyedCollection();
			for (int i = 0; i <= buLayers.Count - 1; i++)
			{
				Layer eyeLayer = null;
				buConversion5.buLayerToeyeLayer(buLayers[i], ref eyeLayer);
				layerKeyedCollection.Add(eyeLayer);
			}
			return layerKeyedCollection;
		}
		catch (Exception mSException)
		{
			LayerUpdating = false;
			buLog.addLog("", "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: true, "");
			return new LayerKeyedCollection();
		}
	}

	public void LayerInfo(LayerBase5 layer, LayerPanelSetting Settings)
	{
		clsItem.FrmTempLayers.txt_layerexplanatiom.Text = "";
		string text = layer.LayerColor.ToString();
		if (layer.LayerColor.IsKnownColor)
		{
			text = layer.LayerColor.ToKnownColor().ToString();
		}
		if (Settings.ShowLayerName)
		{
			clsItem.FrmTempLayers.txt_layerexplanatiom.Text = clsItem.FrmTempLayers.txt_layerexplanatiom.Text + AppLanguage.CadCamDynamic[40] + " : " + layer.Name + Environment.NewLine;
		}
		if (Settings.ShowLayerColor)
		{
			clsItem.FrmTempLayers.txt_layerexplanatiom.Text = clsItem.FrmTempLayers.txt_layerexplanatiom.Text + AppLanguage.CadCamDynamic[17] + " : " + text + Environment.NewLine;
		}
		if (Settings.ShowLayerThickness)
		{
			clsItem.FrmTempLayers.txt_layerexplanatiom.Text = clsItem.FrmTempLayers.txt_layerexplanatiom.Text + AppLanguage.CadCamDynamic[42] + " : " + layer.LayerThickness + Environment.NewLine;
		}
	}

