	public void cmdViewZoomZero()
	{
		try
		{
			System.Drawing.Point point = default(System.Drawing.Point);
			System.Drawing.Point to = default(System.Drawing.Point);
			Pnt3D MinPoint = new Pnt3D();
			Pnt3D MaxPoint = new Pnt3D();
			Pnt3D pnt3D = new Pnt3D();
			clsInit.cVector5.GetBoxSizeOFViewport(ccVars.Pages[ccVars.PageIndex].Form.viewportcad, ccVars.Pages[ccVars.PageIndex].Scene[ccVars.Pages[ccVars.PageIndex].SceneIndex].ScenePlane, ref MinPoint, ref MaxPoint);
			pnt3D.X = (MaxPoint.X + MinPoint.X) / 2.0;
			pnt3D.Y = (MaxPoint.Y + MinPoint.Y) / 2.0;
			pnt3D.Z = (MaxPoint.Z + MinPoint.Z) / 2.0;
			double num = Convert.ToDouble(ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Height) / (MaxPoint.Y - MinPoint.Y);
			double num2 = Convert.ToDouble(ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Width) / (MaxPoint.X - MinPoint.X);
			point.X = 0;
			point.Y = 0;
			to.X = Convert.ToInt32(0.0 + pnt3D.X * num2);
			to.Y = Convert.ToInt32(0.0 - pnt3D.Y * num);
			ccVars.Pages[ccVars.PageIndex].Form.viewportcad.PanCamera(point, to);
			ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Invalidate();
		}
		catch (Exception mSException)
		{
			buLog.addLog("", "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: true, "");
		}
	}

