	public void cmdSelectDynamicEdge()
	{
		try
		{
			if (clsItem.FrmMeasure != null && clsItem.FrmMeasure.Visible)
			{
				Color dimGray = Color.DimGray;
				Color gainsboro = Color.Gainsboro;
				clsItem.FrmMeasure.btn_edge.BackColor = dimGray;
				clsItem.FrmMeasure.btn_face.BackColor = gainsboro;
				clsItem.FrmMeasure.btn_entity.BackColor = gainsboro;
				clsItem.FrmMeasure.btn_vertex.BackColor = gainsboro;
			}
			for (int i = 0; i <= ccVars.Pages.Count - 1; i++)
			{
				ccVars.Pages[i].Form.UpdateForm();
			}
			if (clsItem.FrmMeasure != null && clsItem.FrmMeasure.Visible)
			{
				Color dimGray2 = Color.DimGray;
				Color gainsboro2 = Color.Gainsboro;
				clsItem.FrmMeasure.btn_edge.BackColor = dimGray2;
				clsItem.FrmMeasure.btn_face.BackColor = gainsboro2;
				clsItem.FrmMeasure.btn_entity.BackColor = gainsboro2;
				clsItem.FrmMeasure.btn_vertex.BackColor = gainsboro2;
				clsItem.FrmMeasure.btn_points.BackColor = gainsboro2;
			}
