	public void cmdLibSaveFile()
	{
		if (!clsVar.appModes_0.DemoMode)
		{
			if (ccVars.Pages.Count <= 0)
			{
				return;
			}
			SaveFileDialog saveFileDialog = new SaveFileDialog();
			saveFileDialog.InitialDirectory = clsVar.varLibrary.pathLibrary;
			saveFileDialog.Filter = "buCad/Cam Library File (*.bulib5)|*.bulib5";
			saveFileDialog.FilterIndex = 1;
			if (saveFileDialog.ShowDialog() != DialogResult.OK)
			{
				return;
			}
			List<buEntity> copiedEntities = new List<buEntity>();
			buEntity.Copy(ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.ToList(), ref copiedEntities);
			for (int i = 0; i <= copiedEntities.Count - 1; i++)
			{
				if (!(copiedEntities[i] is buLinearDim))
				{
					continue;
				}
				copiedEntities[i].Dimension = new DimensionInfo();
				if (i > ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Count - 1)
				{
					continue;
				}
				CustomData customData = ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[i].EntityData as CustomData;
				copiedEntities[i].Dimension.ReSizedEntityIndex = customData.RefIndex;
				copiedEntities[i].Dimension.ReSizedEntitySubIndex = -1;
				copiedEntities[i].Dimension.SelectedEntities = customData.Tags;
				Enum.TryParse<DimensionType>(customData.ActionName, out var result);
				copiedEntities[i].Dimension.Type = result;
				copiedEntities[i].Dimension.Chars = customData.infoData;
				copiedEntities[i].Dimension.Distance = customData.infoLength;
				copiedEntities[i].Dimension.Explanation = customData.infoString;
				if (result == DimensionType.Length)
				{
					if (!buCompare5.EQ(customData.infoBasePoint, copiedEntities[customData.RefIndex].EndPoint, 0.1))
					{
						copiedEntities[i].Dimension.BasePoint = buVector5.ToPoint3D(copiedEntities[customData.RefIndex].StartPoint);
						copiedEntities[i].Dimension.CatchPoint = buVector5.ToPoint3D(copiedEntities[customData.RefIndex].EndPoint);
					}
					else
					{
						copiedEntities[i].Dimension.BasePoint = buVector5.ToPoint3D(copiedEntities[customData.RefIndex].EndPoint);
						copiedEntities[i].Dimension.CatchPoint = buVector5.ToPoint3D(copiedEntities[customData.RefIndex].StartPoint);
					}
				}
			}
			clsInit.appFiles.SaveLibraryFile(saveFileDialog.FileName, copiedEntities, clsVar.varLibrary);
			clsVar.varLibrary.pathLibrary = buFile.GetPath(saveFileDialog.FileName);
			clsFiles.SaveParameter();
		}
		else
		{
			MessageBox.Show("You can't save in Demo Mode");
		}
	}

