	public void LibraryEntityCalculation(ref Entity dimEntity, string Char, string Explanation, double Length, DimensionType Type, Point3D pntBase)
	{
		((CustomData)dimEntity.EntityData).infoData = Char;
		((CustomData)dimEntity.EntityData).infoString = Explanation;
		((CustomData)dimEntity.EntityData).infoLength = Length;
		((CustomData)dimEntity.EntityData).ActionName = Type.ToString();
		((CustomData)dimEntity.EntityData).infoBasePoint = buVector5.ToPoint3D(pntBase);
		if (!((ccVars.libSelectedEntityIndex >= 0) & (ccVars.libSelectedEntityIndex <= ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Count - 1)))
		{
			return;
		}
		((CustomData)dimEntity.EntityData).RefIndex = ccVars.libSelectedEntityIndex;
		Entity entity = ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[ccVars.libSelectedEntityIndex];
		if (!(entity is ICurve))
		{
			return;
		}
		List<Entity> copiedEnt = new List<Entity>();
		List<Entity> SortedEntities = new List<Entity>();
		SortSettings sortSettings = new SortSettings();
		SortResult Result = new SortResult();
		sortSettings.Option.NextGroupRules = SortingNextGroupFindRulesType.NoNextGroup;
		buVector5.CopyEntities(ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities, ref copiedEnt);
		clsInit.cVector5.SortEntitiesByRefPoint(((ICurve)entity).StartPoint, ref copiedEnt, sortSettings, ref SortedEntities, ref Result);
		if (SortedEntities.Count <= 0)
		{
			return;
		}
		int num = 0;
		for (int i = 0; i <= SortedEntities.Count - 1; i++)
		{
			CustomData customData = SortedEntities[i].EntityData as CustomData;
			if (customData.OriginalEntityIndex >= 0)
			{
				if (num != 0)
				{
					((CustomData)dimEntity.EntityData).Tags = ((CustomData)dimEntity.EntityData).Tags + " ; " + customData.OriginalEntityIndex;
				}
				else
				{
					((CustomData)dimEntity.EntityData).Tags = ((CustomData)dimEntity.EntityData).Tags + customData.OriginalEntityIndex;
				}
				num++;
			}
		}
	}

