	public void KeyDown(KeyEventArgs e)
	{
		if (e.KeyCode != Keys.Return)
		{
		}
		if (e.KeyCode == Keys.F8)
		{
			if (buVector5.AskMe.FoundEntities.Count > 0)
			{
				if (buVector5.AskMe.SelectedIndex == buVector5.AskMe.FoundEntities.Count - 1)
				{
					buVector5.AskMe.SelectedIndex = 0;
					ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Invalidate();
					return;
				}
				if (buVector5.AskMe.SelectedIndex < buVector5.AskMe.FoundEntities.Count - 1)
				{
					buVector5.AskMe.SelectedIndex++;
					ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Invalidate();
				}
			}
			if (buVector5.AskMeBu.FoundEntities.Count > 0)
			{
				if (buVector5.AskMeBu.SelectedIndex == buVector5.AskMeBu.FoundEntities.Count - 1)
				{
					buVector5.AskMeBu.SelectedIndex = 0;
					ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Invalidate();
					return;
				}
				if (buVector5.AskMeBu.SelectedIndex < buVector5.AskMeBu.FoundEntities.Count - 1)
				{
					buVector5.AskMeBu.SelectedIndex++;
					ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Invalidate();
				}
			}
		}
		if (e.KeyCode == Keys.F9 && ccVars.Action == actionTypeBU.quiltingSelectPattern)
		{
			clsInit.appQuilting.doAskMeReturn();
		}
	}

	public void undoBuffer()
	{
		if (ccVars.Pages.Count > 0)
		{
			undoBuffer(ccVars.Pages[ccVars.PageIndex]);
		}
	}

	public void undoBuffer(Pages page)
	{
		undoBuffer(page, ClearRedoBuffer: false);
	}

	public void undoBuffer(Pages page, bool ClearRedoBuffer)
	{
		if (clsVar.varProgram.UndoBufferCount > 0 && clsVar.varProgram.UndoEnable && !ccVars.UndoDont)
		{
			UndoV5 item = UndoNew(page);
			page.UndoBuffer.Add(item);
			if ((((page.UndoBuffer.Count > clsVar.varProgram.UndoBufferCount) ? 1u : 0u) | 0u) != 0)
			{
				page.UndoBuffer.RemoveAt(0);
				GC.Collect();
			}
			if (ClearRedoBuffer)
			{
				page.RedoBuffer.Clear();
			}
		}
	}

	public void undoGetBack(Pages page)
	{
		if (!clsVar.varProgram.UndoEnable)
		{
			return;
		}
		if (!clsVar.appModes_0.ProfileMode.Enable)
		{
			if ((ccVars.SimCamBaseIndex > 0) | (ccVars.SimCamPointIndex > 0))
			{
				simStop();
			}
			if (page.UndoBuffer.Count == 0)
			{
				List<UndoV5> list = new List<UndoV5>();
				list.Reverse();
				for (int i = 0; i <= list.Count - 1; i++)
				{
					UndoV5 item = new UndoV5(list[i]);
					page.UndoBuffer.Add(item);
				}
			}
			if (page.UndoBuffer.Count > 0)
			{
				UndoV5 undoV = null;
				undoV = UndoNew(page);
				page.RedoBuffer.Add(undoV);
				UndoV5 undoV2 = new UndoV5(page.UndoBuffer[page.UndoBuffer.Count - 1]);
				page.UndoBuffer.RemoveAt(page.UndoBuffer.Count - 1);
				UndoClassToPage(undoV2, ref page);
				CamsUpdate(FillCam: true, ccVars.Pages[ccVars.PageIndex].CamIndex);
				if ((clsInit.appProfile != null) & clsVar.UserMode.ProfileMode.Enable)
				{
					clsInit.appProfile.doUndoRedoGetBack(undoV2);
				}
				if (ccVars.MaterialList.Count > 0)
				{
					MaterialUpdate(FillMaterial: true, -1);
				}
				Reset(ClearSelection: true, ReDraw: true);
				clsItem.timSim.Enabled = false;
				simStop();
			}
		}
		else
		{
			clsInit.appProfile.UndoGetBack();
		}
	}

	public void redoGetBack(Pages page)
	{
		if (clsVar.varProgram.UndoEnable && page.RedoBuffer.Count > 0)
		{
			undoBuffer(page, ClearRedoBuffer: false);
			UndoV5 undoV = new UndoV5(page.RedoBuffer[page.RedoBuffer.Count - 1]);
			page.RedoBuffer.RemoveAt(page.RedoBuffer.Count - 1);
			UndoClassToPage(undoV, ref page);
			CamsUpdate(FillCam: true, ccVars.Pages[ccVars.PageIndex].CamIndex);
			if ((clsInit.appProfile != null) & clsVar.UserMode.ProfileMode.Enable)
			{
				clsInit.appProfile.doUndoRedoGetBack(undoV);
			}
			Reset(ClearSelection: true, ReDraw: true);
		}
	}

	public void UndoClassToPage(UndoV5 U, ref Pages page)
	{
		page.Form.viewportcad.Entities.Clear();
		for (int i = 0; i <= U.Entities.Count - 1; i++)
		{
			Entity item = buVector5.CopyEntities(U.Entities[i]);
			page.Form.viewportcad.Entities.Add(item);
		}
		page.Cams.Clear();
		for (int j = 0; j <= U.Cams.Count - 1; j++)
		{
			camTp copiedCam = new camTp();
			camTp.CopyCam(U.Cams[j], ref copiedCam);
			page.Cams.Add(copiedCam);
		}
		page.OsnapPoints.Clear();
		for (int k = 0; k <= U.Osnaps.Count - 1; k++)
		{
			OsnapPoint item2 = new OsnapPoint(U.Osnaps[k], U.Osnaps[k].Type, U.Osnaps[k].EntName, U.Osnaps[k].LayerName, U.Osnaps[k].OtherEntName);
			page.OsnapPoints.Add(item2);
		}
	}

