		}
		return new UndoV5(page.Form.viewportcad.Entities, page.Cams, page.OsnapPoints, null);
	}

	public void SpinLocation(ref NumericUpDown Spn, ref Panel Pnl, ContentAlignment Align, Pnt3D MinPoint, Pnt3D MidPoint, Pnt3D MaxPoint, bool Focus, bool SelectAll)
	{
		System.Drawing.Point location = default(System.Drawing.Point);
		int height = ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Height;
		int num = 4;
		if (Align == ContentAlignment.MiddleCenter)
		{
			location.X = (int)ccVars.Pages[ccVars.PageIndex].Form.viewportcad.WorldToScreen(MidPoint.X, MidPoint.Y, MidPoint.Z).X;
			location.Y = height - (int)ccVars.Pages[ccVars.PageIndex].Form.viewportcad.WorldToScreen(MidPoint.X, MidPoint.Y, MidPoint.Z).Y;
		}
		if (Align == ContentAlignment.MiddleRight)
		{
			Pnt3D pnt3D = new Pnt3D();
			if (buVector5.isPlaneXYorYX(ccVars.planeActive))
			{
				pnt3D = new Pnt3D(MaxPoint.X, MidPoint.Y, MidPoint.Z);
			}
			if (buVector5.isPlaneXZorZX(ccVars.planeActive))
			{
				pnt3D = new Pnt3D(MaxPoint.X, MidPoint.Y, MidPoint.Z);
			}
			if (buVector5.isPlaneYZ(ccVars.planeActive))
			{
				pnt3D = new Pnt3D(MaxPoint.X, MaxPoint.Y, MidPoint.Z);
			}
			location.X = (int)ccVars.Pages[ccVars.PageIndex].Form.viewportcad.WorldToScreen(pnt3D.X, pnt3D.Y, pnt3D.Z).X + num;
			location.Y = height - (int)ccVars.Pages[ccVars.PageIndex].Form.viewportcad.WorldToScreen(pnt3D.X, pnt3D.Y, pnt3D.Z).Y - Convert.ToInt32((float)Spn.Height / 2f);
		}
		if (Align == ContentAlignment.TopCenter)
		{
			Pnt3D pnt3D2 = new Pnt3D();
			pnt3D2 = (buVector5.isPlaneXYorYX(ccVars.planeActive) ? new Pnt3D(MidPoint.X, MaxPoint.Y, MaxPoint.Z) : (buVector5.isPlaneXZorZX(ccVars.planeActive) ? new Pnt3D(MidPoint.X, MaxPoint.Y, MaxPoint.Z) : (buVector5.isPlaneYZ(ccVars.planeActive) ? new Pnt3D(MidPoint.X, MidPoint.Y, MaxPoint.Z) : new Pnt3D(MidPoint.X, MaxPoint.Y, MaxPoint.Z))));
			location.X = (int)ccVars.Pages[ccVars.PageIndex].Form.viewportcad.WorldToScreen(pnt3D2.X, pnt3D2.Y, pnt3D2.Z).X - Convert.ToInt32((float)Spn.Width / 2f);
			location.Y = height - (int)ccVars.Pages[ccVars.PageIndex].Form.viewportcad.WorldToScreen(pnt3D2.X, pnt3D2.Y, pnt3D2.Z).Y - Spn.Height - num;
		}
		if (ccVars.Pages[ccVars.PageIndex].Form.pnl_coords.Visible)
		{
			ccVars.Pages[ccVars.PageIndex].Form.pnl_coords.Location = location;
		}
		Pnl.Location = location;
		if (Focus)
		{
			Spn.Focus();
		}
		if (SelectAll)
		{
			Spn.Select(0, 100);
		}
		Spn.Refresh();
	}

