	public void SpinDrawData_KeyDown(object sender, KeyEventArgs e)
	{
		if (sender.GetType() != typeof(NumericUpDown))
		{
			return;
		}
		NumericUpDown numericUpDown = new NumericUpDown();
		numericUpDown = (NumericUpDown)sender;
		Point3D EndPnt = new Point3D();
		if (ccVars.Pages.Count <= 0 || e.KeyCode != Keys.Return)
		{
			return;
		}
		if (!(((numericUpDown.Name == "spn_val1") | (numericUpDown.Name == "spn_val2") | (numericUpDown.Name == "spn_val3")) & e.Alt))
		{
			if (!(((numericUpDown.Name == "spn_x") | (numericUpDown.Name == "spn_y") | (numericUpDown.Name == "spn_z")) & e.Alt))
			{
				if ((numericUpDown.Name == "spn_val1") & !e.Control & !e.Alt)
				{
					double num = (double)numericUpDown.Value;
					if (ccVars.Pages[ccVars.PageIndex].Form.spn_val1_1.Visible)
					{
						ccVars.Pages[ccVars.PageIndex].Form.spn_val1_1.Focus();
						ccVars.Pages[ccVars.PageIndex].Form.spn_val1_1.Refresh();
					}
					else
					{
						if ((ccVars.Action == actionTypeBU.drawLine) | (ccVars.Action == actionTypeBU.drawCircle) | (ccVars.Action == actionTypeBU.drawPolyline) | (ccVars.Action == actionTypeBU.drawPolygon) | (ccVars.Action == actionTypeBU.drawPolygonIrregular) | (ccVars.Action == actionTypeBU.drawTriangle) | (ccVars.Action == actionTypeBU.drawStar) | (ccVars.Action == actionTypeBU.drawSpline) | (ccVars.Action == actionTypeBU.drawBezeir))
						{
							clsInit.cVector5.LineWithLengthAndAngle(ccVars.pntBase, num, dynamicInfo.Ang, ccVars.planeActive, ref EndPnt);
							viewportMouseDown(EndPnt, null, new MouseEventArgs(MouseButtons.Left, 0, 0, 0, 0));
							ccVars.Pages[ccVars.PageIndex].Form.pnl_val1.Visible = false;
						}
						if ((ccVars.Action == actionTypeBU.drawRectangle3Point) | (ccVars.Action == actionTypeBU.drawCircle2Point) | (ccVars.Action == actionTypeBU.drawCircle3Point) | (ccVars.Action == actionTypeBU.drawArc3PointSEM) | (ccVars.Action == actionTypeBU.drawArc3PointSME))
						{
							clsInit.cVector5.LineWithLengthAndAngle(ccVars.pntBase, num, dynamicInfo.Ang, ccVars.planeActive, ref EndPnt);
							viewportMouseDown(EndPnt, null, new MouseEventArgs(MouseButtons.Left, 0, 0, 0, 0));
							ccVars.Pages[ccVars.PageIndex].Form.pnl_val1.Visible = false;
						}
						if ((ccVars.Action == actionTypeBU.drawEllipse) | (ccVars.Action == actionTypeBU.drawEllipseArc))
						{
							if (ccVars.stpDrawing == 3)
							{
								clsInit.cVector5.LineWithLengthAndAngle(ccVars.pntBase, num, dynamicInfo.Ang, ccVars.planeActive, ref EndPnt);
								viewportMouseDown(EndPnt, null, new MouseEventArgs(MouseButtons.Left, 0, 0, 0, 0));
							}
							if (ccVars.stpDrawing == 2)
							{
								clsInit.cVector5.LineWithLengthAndAngle(ccVars.pntBase, num, dynamicInfo.Ang, ccVars.planeActive, ref EndPnt);
								viewportMouseDown(EndPnt, null, new MouseEventArgs(MouseButtons.Left, 0, 0, 0, 0));
								ccVars.Pages[ccVars.PageIndex].Form.pnl_val1.Visible = false;
							}
							ccVars.Pages[ccVars.PageIndex].Form.pnl_val1.Visible = false;
						}
						if (ccVars.Action == actionTypeBU.drawArc)
						{
							if ((ccVars.stpDrawing == 3) | (ccVars.stpDrawing == 4))
							{
								clsInit.cVector5.LineWithLengthAndAngle(ccVars.pntBase, 100.0, num, ccVars.planeActive, ref EndPnt);
								viewportMouseDown(EndPnt, null, new MouseEventArgs(MouseButtons.Left, 0, 0, 0, 0));
							}
							if (ccVars.stpDrawing == 2)
							{
								clsInit.cVector5.LineWithLengthAndAngle(ccVars.pntBase, num, dynamicInfo.Ang, ccVars.planeActive, ref EndPnt);
								viewportMouseDown(EndPnt, null, new MouseEventArgs(MouseButtons.Left, 0, 0, 0, 0));
							}
							ccVars.Pages[ccVars.PageIndex].Form.pnl_val1.Visible = false;
						}
						if ((ccVars.Action == actionTypeBU.drawRectangle) | (ccVars.Action == actionTypeBU.drawRectangleRound) | (ccVars.Action == actionTypeBU.drawRectangleChamfer) | (ccVars.Action == actionTypeBU.drawObjectImage))
						{
							SpinShow(2, Focus: true, SelectAll: true);
