						if ((ccVars.Action == actionTypeBU.eventMove) | (ccVars.Action == actionTypeBU.eventCopy))
						{
							clsInit.cVector5.LineWithLengthAndAngle(ccVars.pntBase, num, dynamicInfo.Ang, ccVars.planeActive, ref EndPnt);
							viewportMouseDown(EndPnt, null, new MouseEventArgs(MouseButtons.Left, 0, 0, 0, 0));
