							SpinShow(2, Focus: true, SelectAll: true);
						}
						if (ccVars.Action == actionTypeBU.eventMoveHorizontal)
						{
							ccVars.Pages[ccVars.PageIndex].Form.pnl_val1.Visible = false;
						}
						if (ccVars.Action == actionTypeBU.eventMoveHorizontalSequence)
						{
							ccVars.Pages[ccVars.PageIndex].Form.pnl_val1.Visible = false;
							return;
						}
						if (ccVars.Action == actionTypeBU.eventMoveVertical)
						{
							ccVars.Pages[ccVars.PageIndex].Form.pnl_val1.Visible = false;
