						ccVars.Pages[ccVars.PageIndex].Form.lbl_val1_1.Visible = true;
						ccVars.Pages[ccVars.PageIndex].Form.spn_val1_1.Visible = true;
						ccVars.Pages[ccVars.PageIndex].Form.spn_val1_1.Focus();
						ccVars.Pages[ccVars.PageIndex].Form.spn_val1_1.Refresh();
					}
				}
				if (numericUpDown.Name == "spn_val2")
				{
					_ = (double)numericUpDown.Value;
					if ((ccVars.Action == actionTypeBU.drawLine) | (ccVars.Action == actionTypeBU.drawPolyline))
					{
						clsInit.cVector5.LineWithLengthAndAngle(ccVars.pntBase, (double)ccVars.Pages[ccVars.PageIndex].Form.spn_val1.Value, (double)ccVars.Pages[ccVars.PageIndex].Form.spn_val2.Value, ccVars.planeActive, ref EndPnt);
