			ccVars.Pages[ccVars.PageIndex].Form.pnl_coords.Top = 10 + ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Height - (int)ccVars.Pages[ccVars.PageIndex].Form.viewportcad.WorldToScreen(ccVars.pntActive.X, ccVars.pntActive.Y, ccVars.pntActive.Z).Y;
			ccVars.Pages[ccVars.PageIndex].Form.spn_x.Value = (decimal)Math.Round(ccVars.pntActive.X, 3);
			ccVars.Pages[ccVars.PageIndex].Form.spn_y.Value = (decimal)Math.Round(ccVars.pntActive.Y, 3);
			ccVars.Pages[ccVars.PageIndex].Form.spn_z.Value = (decimal)Math.Round(ccVars.pntActive.Z, 3);
			ccVars.Pages[ccVars.PageIndex].Form.spn_x.Focus();
			ccVars.Pages[ccVars.PageIndex].Form.spn_x.Select(0, 100);
		}
	}

	public void cmdDrawLineMenu(string cmd)
	{
		if (cmd.ToLower() == "line")
		{
			clsVar.varInterface.LineCommandIndex = 0;
			cmdDrawLine();
		}
		if (cmd.ToLower() == "polyline")
		{
			clsVar.varInterface.LineCommandIndex = 1;
			cmdDrawPolyline();
		}
		if (cmd.ToLower() == "points")
		{
			clsVar.varInterface.LineCommandIndex = 2;
			cmdDrawPoint();
		}
		if (cmd.ToLower() == "line")
		{
		}
		clsFiles.SaveParameter();
	}

	public void cmdDrawLine()
	{
		try
		{
			Reset(ClearSelection: false);
			ccVars.Pages[ccVars.PageIndex].Form.viewportcad.ActionMode = actionType.None;
			ccVars.Action = actionTypeBU.drawLine;
			ccVars.stpDrawing = 1;
			ccVars.selectionProcess = false;
			dynamicInfo.Command = AppLanguage.CadCamCommand[1] + " ";
