	public void cmdDrawImage()
	{
		try
		{
			Reset(ClearSelection: false);
			if (DialogBoxes.OpenImageFileDialog(clsVar.varInterface.pathImage) == DialogResult.OK)
			{
				clsVar.ImageFileName = DialogBoxes.FileName;
				Image image = Image.FromFile(clsVar.ImageFileName);
				ccVars.WidthHeightRatio = (double)image.Width / (double)image.Height;
				clsVar.varInterface.pathImage = buFile.GetPath(clsVar.ImageFileName);
				clsFiles.SaveParameter();
				ccVars.Pages[ccVars.PageIndex].Form.viewportcad.ActionMode = actionType.None;
				ccVars.Action = actionTypeBU.drawObjectImage;
				ccVars.stpDrawing = 1;
				ccVars.selectionProcess = false;
