	public void cmdDrawUndo()
	{
		if (!((ccVars.Action == actionTypeBU.drawPolyline) | (ccVars.Action == actionTypeBU.profileFreeDraw)))
		{
			if (ccVars.Action != actionTypeBU.drawPolygonIrregular)
			{
				if (ccVars.Action != actionTypeBU.drawSpline)
				{
					if (ccVars.Action != actionTypeBU.drawBezeir || ccVars.pntBuffered.Count <= 1)
					{
						return;
					}
					ccVars.pntBuffered.RemoveAt(ccVars.pntBuffered.Count - 1);
					ccVars.pntBase = buVector5.ToPoint3D(ccVars.pntBuffered[ccVars.pntBuffered.Count - 1]);
					if (ccVars.Pages[ccVars.PageIndex].OsnapTempPoints.Count > 0)
					{
						ccVars.Pages[ccVars.PageIndex].OsnapTempPoints.RemoveAt(ccVars.Pages[ccVars.PageIndex].OsnapTempPoints.Count - 1);
						if (ccVars.Pages[ccVars.PageIndex].OsnapTempPoints.Count > 0)
						{
							ccVars.Pages[ccVars.PageIndex].OsnapTempPoints.RemoveAt(ccVars.Pages[ccVars.PageIndex].OsnapTempPoints.Count - 1);
						}
					}
					return;
				}
				if (ccVars.pntBuffered.Count <= 2)
				{
					if (ccVars.pntBuffered.Count <= 1)
					{
						return;
					}
					ccVars.pntBuffered.RemoveAt(ccVars.pntBuffered.Count - 1);
					ccVars.pntBase = buVector5.ToPoint3D(ccVars.pntBuffered[ccVars.pntBuffered.Count - 1]);
					ccVars.stpDrawing = 2;
					if (ccVars.Pages[ccVars.PageIndex].OsnapTempPoints.Count > 0)
					{
						ccVars.Pages[ccVars.PageIndex].OsnapTempPoints.RemoveAt(ccVars.Pages[ccVars.PageIndex].OsnapTempPoints.Count - 1);
						if (ccVars.Pages[ccVars.PageIndex].OsnapTempPoints.Count > 0)
						{
							ccVars.Pages[ccVars.PageIndex].OsnapTempPoints.RemoveAt(ccVars.Pages[ccVars.PageIndex].OsnapTempPoints.Count - 1);
						}
					}
					return;
				}
				ccVars.pntBuffered.RemoveAt(ccVars.pntBuffered.Count - 1);
				ccVars.pntBase = buVector5.ToPoint3D(ccVars.pntBuffered[ccVars.pntBuffered.Count - 1]);
				if (ccVars.Pages[ccVars.PageIndex].OsnapTempPoints.Count > 0)
				{
					ccVars.Pages[ccVars.PageIndex].OsnapTempPoints.RemoveAt(ccVars.Pages[ccVars.PageIndex].OsnapTempPoints.Count - 1);
					if (ccVars.Pages[ccVars.PageIndex].OsnapTempPoints.Count > 0)
					{
						ccVars.Pages[ccVars.PageIndex].OsnapTempPoints.RemoveAt(ccVars.Pages[ccVars.PageIndex].OsnapTempPoints.Count - 1);
					}
				}
			}
			else
			{
				if (ccVars.pntBuffered.Count <= 2)
				{
					return;
				}
				ccVars.pntBuffered.RemoveAt(ccVars.pntBuffered.Count - 2);
				ccVars.pntBase = buVector5.ToPoint3D(ccVars.pntBuffered[ccVars.pntBuffered.Count - 1]);
				ccVars.pntDrawDynamicArr = new Point3D[ccVars.pntBuffered.Count + 1];
				for (int i = 0; i <= ccVars.pntBuffered.Count - 1; i++)
				{
					ccVars.pntDrawDynamicArr[i] = buVector5.ToPoint3D(ccVars.pntBuffered[i]);
				}
				ccVars.pntDrawDynamicArr[ccVars.pntBuffered.Count] = buVector5.ToPoint3D(ccVars.pntBuffered[ccVars.pntBuffered.Count - 1]);
				if (ccVars.Pages[ccVars.PageIndex].OsnapTempPoints.Count > 0)
				{
					ccVars.Pages[ccVars.PageIndex].OsnapTempPoints.RemoveAt(ccVars.Pages[ccVars.PageIndex].OsnapTempPoints.Count - 1);
					if (ccVars.Pages[ccVars.PageIndex].OsnapTempPoints.Count > 0)
					{
						ccVars.Pages[ccVars.PageIndex].OsnapTempPoints.RemoveAt(ccVars.Pages[ccVars.PageIndex].OsnapTempPoints.Count - 1);
					}
				}
			}
		}
		else
		{
			if (ccVars.pntBuffered.Count <= 1)
			{
				return;
			}
			ccVars.pntBuffered.RemoveAt(ccVars.pntBuffered.Count - 1);
			ccVars.pntBase = buVector5.ToPoint3D(ccVars.pntBuffered[ccVars.pntBuffered.Count - 1]);
			ccVars.pntDrawDynamicArr = new Point3D[ccVars.pntBuffered.Count + 1];
			for (int j = 0; j <= ccVars.pntBuffered.Count - 1; j++)
			{
				ccVars.pntDrawDynamicArr[j] = buVector5.ToPoint3D(ccVars.pntBuffered[j]);
			}
			ccVars.pntDrawDynamicArr[ccVars.pntBuffered.Count] = buVector5.ToPoint3D(ccVars.pntBuffered[ccVars.pntBuffered.Count - 1]);
			if (ccVars.Pages[ccVars.PageIndex].OsnapTempPoints.Count > 0)
			{
				ccVars.Pages[ccVars.PageIndex].OsnapTempPoints.RemoveAt(ccVars.Pages[ccVars.PageIndex].OsnapTempPoints.Count - 1);
				if (ccVars.Pages[ccVars.PageIndex].OsnapTempPoints.Count > 0)
				{
					ccVars.Pages[ccVars.PageIndex].OsnapTempPoints.RemoveAt(ccVars.Pages[ccVars.PageIndex].OsnapTempPoints.Count - 1);
				}
			}
		}
	}

	public void cmdDrawClose()
	{
		if (ccVars.Action != actionTypeBU.drawPolyline)
		{
			return;
		}
		if (ccVars.pntBuffered.Count > 2)
		{
			if (!Utility.IsClosedProfile(ccVars.pntBuffered))
			{
				ccVars.pntBuffered.Add(buVector5.ToPoint3D(ccVars.pntBuffered[0]));
			}
			LinearPath Ent = null;
			EntityDataSet entData = new EntityDataSet(-1, ccVars.Pages[ccVars.PageIndex].LayerName, ccVars.Pages[ccVars.PageIndex].SceneName, "", "Polyline", null, ccVars.pntBase);
			CreatePolyLine(ccVars.pntBuffered, entData, EntityDataSet.ConvertCustomData(entData), ref Ent);
			if (Ent != null)
			{
				AddPolyline(Ent);
			}
		}
		Reset();
	}

	public void cmdDrawFinish()
	{
		if (ccVars.Action == actionTypeBU.marbleDrawCompositeCurve && clsInit.appMarble != null)
		{
			clsInit.appMarble.AddCompositeCurve();
		}
		if (ccVars.Action == actionTypeBU.marbleDrawPolyline && clsInit.appMarble != null)
		{
			clsInit.appMarble.AddPolyLine(null);
		}
		if (ccVars.Action != actionTypeBU.drawPolyline)
		{
			if (ccVars.Action != actionTypeBU.drawFreeDraw)
			{
				if (ccVars.Action != actionTypeBU.drawPolygonIrregular)
				{
					if (ccVars.Action != actionTypeBU.drawSpline)
					{
						Reset();
						return;
					}
					if (ccVars.pntBuffered.Count >= 3)
					{
						if (clsVar.varInterface.SplineVar.Closed)
						{
							ccVars.pntBuffered.Add(buVector5.ToPoint3D(ccVars.pntBuffered[0]));
						}
						new CustomData();
						string actionName = "";
						int degree = 1;
						if (clsVar.varInterface.SplineVar.Type != entitySplineType.SplineCubic)
						{
							if (clsVar.varInterface.SplineVar.Type != entitySplineType.BsplineCubic)
							{
								if (clsVar.varInterface.SplineVar.Type == entitySplineType.BsplineQuadratic)
								{
									actionName = "BSplineQuadratic";
									degree = 2;
								}
							}
							else
							{
								actionName = "BSplineCubic";
								degree = 3;
							}
						}
						else
						{
							actionName = "SplineCubic";
							degree = 3;
						}
						Curve Ent = null;
						EntityDataSet entityDataSet = new EntityDataSet(-1, ccVars.Pages[ccVars.PageIndex].LayerName, ccVars.Pages[ccVars.PageIndex].SceneName, "", actionName, null, ccVars.pntBase);
						entityDataSet.Degree = degree;
						CreateSpline(ccVars.pntBuffered, clsVar.varInterface.SplineVar.Type, entityDataSet, EntityDataSet.ConvertCustomData(entityDataSet), ref Ent);
						if (Ent != null)
						{
							AddSpline(Ent);
						}
					}
					Reset();
					return;
				}
				if (ccVars.pntBuffered.Count >= 2)
				{
					List<Entity> list = new List<Entity>();
					for (int i = 1; i <= ccVars.pntBuffered.Count - 1; i++)
					{
						list.Add(new Line(ccVars.pntBuffered[i - 1], ccVars.pntBuffered[i]));
					}
					CompositeCurve Ent2 = null;
					EntityDataSet entData = new EntityDataSet(-1, ccVars.Pages[ccVars.PageIndex].LayerName, ccVars.Pages[ccVars.PageIndex].SceneName, "", "Irregular", null, ccVars.pntBase);
					CreateCompositeCurve(list, entData, EntityDataSet.ConvertCustomData(entData), ref Ent2);
					if (Ent2 != null)
					{
						AddCompositeCurve(Ent2);
					}
				}
				Reset();
				return;
			}
			if (clsVar.varInterface.FreeDrawVar.ConverToSpline)
			{
				for (int j = 0; j <= ccVars.pntDrawDynamicLinesArr.Count - 1; j++)
				{
					if (ccVars.pntDrawDynamicLinesArr[j].Count < 2)
					{
						continue;
					}
					new CustomData();
					string actionName2 = "";
					int degree2 = 1;
					if (clsVar.varInterface.FreeDrawVar.SplineType != entitySplineType.SplineCubic)
					{
						if (clsVar.varInterface.FreeDrawVar.SplineType != entitySplineType.BsplineCubic)
						{
							if (clsVar.varInterface.FreeDrawVar.SplineType == entitySplineType.BsplineQuadratic)
							{
								actionName2 = "BSplineQuadratic";
								degree2 = 2;
							}
						}
						else
						{
							actionName2 = "BSplineCubic";
							degree2 = 3;
						}
					}
					else
					{
						actionName2 = "SplineCubic";
						degree2 = 3;
					}
					Curve Ent3 = null;
					EntityDataSet entityDataSet2 = new EntityDataSet(-1, ccVars.Pages[ccVars.PageIndex].LayerName, ccVars.Pages[ccVars.PageIndex].SceneName, "", actionName2, null, ccVars.pntBase);
					entityDataSet2.Degree = degree2;
					CreateSpline(ccVars.pntDrawDynamicLinesArr[j], clsVar.varInterface.FreeDrawVar.SplineType, entityDataSet2, EntityDataSet.ConvertCustomData(entityDataSet2), ref Ent3);
					if (Ent3 != null)
					{
						AddSpline(Ent3);
					}
				}
			}
			else
			{
				for (int k = 0; k <= ccVars.pntDrawDynamicLinesArr.Count - 1; k++)
				{
					if (ccVars.pntDrawDynamicLinesArr[k].Count >= 2)
					{
						LinearPath Ent4 = null;
						EntityDataSet entData2 = new EntityDataSet(-1, ccVars.Pages[ccVars.PageIndex].LayerName, ccVars.Pages[ccVars.PageIndex].SceneName, "", "FreeDraw", null, ccVars.pntBase);
						CreatePolyLine(ccVars.pntDrawDynamicLinesArr[k], entData2, EntityDataSet.ConvertCustomData(entData2), ref Ent4);
						if (Ent4 != null)
						{
							AddPolyline(Ent4);
						}
					}
				}
			}
			Reset();
			return;
		}
		if (ccVars.pntBuffered.Count >= 2)
		{
			LinearPath Ent5 = null;
			if (!clsInit.cVector5.IsLayerNameAvailable(ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Layers, ccVars.Pages[ccVars.PageIndex].LayerName))
			{
				ccVars.Pages[ccVars.PageIndex].LayerName = ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Layers[0].Name;
			}
			EntityDataSet entData3 = new EntityDataSet(-1, ccVars.Pages[ccVars.PageIndex].LayerName, ccVars.Pages[ccVars.PageIndex].SceneName, "", "Polyline", null, ccVars.pntBase);
			CreatePolyLine(ccVars.pntBuffered, entData3, EntityDataSet.ConvertCustomData(entData3), ref Ent5);
			if (Ent5 != null)
			{
				if (!clsVar.appModes_0.TuftingMode.Enable)
				{
					AddPolyline(Ent5);
				}
				else
				{
					clsInit.appTufting.doAddManuelEntities(Ent5);
				}
			}
		}
		Reset();
	}

