				clsItem.FrmMeasure.btn_edge.BackColor = clsVar.varProgram.ButtonUnselectedColor;
				clsItem.FrmMeasure.btn_face.BackColor = clsVar.varProgram.ButtonUnselectedColor;
				clsItem.FrmMeasure.btn_entity.BackColor = clsVar.varProgram.ButtonUnselectedColor;
				clsItem.FrmMeasure.btn_vertex.BackColor = clsVar.varProgram.ButtonUnselectedColor;
				clsItem.FrmMeasure.btn_points.BackColor = clsVar.varProgram.ButtonSelectedColor;
