	public void cmdImageToVector()
	{
		try
		{
			clsVar.varInterface.FileNameImageProcess = Application.StartupPath + "\\OutputImage.png";
			F_ImageToVector f_ImageToVector = new F_ImageToVector();
			f_ImageToVector.pathInit = clsVar.varInterface.pathImageProcess;
			f_ImageToVector.Settings = new RasterToVectorVar(clsVar.varInterface.RasterVectorVar);
			f_ImageToVector.Init();
			f_ImageToVector.ShowDialog();
			if (f_ImageToVector.PropertiesForm.Result == DialogResult.OK)
			{
				clsVar.varInterface.RasterVectorVar = new RasterToVectorVar(f_ImageToVector.Settings);
				clsVar.varInterface.pathImageProcess = f_ImageToVector.pathInit;
				if (f_ImageToVector.imageOutput != null)
				{
					clsVar.varInterface.InsertFileVar.InsertToZeroPosition = true;
					f_ImageToVector.imageOutput.Save(clsVar.varInterface.FileNameImageProcess);
					string text = " OutputImage.png " + clsVar.varInterface.RasterVectorVar.ColorToBWThreshold + " " + clsVar.varInterface.RasterVectorVar.DPI + " " + clsVar.varInterface.RasterVectorVar.SimplifyTolerance.ToString("f2") + " " + clsVar.varInterface.RasterVectorVar.SplineToleranca.ToString("f2") + " Outtt.igs";
					List<string> list = new List<string>();
					list.Add("; @echo off");
					list.Add("mwRaster2VectorSample.exe" + text);
					list.Add("PAUSE");
					buFile.SaveToFile(list, Application.StartupPath + "\\Raster.bat");
					Process process = new Process();
					process.StartInfo.WorkingDirectory = Application.StartupPath;
					process.StartInfo.FileName = "Raster.bat";
					process.StartInfo.CreateNoWindow = true;
					process.Start();
					process.WaitForExit();
					clsInit.appFiles.OpenCadFiles(Application.StartupPath + "\\Outtt.igs", ClearEntities: true, ref clsItem.ModelOpenInsert);
					f_ImageToVector.imageOutput = null;
					f_ImageToVector.Dispose();
					GC.Collect();
				}
				clsFiles.SaveParameter();
			}
		}
		catch (Exception mSException)
		{
			buLog.addLog("", "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: true, "");
		}
	}

	public void CreateEntity(Entity refEntity, ref Entity Ent)
	{
		if (!(refEntity is buLinearPathCam))
		{
			if (!(refEntity is buLineCam))
			{
				if (!(refEntity is buArcCam))
				{
					if (!(refEntity is buCompositeCurveCam))
					{
						if (!(refEntity is devDept.Eyeshot.Entities.Point))
						{
							if (!(refEntity is Line))
							{
								if (!(refEntity is Arc))
								{
									if (!(refEntity is Circle))
									{
										if (!(refEntity is LinearPath))
										{
											if (!(refEntity is Ellipse))
											{
												if (!(refEntity is EllipticalArc))
												{
													if (!(refEntity is Curve))
													{
														if (!(refEntity is CompositeCurve))
														{
															if (!(refEntity is Text))
															{
																if (!(refEntity is Picture))
																{
																	if (!(refEntity is LinearDim))
																	{
																		if (!(refEntity is AngularDim))
																		{
																			if (!(refEntity is RadialDim))
																			{
																				if (!(refEntity is DiametricDim))
																				{
																					if (!(refEntity is OrdinateDim))
																					{
																						if (!(refEntity is Leader))
																						{
																							Ent = (Entity)refEntity.Clone();
																						}
																						else
																						{
																							CreateLeader(refEntity, ref Ent);
																						}
																					}
																					else
																					{
																						CreateDimensionOrdinate(refEntity, ref Ent);
																					}
																				}
																				else
																				{
																					CreateDimensionDiametric(refEntity, ref Ent);
																				}
																			}
																			else
																			{
																				CreateDimensionRadial(refEntity, ref Ent);
																			}
																		}
																		else
																		{
																			CreateDimensionAngular(refEntity, ref Ent);
																		}
																	}
																	else
																	{
																		CreateDimensionLinear(refEntity, ref Ent);
																	}
																}
																else
																{
																	CreatePicture(refEntity, ref Ent);
																}
															}
															else
															{
																CreateText(refEntity, ref Ent);
															}
														}
														else
														{
															CreateCompositeCurve(refEntity, ref Ent);
														}
													}
													else
													{
														CreateSpline(refEntity, ref Ent);
													}
												}
												else
												{
													CreateEllipseArc(refEntity, ref Ent);
												}
											}
											else
											{
												CreateEllipse(refEntity, ref Ent);
											}
										}
										else
										{
											CreatePolyLine(refEntity, ref Ent);
										}
									}
									else
									{
										CreateCircle(refEntity, ref Ent);
									}
								}
								else
								{
									CreateArc(refEntity, ref Ent);
								}
							}
							else
							{
								CreateLine(refEntity, ref Ent);
							}
						}
						else
						{
							CreatePoint(refEntity, ref Ent);
						}
					}
					else
					{
						Ent = new buCompositeCurveCam((buCompositeCurveCam)refEntity);
					}
				}
				else
				{
					Ent = new buArcCam((buArcCam)refEntity);
				}
			}
			else
			{
				Ent = new buLineCam((buLineCam)refEntity);
			}
		}
		else
		{
			Ent = new buLinearPathCam((buLinearPathCam)refEntity);
		}
		Ent.Regen(new RegenParams(clsVar.varEntities.RegenDeviation, ccVars.Pages[ccVars.PageIndex].Form.viewportcad));
		ccVars.Pages[ccVars.PageIndex].EntityCounter++;
	}

	public void AddTempEntity(Entity Ent)
	{
		if (Ent is Text)
		{
			Ent.Regen(new RegenParams(clsVar.varEntities.RegenDeviation, ccVars.Pages[ccVars.PageIndex].Form.viewportcad));
		}
		if (Ent.EntityData is CustomData)
		{
			((CustomData)Ent.EntityData).typeDefination = entityTypeDefination.Temp;
			ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Add(Ent);
			ccVars.Pages[ccVars.PageIndex].Changed = true;
			ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Invalidate();
		}
	}

	public void AddEntity(Entity Ent, bool OsnapCalc = true)
	{
		if (Ent != null)
		{
			undoBuffer(ccVars.Pages[ccVars.PageIndex]);
			if (Ent is Text)
			{
				Ent.Regen(new RegenParams(clsVar.varEntities.RegenDeviation, ccVars.Pages[ccVars.PageIndex].Form.viewportcad));
			}
			bool flag = false;
			if (Ent is buLineCam || Ent is buLinearPathCam || Ent is buCompositeCurveCam || Ent is buArcCam)
			{
				flag = true;
			}
			if (!flag && OsnapCalc)
			{
				OsnapCalculation(Ent);
			}
			ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Add(Ent);
			ccVars.Pages[ccVars.PageIndex].Changed = true;
			eventAddEntityToPage(Ent, ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Count - 1);
		}
	}

	public void CopyCommonProps(Entity baseEntity, ref Entity commonEntitiy)
	{
		commonEntitiy.ColorMethod = baseEntity.ColorMethod;
		commonEntitiy.LineTypeMethod = baseEntity.LineTypeMethod;
		commonEntitiy.LineWeightMethod = baseEntity.LineWeightMethod;
		commonEntitiy.Color = baseEntity.Color;
		commonEntitiy.Selectable = baseEntity.Selectable;
		commonEntitiy.LineWeight = baseEntity.LineWeight;
		if (baseEntity.LineTypeName != null)
		{
			commonEntitiy.LineTypeName = baseEntity.LineTypeName;
		}
		commonEntitiy.LineTypeScale = baseEntity.LineTypeScale;
	}

	public void CreatePoint(Point3D StartPoint, EntityDataSet entData, CustomData customData, ref devDept.Eyeshot.Entities.Point Ent)
	{
		Ent = new devDept.Eyeshot.Entities.Point(StartPoint, ccVars.Pages[ccVars.PageIndex].Layers[ccVars.Pages[ccVars.PageIndex].LayerIndex].LayerThickness + 3f);
		Ent.EntityData = new CustomData(customData);
		Ent.LineTypeMethod = colorMethodType.byLayer;
		Ent.ColorMethod = colorMethodType.byLayer;
		Ent.LineWeightMethod = colorMethodType.byEntity;
		Ent.LayerName = entData.LayerName;
		((CustomData)Ent.EntityData).GroupIdIndex = entData.GroupIDIndex;
		((CustomData)Ent.EntityData).EntityName = "Ent" + ccVars.Pages[ccVars.PageIndex].EntityCounter;
		((CustomData)Ent.EntityData).SceneName = entData.SceneName;
		((CustomData)Ent.EntityData).ActionName = entData.ActionName;
		ccVars.Pages[ccVars.PageIndex].EntityCounter++;
	}

	public void CreatePoint(Entity baseEntity, ref Entity Ent)
	{
		if (baseEntity is devDept.Eyeshot.Entities.Point)
		{
			devDept.Eyeshot.Entities.Point point = (devDept.Eyeshot.Entities.Point)baseEntity;
			Ent = new devDept.Eyeshot.Entities.Point(point.StartPoint, point.LineWeight);
			Ent.EntityData = new CustomData(clsInit.cVector5.GetEntityCustomData(baseEntity));
			Ent.LayerName = baseEntity.LayerName;
			CopyCommonProps(baseEntity, ref Ent);
			((CustomData)Ent.EntityData).EntityName = "Ent" + ccVars.Pages[ccVars.PageIndex].EntityCounter;
			ccVars.Pages[ccVars.PageIndex].EntityCounter++;
		}
	}

	public void AddPoint(devDept.Eyeshot.Entities.Point Ent)
	{
		undoBuffer(ccVars.Pages[ccVars.PageIndex]);
		OsnapCalculation(Ent);
		ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Add(Ent);
		ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Invalidate();
		ccVars.Pages[ccVars.PageIndex].Changed = true;
		if (drawingFinisedEvent_0 != null)
		{
			DrawingFinisedEventArgs e = new DrawingFinisedEventArgs();
			e.FinshedEntity = buVector5.CopyEntities(Ent);
			e.DrawingIndex = ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Count - 1;
			drawingFinisedEvent_0(e);
		}
		eventAddEntityToPage(Ent, ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Count - 1);
	}

	public void CreateLine(Point3D StartPoint, Point3D EndPoint, EntityDataSet entData, CustomData customData, ref Line Ent)
	{
		Ent = new Line(StartPoint, EndPoint);
		Ent.EntityData = new CustomData(customData);
		Ent.LineTypeMethod = colorMethodType.byLayer;
		Ent.ColorMethod = colorMethodType.byLayer;
		Ent.LineWeightMethod = colorMethodType.byLayer;
		Ent.LayerName = entData.LayerName;
		((CustomData)Ent.EntityData).GroupIdIndex = entData.GroupIDIndex;
		((CustomData)Ent.EntityData).EntityName = "Ent" + ccVars.Pages[ccVars.PageIndex].EntityCounter;
		((CustomData)Ent.EntityData).SceneName = entData.SceneName;
		((CustomData)Ent.EntityData).ActionName = entData.ActionName;
		((CustomData)Ent.EntityData).infoLength = Ent.Length();
		ccVars.Pages[ccVars.PageIndex].EntityCounter++;
	}

	public void CreateLine(Entity baseEntity, ref Entity Ent)
	{
		if (baseEntity is Line)
		{
			Line line = (Line)baseEntity;
			Ent = new Line(line.StartPoint, line.EndPoint);
			Ent.EntityData = new CustomData(clsInit.cVector5.GetEntityCustomData(baseEntity));
			Ent.LayerName = baseEntity.LayerName;
			CopyCommonProps(baseEntity, ref Ent);
			((CustomData)Ent.EntityData).EntityName = "Ent" + ccVars.Pages[ccVars.PageIndex].EntityCounter;
			ccVars.Pages[ccVars.PageIndex].EntityCounter++;
		}
	}

	public void AddLine(Line Ent)
	{
		if (ccVars.Pages[ccVars.PageIndex].Form.viewportcad.CurrentSketch == null || !ccVars.Pages[ccVars.PageIndex].Form.viewportcad.CurrentSketch.Editing)
