		Ent = new Arc(refPlane, arc.Center, arc.Radius, arc.StartPoint, arc.EndPoint, flip: false);
		if (!buCompare.EQ(arc.AngleInDegrees, Ent.AngleInDegrees, 0.001))
		{
			Ent = new Arc(refPlane, arc.Center, arc.Radius, arc.StartPoint, arc.EndPoint, flip: true);
