	public void CreateCompositeCurve(List<Entity> refEntities, EntityDataSet entData, CustomData customData, ref CompositeCurve Ent)
	{
		List<ICurve> list = new List<ICurve>();
		for (int i = 0; i <= refEntities.Count - 1; i++)
		{
			ICurve curve = null;
			if (!(refEntities[i] is Line))
			{
				if (!(refEntities[i] is Arc))
				{
					if (!(refEntities[i] is Circle))
					{
						if (!(refEntities[i] is Curve))
						{
							if (!(refEntities[i] is Ellipse))
							{
								if (!(refEntities[i] is LinearPath))
								{
									if (refEntities[i] is CompositeCurve)
									{
										curve = (CompositeCurve)refEntities[i];
									}
								}
								else
								{
									curve = (LinearPath)refEntities[i];
								}
							}
							else
							{
								curve = (Ellipse)refEntities[i];
							}
						}
						else
						{
							curve = (Curve)refEntities[i];
						}
					}
					else
					{
						curve = (Circle)refEntities[i];
					}
				}
				else
				{
					curve = (Arc)refEntities[i];
				}
			}
			else
			{
				curve = (Line)refEntities[i];
			}
			if (curve != null)
			{
				list.Add(curve);
			}
		}
		Ent = new CompositeCurve(list);
		Ent.EntityData = new CustomData(customData);
		Ent.LineTypeMethod = colorMethodType.byLayer;
		Ent.ColorMethod = colorMethodType.byLayer;
		Ent.LineWeightMethod = colorMethodType.byLayer;
		Ent.LayerName = entData.LayerName;
		((CustomData)Ent.EntityData).GroupIdIndex = entData.GroupIDIndex;
		((CustomData)Ent.EntityData).EntityName = "Ent" + ccVars.Pages[ccVars.PageIndex].EntityCounter;
		((CustomData)Ent.EntityData).SceneName = entData.SceneName;
		((CustomData)Ent.EntityData).ActionName = entData.ActionName;
		((CustomData)Ent.EntityData).infoBasePoint = buVector5.ToPoint3D(entData.PntBase);
		if (((CustomData)Ent.EntityData).ActionName.Trim().ToLower() == "rectangle")
		{
			((CustomData)Ent.EntityData).infoWidth = entData.Width;
			((CustomData)Ent.EntityData).infoHeight = entData.Height;
		}
		if (((CustomData)Ent.EntityData).ActionName.Trim().ToLower() == "rectangleround")
		{
			((CustomData)Ent.EntityData).infoRadius = entData.Radius;
			((CustomData)Ent.EntityData).infoWidth = entData.Width;
			((CustomData)Ent.EntityData).infoHeight = entData.Height;
		}
		if (((CustomData)Ent.EntityData).ActionName.Trim().ToLower() == "rectanglechamfer")
		{
			((CustomData)Ent.EntityData).infoLength = entData.Length;
			((CustomData)Ent.EntityData).infoWidth = entData.Width;
			((CustomData)Ent.EntityData).infoHeight = entData.Height;
		}
		if (((CustomData)Ent.EntityData).ActionName.Trim().ToLower() == "polygon")
		{
			((CustomData)Ent.EntityData).infoSide = entData.Side;
			((CustomData)Ent.EntityData).infoRadius = entData.Radius;
			((CustomData)Ent.EntityData).infoAngle = entData.Angle;
		}
		if (((CustomData)Ent.EntityData).ActionName.Trim().ToLower() == "keyhole")
		{
			((CustomData)Ent.EntityData).infoRadius = entData.Radius;
			((CustomData)Ent.EntityData).infoLength = entData.Length;
			((CustomData)Ent.EntityData).infoHeadRadius = entData.HeadRadius;
			((CustomData)Ent.EntityData).infoAngle = entData.Angle;
		}
		ccVars.Pages[ccVars.PageIndex].EntityCounter++;
	}

