	public void CreateSpline(List<Point3D> PointsList, entitySplineType Type, EntityDataSet entData, CustomData customData, ref Curve Ent)
	{
		switch (Type)
		{
		case entitySplineType.SplineCubic:
			Ent = Curve.CubicSplineInterpolation(PointsList);
			break;
		case entitySplineType.BsplineQuadratic:
			Ent = new Curve(2, PointsList);
			break;
		case entitySplineType.BsplineCubic:
			Ent = new Curve(3, PointsList);
			break;
		}
		Ent.EntityData = new CustomData(customData);
		Ent.LineTypeMethod = colorMethodType.byLayer;
		Ent.ColorMethod = colorMethodType.byLayer;
		Ent.LineWeightMethod = colorMethodType.byLayer;
		Ent.LayerName = entData.LayerName;
		((CustomData)Ent.EntityData).GroupIdIndex = entData.GroupIDIndex;
		((CustomData)Ent.EntityData).EntityName = "Ent" + ccVars.Pages[ccVars.PageIndex].EntityCounter;
		((CustomData)Ent.EntityData).SceneName = entData.SceneName;
		((CustomData)Ent.EntityData).ActionName = entData.ActionName;
		ccVars.Pages[ccVars.PageIndex].EntityCounter++;
	}

	public void CreateSpline(Entity baseEntity, ref Entity Ent)
	{
		if (!(baseEntity is Curve))
		{
			return;
		}
		Curve curve = (Curve)baseEntity;
		if (clsInit.cVector5.GetEntityCustomData(baseEntity).CurveType != entitySplineType.SplineCubic)
		{
			if (clsInit.cVector5.GetEntityCustomData(baseEntity).CurveType != entitySplineType.BsplineQuadratic)
			{
				if (clsInit.cVector5.GetEntityCustomData(baseEntity).CurveType == entitySplineType.BsplineCubic)
				{
					Point3D[] controlPoints = curve.ControlPoints;
					Ent = new Curve(3, controlPoints);
				}
			}
			else
			{
				Point3D[] controlPoints = curve.ControlPoints;
				Ent = new Curve(2, controlPoints);
			}
		}
		else
		{
			Point3D[] controlPoints = curve.ControlPoints;
			Ent = Curve.CubicSplineInterpolation(buVector5.VerticeToPointsList(controlPoints));
		}
		Ent.EntityData = new CustomData(clsInit.cVector5.GetEntityCustomData(baseEntity));
		Ent.LayerName = baseEntity.LayerName;
		CopyCommonProps(baseEntity, ref Ent);
		((CustomData)Ent.EntityData).EntityName = "Ent" + ccVars.Pages[ccVars.PageIndex].EntityCounter;
		ccVars.Pages[ccVars.PageIndex].EntityCounter++;
	}

