	public void CreateFreeDraw(List<Point3D> Points, EntityDataSet entData, CustomData customData, ref Entity Ent)
	{
		if (Points.Count < 2)
		{
			return;
		}
		if (!clsVar.varInterface.FreeDrawVar.ConverToSpline)
		{
			LinearPath Ent2 = null;
			EntityDataSet entData2 = new EntityDataSet(-1, ccVars.Pages[ccVars.PageIndex].LayerName, ccVars.Pages[ccVars.PageIndex].SceneName, "", "Polyline", null, ccVars.pntBase);
			CreatePolyLine(ccVars.pntDrawDynamicLines, entData2, EntityDataSet.ConvertCustomData(entData2), ref Ent2);
			if (Ent2 != null)
			{
				Ent = Ent2;
			}
		}
		else
		{
			Curve Ent3 = null;
			CreateSpline(Points, clsVar.varInterface.FreeDrawVar.SplineType, entData, customData, ref Ent3);
			Ent = Ent3;
		}
	}

