	public void CreateAndAddVectorText(string Text, double Height, Point3D Points, bool isVectorText)
	{
		string actionName = "VectorText";
		if (!isVectorText)
		{
			actionName = "CustomText";
		}
		int GroupIndex = 0;
		clsInit.cVector5.GetAvailableGroupIndex(ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities, ref GroupIndex);
		for (int i = 0; i <= ccVars.ContourPoints5.Count - 1; i++)
		{
			ccVars.UndoDont = true;
			List<Point3D> copiedPoint = new List<Point3D>();
			List<Point3D> copiedPoint2 = new List<Point3D>();
			buVector5.Copy(ccVars.ContourPoints5[i].Outter, ref copiedPoint2);
			clsInit.cVector5.Move(new Point3D(), new Point3D(Points.X, Points.Y, Points.Z), ref copiedPoint2);
			if (!(ccVars.VectorTextRunVar.DrawAsCurve && isVectorText))
			{
				buVector5.Copy(copiedPoint2, ref copiedPoint);
			}
			else
			{
				List<Point3D> calculatedPoints = new List<Point3D>();
				bool closed = false;
				if (clsInit.cVector5.IsClosed(copiedPoint2))
				{
					copiedPoint2.RemoveAt(copiedPoint2.Count - 1);
					closed = true;
				}
				clsInit.cVector5.BSplineQuadraticUniform(copiedPoint2, 0.1, closed, ref calculatedPoints);
				buVector5.Copy(calculatedPoints, ref copiedPoint);
			}
			LinearPath Ent = null;
			EntityDataSet entData = new EntityDataSet(GroupIndex, ccVars.Pages[ccVars.PageIndex].LayerName, ccVars.Pages[ccVars.PageIndex].SceneName, "", actionName, null, ccVars.pntBase);
			CustomData customData = new CustomData();
			customData.infoString = Text;
			customData.infoHeight = Height;
			customData.infoBasePoint = buVector5.ToPoint3D(Points);
			CreatePolyLine(copiedPoint, entData, customData, ref Ent);
			if (Ent != null)
			{
				AddPolyline(Ent);
			}
			for (int j = 0; j <= ccVars.ContourPoints5[i].Inside.Count - 1; j++)
			{
				ccVars.UndoDont = true;
				copiedPoint2 = new List<Point3D>();
				buVector5.Copy(ccVars.ContourPoints5[i].Inside[j], ref copiedPoint2);
				clsInit.cVector5.Move(new Point3D(), new Point3D(Points.X, Points.Y, Points.Z), ref copiedPoint2);
				copiedPoint = new List<Point3D>();
				buVector5.Copy(copiedPoint2, ref copiedPoint);
				LinearPath Ent2 = null;
				entData = new EntityDataSet(GroupIndex, ccVars.Pages[ccVars.PageIndex].LayerName, ccVars.Pages[ccVars.PageIndex].SceneName, "", actionName, null, ccVars.pntBase);
				customData = new CustomData();
				customData.infoString = Text;
				customData.infoHeight = Height;
				customData.infoBasePoint = buVector5.ToPoint3D(Points);
				CreatePolyLine(copiedPoint, entData, customData, ref Ent2);
				if (Ent2 != null)
				{
					if (!clsVar.appModes_0.TuftingMode.Enable)
					{
						AddPolyline(Ent2);
					}
					else
					{
						clsInit.appTufting.doAddOutlineEntities(Ent2);
					}
				}
			}
		}
	}

