	public void CreateDimensionOrdinate(Point3D StartPoint, Point3D LinePoint, double TextHeight, bool isVertical, Plane refPlane, EntityDataSet entData, CustomData customData, ref OrdinateDim Ent)
	{
		Ent = new OrdinateDim(refPlane, StartPoint, LinePoint, isVertical, TextHeight);
		string text = "( ";
		if (clsVar.varInterface.OrdinateVar.XCoordinate)
		{
			text = text + "X: " + StartPoint.X.ToString("f2");
		}
		if (clsVar.varInterface.OrdinateVar.YCoordinate)
		{
			if (clsVar.varInterface.OrdinateVar.XCoordinate)
			{
				text += " , ";
			}
			text = text + "Y: " + StartPoint.Y.ToString("f2");
		}
		if (clsVar.varInterface.OrdinateVar.ZCoordinate)
		{
			if (clsVar.varInterface.OrdinateVar.XCoordinate | clsVar.varInterface.OrdinateVar.YCoordinate)
			{
				text += " , ";
			}
			text = text + "Z: " + StartPoint.Z.ToString("f2");
		}
		text += " )";
		Ent.EntityData = new CustomData(customData);
		Ent.TextOverride = text;
		Ent.LineTypeMethod = colorMethodType.byLayer;
		Ent.ColorMethod = colorMethodType.byLayer;
		Ent.LineWeightMethod = colorMethodType.byLayer;
		Ent.LayerName = entData.LayerName;
		((CustomData)Ent.EntityData).GroupIdIndex = entData.GroupIDIndex;
		((CustomData)Ent.EntityData).EntityName = "Ent" + ccVars.Pages[ccVars.PageIndex].EntityCounter;
		((CustomData)Ent.EntityData).SceneName = entData.SceneName;
		((CustomData)Ent.EntityData).ActionName = entData.ActionName;
		if (!clsVar.varEntities.DimensionDrawingPropertiesFromLayer)
		{
			Ent.ColorMethod = colorMethodType.byEntity;
			Ent.LineTypeMethod = colorMethodType.byEntity;
			Ent.LineWeightMethod = colorMethodType.byEntity;
			Ent.Color = clsVar.varEntities.DimensionDrawing.Color;
			Ent.LineWeight = clsVar.varEntities.DimensionDrawing.Thickness;
		}
		ccVars.Pages[ccVars.PageIndex].EntityCounter++;
	}

