	public void surfaceRevolveByPath(ref Entity surfEntity)
	{
		CompositeCurve compositeCurve = null;
		SortSettings sortSettings = new SortSettings();
		SortResult Result = new SortResult();
		List<Entity> selectedEntities = new List<Entity>();
		List<Entity> SortedEntities = new List<Entity>();
		SelectionOption selectionOption = new SelectionOption();
		selectionOption.SplitArcIfGreatThen180 = true;
		selectionOption.CircleToArc = true;
		clsInit.appCommand.SelectionToEntities(ref selectedEntities, selectionOption);
		sortSettings.Option.NextGroupRules = SortingNextGroupFindRulesType.NoNextGroup;
		if (ccVars.SelectionOP.ClickList.Count <= 0)
		{
			clsInit.cVector5.SortEntitiesByRefPoint(ccVars.SelectionOP.Selections[0].pntClick, ref selectedEntities, sortSettings, ref SortedEntities, ref Result);
		}
		else
		{
			sortSettings.Option.ClickList = buVector5.ToPoint3D(ccVars.SelectionOP.ClickList);
			clsInit.cVector5.SortEntitiesByRefPoint(ccVars.SelectionOP.ClickList[0], ref selectedEntities, sortSettings, ref SortedEntities, ref Result);
		}
		List<ICurve> list = new List<ICurve>();
		for (int i = 0; i <= SortedEntities.Count - 1; i++)
		{
			if (!(SortedEntities[i] is Curve))
			{
				ICurve item = (ICurve)SortedEntities[i].Clone();
				list.Add(item);
				continue;
			}
			SortedEntities[i].Regen(0.1);
			LinearPath linearPath = new LinearPath(SortedEntities[i].Vertices);
			linearPath.Regen(0.01);
			ICurve item2 = linearPath;
			list.Add(item2);
		}
		compositeCurve = new CompositeCurve(list);
		compositeCurve.Regen(0.01);
		clsInit.cVector5.surfaceRevolveByPath(compositeCurve, Vector3D.AxisX, Point3D.Origin, 0.0, 360.0, ref surfEntity);
	}

	public void surfaceToFaceAsMesh()
	{
		List<Entity> selectedEntities = new List<Entity>();
		SelectionOption selectionOption = new SelectionOption(AllSelected: false);
		selectionOption.Mesh = true;
		selectionOption.Surface = true;
		selectionOption.Brep = true;
		clsInit.appCommand.SelectionToEntities(ref selectedEntities, selectionOption);
		if (selectedEntities.Count <= 0)
		{
			return;
		}
		undoBuffer();
		List<Mesh> list = new List<Mesh>();
		for (int i = 0; i <= selectedEntities.Count - 1; i++)
		{
			List<Mesh> FaceMeshes = new List<Mesh>();
			clsInit.cVector5.SurfaceToFaceAsMesh(selectedEntities[i], ref FaceMeshes);
			list.AddRange(FaceMeshes);
		}
		if (list.Count > 0)
		{
			Delete(applyReset: true);
			for (int j = 0; j <= list.Count - 1; j++)
			{
				list[j].EntityData = new CustomData();
				ccVars.UndoDont = true;
				AddEntity(list[j]);
			}
		}
	}

