	public void EntitiesToCompositeCurve(List<Entity> refEntities, double Regen, ref CompositeCurve Curve)
	{
		List<ICurve> list = new List<ICurve>();
		for (int i = 0; i <= refEntities.Count - 1; i++)
		{
			if (!(refEntities[i] is Curve))
			{
				ICurve item = (ICurve)refEntities[i].Clone();
				list.Add(item);
				continue;
			}
			refEntities[i].Regen(Regen);
			LinearPath linearPath = new LinearPath(refEntities[i].Vertices);
			linearPath.Regen(0.01);
			ICurve item2 = linearPath;
			list.Add(item2);
		}
		Curve = new CompositeCurve(list);
		Curve.Regen(Regen);
	}

	public void CompositeCurveToEntities(CompositeCurve Curve, double Regen, ref List<Entity> refEntities)
	{
		try
		{
			if (refEntities != null)
			{
				refEntities.Clear();
			}
			refEntities = new List<Entity>();
			if (Curve != null && Curve.CurveList != null && Curve.CurveList.Count > 0)
			{
				for (int i = 0; i <= Curve.CurveList.Count - 1; i++)
				{
					Entity entity = (Entity)((Entity)Curve.CurveList[i]).Clone();
					entity.Regen(new RegenParams(Regen));
					entity.EntityData = new CustomData();
					refEntities.Add(entity);
				}
			}
		}
		catch (Exception)
		{
		}
	}

	public void SplitEntitiesByClosedPointList(bool Selected, List<Point3D> Points, ref List<Entity> entSplited)
	{
		LinearPath linearPath = new LinearPath(Points);
		entSplited.Clear();
		entSplited = new List<Entity>();
		for (int i = 0; i <= ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Count - 1; i++)
		{
			ICurve curve = ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[i] as ICurve;
			CustomData customData = ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[i].EntityData as CustomData;
			if (customData.DontUseForCalculation)
			{
				continue;
			}
			Point3D[] array = linearPath.IntersectWith(curve);
			if (array == null || array.Length == 0)
			{
				continue;
			}
			List<Point3D> list = new List<Point3D>();
			list.AddRange(array);
			ICurve[] segments = null;
			curve.SplitBy(list, out segments);
			if (segments != null && segments.Length != 0)
			{
				for (int j = 0; j <= segments.Length - 1; j++)
				{
					Entity entity = (Entity)segments[j];
					entity.LayerName = ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[i].LayerName;
					entity.EntityData = new CustomData();
					entSplited.Add(entity);
				}
				ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[i].Selected = Selected;
			}
		}
	}

	public void AnalyseEntities()
	{
		try
		{
			AnalyseEntitiesResult Result = new AnalyseEntitiesResult();
			List<Entity> copiedEnt = new List<Entity>();
			buVector5.CopyEntities(ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities, ref copiedEnt);
			clsInit.cVector5.AnalyseEntities(copiedEnt, clsVar.varInterface5.AnalyseEntitySetting, ref Result);
			if (!Result.isError)
			{
				return;
			}
			for (int i = 0; i <= copiedEnt.Count - 1; i++)
			{
				ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[i].Selected = copiedEnt[i].Selected;
			}
			ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Invalidate();
			F_AnalyseResult f_AnalyseResult = new F_AnalyseResult();
			f_AnalyseResult.Result = new AnalyseEntitiesResult(Result);
			f_AnalyseResult.Init();
			f_AnalyseResult.ShowDialog();
			if (f_AnalyseResult.PropertiesForm.Result != DialogResult.OK)
			{
				return;
			}
			for (int j = 0; j <= copiedEnt.Count - 1; j++)
			{
				ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[j].Selected = false;
			}
			for (int k = 0; k <= f_AnalyseResult.Result.ErrorList.Count - 1; k++)
			{
				int indexEntity = f_AnalyseResult.Result.ErrorList[k].IndexEntity;
				if (((indexEntity >= 0) & (indexEntity <= ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Count - 1)) && ((f_AnalyseResult.Result.ErrorList[k].Action == AnalyseEntitiesActionType.Delete) & f_AnalyseResult.Result.ErrorList[k].Enable))
				{
					ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[indexEntity].Selected = true;
				}
			}
			ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.DeleteSelected();
		}
		catch (Exception mSException)
		{
			buLog.addLog("", "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: true, "");
		}
	}

	public void DrawingPropertiesUpdate()
	{
		if (ccVars.Pages.Count > 0)
		{
			DrawingPropertiesUpdate(ccVars.Pages[ccVars.PageIndex]);
		}
	}

	public void DrawingPropertiesUpdate(Pages Page)
	{
		if (ccVars.Pages.Count == 0)
		{
			return;
		}
		_ = Page.Form.viewportcad.Materials.Count;
		for (int i = 0; i <= Page.Form.viewportcad.Layers.Count - 1; i++)
		{
			LayerBase5 FoundLayer = null;
			clsInit.cVector5.LayerGetByName(Page.Layers, Page.Form.viewportcad.Layers[i].Name, ref FoundLayer);
			if (FoundLayer != null)
			{
				Layer eyeLayer = Page.Form.viewportcad.Layers[i];
				buConversion5.buLayerToeyeLayer(FoundLayer, ref eyeLayer);
				Page.Form.viewportcad.Layers[i] = eyeLayer;
			}
		}
		for (int j = 0; j <= Page.Form.viewportcad.Blocks.Count - 1; j++)
		{
			for (int k = 0; k <= Page.Form.viewportcad.Blocks[j].Entities.Count - 1; k++)
			{
				if (clsVar.varDisplay.TransperancyOverwrite)
				{
					Page.Form.viewportcad.Blocks[j].Entities[k].Color = Color.FromArgb(clsVar.varDisplay.Transperancy, Page.Form.viewportcad.Blocks[j].Entities[k].Color);
				}
			}
		}
		for (int l = 0; l <= Page.Form.viewportcad.Entities.Count - 1; l++)
		{
			PageScene FoundScene = null;
			bool visible = true;
			clsInit.cVector5.SceneGetByName(Page.Scene, clsInit.cVector5.GetEntityName(Page.Form.viewportcad.Entities[l]), ref FoundScene);
			if (Page.Form.viewportcad.Entities[l].ColorMethod == colorMethodType.byEntity && clsVar.varDisplay.TransperancyOverwrite)
			{
				Page.Form.viewportcad.Entities[l].Color = Color.FromArgb(clsVar.varDisplay.Transperancy, Page.Form.viewportcad.Entities[l].Color);
			}
			if (FoundScene != null && !FoundScene.Visible)
			{
				visible = false;
			}
			Page.Form.viewportcad.Entities[l].Visible = visible;
			FoundScene = null;
		}
		Page.Form.viewportcad.Entities.Regen();
		Page.Form.viewportcad.Invalidate();
	}

	public void SetEntityCountForScene(int Index)
	{
		for (int i = 0; i <= ccVars.Pages[Index].Form.viewportcad.Entities.Count - 1; i++)
		{
			if (ccVars.Pages[Index].Form.viewportcad.Entities[i].EntityData == null)
			{
				continue;
			}
			for (int j = 0; j <= ccVars.Pages[Index].Scene.Count - 1; j++)
			{
				if (clsInit.cVector5.GetEntityName(ccVars.Pages[Index].Form.viewportcad.Entities[i]) == ccVars.Pages[Index].Scene[j].SceneName)
				{
					ccVars.Pages[Index].Scene[j].EntitiesCount++;
					j = 2147483645;
				}
			}
		}
		PagesUpdate(FillPages: false, "");
	}

	public void TransperancyUpdate()
	{
		if (!clsVar.varDisplay.TransperancyOverwrite)
		{
			return;
		}
		for (int i = 0; i <= ccVars.Pages.Count - 1; i++)
		{
			for (int j = 0; j <= ccVars.Pages[ccVars.PageIndex].Layers.Count - 1; j++)
			{
				ccVars.Pages[ccVars.PageIndex].Layers[j].LayerColor = Color.FromArgb(clsVar.varDisplay.Transperancy, ccVars.Pages[ccVars.PageIndex].Layers[j].LayerColor);
				ccVars.Pages[ccVars.PageIndex].Layers[j].Transparency = clsVar.varDisplay.Transperancy;
			}
		}
		DrawingPropertiesUpdate();
	}

	public void VectorTextCreate(string text, Font font, double height, ContentAlignment Alignment, Plane plane, ref List<ContourPoints> contourPoints)
	{
		contourPoints.Clear();
		List<TriangulationPoints> CalculatedPoints = new List<TriangulationPoints>();
		clsInit.cVector.FontToVectorConvert(font, text, buVector5.PlaneToWorkPlane(plane), new Pnt3D(), ref CalculatedPoints);
		new List<List<Pnt3D>>();
		for (int i = 0; i <= CalculatedPoints.Count - 1; i++)
		{
			contourPoints.Add(new ContourPoints(CalculatedPoints[i]));
		}
		List<List<Pnt3D>> list = new List<List<Pnt3D>>();
		for (int j = 0; j <= CalculatedPoints.Count - 1; j++)
		{
			list.Add(CalculatedPoints[j].Points);
		}
		Pnt3D MinPoint = new Pnt3D();
		Pnt3D MaxPoint = new Pnt3D();
		clsInit.cVector.BoxSizeCalculate(list, ref MinPoint, ref MaxPoint);
		double num = MaxPoint.Y - MinPoint.Y;
		double num2 = height / num;
		clsInit.cVector.Scale(new Pnt3D(), num2, num2, 1.0, ScaleX: true, ScaleY: true, ScaleZ: false, ref ccVars.ContourPoints);
		MinPoint = new Pnt3D();
		MaxPoint = new Pnt3D();
		clsInit.cVector.BoxSizeCalculate(ccVars.ContourPoints, ref MinPoint, ref MaxPoint);
		Pnt3D CalcPoint = new Pnt3D();
		clsInit.cVector.AlingementContentPointByPlane(MinPoint, MaxPoint, Alignment, buVector5.PlaneToWorkPlane(ccVars.planeActive), ref CalcPoint);
		clsInit.cVector.Move(CalcPoint, MinPoint, ref ccVars.ContourPoints);
		list.Clear();
	}

	public void CustomTextCreate(string Text, double CharSpace, double SpaceValue, double CharHeight, ContentAlignment Alignment, Plane plane, ref List<ContourPoints5> contourPoints)
	{
		contourPoints.Clear();
		List<buEntity> TextEntities = new List<buEntity>();
		clsInit.appLibrary.doCreateEntitiesFromCustomText(Text, CharSpace, SpaceValue, CharHeight, ref TextEntities);
		Point3D MinPoint = new Point3D();
		Point3D MaxPoint = new Point3D();
		clsInit.cVector5.BoxSizeCalculate(TextEntities, ref MinPoint, ref MaxPoint);
		Point3D CalcPoint = new Point3D();
		clsInit.cVector5.AlingementContentPointByPlane(MinPoint, MaxPoint, Alignment, ccVars.planeActive, ref CalcPoint);
		clsInit.cVector5.Move(MinPoint.X - CalcPoint.X, MinPoint.Y - CalcPoint.Y, MinPoint.Z - CalcPoint.Z, ref TextEntities);
		for (int i = 0; i <= TextEntities.Count - 1; i++)
		{
			ContourPoints5 contourPoints2 = new ContourPoints5();
			contourPoints2.Outter.AddRange(TextEntities[i].Vertices);
			contourPoints.Add(contourPoints2);
		}
	}

