			Text text = (Text)entity;
			Text Ent13 = null;
			num2 = text.Height;
			ccVars.Pages[ccVars.PageIndex].Scene[ccVars.Pages[ccVars.PageIndex].SceneIndex].ScenePlane.Project(text.BoxMin, out s, out t);
			if (Data.Height != 0.0)
			{
				num2 = Data.Height;
			}
			OsnapDeleteByEntityName(clsInit.cVector5.GetEntityCustomData(text).EntityName);
			EntityDataSet entData13 = new EntityDataSet(entity);
			CreateText(text.InsertionPoint, num2, Data.TextString, Simplify: false, clsVar.varInterface.TextVar.Alignment, entData13, EntityDataSet.ConvertCustomData(entData13), ref Ent13);
			ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[EntityIndex] = Ent13;
			DrawingPropertiesUpdate();
			OsnapCalculation(Ent13);
		}
		if (entity is LinearPath && clsInit.cVector5.GetEntityCustomData(entity).ActionName.ToLower() == "vectortext" && Data.TextString.Length > 0)
		{
			num2 = clsInit.cVector5.GetEntityCustomData(entity).infoHeight;
			if (Data.Height != 0.0)
			{
				num2 = Data.Height;
			}
			Font font = (Font)clsVar.varInterface.VectorTextVar.Font.Clone();
			if (Data.TextFont != null)
			{
				font = Data.TextFont;
			}
			clsInit.appCommand.VectorTextCreate(Data.TextString, font, num2, ccVars.VectorTextRunVar.Alignment, ccVars.planeActive, ref ccVars.ContourPoints);
			Delete(applyReset: false);
			CreateAndAddVectorText(Data.TextString, num2, clsInit.cVector5.GetEntityCustomData(entity).infoBasePoint, isVectorText: true);
		}
		if (entity is LinearPath && clsInit.cVector5.GetEntityCustomData(entity).ActionName.ToLower() == "customtext" && Data.TextString.Length > 0)
		{
			num2 = clsInit.cVector5.GetEntityCustomData(entity).infoHeight;
			if (Data.Height != 0.0)
			{
				num2 = Data.Height;
			}
			clsInit.appCommand.CustomTextCreate(Data.TextString, ccVars.CustomTextRunVar.CharSpace, ccVars.CustomTextRunVar.SpaceValue, num2, ccVars.CustomTextRunVar.Alignment, ccVars.planeActive, ref ccVars.ContourPoints5);
			Delete(applyReset: false);
			CreateAndAddVectorText(Data.TextString, num2, clsInit.cVector5.GetEntityCustomData(entity).infoBasePoint, isVectorText: false);
		}
