	public void cmdEventScaleWithForm()
	{
		try
		{
			if (ccVars.SelectionOP.Selections.Count == 0)
			{
				SelectAll();
			}
			F_Scale f_Scale = new F_Scale();
			f_Scale.Settings = new ScaleEventFormVars(clsVar.varInterface5.scaleEventFormVar);
			f_Scale.Init();
			f_Scale.ShowDialog();
			if (f_Scale.Properties.Result == DialogResult.OK)
			{
				clsVar.varInterface5.scaleEventFormVar = new ScaleEventFormVars(f_Scale.Settings);
				Point3D CalcPoint = new Point3D();
				SelectionBoxSizeCalculate();
				clsInit.cVector5.AlingementContentPointByPlane(ccVars.SelectionOP.SelectionBoxMin, ccVars.SelectionOP.SelectionBoxMax, f_Scale.Settings.Alignment, ccVars.planeActive, ref CalcPoint);
				double num = 1.0;
				double num2 = 1.0;
				double scaleRatio = 0.0;
				if (ccVars.SelectionOP.SelectionBoxMax.X - ccVars.SelectionOP.SelectionBoxMin.X > 0.0)
				{
					num = clsVar.varInterface5.scaleEventFormVar.Ratio.X / (ccVars.SelectionOP.SelectionBoxMax.X - ccVars.SelectionOP.SelectionBoxMin.X);
				}
				if (ccVars.SelectionOP.SelectionBoxMax.Y - ccVars.SelectionOP.SelectionBoxMin.Y > 0.0)
				{
					num2 = clsVar.varInterface5.scaleEventFormVar.Ratio.Y / (ccVars.SelectionOP.SelectionBoxMax.Y - ccVars.SelectionOP.SelectionBoxMin.Y);
				}
				if (clsVar.varInterface5.scaleEventFormVar.KeepRatio)
				{
					scaleRatio = ((num > 0.0) ? num : num2);
				}
				Scale(new Point3D(), clsVar.varInterface5.scaleEventFormVar.Alignment, scaleRatio, num, num2, 1.0, clsVar.varInterface5.scaleEventFormVar.KeepRatio, DeleteOriginal: true);
				Reset();
			}
		}
		catch (Exception mSException)
		{
			buLog.addLog("", "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: true, "");
		}
	}

