	public void InsertFromFile(double dX, double dY, double dZ)
	{
		undoBuffer();
		Vector3D v = new Vector3D(dX, dY, dZ);
		for (int i = 0; i <= ccVars.tempEntities.Count - 1; i++)
		{
			ccVars.UndoDont = true;
			Entity Ent = null;
			CreateEntity(ccVars.tempEntities[i], ref Ent);
			if (Ent != null)
			{
				Ent.Translate(v);
				AddEntity(Ent);
			}
		}
		ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Regen();
		Reset();
	}

	public void Join()
	{
		undoBuffer();
		List<buEntity> selectedEntities = new List<buEntity>();
		clsInit.cVector5.SelectedEntitiesToEntityList(ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities, ref selectedEntities);
		if (selectedEntities.Count > 0)
		{
			ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.DeleteSelected();
			SortbuSettings sortbuSettings = new SortbuSettings();
			sortbuSettings.Option.NextGroupRules = SortingNextGroupFindRulesType.ClosestLength;
			List<buEntity> SortedEntities = new List<buEntity>();
			clsInit.cVector5.SortEntitiesByRefPoint(selectedEntities[0].StartPoint, ref selectedEntities, sortbuSettings, ref SortedEntities);
			List<List<buEntity>> SplitedEntitites = new List<List<buEntity>>();
			clsInit.cVector5.EntitiesSplitByUpperLine(SortedEntities, ref SplitedEntitites);
			for (int i = 0; i <= SplitedEntitites.Count - 1; i++)
			{
				buCompositeCurve calcCompositeCurve = null;
				clsInit.cVector5.CreateCompositeCurveFromEntitiesWithCamDirection(SplitedEntitites[i], ref calcCompositeCurve);
				if (calcCompositeCurve != null && calcCompositeCurve.CurveList.Count > 0)
				{
					Entity copiedEntity = null;
					buEntity.Copy(calcCompositeCurve, ref copiedEntity);
					if (copiedEntity != null)
					{
						AddEntity(copiedEntity);
						OsnapCalculation(copiedEntity);
					}
				}
			}
		}
		ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Regen();
		Reset();
	}

	public void MoveZero(string Cmd)
	{
		List<Entity> list = new List<Entity>();
		for (int i = 0; i <= ccVars.SelectionOP.Selections.Count - 1; i++)
		{
			Entity selectedEntity = ccVars.SelectionOP.Selections[i].SelectedEntity;
			list.Add(selectedEntity);
		}
		Point3D MinPoint = new Point3D();
		Point3D MidPoint = new Point3D();
		Point3D MaxPoint = new Point3D();
		clsInit.cVector5.BoxSizeCalculate(list, ref MinPoint, ref MidPoint, ref MaxPoint);
		if (Cmd == "XY")
		{
			Move(new Point3D(MinPoint.X, MinPoint.Y, 0.0), new Point3D());
		}
		if (Cmd == "XYCenter")
		{
			Move(new Point3D(MidPoint.X, MidPoint.Y, 0.0), new Point3D());
		}
		if (Cmd == "ZUp")
		{
			Move(new Point3D(0.0, 0.0, MaxPoint.Z), new Point3D());
		}
		if (Cmd == "ZDown")
		{
			Move(new Point3D(0.0, 0.0, MinPoint.Z), new Point3D());
		}
	}

	public void Move(Point3D pntStart, Point3D pntEnd)
	{
		undoBuffer();
		Vector3D vector3D = new Vector3D(pntStart, pntEnd);
		List<int> list = new List<int>();
		for (int i = 0; i <= ccVars.SelectionOP.Selections.Count - 1; i++)
		{
			Entity selectedEntity = ccVars.SelectionOP.Selections[i].SelectedEntity;
			string entityName = clsInit.cVector5.GetEntityName(selectedEntity);
			OsnapDeleteByEntityName(entityName);
			selectedEntity.Translate(vector3D);
			if (!(selectedEntity is CompositeCurve))
			{
				if (!(selectedEntity is LinearPath))
				{
					if (!(selectedEntity is Text))
					{
						if (selectedEntity is ICurve)
						{
							selectedEntity.Regen(new RegenParams(clsVar.varEntities.RegenDeviation));
						}
					}
					else
					{
						((Text)selectedEntity).Regen(new RegenParams(clsVar.varEntities.RegenDeviation, ccVars.Pages[ccVars.PageIndex].Form.viewportcad));
					}
				}
				else if (clsInit.cVector5.GetEntityCustomData(selectedEntity).infoBasePoint != null)
				{
					clsInit.cVector5.GetEntityCustomData(selectedEntity).infoBasePoint.X = clsInit.cVector5.GetEntityCustomData(selectedEntity).infoBasePoint.X + vector3D.X;
					clsInit.cVector5.GetEntityCustomData(selectedEntity).infoBasePoint.Y = clsInit.cVector5.GetEntityCustomData(selectedEntity).infoBasePoint.Y + vector3D.Y;
					clsInit.cVector5.GetEntityCustomData(selectedEntity).infoBasePoint.Z = clsInit.cVector5.GetEntityCustomData(selectedEntity).infoBasePoint.Z + vector3D.Z;
				}
			}
			else if (clsInit.cVector5.GetEntityCustomData(selectedEntity).infoBasePoint != null)
			{
				clsInit.cVector5.GetEntityCustomData(selectedEntity).infoBasePoint.X = clsInit.cVector5.GetEntityCustomData(selectedEntity).infoBasePoint.X + vector3D.X;
				clsInit.cVector5.GetEntityCustomData(selectedEntity).infoBasePoint.Y = clsInit.cVector5.GetEntityCustomData(selectedEntity).infoBasePoint.Y + vector3D.Y;
				clsInit.cVector5.GetEntityCustomData(selectedEntity).infoBasePoint.Z = clsInit.cVector5.GetEntityCustomData(selectedEntity).infoBasePoint.Z + vector3D.Z;
			}
			OsnapCalculation(selectedEntity);
			list.Add(ccVars.SelectionOP.Selections[i].Index);
		}
		ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Regen();
		Reset();
		if (clsVar.varProgram.EventCommandRepitation)
		{
			SelectedToSelectionAdd(list);
			cmdEventMove();
			ccVars.Moved = true;
		}
	}

	public void Copy(Point3D pntStart, Point3D pntEnd)
	{
		undoBuffer();
		Vector3D v = new Vector3D(pntStart, pntEnd);
		List<int> Values = new List<int>();
		for (int i = 0; i <= ccVars.SelectionOP.Selections.Count - 1; i++)
		{
			if (ccVars.SelectionOP.Selections[i].SelectedEntity.EntityData != null && ccVars.SelectionOP.Selections[i].SelectedEntity.EntityData is CustomData && ((CustomData)ccVars.SelectionOP.Selections[i].SelectedEntity.EntityData).GroupIdIndex >= 0)
			{
				Values.Add(((CustomData)ccVars.SelectionOP.Selections[i].SelectedEntity.EntityData).GroupIdIndex);
			}
		}
		int GroupIndex = -1;
		if (Values.Count > 0)
		{
			Values.Sort();
			buNumeric5.CheckDuplicatedWithPrevious(ref Values);
			if (Values.Count == 1)
			{
				clsInit.cVector5.GetAvailableGroupIndex(ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities, ref GroupIndex);
			}
		}
		bool flag = true;
		if (ccVars.SelectionOP.Selections.Count > 20)
		{
			flag = false;
		}
		for (int j = 0; j <= ccVars.SelectionOP.Selections.Count - 1; j++)
		{
			Entity refEntity = buVector5.CopyEntities(ccVars.SelectionOP.Selections[j].SelectedEntity);
			ccVars.UndoDont = true;
			Entity Ent = null;
			CreateEntity(refEntity, ref Ent);
			if (GroupIndex > 0 && Ent.EntityData != null && Ent.EntityData is CustomData && ((CustomData)Ent.EntityData).GroupIdIndex > 0)
			{
				((CustomData)Ent.EntityData).GroupIdIndex = GroupIndex;
			}
			if (Ent != null)
			{
				Ent.Translate(v);
				AddEntity(Ent, flag);
			}
		}
		if (!flag)
		{
			ThreadCommands.OsnapCalculationAll = true;
		}
		ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Invalidate();
	}

	public void Rotate(Point3D pntBase, double angleInRadian, bool DeleteOriginal, bool CommandRepat)
	{
		undoBuffer();
		List<int> list = new List<int>();
		bool flag = true;
		if (ccVars.SelectionOP.Selections.Count > 20)
		{
			flag = false;
		}
		for (int i = 0; i <= ccVars.SelectionOP.Selections.Count - 1; i++)
		{
			Entity refEntity = buVector5.CopyEntities(ccVars.SelectionOP.Selections[i].SelectedEntity);
			ccVars.UndoDont = true;
			Entity Ent = null;
			CreateEntity(refEntity, ref Ent);
			if (Ent != null)
			{
				Ent.Rotate(angleInRadian, ccVars.planeActive.AxisZ, pntBase);
				AddEntity(Ent, flag);
			}
			list.Add(ccVars.SelectionOP.Selections[i].Index);
		}
		if (DeleteOriginal)
		{
			Delete(applyReset: true);
			list.Clear();
		}
		if (!flag)
		{
			ThreadCommands.OsnapCalculationAll = true;
		}
		Reset();
		if (CommandRepat)
		{
			SelectedToSelectionAdd(list);
			cmdEventRotate();
		}
	}

	public void RotateVector(Point3D pntBase)
	{
		undoBuffer();
		bool flag = true;
		if (ccVars.SelectionOP.Selections.Count > 20)
		{
			flag = false;
		}
		for (int i = 0; i <= ccVars.SelectionOP.Selections.Count - 1; i++)
		{
			Entity refEntity = buVector5.CopyEntities(ccVars.SelectionOP.Selections[i].SelectedEntity);
			ccVars.UndoDont = true;
			Entity Ent = null;
			CreateEntity(refEntity, ref Ent);
			if (Ent == null)
			{
				continue;
			}
			if (clsVar.varInterface.RotateVectorVar.Axis != VectorType.XVector)
			{
				if (clsVar.varInterface.RotateVectorVar.Axis != VectorType.YVector)
				{
					Ent.Rotate(buConversion5.DegreeToRadian(clsVar.varInterface.RotateVectorVar.Angle), new Vector3D(0.0, 0.0, 1.0), pntBase);
				}
				else
				{
					Ent.Rotate(buConversion5.DegreeToRadian(clsVar.varInterface.RotateVectorVar.Angle), new Vector3D(0.0, 1.0, 0.0), pntBase);
				}
			}
			else
			{
				Ent.Rotate(buConversion5.DegreeToRadian(clsVar.varInterface.RotateVectorVar.Angle), new Vector3D(1.0, 0.0, 0.0), pntBase);
			}
			AddEntity(Ent, flag);
		}
		if (clsVar.varInterface.RotateVar.DeleteOriginal)
		{
			Delete(applyReset: true);
		}
		if (!flag)
		{
			ThreadCommands.OsnapCalculationAll = true;
		}
