	public void RotateClick(Point3D pntBase)
	{
		undoBuffer();
		List<int> list = new List<int>();
		for (int i = 0; i <= ccVars.SelectionOP.Selections.Count - 1; i++)
		{
			Entity entity = ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[ccVars.SelectionOP.Selections[i].Index];
