	public void Mirror(Point3D pntBase, Point3D pntTip, bool DeleteOriginal, bool CommandRepat, bool ApplyReset)
	{
		undoBuffer();
		Vector3D x = new Vector3D(pntBase, pntTip);
		Plane plane = new Plane(ccVars.pntBase, x, ccVars.planeActive.AxisZ);
		List<int> list = new List<int>();
		bool flag = true;
		if (ccVars.SelectionOP.Selections.Count > 20)
		{
			flag = false;
		}
		for (int i = 0; i <= ccVars.SelectionOP.Selections.Count - 1; i++)
		{
			Entity refEntity = buVector5.CopyEntities(ccVars.SelectionOP.Selections[i].SelectedEntity);
			ccVars.UndoDont = true;
			Entity Ent = null;
			CreateEntity(refEntity, ref Ent);
			if (Ent != null)
			{
				Mirror xform = new Mirror(plane);
				Ent.TransformBy(xform);
				AddEntity(Ent, flag);
			}
		}
		if (DeleteOriginal)
		{
			Delete(ApplyReset);
			list.Clear();
		}
		if (ApplyReset)
		{
			Reset();
		}
		if (!flag)
		{
			ThreadCommands.OsnapCalculationAll = true;
		}
		if (CommandRepat)
		{
			SelectedToSelectionAdd(list);
			cmdEventMirror();
		}
	}

	public void Exchange()
	{
		undoBuffer();
		Entity selectedEntity = ccVars.SelectionOP.Selections[0].SelectedEntity;
		Entity selectedEntity2 = ccVars.SelectionOP.Selections[1].SelectedEntity;
		Pnt3D CalcPoint = new Pnt3D();
		Pnt3D CalcPoint2 = new Pnt3D();
		clsInit.cVector.AlingementContentPointByPlane(buConversion5.Point3DToPnt3D(selectedEntity.BoxMin), buConversion5.Point3DToPnt3D(selectedEntity.BoxMax), clsVar.varInterface.ExchangeVar.FirstGroupAlingement, buVector5.PlaneToWorkPlane(ccVars.planeActive), ref CalcPoint);
		clsInit.cVector.AlingementContentPointByPlane(buConversion5.Point3DToPnt3D(selectedEntity2.BoxMin), buConversion5.Point3DToPnt3D(selectedEntity2.BoxMax), clsVar.varInterface.ExchangeVar.SecondGroupAlingement, buVector5.PlaneToWorkPlane(ccVars.planeActive), ref CalcPoint2);
		Point3D point3D = new Point3D(CalcPoint.X, CalcPoint.Y, CalcPoint.Z);
		Point3D point3D2 = new Point3D(CalcPoint2.X, CalcPoint2.Y, CalcPoint2.Z);
		string entityName = clsInit.cVector5.GetEntityName(selectedEntity);
		string entityName2 = clsInit.cVector5.GetEntityName(selectedEntity2);
		OsnapDeleteByEntityName(entityName);
		OsnapDeleteByEntityName(entityName2);
		Vector3D v = new Vector3D(point3D, point3D2);
		selectedEntity.Translate(v);
		OsnapCalculation(selectedEntity);
		v = new Vector3D(point3D2, point3D);
		selectedEntity2.Translate(v);
		OsnapCalculation(selectedEntity2);
		ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Regen();
		Reset();
		PagesUpdate(FillPages: true, "");
		if (clsVar.varProgram.EventCommandRepitation)
		{
			cmdEventExchange();
		}
	}

	public void LinearArray(Point3D pntEnd, bool OkButton)
	{
		undoBuffer();
		if (OkButton)
		{
			for (int i = 0; i <= clsVar.varInterface.ArrayLineerVar.LevelCountZ - 1; i++)
			{
				for (int j = 0; j <= clsVar.varInterface.ArrayLineerVar.RowsCountY - 1; j++)
				{
					for (int k = 0; k <= clsVar.varInterface.ArrayLineerVar.ColomnsCountX - 1; k++)
					{
						if (!(i > 0 || k > 0 || j > 0))
						{
							continue;
						}
						for (int l = 0; l <= ccVars.SelectionOP.Selections.Count - 1; l++)
						{
							Entity refEntity = buVector5.CopyEntities(ccVars.SelectionOP.Selections[l].SelectedEntity);
							ccVars.UndoDont = true;
							Entity Ent = null;
							CreateEntity(refEntity, ref Ent);
							Vector3D vector3D = new Vector3D();
							vector3D.X = clsVar.varInterface.ArrayLineerVar.ColomnsDistanceX * (double)k;
							vector3D.Y = clsVar.varInterface.ArrayLineerVar.RowDistanceY * (double)j;
							vector3D.Z = clsVar.varInterface.ArrayLineerVar.LevelDistanceZ * (double)i;
							if (Ent != null)
							{
								Ent.Translate(vector3D);
								AddEntity(Ent);
							}
						}
					}
				}
			}
		}
		else
		{
			Pnt3D CalcPoint = new Pnt3D();
			clsInit.cVector.AlingementContentPointByPlane(buConversion5.Point3DToPnt3D(ccVars.SelectionOP.SelectionBoxMin), buConversion5.Point3DToPnt3D(ccVars.SelectionOP.SelectionBoxMax), clsVar.varInterface.ArrayLineerVar.Alingement, buVector5.PlaneToWorkPlane(ccVars.planeActive), ref CalcPoint);
			Point3D p = new Point3D(CalcPoint.X, CalcPoint.Y, CalcPoint.Z);
			for (int m = 0; m <= clsVar.varInterface.ArrayLineerVar.LevelCountZ - 1; m++)
			{
				for (int n = 0; n <= clsVar.varInterface.ArrayLineerVar.RowsCountY - 1; n++)
				{
					for (int num = 0; num <= clsVar.varInterface.ArrayLineerVar.ColomnsCountX - 1; num++)
					{
						if (!(m > 0 || num > 0 || n > 0))
						{
							continue;
						}
						for (int num2 = 0; num2 <= ccVars.SelectionOP.Selections.Count - 1; num2++)
						{
							Entity refEntity2 = buVector5.CopyEntities(ccVars.SelectionOP.Selections[num2].SelectedEntity);
							ccVars.UndoDont = true;
							Entity Ent2 = null;
							CreateEntity(refEntity2, ref Ent2);
							Vector3D vector3D2 = new Vector3D(p, pntEnd);
							vector3D2.X *= num;
							vector3D2.Y *= n;
							vector3D2.Z *= m;
							if (Ent2 != null)
							{
								Ent2.Translate(vector3D2);
								AddEntity(Ent2);
							}
						}
					}
				}
			}
		}
		Reset();
	}

	public void PolarArray(Point3D pntCenter)
	{
		undoBuffer();
		for (int i = 1; i <= clsVar.varInterface.ArrayPolarVar.ItemCount - 1; i++)
		{
			for (int j = 0; j <= ccVars.SelectionOP.Selections.Count - 1; j++)
			{
				Entity refEntity = buVector5.CopyEntities(ccVars.SelectionOP.Selections[j].SelectedEntity);
				ccVars.UndoDont = true;
				Entity Ent = null;
				CreateEntity(refEntity, ref Ent);
				double num = (double)i * clsVar.varInterface.ArrayPolarVar.ItemAngle;
				if (clsVar.varInterface.ArrayPolarVar.Direction == ClockDirectionType.CW)
				{
					num *= -1.0;
				}
				if (Ent != null)
				{
					Ent.Rotate(Utility.DegToRad(num), ccVars.planeActive.AxisZ, pntCenter);
					AddEntity(Ent);
				}
			}
		}
		Reset();
	}

	public void Scale(Point3D pntEnd, ContentAlignment Alignmet, double ScaleRatio, double sX, double sY, double sZ, bool KeepRatio, bool DeleteOriginal)
	{
		undoBuffer();
		Pnt3D CalcPoint = new Pnt3D();
		Vec3D Size = new Vec3D();
		clsInit.cVector.AlingementContentPointByPlane(buConversion5.Point3DToPnt3D(ccVars.SelectionOP.SelectionBoxMin), buConversion5.Point3DToPnt3D(ccVars.SelectionOP.SelectionBoxMax), Alignmet, buVector5.PlaneToWorkPlane(ccVars.planeActive), ref CalcPoint, ref Size);
		Point3D point3D = new Point3D(CalcPoint.X, CalcPoint.Y, CalcPoint.Z);
		double num = Math.Sqrt(Size.X * Size.X + Size.Y * Size.Y + Size.Z * Size.Z);
		double sx = 1.0;
		double sy = 1.0;
		double num2 = 1.0;
		if (Size.X > 0.0)
		{
			sx = Math.Abs(pntEnd.X - point3D.X) / Size.X;
		}
		if (Size.Y > 0.0)
		{
			sy = Math.Abs(pntEnd.Y - point3D.Y) / Size.Y;
		}
		if (Size.Z > 0.0)
		{
			num2 = Math.Abs(pntEnd.Z - point3D.Z) / Size.Z;
		}
		if (num2 == 0.0)
		{
			num2 = 1.0;
		}
		if (!(sX > 0.0 && sY > 0.0))
		{
			if (!(sX > 0.0 && sZ > 0.0))
			{
				if (sY > 0.0 && sZ > 0.0)
				{
					sx = 1.0;
					sy = sY;
					num2 = sZ;
				}
			}
			else
			{
				sx = sX;
				sy = 1.0;
				num2 = sZ;
			}
		}
		else
		{
			sx = sX;
			sy = sY;
			num2 = 1.0;
		}
		if (clsVar.varEntities.ScaleMode == ScaleType.Size && !KeepRatio)
		{
			sx = 1.0;
			sy = 1.0;
			num2 = 1.0;
			if (!((buVector5.isPlaneXZorZX(ccVars.planeActive) && sX > 0.0 && sZ > 0.0) & (Size.X > 0.0) & (Size.Z > 0.0)))
			{
				if (!((buVector5.isPlaneYZorZY(ccVars.planeActive) && sY > 0.0 && sZ > 0.0) & (Size.Y > 0.0) & (Size.Z > 0.0)))
				{
					if ((sX > 0.0 && sY > 0.0) & (Size.X > 0.0) & (Size.Y > 0.0))
					{
						sx = sX / Size.X;
						sy = sY / Size.Y;
					}
				}
				else
				{
					sy = sY / Size.Y;
					num2 = sZ / Size.Z;
				}
			}
			else
			{
				sx = sX / Size.X;
				num2 = sZ / Size.Z;
			}
		}
		double num3 = 1.0;
		num3 = ((buNumeric.IsNumeric(num.ToString()) && num != 0.0) ? (point3D.DistanceTo(pntEnd) / num) : (point3D.DistanceTo(pntEnd) / point3D.DistanceTo(ccVars.SelectionOP.SelectionBoxMax)));
		if (ScaleRatio != 0.0 && ScaleRatio > 0.0)
		{
			num3 = ScaleRatio;
		}
		ccVars.pntDrawDynamicLinesArr.Clear();
		if (!KeepRatio)
		{
			for (int i = 0; i <= ccVars.SelectionOP.Selections.Count - 1; i++)
			{
				Entity entity = buVector5.CopyEntities(ccVars.SelectionOP.Selections[i].SelectedEntity);
				if ((entity.GetType() != typeof(Line)) & (entity.GetType() != typeof(LinearPath)) & (entity.GetType() != typeof(Text)) & (entity.GetType() != typeof(MultilineText)))
				{
					entity.Regen(clsVar.varEntities.RegenDeviation);
					entity = new LinearPath(entity.Vertices);
					entity.LayerName = ccVars.SelectionOP.Selections[i].SelectedEntity.LayerName;
				}
				ccVars.UndoDont = true;
				Entity Ent = null;
				CreateEntity(entity, ref Ent);
				Ent.Scale(point3D, sx, sy, num2);
				AddEntity(Ent);
			}
		}
		else
		{
			for (int j = 0; j <= ccVars.SelectionOP.Selections.Count - 1; j++)
			{
				Entity refEntity = buVector5.CopyEntities(ccVars.SelectionOP.Selections[j].SelectedEntity);
				ccVars.UndoDont = true;
				Entity Ent2 = null;
				CreateEntity(refEntity, ref Ent2);
				Ent2.Scale(point3D, num3);
				AddEntity(Ent2);
			}
		}
		if (DeleteOriginal)
		{
			Delete(applyReset: true);
		}
		Reset();
	}

	public void Offset(Point3D pntEnd)
	{
		undoBuffer();
		int num = 0;
		Vector3D vector3D = null;
		while (true)
		{
			int count = ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Count;
			for (int i = 0; i <= ccVars.SelectionOP.Selections.Count - 1; i++)
			{
				Entity entity = buVector5.CopyEntities(ccVars.SelectionOP.Selections[i].SelectedEntity);
				ccVars.UndoDont = true;
				if (!(entity is ICurve))
				{
					continue;
				}
				List<Point2D> list = new List<Point2D>();
				List<Point3D> list2 = new List<Point3D>();
				list2.AddRange(entity.Vertices);
				if (list2.Count >= 3)
				{
					Point3D pntIntersect = new Point3D();
					clsInit.cVector5.LineLineIntersection(list2[0], list2[1], list2[list2.Count - 2], list2[list2.Count - 1], ccVars.planeActive, ref pntIntersect);
					double num2 = Point3D.Distance(pntIntersect, list2[0]);
					double num3 = Point3D.Distance(pntIntersect, list2[list2.Count - 1]);
					if ((num2 < clsVar.varInterface.OffsetVar.Offset) | (num3 < clsVar.varInterface.OffsetVar.Offset))
					{
						list2[0] = buVector5.ToPoint3D(pntIntersect);
						list2[list2.Count - 1] = buVector5.ToPoint3D(pntIntersect);
					}
				}
				for (int j = 0; j <= list2.Count - 1; j++)
				{
					list.Add(ccVars.planeActive.Project(entity.Vertices[j]));
