					ICurve[] array = linearPath.QuickOffset(clsVar.varInterface.OffsetVar.Offset, ccVars.planeActive, cornerType.Flat, 0.01, 0.1);
					ICurve[] array2 = linearPath.QuickOffset(0.0 - clsVar.varInterface.OffsetVar.Offset, ccVars.planeActive, cornerType.Flat, 0.01, 0.1);
