	public void Break(Point3D pntEnd)
	{
		if (!((ccVars.OsnapCatchPoint.UnderEntityIndex >= 0) & (ccVars.OsnapCatchPoint.UnderEntityIndex <= ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Count - 1)))
		{
			return;
		}
		undoBuffer();
		Entity entity = ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[ccVars.OsnapCatchPoint.UnderEntityIndex];
		if (entity is ICurve)
		{
			if (clsVar.appModes_0.TuftingMode.Enable && clsTufting.varTuftingRunSettings.BreakTuftCurve)
			{
				clsInit.appTufting.DeleteArrowByReleatedEntityName(((CustomData)entity.EntityData).EntityName);
				clsInit.appTufting.DeleteMarkerByReleatedEntityName(((CustomData)entity.EntityData).EntityName);
			}
			string actionName = ((CustomData)entity.EntityData).ActionName;
			if (clsVar.varInterface.BreakVar.Type != BreakEntityType.ByClick)
			{
				if (clsVar.varInterface.BreakVar.Type != BreakEntityType.ByNumber)
				{
					if (clsVar.varInterface.BreakVar.Type == BreakEntityType.ByLength)
					{
						double num = ((ICurve)entity).Length();
						int num2 = Convert.ToInt32(num / clsVar.varInterface.BreakVar.Length);
						List<double> Values = new List<double>();
						List<Point3D> list = new List<Point3D>();
						buNumeric.DevideMinMaxValueByNumber(((ICurve)entity).Domain.t0, ((ICurve)entity).Domain.t1, num2 + 1, ref Values);
						for (int i = 0; i <= Values.Count - 1; i++)
						{
							list.Add(((ICurve)entity).PointAt(Values[i]));
						}
						Values.RemoveAt(Values.Count - 1);
						Values.RemoveAt(0);
						ICurve[] segments = null;
						((ICurve)entity).SplitBy(list, out segments);
						if (segments != null && segments.Length != 0)
						{
							EntityDataSet entData = new EntityDataSet(entity);
							for (int j = 0; j <= segments.Length - 1; j++)
							{
								ccVars.UndoDont = true;
								Entity Ent = null;
								Entity entity2 = (Entity)segments[j];
								entity2.EntityData = EntityDataSet.ConvertCustomData(entData);
								CreateEntity(entity2, ref Ent);
								if (Ent != null)
