							entity.Selected = true;
							string entityName = clsInit.cVector5.GetEntityName(entity);
							OsnapDeleteByEntityName(entityName);
							Delete(applyReset: true);
						}
					}
				}
				else
				{
					double t = 0.0;
					double t2 = 0.0;
					((ICurve)entity).ClosestPointTo(((ICurve)entity).StartPoint, out t);
					((ICurve)entity).ClosestPointTo(((ICurve)entity).EndPoint, out t2);
					List<double> Values2 = new List<double>();
					List<Point3D> list2 = new List<Point3D>();
					buNumeric.DevideMinMaxValueByNumber(t, t2, (int)clsVar.varInterface.BreakVar.Count + 1, ref Values2);
					for (int k = 0; k <= Values2.Count - 1; k++)
					{
						list2.Add(((ICurve)entity).PointAt(Values2[k]));
					}
					Values2.RemoveAt(Values2.Count - 1);
					Values2.RemoveAt(0);
					ICurve[] segments2 = null;
					((ICurve)entity).SplitBy(list2, out segments2);
					if (segments2 != null)
					{
						EntityDataSet entData2 = new EntityDataSet(entity);
						for (int l = 0; l <= segments2.Length - 1; l++)
						{
							ccVars.UndoDont = true;
							Entity Ent2 = null;
							Entity entity3 = (Entity)segments2[l];
							entity3.EntityData = EntityDataSet.ConvertCustomData(entData2);
							CreateEntity(entity3, ref Ent2);
							if (Ent2 != null)
							{
								AddEntity(Ent2);
							}
						}
						entity.Selected = true;
						string entityName2 = clsInit.cVector5.GetEntityName(entity);
						OsnapDeleteByEntityName(entityName2);
						Delete(applyReset: true);
					}
				}
			}
			else
			{
				((ICurve)entity).ClosestPointTo(ccVars.OsnapCatchPoint.EntityPoint, out var t3);
				ICurve lower = null;
				ICurve upper = null;
				((ICurve)entity).SplitAt(t3, out lower, out upper);
				if (lower != null && upper != null)
				{
					if (clsInit.appTufting != null)
					{
						clsInit.appTufting.DeleteAllMarkerPoint();
					}
					Entity Ent3 = null;
					EntityDataSet entData3 = new EntityDataSet(entity);
					((Entity)lower).EntityData = EntityDataSet.ConvertCustomData(entData3);
					CreateEntity((Entity)lower, ref Ent3);
					if (Ent3 != null)
					{
						((CustomData)Ent3.EntityData).ActionName = actionName;
						Ent3.LayerName = entity.LayerName;
						AddEntity(Ent3);
					}
					Entity Ent4 = null;
					((Entity)upper).EntityData = EntityDataSet.ConvertCustomData(entData3);
					CreateEntity((Entity)upper, ref Ent4);
					if (Ent4 != null)
					{
						((CustomData)Ent4.EntityData).ActionName = actionName;
						Ent4.LayerName = entity.LayerName;
						AddEntity(Ent4);
					}
					entity.Selected = true;
					string entityName3 = clsInit.cVector5.GetEntityName(entity);
					OsnapDeleteByEntityName(entityName3);
					Delete(applyReset: true);
					if (!clsVar.appModes_0.TuftingMode.Enable)
