	public void Trim(Point3D pntEnd)
	{
		List<double> Points = new List<double>();
		ICurve[] segments = null;
		if (((ccVars.OsnapCatchPoint.UnderEntityIndex >= 0) & (ccVars.OsnapCatchPoint.UnderEntityIndex <= ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Count - 1)) && ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[ccVars.OsnapCatchPoint.UnderEntityIndex] is ICurve)
		{
			ICurve curve = (ICurve)ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[ccVars.OsnapCatchPoint.UnderEntityIndex].Clone();
			for (int i = 0; i <= ccVars.Pages[ccVars.PageIndex].OsnapPoints.Count - 1; i++)
			{
				if (ccVars.Pages[ccVars.PageIndex].OsnapPoints[i].Type == osnapType.Intersection)
				{
					double t = 0.0;
					curve.ClosestPointTo(ccVars.Pages[ccVars.PageIndex].OsnapPoints[i], out t);
					double num = Point3D.Distance(ccVars.Pages[ccVars.PageIndex].OsnapPoints[i], curve.PointAt(t));
					if (num < 0.01)
					{
						Points.Add(t);
					}
				}
			}
			double num2 = 1.0;
			if (Points.Count == 0)
			{
				List<OsnapPoint> OsnapPoints = new List<OsnapPoint>();
				clsInit.cVector5.IntersectionOfEntities(ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.ToList(), (Entity)curve, ccVars.OsnapCatchPoint.UnderEntityIndex, 0, ref OsnapPoints);
				for (int j = 0; j <= OsnapPoints.Count - 1; j++)
				{
					if (OsnapPoints[j].Type == osnapType.Intersection)
					{
						double t2 = 0.0;
						curve.ClosestPointTo(OsnapPoints[j], out t2);
						double num3 = Point3D.Distance(OsnapPoints[j], curve.PointAt(t2));
						if (num3 < 0.01)
						{
							Points.Add(t2);
						}
					}
				}
			}
			if (Points.Count > 0)
			{
				Points.Sort();
				buNumeric.CheckDuplicatedPointsWithPrevious(ref Points, 0.001);
				curve.ClosestPointTo(pntEnd, out var t3);
				num2 = Point3D.Distance(pntEnd, curve.PointAt(t3));
				num2 += num2 / 1000.0;
				if (!(t3 <= Points[0]))
				{
					if (!(t3 > Points[Points.Count - 1]))
					{
						for (int k = 0; k < Points.Count - 1; k++)
						{
							if (!(t3 <= Points[k]) && t3 <= Points[k + 1])
							{
								curve.SplitBy(new Point3D[2]
								{
									curve.PointAt(Points[k]),
									curve.PointAt(Points[k + 1])
								}, out segments);
							}
						}
					}
					else
					{
						curve.SplitBy(new Point3D[1] { curve.PointAt(Points[Points.Count - 1]) }, out segments);
					}
				}
				else
				{
					curve.SplitBy(new Point3D[1] { curve.PointAt(Points[0]) }, out segments);
				}
				undoBuffer();
				foreach (ICurve curve2 in segments)
				{
					curve2.ClosestPointTo(pntEnd, out var t4);
					if (!((t4 > curve2.Domain.t0) & (t4 < curve2.Domain.t1)))
					{
						if (((Entity)curve2).Vertices == null)
						{
							((Entity)curve2).Regen(new RegenParams(clsVar.varEntities.RegenDeviation));
						}
						Entity Ent = null;
						EntityDataSet entData = new EntityDataSet((Entity)curve);
						Entity entity = (Entity)curve2;
						entity.EntityData = EntityDataSet.ConvertCustomData(entData);
						CreateEntity(entity, ref Ent);
						if (Ent != null)
						{
							AddEntity(Ent);
						}
					}
					else if (((Entity)curve2).Vertices == null)
					{
						((Entity)curve2).Regen(new RegenParams(clsVar.varEntities.RegenDeviation));
					}
				}
				string entityName = clsInit.cVector5.GetEntityName(ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[ccVars.OsnapCatchPoint.UnderEntityIndex]);
				OsnapDeleteByEntityName(entityName);
				ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[ccVars.OsnapCatchPoint.UnderEntityIndex].Selected = true;
				Delete(applyReset: false);
			}
		}
		if (!clsVar.varProgram.EventCommandRepitation & !clsVar.varEntities.ContinuesTrim)
		{
			Reset();
		}
	}

	public void Extend(Point3D pntEnd)
	{
		if (((ccVars.OsnapCatchPoint.UnderEntityIndex >= 0) & (ccVars.OsnapCatchPoint.UnderEntityIndex <= ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Count - 1)) && ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[ccVars.OsnapCatchPoint.UnderEntityIndex] is ICurve)
		{
			ICurve curve = (ICurve)ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[ccVars.OsnapCatchPoint.UnderEntityIndex].Clone();
			ICurve icurve_ = null;
			double num = Point3D.Distance(curve.StartPoint, pntEnd);
			double num2 = Point3D.Distance(curve.EndPoint, pntEnd);
			bool flag = false;
			if (!(curve is Line))
			{
				if (!(curve is LinearPath))
				{
					if (curve is Arc)
					{
						if (!(num < num2))
						{
							EntityList entities = ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities;
							int underEntityIndex = ccVars.OsnapCatchPoint.UnderEntityIndex;
							List<Point3D> list_ = new List<Point3D>();
							double length = clsVar.varInterface.ExtendVar.Length;
							flag = Class5.smethod_128(length, list_, underEntityIndex, ref icurve_, entities, this, curve, false);
						}
						else
						{
							EntityList entities = ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities;
							int underEntityIndex = ccVars.OsnapCatchPoint.UnderEntityIndex;
							List<Point3D> list_ = new List<Point3D>();
							double length = clsVar.varInterface.ExtendVar.Length;
							flag = Class5.smethod_128(length, list_, underEntityIndex, ref icurve_, entities, this, curve, true);
						}
						if (flag && icurve_ != null)
