	public void Devide()
	{
		undoBuffer();
		for (int i = 0; i <= ccVars.SelectionOP.Selections.Count - 1; i++)
		{
			_ = ccVars.SelectionOP.Selections[i].Index;
			Entity selectedEntity = ccVars.SelectionOP.Selections[i].SelectedEntity;
			bool flag = false;
			double num = 0.0;
			List<Entity> entitiesDevided = new List<Entity>();
			List<ICurve> list = new List<ICurve>();
			if (clsVar.varInterface.ExplodeVar.UnGroup)
			{
				selectedEntity.GroupIndex = -1;
			}
			if (selectedEntity.GetType() == typeof(Circle))
			{
				flag = clsVar.varInterface5.devideEventFormVar.CircleEnable;
				num = clsVar.varInterface5.devideEventFormVar.CircleLength;
			}
			if (selectedEntity.GetType() == typeof(Arc))
			{
				flag = clsVar.varInterface5.devideEventFormVar.ArcEnable;
				num = clsVar.varInterface5.devideEventFormVar.ArcLength;
			}
			if (selectedEntity.GetType() == typeof(Line))
			{
				flag = clsVar.varInterface5.devideEventFormVar.LineEnable;
				num = clsVar.varInterface5.devideEventFormVar.LineLength;
			}
			if ((selectedEntity.GetType() == typeof(Ellipse)) | (selectedEntity.GetType() == typeof(EllipticalArc)))
			{
				flag = clsVar.varInterface5.devideEventFormVar.EllipseEnable;
				num = clsVar.varInterface5.devideEventFormVar.EllipseLength;
			}
			if (selectedEntity.GetType() == typeof(Curve))
			{
				flag = clsVar.varInterface5.devideEventFormVar.CurveEnable;
				num = clsVar.varInterface5.devideEventFormVar.CurveLength;
			}
			if (selectedEntity.GetType() == typeof(LinearPath))
			{
				flag = clsVar.varInterface5.devideEventFormVar.PolylineEnable;
				num = clsVar.varInterface5.devideEventFormVar.PolylineLength;
			}
			if (selectedEntity.GetType() == typeof(CompositeCurve))
			{
				flag = clsVar.varInterface5.devideEventFormVar.CompositeCurveEnable;
				num = clsVar.varInterface5.devideEventFormVar.CompositeCurveLength;
				list = ((CompositeCurve)selectedEntity).CurveList;
			}
			if (!(flag && num > 0.0))
			{
				continue;
			}
			if (list.Count != 0)
			{
				for (int j = 0; j <= list.Count - 1; j++)
				{
					Entity copiedEntity = null;
					buEntity.Copy((Entity)list[j], ref copiedEntity);
					clsInit.cVector5.EntityDevide(copiedEntity, num, clsVar.varInterface5.devideEventFormVar.ConvertAllToPolyline, ref entitiesDevided);
					for (int k = 0; k <= entitiesDevided.Count - 1; k++)
					{
						ccVars.UndoDont = true;
						AddEntity(entitiesDevided[k]);
					}
				}
			}
			else
			{
				clsInit.cVector5.EntityDevide(selectedEntity, num, clsVar.varInterface5.devideEventFormVar.ConvertAllToPolyline, ref entitiesDevided);
				for (int l = 0; l <= entitiesDevided.Count - 1; l++)
				{
					ccVars.UndoDont = true;
					AddEntity(entitiesDevided[l]);
				}
			}
		}
		ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Regen();
		ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.DeleteSelected();
		Delete(applyReset: true);
		Reset(ClearSelection: true, ReDraw: true);
	}

	public void GroupAdd()
	{
		try
		{
			if (ccVars.Pages.Count > 0)
			{
				undoBuffer();
				int GroupIndex = -1;
				clsInit.cVector5.GetAvailableGroupIndex(ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities, ref GroupIndex);
				for (int i = 0; i <= ccVars.SelectionOP.Selections.Count - 1; i++)
				{
					int index = ccVars.SelectionOP.Selections[i].Index;
					((CustomData)ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index].EntityData).GroupIdIndex = GroupIndex;
				}
				Reset();
			}
		}
		catch (Exception mSException)
		{
			buLog.addLog("", "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: true, "");
		}
	}

	public void GroupRemove()
	{
		if (ccVars.Pages.Count > 0)
		{
			undoBuffer();
			for (int i = 0; i <= ccVars.SelectionOP.Selections.Count - 1; i++)
			{
				int index = ccVars.SelectionOP.Selections[i].Index;
				_ = ccVars.SelectionOP.Selections[i].SelectedEntity;
				((CustomData)ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index].EntityData).GroupIdIndex = -1;
			}
			Reset();
		}
	}

	internal Point3D method_0(Point3D point3D_0, List<Point3D> list_0)
	{
		double num = double.MaxValue;
		Point3D result = null;
		foreach (Point3D item in list_0)
		{
			double num2 = Point3D.DistanceSquared(point3D_0, item);
			if (!(num2 >= num) && !point3D_0.Equals(item))
			{
				num = num2;
				result = item;
			}
		}
		return result;
	}

