	public void SetLockPropertiesForAllEntities()
	{
		for (int i = 0; i <= ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Count - 1; i++)
		{
			LayerProperties Props = new LayerProperties();
			if (clsInit.cVector5.GetLayerPropertiesFromName(ccVars.Pages[ccVars.PageIndex].Layers, ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[i].LayerName, ref Props))
			{
				ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[i].Selectable = !Props.isLock;
				if (ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[i].EntityData != null)
				{
					((CustomData)ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[i].EntityData).DontUseForCalculation = Props.isLock;
				}
			}
		}
		ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Regen();
		ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Invalidate();
	}

