		Properties.RotateMouseButtons = new MouseButton(buConversion5.MouseButtonConv(SettingsMouse.RotateConfigration.Button), buConversion5.KeyConv(SettingsMouse.RotateConfigration.Key));
		Properties.ZoomMouseButtons = new MouseButton(buConversion5.MouseButtonConv(SettingsMouse.ZoomConfigration.Button), buConversion5.KeyConv(SettingsMouse.ZoomConfigration.Key));
		Properties.ProjetionType = buConversion5.ProjectionTypeConvert(SettingsView.Projection);
		Properties.ReverseMouseWheel = SettingsView.ZoomReverse;
		Properties.ToolBorVisible = SettingsView.ShowToolbar;
		Properties.ViewCubeIconVisible = SettingsView.ShowCubeIcon;
	}

