		Properties.TopColor = SettingsView.TopColor;
		Properties.BottomColor = SettingsView.BottomColor;
		Properties.IntermediateColor = SettingsView.IntermediateColor;
		Properties.ShowCoordinateArrow = SettingsView.ShowCoordinateSystemIcon;
		Properties.DisplayType = buConversion5.DisplayModeConvert(SettingsView.DisplayMode);
		Properties.ShowGrid = SettingsView.ShowGrid;
		Properties.ShowOriginCaption = SettingsView.ShowOrigineCaption;
		Properties.OriginSymbol = buConversion5.OrigineIconConvert(SettingsView.OrigineIcon);
		Properties.ShowOrigin = SettingsView.ShowOrigineIcon;
		Properties.PanMouseButton = new MouseButton(buConversion5.MouseButtonConv(SettingsMouse.PanConfigration.Button), buConversion5.KeyConv(SettingsMouse.PanConfigration.Key));
		Properties.RotateMouseButton = new MouseButton(buConversion5.MouseButtonConv(SettingsMouse.RotateConfigration.Button), buConversion5.KeyConv(SettingsMouse.RotateConfigration.Key));
		Properties.ZoomMouseButton = new MouseButton(buConversion5.MouseButtonConv(SettingsMouse.ZoomConfigration.Button), buConversion5.KeyConv(SettingsMouse.ZoomConfigration.Key));
		Properties.ProjectionType = buConversion5.ProjectionTypeConvert(SettingsView.Projection);
		Properties.ReverseMouseWheel = SettingsView.ZoomReverse;
		Properties.ShowToolBar = SettingsView.ShowToolbar;
		Properties.ShowViewCube = SettingsView.ShowCubeIcon;
	}

	public void ResetSelectedEntities(int PageIndex)
	{
		if (ccVars.Pages.Count <= 0)
		{
			return;
		}
		for (int i = 0; i <= ccVars.Pages[PageIndex].Form.viewportcad.Entities.Count - 1; i++)
		{
			ccVars.Pages[PageIndex].Form.viewportcad.Entities[i].Selected = false;
			if (!(ccVars.Pages[PageIndex].Form.viewportcad.Entities[i].GetType() == typeof(Brep)))
			{
				continue;
			}
			((Brep)ccVars.Pages[PageIndex].Form.viewportcad.Entities[i]).ClearEdgesSelection(null);
			((Brep)ccVars.Pages[PageIndex].Form.viewportcad.Entities[i]).ClearFacesSelection();
			((Brep)ccVars.Pages[PageIndex].Form.viewportcad.Entities[i]).ClearVerticesSelection(null);
			for (int j = 0; j <= ((Brep)ccVars.Pages[PageIndex].Form.viewportcad.Entities[i]).Edges.Length - 1; j++)
			{
				ICurve curve = ((Brep)ccVars.Pages[PageIndex].Form.viewportcad.Entities[i]).Edges[j].Curve;
				if (curve.GetType() == typeof(Line))
				{
					((Line)curve).Selected = false;
				}
				if (curve.GetType() == typeof(Arc))
				{
					((Arc)curve).Selected = false;
				}
			}
		}
	}

	public void MoveToPlane(double X, double Y, Plane refPlane, ref Point3D refPoint)
	{
		Point3D item = new Point3D(X, Y);
		List<Point3D> list = new List<Point3D>();
		list.Add(item);
		ccVars.Pages[ccVars.PageIndex].Form.viewportcad.MoveToPlane(list, refPlane);
		refPoint = list[0];
	}

	public void viewportMouseDown(Point3D Points, object sender, MouseEventArgs e)
	{
		try
		{
			if (Points != null)
			{
				ccVars.pntMouseDown.X = Points.X;
				ccVars.pntMouseDown.Y = Points.Y;
				ccVars.pntMouseDown.Z = Points.Z;
			}
			clsVar.ContextMenuCancel = false;
			if (mouseDownViewport_0 != null)
			{
				mouseDownViewport_0(Points.X, Points.Y, Points.Z, sender, e);
			}
			if ((clsInit.appDrill != null) & clsVar.UserMode.DrillMode.Enable)
			{
				clsInit.appDrill.viewportMouseDown(Points, sender, e);
			}
			if ((clsInit.appMarble != null) & clsVar.UserMode.MarbleMode.Enable)
			{
				clsInit.appMarble.viewportMouseDown(Points, sender, e);
			}
			if (e.Button == MouseButtons.Right && ccVars.stpDrawing >= 1 && ccVars.selectionProcess)
			{
				clsVar.ContextMenuCancel = true;
			}
			if (!((ccVars.stpDrawing == 0) & (ccVars.Action == actionTypeBU.None) & (e.Button == MouseButtons.Left)))
			{
				if (!((ccVars.stpDrawing == 1) & (e.Button == MouseButtons.Left)))
				{
					if (!((ccVars.stpDrawing == 2) & (e.Button == MouseButtons.Left)))
					{
						if (!((ccVars.stpDrawing == 3) & (e.Button == MouseButtons.Left)))
						{
							if (!((ccVars.stpDrawing == 4) & (e.Button == MouseButtons.Left)))
							{
								if ((ccVars.stpDrawing == 5) & (e.Button == MouseButtons.Left))
								{
									DownStep5(Points, sender, e);
								}
							}
							else
							{
								DownStep4(Points, sender, e);
							}
						}
						else
						{
							DownStep3(Points, sender, e);
						}
					}
					else
					{
						DownStep2(Points, sender, e);
					}
				}
				else
				{
					DownStep1(Points, sender, e);
				}
			}
			else
			{
				DownStep0(Points, sender, e);
			}
		}
		catch (Exception mSException)
		{
			buLog.addLog("", "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: true, "");
		}
	}

	public void DownStep0(Point3D Points, object sender, MouseEventArgs e)
	{
		if (AppBool.ControlKeyPressed)
		{
			return;
		}
		for (int i = 0; i <= ccVars.SelectionOP.Selections.Count - 1; i++)
		{
			if (clsVar.varDisplay.ShowSelectedEntitiesTipPoint)
			{
				for (int j = 0; j <= ccVars.SelectionOP.Selections[i].AlingPoints.TipPoints.Count - 1; j++)
				{
					if (!clsInit.cVector5.IsPointInsideWindow(Points, ccVars.SelectionOP.Selections[i].AlingPoints.TipPoints[j], clsVar.varMouse.Osnap.CatchResolution * ccVars.Pages[ccVars.PageIndex].Form.viewportcad.ZoomRatio, ccVars.planeActive))
					{
						continue;
					}
					ccVars.entCalculations.Clear();
					ccVars.entCalculations = new List<Entity>();
					for (int k = 0; k <= ccVars.SelectionOP.Selections.Count - 1; k++)
					{
						int VerticeIndex = -1;
						int index = ccVars.SelectionOP.Selections[k].Index;
						osnapType OsnapTypes = osnapType.None;
						if (!clsInit.cVector5.IsPointTouchEntityPoint(Points, ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index], ccVars.planeActive, 0.1, TipPoint: true, Middle: true, Outter: true, Center: true, Over: false, ControlPoint: true, ref VerticeIndex, ref ccVars.pntBase, ref OsnapTypes))
						{
							if (!(ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index] is Curve))
							{
								continue;
							}
							Curve curve = ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index] as Curve;
							for (int l = 0; l <= curve.ControlPoints.Length - 1; l++)
							{
								if (buCompare5.EQ(curve.ControlPoints[l], Points, buSystem.resolutionCompare))
								{
									Entity copiedEnt = null;
									buVector5.CopyEntities(ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index], ref copiedEnt);
									((CustomData)copiedEnt.EntityData).OriginalEntityIndex = index;
									ccVars.entCalculations.Add(copiedEnt);
								}
							}
						}
						else
						{
							Entity copiedEnt2 = null;
							buVector5.CopyEntities(ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index], ref copiedEnt2);
							((CustomData)copiedEnt2.EntityData).OriginalEntityIndex = index;
							ccVars.entCalculations.Add(copiedEnt2);
						}
					}
					ccVars.pntBase = buVector5.ToPoint3D(ccVars.SelectionOP.Selections[i].AlingPoints.TipPoints[j]);
					ccVars.Pages[ccVars.PageIndex].Form.viewportcad.ActionMode = actionType.None;
					ccVars.Action = actionTypeBU.drawEdit;
					ccVars.stpDrawing = 2;
					ccVars.selectionProcess = false;
					dynamicInfo.Command = AppLanguage.CadCamCommand[51];
					return;
				}
			}
			if (clsVar.varDisplay.ShowSelectedEntitiesMovePoint)
			{
				for (int m = 0; m <= ccVars.SelectionOP.Selections[i].AlingPoints.MovePoints.Count - 1; m++)
				{
					if (!clsInit.cVector5.IsPointInsideWindow(Points, ccVars.SelectionOP.Selections[i].AlingPoints.MovePoints[m], clsVar.varMouse.Osnap.CatchResolution * ccVars.Pages[ccVars.PageIndex].Form.viewportcad.ZoomRatio, ccVars.planeActive))
					{
						continue;
					}
					ccVars.entCalculations.Clear();
					ccVars.entCalculations = new List<Entity>();
					for (int n = 0; n <= ccVars.SelectionOP.Selections.Count - 1; n++)
					{
						int VerticeIndex2 = -1;
						int index2 = ccVars.SelectionOP.Selections[n].Index;
						osnapType OsnapTypes2 = osnapType.None;
						if (clsInit.cVector5.IsPointTouchEntityPoint(Points, ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index2], ccVars.planeActive, 0.1, TipPoint: true, Middle: true, Outter: true, Center: true, Over: false, ControlPoint: true, ref VerticeIndex2, ref ccVars.pntBase, ref OsnapTypes2))
						{
							Entity copiedEnt3 = null;
							buVector5.CopyEntities(ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[index2], ref copiedEnt3);
							ccVars.entCalculations.Add(copiedEnt3);
						}
					}
					ccVars.pntBase = buVector5.ToPoint3D(ccVars.SelectionOP.Selections[i].AlingPoints.MovePoints[m]);
					ccVars.Pages[ccVars.PageIndex].Form.viewportcad.ActionMode = actionType.None;
					ccVars.Action = actionTypeBU.eventMove;
					ccVars.stpDrawing = 2;
					ccVars.selectionProcess = false;
					ccVars.MoveEntityPointPressed = true;
					DownStep2(ccVars.pntBase, null, null);
					return;
				}
			}
			if (ViewportCC.UnderMouseEntities == null || ViewportCC.UnderMouseEntities.Length == 0 || !clsVar.varSelection.MoveEntityWhenClickAlreadySelected)
			{
				continue;
			}
			for (int num = 0; num <= ViewportCC.UnderMouseEntities.Length - 1; num++)
			{
				if (ccVars.SelectionOP.Selections[i].Index == ViewportCC.UnderMouseEntities[num])
				{
					ccVars.pntBase = buVector5.ToPoint3D(Points);
					ccVars.Pages[ccVars.PageIndex].Form.viewportcad.ActionMode = actionType.None;
					ccVars.Action = actionTypeBU.eventMove;
					ccVars.stpDrawing = 2;
					ccVars.selectionProcess = false;
					ccVars.MoveEntityPointPressed = true;
					DownStep2(ccVars.pntBase, null, null);
					return;
				}
			}
		}
	}

	public void DownStep1(Point3D Points, object sender, MouseEventArgs e)
	{
		ccVars.planeActive.Project(Points, out var s, out var t);
		ccVars.planeActive.Project(ccVars.pntBase, out var s2, out var t2);
		dynamicInfo.Len = clsInit.cVector5.Length2D(s, t, s2, t2);
		dynamicInfo.Ang = clsInit.cVector5.PointAngle(s, t, s2, t2);
		dynamicInfo.dX = clsInit.cVector5.DeltaX(Points, ccVars.pntBase);
		dynamicInfo.dY = clsInit.cVector5.DeltaY(Points, ccVars.pntBase);
		dynamicInfo.dZ = clsInit.cVector5.DeltaZ(Points, ccVars.pntBase);
		if (ccVars.Action != actionTypeBU.drawPoint)
		{
			if (!((ccVars.Action == actionTypeBU.drawLine) | (ccVars.Action == actionTypeBU.marbleDrawLine)))
			{
				if (!((ccVars.Action == actionTypeBU.drawPolyline) | (ccVars.Action == actionTypeBU.marbleDrawPolyline)))
				{
					if (ccVars.Action != actionTypeBU.marbleDrawCompositeCurve)
					{
						if (!((ccVars.Action == actionTypeBU.drawRectangle) | (ccVars.Action == actionTypeBU.marbleDrawRectangle) | (ccVars.Action == actionTypeBU.drawRectangleRound) | (ccVars.Action == actionTypeBU.drawRectangleChamfer)))
						{
							if (!((ccVars.Action == actionTypeBU.drawPolygon) | (ccVars.Action == actionTypeBU.marbleDrawPolygon)))
							{
								if (ccVars.Action != actionTypeBU.drawPolygonIrregular)
								{
									if (ccVars.Action != actionTypeBU.drawTriangle)
									{
										if (ccVars.Action != actionTypeBU.drawStar)
										{
											if (ccVars.Action != actionTypeBU.drawObjectImage)
											{
												if (ccVars.Action != actionTypeBU.drawObjectText)
												{
													if (ccVars.Action != actionTypeBU.drawVectorText)
													{
														if (ccVars.Action != actionTypeBU.drawCustomText)
														{
