	public void DownStep2(Point3D Points, object sender, MouseEventArgs e)
	{
		ccVars.planeActive.Project(Points, out var s, out var t);
		ccVars.planeActive.Project(ccVars.pntBase, out var s2, out var t2);
		dynamicInfo.Len = clsInit.cVector5.Length2D(s, t, s2, t2);
		dynamicInfo.Ang = clsInit.cVector5.PointAngle(s, t, s2, t2);
		dynamicInfo.dX = clsInit.cVector5.DeltaX(Points, ccVars.pntBase);
		dynamicInfo.dY = clsInit.cVector5.DeltaY(Points, ccVars.pntBase);
		dynamicInfo.dZ = clsInit.cVector5.DeltaZ(Points, ccVars.pntBase);
		if (ccVars.Action != actionTypeBU.drawLine)
		{
			if (ccVars.Action == actionTypeBU.marbleDrawLine && clsInit.appMarble != null)
			{
				clsInit.appMarble.AddLine(Points);
			}
			if (ccVars.Action != actionTypeBU.drawPolyline)
			{
				if (ccVars.Action == actionTypeBU.marbleDrawPolyline && clsInit.appMarble != null)
				{
					clsInit.appMarble.AddPolyLine(Points);
				}
				if (ccVars.Action != actionTypeBU.drawRectangle)
				{
					if (ccVars.Action == actionTypeBU.marbleDrawRectangle && clsInit.appMarble != null)
					{
						clsInit.appMarble.AddRectangle(Points);
					}
					if (ccVars.Action != actionTypeBU.drawRectangleChamfer)
					{
						if (ccVars.Action != actionTypeBU.drawRectangleRound)
						{
							if (ccVars.Action != actionTypeBU.drawPolygon)
							{
								if (ccVars.Action == actionTypeBU.marbleDrawPolygon && clsInit.appMarble != null)
								{
									clsInit.appMarble.AddPolygon(Points);
								}
								if (ccVars.Action != actionTypeBU.drawPolygonIrregular)
								{
									if (ccVars.Action != actionTypeBU.drawTriangle)
									{
										if (ccVars.Action != actionTypeBU.drawStar)
										{
											if (ccVars.Action != actionTypeBU.drawObjectImage)
											{
												if (ccVars.Action != actionTypeBU.drawCircle)
												{
													if (ccVars.Action == actionTypeBU.marbleDrawCircle && clsInit.appMarble != null)
													{
														clsInit.appMarble.AddCircle(Points, 0.0);
													}
													if (ccVars.Action != actionTypeBU.drawCircle3Point)
													{
														if (ccVars.Action != actionTypeBU.drawCircle2Point)
														{
															if (ccVars.Action != actionTypeBU.drawArc)
															{
																if (ccVars.Action != actionTypeBU.drawArc3PointSME)
																{
																	if (!((ccVars.Action == actionTypeBU.drawArc3PointSEM) | (ccVars.Action == actionTypeBU.marbleDrawArc)))
																	{
																		if (ccVars.Action != actionTypeBU.drawEllipse)
																		{
																			if (ccVars.Action != actionTypeBU.drawEllipseArc)
																			{
																				if (ccVars.Action != actionTypeBU.drawSpline)
																				{
																					if (ccVars.Action != actionTypeBU.drawFreeDraw)
																					{
																						if (ccVars.Action != actionTypeBU.marbleDimLinear)
																						{
																							if (ccVars.Action != actionTypeBU.marbleDimAlinged)
																							{
																								if (ccVars.Action != actionTypeBU.drawDimLinear)
																								{
																									if (ccVars.Action != actionTypeBU.drawDimAlinged)
																									{
																										if (ccVars.Action != actionTypeBU.drawDimRadial)
																										{
																											if (ccVars.Action != actionTypeBU.drawDimDiameter)
																											{
																												if (ccVars.Action == actionTypeBU.drawDimAngular)
																												{
																													if (ccVars.AngularDimType == 0)
																													{
																														AngularDim Ent = null;
																														Arc arc = (Arc)ccVars.SelectionOP.Selections[0].SelectedEntity;
																														Point3D startPoint = buVector5.ToPoint3D(arc.StartPoint);
																														Point3D endPoint = buVector5.ToPoint3D(arc.EndPoint);
																														Plane plane = (Plane)arc.Plane.Clone();
																														if (Utility.IsOrientedClockwise(arc.Vertices))
																														{
																															startPoint = buVector5.ToPoint3D(arc.EndPoint);
																															endPoint = buVector5.ToPoint3D(arc.StartPoint);
																															plane.Flip();
																														}
																														EntityDataSet entData = new EntityDataSet(-1, ccVars.Pages[ccVars.PageIndex].LayerName, ccVars.Pages[ccVars.PageIndex].SceneName, "", "AngularDim", null, ccVars.pntBase);
																														CreateDimensionAngular(startPoint, endPoint, Points, clsVar.varEntities.DimensionTextHeight, plane, entData, EntityDataSet.ConvertCustomData(entData), ref Ent);
																														if (Ent != null)
																														{
																															AddDimensionAngular(Ent);
																														}
																														Reset();
																														return;
																													}
																													if (ccVars.AngularDimType == 1)
																													{
																														formStatusUpdate_0(AppLanguage.CadCamStatus[119]);
																														ccVars.enableViewportDrawCurrentLine = true;
																														ccVars.pntBase = buVector5.ToPoint3D(Points);
																														ccVars.pntDrawDynamicMarkers.Add(buVector5.ToPoint3D(Points));
																														ccVars.stpDrawing = 3;
																													}
																												}
																												if (ccVars.Action != actionTypeBU.drawDimHorizontalOrdinate)
																												{
																													if (ccVars.Action != actionTypeBU.drawDimVerticalOrdinate)
																													{
																														if (ccVars.Action != actionTypeBU.drawDimLeader)
																														{
																															if (ccVars.Action == actionTypeBU.drawInsertFromFile)
																															{
																																double dX = Points.X - ccVars.pntMid.X;
																																double dY = Points.Y - ccVars.pntMid.Y;
																																double dZ = Points.Z - ccVars.pntMid.Z;
																																InsertFromFile(dX, dY, dZ);
																															}
																															if (ccVars.Action != actionTypeBU.drawEdit)
																															{
																																if (ccVars.Action != actionTypeBU.eventMove)
																																{
																																	if (ccVars.Action != actionTypeBU.eventCopy)
																																	{
																																		if (ccVars.Action != actionTypeBU.eventRotate)
																																		{
																																			if (ccVars.Action != actionTypeBU.eventMirror)
																																			{
																																				if (ccVars.Action != actionTypeBU.eventLineerArray)
																																				{
																																					if (ccVars.Action != actionTypeBU.eventPolarArray)
																																					{
																																						if (ccVars.Action != actionTypeBU.eventRotateVector)
																																						{
																																							if (ccVars.Action != actionTypeBU.eventRotateClick)
																																							{
																																								if (ccVars.Action != actionTypeBU.eventScale)
																																								{
																																									if (ccVars.Action != actionTypeBU.eventOffset)
																																									{
