	public void DownStep3(Point3D Points, object sender, MouseEventArgs e)
	{
		ccVars.planeActive.Project(Points, out var s, out var t);
		ccVars.planeActive.Project(ccVars.pntBase, out var s2, out var t2);
		dynamicInfo.Len = clsInit.cVector5.Length2D(s, t, s2, t2);
		dynamicInfo.Ang = clsInit.cVector5.PointAngle(s, t, s2, t2);
		dynamicInfo.dX = clsInit.cVector5.DeltaX(Points, ccVars.pntBase);
		dynamicInfo.dY = clsInit.cVector5.DeltaY(Points, ccVars.pntBase);
		dynamicInfo.dZ = clsInit.cVector5.DeltaZ(Points, ccVars.pntBase);
		if (ccVars.Action != actionTypeBU.drawStar)
		{
			if (ccVars.Action != actionTypeBU.drawCircle3Point)
			{
				if (ccVars.Action != actionTypeBU.drawArc)
				{
					if (ccVars.Action != actionTypeBU.drawArc3PointSME)
					{
						if (ccVars.Action != actionTypeBU.drawArc3PointSEM)
						{
							if (ccVars.Action == actionTypeBU.marbleDrawArc && clsInit.appMarble != null)
							{
								clsInit.appMarble.AddArc(ccVars.pntStart, Points, ccVars.pntTip);
							}
							if (ccVars.Action == actionTypeBU.drawEllipse)
							{
								dynamicInfo.MinorRad = Points.DistanceTo(new Segment3D(ccVars.pntBase, ccVars.pntTip));
								Plane refPlane = new Plane(ccVars.pntBase, ccVars.pntTip, Points);
								Ellipse Ent = null;
								EntityDataSet entData = new EntityDataSet(-1, ccVars.Pages[ccVars.PageIndex].LayerName, ccVars.Pages[ccVars.PageIndex].SceneName, "", "Ellipse", null, ccVars.pntBase);
								CreateEllipse(ccVars.pntBase, dynamicInfo.MajorRad, dynamicInfo.MinorRad, refPlane, entData, EntityDataSet.ConvertCustomData(entData), ref Ent);
								if (Ent != null)
								{
									AddEllipse(Ent);
								}
								Reset();
								if (clsVar.varProgram.DrawCommandRepitation)
								{
									cmdDrawEllipseCenter();
								}
							}
							if (ccVars.Action == actionTypeBU.drawEllipseArc)
							{
								dynamicInfo.MinorRad = Points.DistanceTo(new Segment3D(ccVars.pntBase, ccVars.pntTip));
								ccVars.planeTemp = new Plane(ccVars.pntBase, ccVars.pntTip, Points);
								ccVars.stpDrawing = 4;
							}
							if (ccVars.Action != actionTypeBU.drawSpline)
							{
								if (ccVars.Action != actionTypeBU.marbleDimLinear)
								{
									if (ccVars.Action != actionTypeBU.marbleDimAlinged)
									{
										if (ccVars.Action != actionTypeBU.drawDimLinear)
										{
											if (ccVars.Action != actionTypeBU.drawDimAlinged)
											{
												if (ccVars.Action != actionTypeBU.drawDimAngular || ccVars.AngularDimType != 1)
												{
													if (ccVars.Action == actionTypeBU.eventMove)
													{
														Move(ccVars.pntBase, Points);
													}
													if (ccVars.Action == actionTypeBU.eventCopy)
													{
														Copy(ccVars.pntBase, Points);
													}
													if (ccVars.Action != actionTypeBU.eventRotate)
													{
														if (ccVars.Action == actionTypeBU.eventMirror)
														{
															Mirror(ccVars.pntBase, Points, clsVar.varInterface.MirrorVar.DeleteOriginal, clsVar.varProgram.EventCommandRepitation, ApplyReset: true);
														}
														return;
													}
													formStatusUpdate_0(AppLanguage.CadCamStatus[21] + " [ " + dynamicInfo.Command + " ]");
													ccVars.enableViewportDrawCurrentLine = true;
													ccVars.enableViewportTextForCommand = true;
													ccVars.enableDynamicalSpins = true;
													ccVars.pntTip = buVector5.ToPoint3D(Points);
