										EntityDataSet entData5 = new EntityDataSet(-1, ccVars.Pages[ccVars.PageIndex].LayerName, ccVars.Pages[ccVars.PageIndex].SceneName, "", "AlignedDim", null, new Point3D());
										CreateDimensionLinear(ccVars.pntStart, ccVars.pntEnd, Points, buEyeBaseVer5.Apps.Marble.buMarbleCalc.varMarbleEntitiesSettings.DimensionTextHeight, drawingPlane3, isAligned: true, entData5, EntityDataSet.ConvertCustomData(entData5), ref Ent5);
										ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Add(Ent5);
										ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Invalidate();
										AddDimensionLinear(Ent5);
										Reset();
									}
								}
								else
								{
									ccVars.planeActive.Project(ccVars.pntStart, out var s9, out var t9);
									ccVars.planeActive.Project(ccVars.pntEnd, out var s10, out var t10);
									Entity Ent6 = null;
									Plane drawingPlane4 = null;
									clsInit.cVector5.LinearDimCalculate(new Point3D(s9, t9), new Point3D(s10, t10), new Point3D(s, t), clsVar.varEntities.DimensionTextHeight, ccVars.planeActive, ref drawingPlane4);
									EntityDataSet entData6 = new EntityDataSet(-1, ccVars.Pages[ccVars.PageIndex].LayerName, ccVars.Pages[ccVars.PageIndex].SceneName, "", "LinearDim", null, new Point3D());
									CreateDimensionLinear(ccVars.pntStart, ccVars.pntEnd, Points, buEyeBaseVer5.Apps.Marble.buMarbleCalc.varMarbleEntitiesSettings.DimensionTextHeight, drawingPlane4, isAligned: false, entData6, EntityDataSet.ConvertCustomData(entData6), ref Ent6);
									Reset();
								}
							}
							else
							{
								ccVars.Pages[ccVars.PageIndex].OsnapTempPoints.Add(new OsnapPoint(buVector5.ToPoint3D(Points), osnapType.Point));
								ccVars.Pages[ccVars.PageIndex].OsnapTempPoints.Add(new OsnapPoint(Point3D.MidPoint(ccVars.pntBase, Points), osnapType.Middle));
								ccVars.pntBuffered.Add(buVector5.ToPoint3D(Points));
								ccVars.pntBase = buVector5.ToPoint3D(Points);
								formStatusUpdate_0(AppLanguage.CadCamCommand[8] + " - " + AppLanguage.CadCamStatus[1]);
							}
						}
						else
						{
							Arc Ent7 = new Arc(ccVars.pntStart, ccVars.pntTip, Points);
							EntityDataSet entData7 = new EntityDataSet(-1, ccVars.Pages[ccVars.PageIndex].LayerName, ccVars.Pages[ccVars.PageIndex].SceneName, "", "Arc", null, Ent7.Center);
							CreateArc3Point(ccVars.pntStart, Points, ccVars.pntTip, ccVars.planeActive, entData7, EntityDataSet.ConvertCustomData(entData7), ref Ent7);
							if (Ent7 != null)
							{
								AddArc(Ent7);
							}
							Reset();
							if (clsVar.varProgram.DrawCommandRepitation)
							{
								cmdDrawArc3Point();
							}
						}
					}
					else
					{
						Arc Ent8 = new Arc(ccVars.pntStart, ccVars.pntTip, Points);
						EntityDataSet entData8 = new EntityDataSet(-1, ccVars.Pages[ccVars.PageIndex].LayerName, ccVars.Pages[ccVars.PageIndex].SceneName, "", "Arc", null, Ent8.Center);
						CreateArc3Point(ccVars.pntStart, ccVars.pntTip, Points, ccVars.planeActive, entData8, EntityDataSet.ConvertCustomData(entData8), ref Ent8);
						if (Ent8 != null)
						{
							AddArc(Ent8);
						}
						Reset();
						if (clsVar.varProgram.DrawCommandRepitation)
						{
							cmdDrawArc3Point();
						}
					}
				}
				else
				{
					dynamicInfo.StartAng = dynamicInfo.Ang;
					ccVars.pntTip = buVector5.ToPoint3D(Points);
					formStatusUpdate_0(AppLanguage.CadCamStatus[5]);
					ccVars.Spin1Prop.Caption = "EA";
					ccVars.stpDrawing = 4;
				}
			}
			else
			{
				Circle Ent9 = new Circle(ccVars.pntStart, ccVars.pntTip, Points);
				EntityDataSet entData9 = new EntityDataSet(-1, ccVars.Pages[ccVars.PageIndex].LayerName, ccVars.Pages[ccVars.PageIndex].SceneName, "", "Circle", null, Ent9.Center);
				CreateCircle3Point(ccVars.pntStart, ccVars.pntTip, Points, ccVars.planeActive, entData9, EntityDataSet.ConvertCustomData(entData9), ref Ent9);
				if (Ent9 != null)
				{
					AddCircle(Ent9);
				}
				Reset();
				if (clsVar.varProgram.DrawCommandRepitation)
				{
					cmdDrawCircle3Point();
				}
			}
		}
		else
		{
			List<Pnt3D> Vertices = new List<Pnt3D>();
			ccVars.Pages[ccVars.PageIndex].Scene[ccVars.Pages[ccVars.PageIndex].SceneIndex].ScenePlane.Project(ccVars.pntTip, out var s11, out var t11);
			clsInit.cVector.PolygonStar(new Pnt3D(s2, t2), new Pnt3D(s11, t11), new Pnt3D(s, t), new WorkPlane(), ref Vertices);
			List<Entity> list = new List<Entity>();
			for (int i = 1; i <= Vertices.Count - 1; i++)
			{
				list.Add(new Line(buConversion5.Pnt3DToPoint3D(Vertices[i - 1]), buConversion5.Pnt3DToPoint3D(Vertices[i])));
			}
			ccVars.Pages[ccVars.PageIndex].Form.viewportcad.MoveToPlane(list, ccVars.planeActive);
			CompositeCurve Ent10 = null;
			EntityDataSet entData10 = new EntityDataSet(-1, ccVars.Pages[ccVars.PageIndex].LayerName, ccVars.Pages[ccVars.PageIndex].SceneName, "", "Star", null, ccVars.pntBase);
			CreateCompositeCurve(list, entData10, EntityDataSet.ConvertCustomData(entData10), ref Ent10);
			if (Ent10 != null)
			{
				AddCompositeCurve(Ent10);
			}
			Reset();
		}
	}

	public void DownStep4(Point3D Points, object sender, MouseEventArgs e)
	{
		ccVars.planeActive.Project(Points, out var s, out var t);
		ccVars.planeActive.Project(ccVars.pntBase, out var s2, out var t2);
		dynamicInfo.Len = clsInit.cVector5.Length2D(s, t, s2, t2);
		dynamicInfo.Ang = clsInit.cVector5.PointAngle(s, t, s2, t2);
		dynamicInfo.dX = clsInit.cVector5.DeltaX(Points, ccVars.pntBase);
		dynamicInfo.dY = clsInit.cVector5.DeltaY(Points, ccVars.pntBase);
		dynamicInfo.dZ = clsInit.cVector5.DeltaZ(Points, ccVars.pntBase);
		if (ccVars.Action != actionTypeBU.drawArc)
		{
			if (ccVars.Action == actionTypeBU.drawEllipseArc && ((dynamicInfo.MinorRad > 0.001) & (dynamicInfo.MajorRad > 0.001)))
			{
				Ellipse ellipse = new Ellipse(ccVars.planeTemp, ccVars.pntBase, dynamicInfo.MajorRad, dynamicInfo.MinorRad);
				clsInit.cVector5.PointAngle(Points, ccVars.pntBase, ccVars.planeActive);
				Pnt3D EndPnt = new Pnt3D();
				clsInit.cVector.LineWithLengthAndAngle(buConversion5.Point3DToPnt3D(ccVars.pntBase), 1000.0, dynamicInfo.Ang, buVector5.PlaneToWorkPlane(ccVars.planeActive), ref EndPnt);
				Line c = new Line(ccVars.pntBase, Points);
				Point3D[] array = ellipse.IntersectWith(c);
				if (array != null && array.Length != 0)
				{
					ccVars.pntStart = buVector5.ToPoint3D(array[0]);
					ellipse.ClosestPointTo(array[0], out dynamicInfo.StartLen);
				}
				ccVars.stpDrawing = 5;
			}
			if (ccVars.Action == actionTypeBU.eventRotate)
			{
				double s3 = 0.0;
				double t3 = 0.0;
				ccVars.planeActive.Project(ccVars.pntTip, out s3, out t3);
				Vector2D vector2D = new Vector2D(new Point2D(s2, t2), new Point2D(s3, t3));
				vector2D.Normalize();
				Vector2D vector2D2 = new Vector2D(new Point2D(s2, t2), new Point2D(s, t));
				vector2D2.Normalize();
				double angleInRadian = Vector2D.SignedAngleBetween(vector2D, vector2D2);
				Rotate(ccVars.pntBase, angleInRadian, clsVar.varInterface.RotateVar.DeleteOriginal, clsVar.varProgram.EventCommandRepitation);
			}
		}
		else
		{
			Arc Ent = new Arc(ccVars.planeActive, ccVars.pntBase, dynamicInfo.Rad, ccVars.pntTip, Points, flip: false);
			EntityDataSet entData = new EntityDataSet(-1, ccVars.Pages[ccVars.PageIndex].LayerName, ccVars.Pages[ccVars.PageIndex].SceneName, "", "Arc", null, Ent.Center);
			CreateArc(ccVars.pntBase, dynamicInfo.Rad, ccVars.pntTip, Points, ccVars.planeActive, entData, EntityDataSet.ConvertCustomData(entData), ref Ent);
			if (Ent != null)
			{
				AddArc(Ent);
			}
			Reset();
			if (clsVar.varProgram.DrawCommandRepitation)
			{
				cmdDrawArcCenter();
			}
		}
	}

	public void DownStep5(Point3D Points, object sender, MouseEventArgs e)
	{
		ccVars.planeActive.Project(Points, out var s, out var t);
		ccVars.planeActive.Project(ccVars.pntBase, out var s2, out var t2);
		dynamicInfo.Len = clsInit.cVector5.Length2D(s, t, s2, t2);
		dynamicInfo.Ang = clsInit.cVector5.PointAngle(s, t, s2, t2);
		dynamicInfo.dX = clsInit.cVector5.DeltaX(Points, ccVars.pntBase);
		dynamicInfo.dY = clsInit.cVector5.DeltaY(Points, ccVars.pntBase);
		dynamicInfo.dZ = clsInit.cVector5.DeltaZ(Points, ccVars.pntBase);
		if (ccVars.Action == actionTypeBU.drawEllipseArc && ((dynamicInfo.MinorRad > 0.001) & (dynamicInfo.MajorRad > 0.001)))
		{
			Ellipse ellipse = new Ellipse(ccVars.planeTemp, ccVars.pntBase, dynamicInfo.MajorRad, dynamicInfo.MinorRad);
			EllipticalArc Ent = null;
			Line c = new Line(ccVars.pntBase, Points);
			Point3D[] array = ellipse.IntersectWith(c);
			if (array != null && array.Length != 0)
			{
				ellipse.ClosestPointTo(array[0], out dynamicInfo.EndLen);
			}
			if (dynamicInfo.StartLen > dynamicInfo.EndLen)
			{
				dynamicInfo.EndLen += Math.PI * 2.0;
			}
			if (dynamicInfo.EndLen - dynamicInfo.StartLen > Math.PI * 2.0)
			{
				dynamicInfo.EndLen = dynamicInfo.StartLen + Math.PI * 2.0;
			}
			EntityDataSet entData = new EntityDataSet(-1, ccVars.Pages[ccVars.PageIndex].LayerName, ccVars.Pages[ccVars.PageIndex].SceneName, "", "EllipseArc", null, ccVars.pntBase);
			CreateEllipseArc(ccVars.pntBase, dynamicInfo.MajorRad, dynamicInfo.MinorRad, dynamicInfo.StartLen, dynamicInfo.EndLen, ccVars.planeTemp, entData, EntityDataSet.ConvertCustomData(entData), ref Ent);
			if (Ent != null)
			{
				AddEllipseArc(Ent);
			}
			Reset();
			if (clsVar.varProgram.DrawCommandRepitation)
			{
				cmdDrawEllipseArcCenter();
			}
		}
	}

	public void viewportMouseMove(Point3D Points, object sender, MouseEventArgs e)
	{
		try
		{
			AppProcess.TickSave = 0;
			if (Points != null)
			{
				ccVars.pntMouseMove.X = Points.X;
				ccVars.pntMouseMove.Y = Points.Y;
				ccVars.pntMouseMove.Z = Points.Z;
			}
			if (mouseDownViewport_2 != null)
			{
				mouseDownViewport_2(Points.X, Points.Y, Points.Z, sender, e);
			}
			if ((clsInit.appDrill != null) & clsVar.UserMode.DrillMode.Enable)
			{
				clsInit.appDrill.viewportMouseMove(Points, sender, e);
			}
			if ((clsInit.appMarble != null) & clsVar.UserMode.MarbleMode.Enable)
			{
				clsInit.appMarble.viewportMouseMove(Points, sender, e);
			}
			if (formXYZUpdate_0 != null && Points != null)
			{
				formXYZUpdate_0(Points.X.ToString("f" + clsVar.varProgram.DecimalVisiblePoint), Points.Y.ToString("f" + clsVar.varProgram.DecimalVisiblePoint), Points.Z.ToString("f" + clsVar.varProgram.DecimalVisiblePoint));
			}
			if (((ccVars.Pages.Count > 0) & (ccVars.PageIndex <= ccVars.Pages.Count - 1)) && ccVars.stpDrawing > 0)
			{
				ccVars.Pages[ccVars.PageIndex].Form.pnl_val1.Visible = false;
				ccVars.Pages[ccVars.PageIndex].Form.pnl_val2.Visible = false;
				ccVars.Pages[ccVars.PageIndex].Form.pnl_val3.Visible = false;
				ccVars.Pages[ccVars.PageIndex].Form.pnl_coords.Visible = false;
			}
			if (ccVars.stpDrawing == 1)
			{
				MoveStep1(Points, sender, e);
			}
			if (ccVars.stpDrawing == 2)
			{
				MoveStep2(Points, sender, e);
			}
			if (ccVars.stpDrawing == 3)
			{
				MoveStep3(Points, sender, e);
			}
			if (ccVars.stpDrawing == 4)
			{
				MoveStep4(Points, sender, e);
			}
			if (ccVars.stpDrawing == 5)
			{
				MoveStep5(Points, sender, e);
			}
			if ((ccVars.stpDrawing > 0) & ccVars.ShowCoordinates)
			{
				ccVars.Pages[ccVars.PageIndex].Form.pnl_coords.Left = e.X + 10;
				ccVars.Pages[ccVars.PageIndex].Form.pnl_coords.Top = e.Y + 10;
			}
			if (ccVars.Pages[ccVars.PageIndex].Form.pnl_val1.Visible | ccVars.Spin1Prop.Visible)
			{
				ccVars.Pages[ccVars.PageIndex].Form.pnl_val1.Left = e.X + 10;
				ccVars.Pages[ccVars.PageIndex].Form.pnl_val1.Top = e.Y;
			}
			if (ccVars.Pages[ccVars.PageIndex].Form.pnl_val2.Visible | ccVars.Spin2Prop.Visible)
			{
				ccVars.Pages[ccVars.PageIndex].Form.pnl_val2.Left = e.X + 10;
				ccVars.Pages[ccVars.PageIndex].Form.pnl_val2.Top = e.Y + 21;
			}
			if (ccVars.Pages[ccVars.PageIndex].Form.pnl_val3.Visible | ccVars.Spin3Prop.Visible)
			{
				ccVars.Pages[ccVars.PageIndex].Form.pnl_val2.Left = e.X + 10;
				ccVars.Pages[ccVars.PageIndex].Form.pnl_val2.Top = e.Y + 42;
			}
		}
		catch (Exception)
		{
			throw;
		}
	}

	public void MoveStep1(Point3D Points, object sender, MouseEventArgs e)
	{
		if (ccVars.Action == actionTypeBU.drawBarrelFast)
		{
			List<Pnt3D> CalculatedPoints = new List<Pnt3D>();
			ccVars.Pages[ccVars.PageIndex].Scene[ccVars.Pages[ccVars.PageIndex].SceneIndex].ScenePlane.Project(Points, out var s, out var t);
			clsInit.cVector.Barrel(new Pnt3D(s, t), clsVar.varInterface.BarrelVar.HeadRadius, clsVar.varInterface.BarrelVar.TaleRadius, clsVar.varInterface.BarrelVar.Length, clsVar.varInterface.BarrelVar.Angle, clsVar.varInterface.BarrelVar.Reverse, new WorkPlane(), buSystem.EntitiesResolution, ref CalculatedPoints);
			ccVars.pntDrawDynamicArr = new Point3D[CalculatedPoints.Count];
			for (int i = 0; i <= CalculatedPoints.Count - 1; i++)
			{
				ccVars.pntDrawDynamicArr[i] = new Point3D(CalculatedPoints[i].X, CalculatedPoints[i].Y, CalculatedPoints[i].Z);
			}
			ccVars.Pages[ccVars.PageIndex].Form.viewportcad.MoveToPlane(ccVars.pntDrawDynamicArr, ccVars.planeActive);
		}
		if (ccVars.Action == actionTypeBU.drawSlotFast)
		{
			ccVars.Pages[ccVars.PageIndex].Scene[ccVars.Pages[ccVars.PageIndex].SceneIndex].ScenePlane.Project(Points, out var s2, out var t2);
			CompositeCurve compositeCurve = CompositeCurve.CreateSlot(ccVars.planeActive, s2, t2, clsVar.varInterface.SlotVar.Length, clsVar.varInterface.SlotVar.Radius, Utility.DegToRad(clsVar.varInterface.SlotVar.Angle), centered: true);
			compositeCurve.Regen(0.1);
			ccVars.pntDrawDynamicArr = new Point3D[compositeCurve.Vertices.Length];
			for (int j = 0; j <= compositeCurve.Vertices.Length - 1; j++)
			{
				ccVars.pntDrawDynamicArr[j] = buVector5.ToPoint3D(compositeCurve.Vertices[j]);
			}
		}
		if (ccVars.Action == actionTypeBU.drawObjectText)
		{
			Text text = new Text(ccVars.planeActive, Points, clsVar.varInterface.TextVar.Text, clsVar.varInterface.TextVar.Height, buConversion5.buAligntoEyeAlign(clsVar.varInterface.TextVar.Alignment));
			RegenParams data = new RegenParams(0.1, ccVars.Pages[ccVars.PageIndex].Form.viewportcad);
			text.Regen(data);
			if (!(text.Vertices[0] != text.Vertices[text.Vertices.Length - 1]))
			{
				ccVars.pntDrawDynamicArr = new Point3D[text.Vertices.Length];
			}
			else
			{
				ccVars.pntDrawDynamicArr = new Point3D[text.Vertices.Length + 1];
				ccVars.pntDrawDynamicArr[text.Vertices.Length] = buVector5.ToPoint3D(text.Vertices[0]);
			}
			for (int k = 0; k <= text.Vertices.Length - 1; k++)
			{
				ccVars.pntDrawDynamicArr[k] = buVector5.ToPoint3D(text.Vertices[k]);
			}
		}
		if (ccVars.Action == actionTypeBU.drawVectorText)
		{
			ccVars.pntDrawDynamicLinesArr.Clear();
			for (int l = 0; l <= ccVars.ContourPoints.Count - 1; l++)
			{
				List<Point3D> CopiedPnt = new List<Point3D>();
				List<Pnt3D> CopiedPnt2 = new List<Pnt3D>();
				Pnt3D.Copy(ccVars.ContourPoints[l].Outter, ref CopiedPnt2);
				clsInit.cVector.Move(new Pnt3D(), new Pnt3D(Points.X, Points.Y, Points.Z), ref CopiedPnt2);
				if (!ccVars.VectorTextRunVar.DrawAsCurve)
				{
					buConversion5.Pnt3DToPoint3D(CopiedPnt2, ref CopiedPnt);
				}
				else
				{
					List<Pnt3D> CalculatedPoints2 = new List<Pnt3D>();
					clsInit.cVector.BSplineQuadraticUniform(CopiedPnt2, 0.1, Closed: true, ref CalculatedPoints2);
					buConversion5.Pnt3DToPoint3D(CalculatedPoints2, ref CopiedPnt);
				}
				ccVars.pntDrawDynamicLinesArr.Add(CopiedPnt);
				for (int m = 0; m <= ccVars.ContourPoints[l].Holes.Count - 1; m++)
				{
					CopiedPnt2 = new List<Pnt3D>();
					Pnt3D.Copy(ccVars.ContourPoints[l].Holes[m], ref CopiedPnt2);
					clsInit.cVector.Move(new Pnt3D(), new Pnt3D(Points.X, Points.Y, Points.Z), ref CopiedPnt2);
					CopiedPnt = new List<Point3D>();
					buConversion5.Pnt3DToPoint3D(CopiedPnt2, ref CopiedPnt);
					ccVars.pntDrawDynamicLinesArr.Add(CopiedPnt);
				}
			}
		}
		if (ccVars.Action != actionTypeBU.drawCustomText)
		{
			return;
		}
		ccVars.pntDrawDynamicLinesArr.Clear();
		for (int n = 0; n <= ccVars.ContourPoints5.Count - 1; n++)
		{
			List<Point3D> copiedPoint = new List<Point3D>();
			new List<Pnt3D>();
			buVector5.Copy(ccVars.ContourPoints5[n].Outter, ref copiedPoint);
			clsInit.cVector5.Move(new Point3D(), new Point3D(Points.X, Points.Y, Points.Z), ref copiedPoint);
			ccVars.pntDrawDynamicLinesArr.Add(copiedPoint);
			for (int num = 0; num <= ccVars.ContourPoints5[n].Inside.Count - 1; num++)
			{
				new List<Pnt3D>();
				copiedPoint = new List<Point3D>();
				buVector5.Copy(ccVars.ContourPoints5[n].Inside[num], ref copiedPoint);
				clsInit.cVector5.Move(new Point3D(), new Point3D(Points.X, Points.Y, Points.Z), ref copiedPoint);
				ccVars.pntDrawDynamicLinesArr.Add(copiedPoint);
			}
		}
	}

	public void MoveStep2(Point3D Points, object sender, MouseEventArgs e)
	{
		ccVars.planeActive.Project(Points, out var s, out var t);
		ccVars.planeActive.Project(ccVars.pntBase, out var s2, out var t2);
		dynamicInfo.Len = clsInit.cVector5.Length2D(s, t, s2, t2);
		dynamicInfo.Ang = clsInit.cVector5.PointAngle(s, t, s2, t2);
		dynamicInfo.dX = clsInit.cVector5.DeltaX(Points, ccVars.pntBase);
		dynamicInfo.dY = clsInit.cVector5.DeltaY(Points, ccVars.pntBase);
		dynamicInfo.dZ = clsInit.cVector5.DeltaZ(Points, ccVars.pntBase);
		if (clsVar.varView.ShowCommandDynamicText)
		{
			dynamicInfo.Info = dynamicInfo.Command + " = ";
		}
		if ((ccVars.Action == actionTypeBU.drawLine) | (ccVars.Action == actionTypeBU.marbleDrawLine))
		{
			dynamicInfo.Info = dynamicInfo.Info + AppLanguage.CadCamDynamic[0] + ": " + dynamicInfo.Len.ToString("f" + clsVar.varProgram.DecimalVisiblePoint) + " - " + AppLanguage.CadCamDynamic[2] + ": " + dynamicInfo.Ang.ToString("f" + clsVar.varProgram.DecimalVisiblePoint) + "º";
			if (clsVar.varView.ShowDxDyDzValuesDynamicText)
			{
				dynamicInfo.Info = dynamicInfo.Info + " dx: " + dynamicInfo.dX.ToString("f" + clsVar.varProgram.DecimalVisiblePoint) + " dy: " + dynamicInfo.dY.ToString("f" + clsVar.varProgram.DecimalVisiblePoint) + " dz: " + dynamicInfo.dZ.ToString("f" + clsVar.varProgram.DecimalVisiblePoint);
			}
			clsInit.cVector.BoxSizeCalculate(buConversion5.Point3DToPnt3D(Points), buConversion5.Point3DToPnt3D(ccVars.pntBase), ref ccVars.Spin1Prop.pntMin, ref ccVars.Spin1Prop.pntMid, ref ccVars.Spin1Prop.pntMax);
			ccVars.Pages[ccVars.PageIndex].Form.spn_val1.Value = (decimal)Math.Round(dynamicInfo.Len, clsVar.varProgram.DecimalVisiblePoint);
		}
		if ((ccVars.Action == actionTypeBU.drawPolyline) | (ccVars.Action == actionTypeBU.marbleDrawPolyline))
		{
			ccVars.pntDrawDynamicArr[ccVars.pntDrawDynamicArr.Length - 1] = buVector5.ToPoint3D(Points);
			dynamicInfo.Info = dynamicInfo.Info + AppLanguage.CadCamDynamic[0] + ": " + dynamicInfo.Len.ToString("f" + clsVar.varProgram.DecimalVisiblePoint) + " - " + AppLanguage.CadCamDynamic[2] + ": " + dynamicInfo.Ang.ToString("f" + clsVar.varProgram.DecimalVisiblePoint) + "º";
			if (clsVar.varView.ShowDxDyDzValuesDynamicText)
			{
