			ccVars.pntDrawDynamicLinesArr.Add(buConversion5.Pnt3dToPoint3D(StartPointExtension2.Vertice));
			ccVars.pntDrawDynamicLinesArr.Add(buConversion5.Pnt3dToPoint3D(EndPointExtension2.Vertice));
			ccVars.pntDrawDynamicLinesArr.Add(buConversion5.Pnt3dToPoint3D(DimLine2.Vertice));
