			ccVars.dynamicTextOnMouse = "L = " + clsInit.cVector.Length3D(DimLine2.Vertice[0], DimLine2.Vertice[1]).ToString("f3");
			for (int num21 = 0; num21 <= ccVars.pntDrawDynamicLinesArr.Count - 1; num21++)
			{
				ccVars.Pages[ccVars.PageIndex].Form.viewportcad.MoveToPlane(ccVars.pntDrawDynamicLinesArr[num21], ccVars.planeActive);
			}
		}
		if (ccVars.Action == actionTypeBU.eventMove)
		{
			ccVars.pntDrawDynamicLinesArr.Clear();
			for (int num22 = 0; num22 <= ccVars.SelectionOP.Selections.Count - 1; num22++)
			{
				if (ccVars.SelectionOP.Selections[num22].SelectedLinearPaths.Count > 0)
				{
					Entity entity = ccVars.SelectionOP.Selections[num22].SelectedLinearPaths[0];
					Entity entity2 = (Entity)entity.Clone();
					Vector3D v = new Vector3D(ccVars.pntBase, Points);
					entity2.Translate(v);
					List<List<Point3D>> refPoints = new List<List<Point3D>>();
					clsInit.cVector5.DrawCurveOrBlockRef(entity2, ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Blocks, ref refPoints);
					for (int num23 = 0; num23 <= refPoints.Count - 1; num23++)
					{
						ccVars.pntDrawDynamicLinesArr.Add(refPoints[num23]);
					}
				}
			}
		}
		if (ccVars.Action == actionTypeBU.eventCopy)
		{
			ccVars.pntDrawDynamicLinesArr.Clear();
			for (int num24 = 0; num24 <= ccVars.SelectionOP.Selections.Count - 1; num24++)
			{
				Entity entity3 = ccVars.SelectionOP.Selections[num24].SelectedLinearPaths[0];
				Entity entity4 = (Entity)entity3.Clone();
				Vector3D v2 = new Vector3D(ccVars.pntBase, Points);
				entity4.Translate(v2);
				List<List<Point3D>> refPoints2 = new List<List<Point3D>>();
				clsInit.cVector5.DrawCurveOrBlockRef(entity4, ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Blocks, ref refPoints2);
				for (int num25 = 0; num25 <= refPoints2.Count - 1; num25++)
				{
					ccVars.pntDrawDynamicLinesArr.Add(refPoints2[num25]);
				}
			}
		}
		if (ccVars.Action == actionTypeBU.eventRotate)
		{
			dynamicInfo.Info = dynamicInfo.Info + AppLanguage.CadCamDynamic[0] + ": " + dynamicInfo.Len.ToString("f" + clsVar.varProgram.DecimalVisiblePoint) + " - " + AppLanguage.CadCamDynamic[2] + ": " + dynamicInfo.Ang.ToString("f" + clsVar.varProgram.DecimalVisiblePoint) + "º";
