		{
			return;
		}
		Vector3D vector3D = new Vector3D(ccVars.pntBase, Points);
		if (!(vector3D.Length > 0.0))
		{
			return;
		}
		Plane plane = new Plane(ccVars.pntBase, vector3D, ccVars.planeActive.AxisZ);
		ccVars.pntDrawDynamicLinesArr.Clear();
		for (int num26 = 0; num26 <= ccVars.SelectionOP.Selections.Count - 1; num26++)
