			clsInit.cVector5.DrawCurveOrBlockRef(entity6, ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Blocks, ref refPoints3);
			for (int num27 = 0; num27 <= refPoints3.Count - 1; num27++)
			{
				ccVars.pntDrawDynamicLinesArr.Add(refPoints3[num27]);
			}
		}
	}

	public void MoveStep4(Point3D Points, object sender, MouseEventArgs e)
	{
		ccVars.planeActive.Project(Points, out var s, out var t);
		ccVars.planeActive.Project(ccVars.pntBase, out var s2, out var t2);
		dynamicInfo.Len = clsInit.cVector5.Length2D(s, t, s2, t2);
		dynamicInfo.Ang = clsInit.cVector5.PointAngle(s, t, s2, t2);
		dynamicInfo.dX = clsInit.cVector5.DeltaX(Points, ccVars.pntBase);
		dynamicInfo.dY = clsInit.cVector5.DeltaY(Points, ccVars.pntBase);
		dynamicInfo.dZ = clsInit.cVector5.DeltaZ(Points, ccVars.pntBase);
		if (clsVar.varView.ShowCommandDynamicText)
		{
			dynamicInfo.Info = dynamicInfo.Command + " = ";
		}
		if (ccVars.Action == actionTypeBU.drawArc)
		{
			dynamicInfo.EndAng = dynamicInfo.Ang;
			if (dynamicInfo.EndAng < dynamicInfo.StartAng)
			{
				dynamicInfo.EndAng += 360.0;
			}
			if ((dynamicInfo.Rad > 0.001) & (dynamicInfo.EndAng > dynamicInfo.StartAng))
			{
				Arc arc = new Arc(ccVars.planeActive, ccVars.pntBase, dynamicInfo.Rad, ccVars.pntTip, Points, flip: false);
				int num = clsInit.cVector.CircleVerticeCountByResolution(arc.Radius, clsVar.varEntities.DynamicEntityResolution);
				dynamicInfo.Rad = arc.Radius;
				ccVars.pntDrawDynamicArr = new Point3D[num + 1];
				for (int i = 0; i <= num; i++)
				{
					ccVars.pntDrawDynamicArr[i] = arc.PointAt(arc.Domain.ParameterAt((double)i / (double)num));
				}
			}
			dynamicInfo.Info = AppLanguage.CadCamDynamic[23] + ": " + dynamicInfo.EndAng.ToString("f" + clsVar.varProgram.DecimalVisiblePoint);
			clsInit.cVector.BoxSizeCalculate(buConversion5.Point3DToPnt3D(Points), buConversion5.Point3DToPnt3D(ccVars.pntBase), ref ccVars.Spin1Prop.pntMin, ref ccVars.Spin1Prop.pntMid, ref ccVars.Spin1Prop.pntMax);
			ccVars.Pages[ccVars.PageIndex].Form.spn_val1.Value = (decimal)Math.Round(dynamicInfo.EndAng, clsVar.varProgram.DecimalVisiblePoint);
		}
		if (ccVars.Action == actionTypeBU.drawEllipseArc)
		{
			if ((dynamicInfo.MinorRad > 0.001) & (dynamicInfo.MajorRad > 0.001))
			{
				Ellipse ellipse = new Ellipse(ccVars.planeTemp, ccVars.pntBase, dynamicInfo.MajorRad, dynamicInfo.MinorRad);
				int num2 = clsInit.cVector.CircleVerticeCountByResolution(ellipse.RadiusX, clsVar.varEntities.DynamicEntityResolution);
				ccVars.pntDrawDynamicArr = new Point3D[num2 + 1];
				for (int j = 0; j <= num2; j++)
				{
					ccVars.pntDrawDynamicArr[j] = ellipse.PointAt(ellipse.Domain.ParameterAt((double)j / (double)num2));
				}
			}
			dynamicInfo.Info = AppLanguage.CadCamDynamic[20] + ": " + dynamicInfo.MajorRad.ToString("f" + clsVar.varProgram.DecimalVisiblePoint) + " - " + AppLanguage.CadCamDynamic[21] + ": " + dynamicInfo.MinorRad.ToString("f" + clsVar.varProgram.DecimalVisiblePoint);
			clsInit.cVector.BoxSizeCalculate(buConversion5.Point3DToPnt3D(Points), buConversion5.Point3DToPnt3D(ccVars.pntBase), ref ccVars.Spin1Prop.pntMin, ref ccVars.Spin1Prop.pntMid, ref ccVars.Spin1Prop.pntMax);
			ccVars.Pages[ccVars.PageIndex].Form.spn_val1.Value = (decimal)Math.Round(dynamicInfo.MinorRad, clsVar.varProgram.DecimalVisiblePoint);
		}
		if (ccVars.Action != actionTypeBU.eventRotate)
		{
			return;
		}
		ccVars.pntDrawDynamicLinesArr.Clear();
		for (int k = 0; k <= ccVars.SelectionOP.Selections.Count - 1; k++)
		{
			if (ccVars.SelectionOP.Selections[k].SelectedLinearPaths.Count > 0)
			{
				Entity entity = ccVars.SelectionOP.Selections[k].SelectedLinearPaths[0];
				double s3 = 0.0;
				double t3 = 0.0;
				ccVars.planeActive.Project(ccVars.pntTip, out s3, out t3);
				Vector2D vector2D = new Vector2D(new Point2D(s2, t2), new Point2D(s3, t3));
				vector2D.Normalize();
				Vector2D vector2D2 = new Vector2D(new Point2D(s2, t2), new Point2D(s, t));
				vector2D2.Normalize();
				double num3 = Vector2D.SignedAngleBetween(vector2D, vector2D2);
				dynamicInfo.Info = dynamicInfo.Info + " : " + buConversion.RadianToDegree(num3).ToString("f3");
				ccVars.Pages[ccVars.PageIndex].Form.spn_val1.Value = (decimal)Math.Round(buConversion.RadianToDegree(num3), clsVar.varProgram.DecimalVisiblePoint);
				Entity entity2 = (Entity)entity.Clone();
				entity2.Rotate(num3, ccVars.planeActive.AxisZ, ccVars.pntBase);
				List<List<Point3D>> refPoints = new List<List<Point3D>>();
				clsInit.cVector5.DrawCurveOrBlockRef(entity2, ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Blocks, ref refPoints);
				for (int l = 0; l <= refPoints.Count - 1; l++)
				{
					ccVars.pntDrawDynamicLinesArr.Add(refPoints[l]);
				}
			}
		}
	}

	public void MoveStep5(Point3D Points, object sender, MouseEventArgs e)
	{
		ccVars.planeActive.Project(Points, out var s, out var t);
		ccVars.planeActive.Project(ccVars.pntBase, out var s2, out var t2);
		dynamicInfo.Len = clsInit.cVector5.Length2D(s, t, s2, t2);
		dynamicInfo.Ang = clsInit.cVector5.PointAngle(s, t, s2, t2);
		dynamicInfo.dX = clsInit.cVector5.DeltaX(Points, ccVars.pntBase);
		dynamicInfo.dY = clsInit.cVector5.DeltaY(Points, ccVars.pntBase);
		dynamicInfo.dZ = clsInit.cVector5.DeltaZ(Points, ccVars.pntBase);
		if (clsVar.varView.ShowCommandDynamicText)
		{
			dynamicInfo.Info = dynamicInfo.Command + " = ";
		}
		if (ccVars.Action != actionTypeBU.drawEllipseArc)
		{
			return;
		}
		if ((dynamicInfo.MinorRad > 0.001) & (dynamicInfo.MajorRad > 0.001))
		{
			Ellipse ellipse = new Ellipse(ccVars.planeTemp, ccVars.pntBase, dynamicInfo.MajorRad, dynamicInfo.MinorRad);
			double angle = clsInit.cVector5.PointAngle(Points, ccVars.pntBase, ccVars.planeActive);
			Pnt3D EndPnt = new Pnt3D();
			clsInit.cVector.LineWithLengthAndAngle(buConversion5.Point3DToPnt3D(ccVars.pntBase), 1000.0, angle, buVector5.PlaneToWorkPlane(ccVars.planeActive), ref EndPnt);
			Line c = new Line(ccVars.pntBase, Points);
			Point3D[] array = ellipse.IntersectWith(c);
			if (array != null && array.Length != 0)
			{
				ellipse.ClosestPointTo(array[0], out dynamicInfo.EndLen);
			}
			if (dynamicInfo.StartLen > dynamicInfo.EndLen)
			{
				dynamicInfo.EndLen += Math.PI * 2.0;
			}
			if (dynamicInfo.EndLen - dynamicInfo.StartLen > Math.PI * 2.0)
			{
				dynamicInfo.EndLen = dynamicInfo.StartLen + Math.PI * 2.0;
			}
			EllipticalArc ellipticalArc = new EllipticalArc(ccVars.planeTemp, ccVars.pntBase, dynamicInfo.MajorRad, dynamicInfo.MinorRad, dynamicInfo.StartLen, dynamicInfo.EndLen);
			int num = clsInit.cVector.CircleVerticeCountByResolution(ellipticalArc.RadiusX, clsVar.varEntities.DynamicEntityResolution);
			ccVars.pntDrawDynamicArr = new Point3D[num + 1];
			for (int i = 0; i <= num; i++)
			{
				ccVars.pntDrawDynamicArr[i] = ellipticalArc.PointAt(ellipticalArc.Domain.ParameterAt((double)i / (double)num));
			}
		}
		dynamicInfo.Info = AppLanguage.CadCamDynamic[20] + ": " + dynamicInfo.MajorRad.ToString("f" + clsVar.varProgram.DecimalVisiblePoint) + " - " + AppLanguage.CadCamDynamic[21] + ": " + dynamicInfo.MinorRad.ToString("f" + clsVar.varProgram.DecimalVisiblePoint);
		clsInit.cVector.BoxSizeCalculate(buConversion5.Point3DToPnt3D(Points), buConversion5.Point3DToPnt3D(ccVars.pntBase), ref ccVars.Spin1Prop.pntMin, ref ccVars.Spin1Prop.pntMid, ref ccVars.Spin1Prop.pntMax);
		ccVars.Pages[ccVars.PageIndex].Form.spn_val1.Value = (decimal)Math.Round(dynamicInfo.MinorRad, clsVar.varProgram.DecimalVisiblePoint);
	}

	public void viewportMouseUp(Point3D Points, object sender, MouseEventArgs e)
	{
		try
		{
			if (Points != null)
			{
				ccVars.pntMouseUp.X = Points.X;
				ccVars.pntMouseUp.Y = Points.Y;
				ccVars.pntMouseUp.Z = Points.Z;
			}
			if (mouseDownViewport_1 != null)
			{
				mouseDownViewport_1(Points.X, Points.Y, Points.Z, sender, e);
			}
			if ((clsInit.appDrill != null) & clsVar.UserMode.DrillMode.Enable)
			{
				clsInit.appDrill.viewportMouseUp(Points, sender, e);
			}
			if ((clsInit.appMarble != null) & clsVar.UserMode.MarbleMode.Enable)
			{
				clsInit.appMarble.viewportMouseUp(Points, sender, e);
			}
			if (!((ccVars.stpDrawing == 0) & (ccVars.Action == actionTypeBU.None) & (e.Button == MouseButtons.Left)))
			{
				if (ccVars.stpDrawing != 1)
				{
					if (ccVars.stpDrawing != 2)
					{
						if (ccVars.stpDrawing != 3)
						{
							if (ccVars.stpDrawing != 4)
							{
								if (ccVars.stpDrawing == 5)
								{
									UpStep5(Points, sender, e);
								}
							}
							else
							{
								UpStep4(Points, sender, e);
							}
						}
						else
						{
							UpStep3(Points, sender, e);
						}
					}
					else
					{
						UpStep2(Points, sender, e);
					}
				}
				else
				{
					UpStep1(Points, sender, e);
				}
			}
			else
			{
				UpStep0(Points, sender, e);
			}
		}
		catch (Exception mSException)
		{
			buLog.addLog("", "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: true, "");
		}
	}

