							{
								buString.MessageBoxError(AppLanguage.CadCamMessages[6]);
								clsInit.appCommand.Reset();
							}
							else
							{
								Exchange();
							}
							return;
						}
						ccVars.stpDrawing = 2;
						ccVars.selectionProcess = false;
						if (ccVars.Action == actionTypeBU.eventRotateVerHor)
						{
							ccVars.selectionProcess = true;
						}
						formStatusUpdate_0(AppLanguage.CadCamStatus[11] + " [ " + dynamicInfo.Command + " ]");
