						{
							formStatusUpdate_0(AppLanguage.CadCamStatus[19] + " [ " + dynamicInfo.Command + " ]");
						}
						if (ccVars.Action == actionTypeBU.eventScale)
						{
							formStatusUpdate_0(AppLanguage.CadCamStatus[31] + " [ " + dynamicInfo.Command + " ]");
							ccVars.enableDynamicalSpins = true;
							if (!clsVar.varInterface.ScaleVar.KeepTheRatio)
							{
								ccVars.Spin1Prop.Visible = true;
								ccVars.Spin2Prop.Visible = true;
							}
							else
							{
								ccVars.Spin1Prop.Visible = true;
							}
						}
						if (ccVars.Action == actionTypeBU.eventOffset)
						{
							formStatusUpdate_0(AppLanguage.CadCamStatus[31] + " [ " + dynamicInfo.Command + " ]");
						}
					}
					else
					{
						Join();
					}
				}
				else
				{
					Delete(applyReset: true);
				}
				return;
			}
			if (ccVars.SelectionOP.Selections.Count != 1)
			{
