			ccVars.stpDrawing = 2;
			formStatusUpdate_0(AppLanguage.CadCamStatus[119]);
			ccVars.selectionProcess = false;
			return;
		}
		if (ccVars.SelectionOP.Selections.Count != 1)
		{
			buString.MessageBoxWarning(AppLanguage.CadCamMessages[24]);
			Reset();
			return;
