				dynamicInfo.Rad = ((Circle)ccVars.SelectionOP.Selections[0].SelectedEntity).Radius;
				ccVars.pntBase = buVector5.ToPoint3D(((Circle)ccVars.SelectionOP.Selections[0].SelectedEntity).Center);
				dynamicInfo.Info = "R : " + ((Circle)ccVars.SelectionOP.Selections[0].SelectedEntity).Radius.ToString("f3");
				ccVars.stpDrawing = 2;
				formStatusUpdate_0(AppLanguage.CadCamStatus[119]);
				ccVars.selectionProcess = false;
			}
			return;
		}
		if (entity4 is Circle)
		{
			dynamicInfo.Rad = ((Circle)entity4).Radius;
			ccVars.pntBase = buVector5.ToPoint3D(((Circle)entity4).Center);
