									clsInit.appDiemaker.doSlot();
								}
							}
							else
							{
								GetChainEntitiesSettings settings14 = new GetChainEntitiesSettings(addToselection: true, ViewportCC.entityPickIndex, clsVar.varSelection.UseSelectedEntityLayerForChainEntities);
								clsInit.cVector5.GetChainEntities(Points, ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.ToList(), ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Blocks, settings14, ref ccVars.SelectionOP);
							}
						}
						else
						{
							clsInit.appRouter3AX.doWireframeCenterPath(Router3AXLayerPurpose.None, ccVars.toolActive);
						}
					}
					else
					{
						clsInit.appRouter3AX.doWireframePocket(Router3AXLayerPurpose.None, ccVars.toolActive);
					}
				}
				else
				{
					clsInit.appRouter3AX.doWireframeContour(Router3AXLayerPurpose.None, ccVars.toolActive);
				}
			}
			else if (ccVars.pntDrawDynamicLines.Count >= 2)
			{
				Entity Ent = null;
