			double num2 = clsInit.cVector5.PointAngle(((ICurve)ViewportCC.PickedLastEntity).EndPoint, ((ICurve)ViewportCC.PickedLastEntity).StartPoint);
			if (!(!buCompare5.EQ(num2, 0.0) & !buCompare5.EQ(num2, 180.0)))
			{
