	public void viewportSelectionChanged(object sender, SelectionChangedEventArgs e)
	{
		int num = 0;
		object[] array = new object[e.AddedItems.Count];
		num = 0;
		MeasureItem measureItem = null;
		Brep brep = null;
		Brep.Edge edge = null;
		int num2 = -1;
		for (int i = 0; i < e.AddedItems.Count; i++)
		{
			SelectedItem selectedItem = e.AddedItems[i];
			if (!(selectedItem is SelectedFace))
			{
				if (!(selectedItem is SelectedEdge))
				{
					if (!(selectedItem is SelectedVertex))
					{
						array[num++] = e.AddedItems[i].Item;
						measureItem = new MeasureItem(e.AddedItems[i].Item, selectionFilterType.Entity, new Point3D());
						continue;
					}
					SelectedVertex selectedVertex = (SelectedVertex)selectedItem;
					ISelectableItem item = selectedVertex.Item;
					if (item is Brep)
					{
						Brep brep2 = (Brep)item;
						array[num++] = brep2.Vertices[selectedVertex.Index];
						measureItem = new MeasureItem(brep2.Vertices[selectedVertex.Index], selectionFilterType.Vertex, new Point3D());
					}
					continue;
				}
				SelectedEdge selectedEdge = (SelectedEdge)selectedItem;
				ISelectableItem item2 = selectedEdge.Item;
				if (item2 is Brep)
				{
					if (clsInit.appPipeBending != null)
					{
						clsInit.appPipeBending.SelectedIndex(selectedEdge.Index);
					}
					num2 = selectedEdge.Index;
					brep = (Brep)item2;
					Brep brep3 = (Brep)item2;
					array[num++] = brep3.Edges[selectedEdge.Index];
					edge = brep3.Edges[selectedEdge.Index];
					Point3D overPoint = new Point3D();
					clsInit.cVector5.GetPointOnEntity(ccVars.pntActive, brep3.Edges[selectedEdge.Index].Curve, ref overPoint);
					measureItem = new MeasureItem(brep3.Edges[selectedEdge.Index], selectionFilterType.Edge, overPoint);
					measureItem.BoxMin = buVector5.ToPoint3D(((Entity)brep3.Edges[selectedEdge.Index].Curve).BoxMin);
					measureItem.BoxMax = buVector5.ToPoint3D(((Entity)brep3.Edges[selectedEdge.Index].Curve).BoxMax);
				}
				continue;
			}
			SelectedFace selectedFace = (SelectedFace)selectedItem;
			ISelectableItem item3 = selectedFace.Item;
			if (item3 is Mesh)
			{
				continue;
			}
			if (!(item3 is Brep))
			{
				if (item3 is Solid)
				{
					Solid solid = (Solid)item3;
					Mesh.FaceElement obj = solid.Faces[selectedFace.Index];
					measureItem = new MeasureItem(obj, selectionFilterType.Face, new Point3D());
				}
				continue;
			}
			brep = (Brep)item3;
			Brep brep4 = (Brep)item3;
			if (selectedFace.ShellIndex != 0)
			{
				ccVars.selectedFace = brep4.Inners[selectedFace.ShellIndex - 1][selectedFace.Index];
				measureItem = new MeasureItem(ccVars.selectedFace, selectionFilterType.Face, new Point3D());
				continue;
			}
			brep4.Rebuild();
			ccVars.selectedFace = brep4.Faces[selectedFace.Index];
			measureItem = new MeasureItem(ccVars.selectedFace, selectionFilterType.Face, new Point3D());
			if (ccVars.Action == actionTypeBU.profileSelectPlaneThenOperation && ccVars.selectedFace != null)
			{
				clsInit.appProfile.doFindPlane(ccVars.selectedFace, RunOperation: true, AddList: true);
			}
			if (ccVars.Action == actionTypeBU.profileSelectPlaneThenAdd && ccVars.selectedFace != null)
			{
				clsInit.appProfile.doFindPlane(ccVars.selectedFace, RunOperation: false, AddList: true);
			}
		}
		if (ccVars.Action == actionTypeBU.drawMeasure)
		{
			MeasureUpdate(measureItem);
		}
		if (!((ccVars.Action == actionTypeBU.camContours) | (ccVars.Action == actionTypeBU.camPocketing)) || !(brep != null && edge != null && num2 >= 0) || brep == null)
		{
			return;
		}
		List<Entity> Curves = new List<Entity>();
		List<int> EdgeIndex = new List<int>();
		clsInit.cVector5.GetEdgesOfBrep(brep, edge, num2, ref Curves, ref EdgeIndex);
		for (int j = 0; j <= EdgeIndex.Count - 1; j++)
		{
			((Brep)ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[0]).SetEdgeSelection(EdgeIndex[j], status: true);
		}
		if (Curves.Count > 0)
		{
			if (ccVars.entityEdges == null)
			{
				ccVars.entityEdges = new List<List<Entity>>();
			}
			ccVars.entityEdges.Clear();
			List<Entity> SortedEntities = new List<Entity>();
			List<int> SortedEntitesIndex = new List<int>();
			GetChainEntities(((ICurve)Curves[0]).StartPoint, Curves, AddToSelection: false, ref SortedEntities, ref SortedEntitesIndex);
			ccVars.entityEdges.Add(SortedEntities);
			SortedEntitesIndex.Clear();
		}
	}

	public void SelectAndBrakeByFreeSelection(List<Point3D> Points)
	{
		undoBuffer();
