	public void ManageSelection(Entity ent, Keys ModifierKeys)
	{
		if (ModifierKeys != Keys.Control)
		{
			ent.Selected = true;
		}
		else
		{
			ent.Selected = !ent.Selected;
		}
	}

	public void ManageSelection(int ent, Keys ModifierKeys, List<int> added, List<int> removed)
	{
		bool remove = false;
		if (ModifierKeys != Keys.Control)
		{
			if (ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[ent].Selected)
			{
				if (ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[ent] is CompositeCurve)
				{
					added.Add(ent);
				}
			}
			else
			{
				added.Add(ent);
			}
			ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[ent].Selected = true;
		}
		else
		{
			ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[ent].Selected = !ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[ent].Selected;
			if (!ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[ent].Selected)
			{
				removed.Add(ent);
			}
			else
			{
				added.Add(ent);
			}
			remove = true;
		}
		if (!clsVar.varSelection.DontSelectGroupItem)
		{
			ManageGroupSelection(ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[ent], ent, remove, added, removed);
		}
	}

	public void ManageGroupSelection(Entity entSelected, int RefEntIndex, bool Remove, List<int> added, List<int> removed)
	{
		int groupIdIndex = clsInit.cVector5.GetGroupIdIndex(entSelected);
		if (groupIdIndex < 0)
		{
			return;
		}
		for (int i = 0; i <= ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Count - 1; i++)
		{
			int groupIdIndex2 = clsInit.cVector5.GetGroupIdIndex(ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[i]);
			if (Remove)
			{
				if (ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[i].Selected && i != RefEntIndex && groupIdIndex == groupIdIndex2)
				{
					ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[i].Selected = false;
					removed.Add(i);
				}
			}
			else if ((entSelected.Selected & !ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[i].Selected) && i != RefEntIndex && groupIdIndex == groupIdIndex2 && groupIdIndex2 >= 0)
			{
				ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[i].Selected = true;
				added.Add(i);
			}
		}
	}

	public void SelectedToSelectionAdd(List<int> Added)
	{
		for (int i = 0; i <= Added.Count - 1; i++)
		{
			SelectionEntity SelEntity = new SelectionEntity(Added[i]);
			SelEntity.SelectedEntity = ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[Added[i]];
			ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[Added[i]].Selected = true;
			clsInit.cVector5.DrawCurveOrBlockRef(SelEntity.SelectedEntity, ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Blocks, ref SelEntity.SelectedVertices);
			if (SelEntity.SelectedEntity is ICurve)
			{
				double t = 0.0;
				((ICurve)SelEntity.SelectedEntity).ClosestPointTo(ccVars.pntActive, out t);
				SelEntity.pntClickEntityOver = ((ICurve)SelEntity.SelectedEntity).PointAt(t);
			}
			if (SelEntity.SelectedEntity is CompositeCurve)
			{
				double num = double.MaxValue;
				for (int j = 0; j <= ((CompositeCurve)SelEntity.SelectedEntity).CurveList.Count - 1; j++)
				{
					ICurve curve = ((CompositeCurve)SelEntity.SelectedEntity).CurveList[j];
					double t2 = 0.0;
					curve.ClosestPointTo(ccVars.pntActive, out t2);
					Point3D point3D = curve.PointAt(t2);
					double num2 = Point3D.Distance(point3D, ccVars.pntActive);
					if (((t2 > 0.0) & (t2 > curve.Domain.Min) & (t2 < curve.Domain.Max)) && num2 < num)
					{
						num = num2;
						buEntity.Copy((Entity)curve, ref SelEntity.SelectedSubEntity);
						SelEntity.SubIndex = j;
						SelEntity.pntClickEntityOver = buVector5.ToPoint3D(point3D);
					}
				}
			}
			SelEntity.SelectedLinearPaths = new List<Entity>();
			for (int k = 0; k <= SelEntity.SelectedVertices.Count - 1; k++)
			{
				LinearPath item = new LinearPath(SelEntity.SelectedVertices[k]);
				SelEntity.SelectedLinearPaths.Add(item);
			}
			if (SelEntity.SelectedEntity.BoxMin == null)
			{
				SelEntity.SelectedEntity.Regen(0.01);
			}
			SelEntity.pntClick = buVector5.ToPoint3D(ccVars.pntActive);
			SelEntity.BoxMin = buVector5.ToPoint3D(SelEntity.SelectedEntity.BoxMin);
			SelEntity.BoxMax = buVector5.ToPoint3D(SelEntity.SelectedEntity.BoxMax);
			SelEntity.EntitiesBoxPointList.Add(SelEntity.BoxMin);
			SelEntity.EntitiesBoxPointList.Add(SelEntity.BoxMax);
			clsInit.cVector5.SelectionAlingPoints(ref SelEntity);
			ccVars.SelectionOP.Selections.Add(SelEntity);
		}
		SelectionBoxSizeCalculate();
	}

	public void SelectedToSelectionRemove(List<int> Removed)
	{
		for (int i = 0; i <= Removed.Count - 1; i++)
		{
			for (int j = 0; j <= ccVars.SelectionOP.Selections.Count - 1; j++)
			{
				if (ccVars.SelectionOP.Selections[j].Index == Removed[i])
				{
					ccVars.SelectionOP.Selections.RemoveAt(j);
				}
			}
		}
	}

	public void SelectionFromEntity(Point3D refPoint, int Index, entitySortDirection Direction, ref SelectionEntity S)
	{
		S = new SelectionEntity(Index);
		S.SelectedEntity = ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[Index];
		clsInit.cVector5.DrawCurveOrBlockRef(S.SelectedEntity, ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Blocks, ref S.SelectedVertices);
		clsInit.cVector5.SetSortDirection(Direction, ref S.SelectedEntity);
		if (S.SelectedEntity is CompositeCurve)
		{
			double num = double.MaxValue;
			for (int i = 0; i <= ((CompositeCurve)S.SelectedEntity).CurveList.Count - 1; i++)
			{
				ICurve curve = ((CompositeCurve)S.SelectedEntity).CurveList[i];
				double t = 0.0;
				curve.ClosestPointTo(refPoint, out t);
				Point3D a = curve.PointAt(t);
				double num2 = Point3D.Distance(a, refPoint);
				if (((t > 0.0) & (t > curve.Domain.Min) & (t < curve.Domain.Max)) && num2 < num)
				{
					num = num2;
					S.SelectedSubEntity = (Entity)((Entity)curve).Clone();
				}
			}
		}
		S.SelectedLinearPaths = new List<Entity>();
		for (int j = 0; j <= S.SelectedVertices.Count - 1; j++)
		{
			LinearPath item = new LinearPath(S.SelectedVertices[j]);
			S.SelectedLinearPaths.Add(item);
		}
		if (S.SelectedEntity.BoxMin == null)
		{
			S.SelectedEntity.Regen(0.01);
		}
		S.pntClick = buVector5.ToPoint3D(refPoint);
		S.BoxMin = buVector5.ToPoint3D(S.SelectedEntity.BoxMin);
		S.BoxMax = buVector5.ToPoint3D(S.SelectedEntity.BoxMax);
		S.EntitiesBoxPointList.Add(S.BoxMin);
		S.EntitiesBoxPointList.Add(S.BoxMax);
	}

	public void SelectionBoxSizeCalculate()
	{
		List<Point3D> list = new List<Point3D>();
		for (int i = 0; i <= ccVars.SelectionOP.Selections.Count - 1; i++)
		{
			list.Add(ccVars.SelectionOP.Selections[i].BoxMin);
			list.Add(ccVars.SelectionOP.Selections[i].BoxMax);
		}
		Utility.BoundingBox(list, out ccVars.SelectionOP.SelectionBoxMin, out ccVars.SelectionOP.SelectionBoxMax);
		ccVars.SelectionOP.SelectionBoxMid = clsInit.cVector5.MiddlePointOfLine(ccVars.SelectionOP.SelectionBoxMin, ccVars.SelectionOP.SelectionBoxMax);
	}

	public void SelectionToEntities(ref List<Entity> selectedEntities, SelectionToEntitiesOptions Options)
	{
		selectedEntities.Clear();
		for (int i = 0; i <= ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Count - 1; i++)
		{
			if (!ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[i].Selected)
			{
				continue;
			}
			Entity entity = buVector5.CopyEntities(ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[i]);
			if (!(entity is CompositeCurve))
			{
				if (!((entity.GetType() == typeof(Circle)) & Options.CircleToArc))
				{
					if (entity.Vertices == null)
					{
						entity.Regen(new RegenParams(clsVar.varEntities.RegenDeviation));
					}
					selectedEntities.Add(entity);
				}
				else
				{
					Circle circle = entity as Circle;
					Arc arc = new Arc(circle.Plane, circle.Center, circle.Radius, 0.0, Math.PI);
					arc.Regen(new RegenParams(clsVar.varEntities.RegenDeviation));
					Arc arc2 = new Arc(circle.Plane, circle.Center, circle.Radius, Math.PI, Math.PI * 2.0);
					arc2.Regen(new RegenParams(clsVar.varEntities.RegenDeviation));
					selectedEntities.Add(arc);
					selectedEntities.Add(arc2);
				}
				continue;
			}
			CompositeCurve compositeCurve = entity as CompositeCurve;
			for (int j = 0; j <= compositeCurve.CurveList.Count - 1; j++)
			{
				Entity entity2 = buVector5.CopyEntities((Entity)compositeCurve.CurveList[j]);
				if (entity2.Vertices == null)
				{
					entity2.Regen(new RegenParams(clsVar.varEntities.RegenDeviation));
				}
				selectedEntities.Add(entity2);
			}
		}
	}

