			List<Entity> copiedEnt = new List<Entity>();
			buVector5.CopyEntities(ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities, ref copiedEnt);
			List<Entity> SortedEntities = new List<Entity>();
			new List<int>();
			new SelectionOperation();
			SortSettings sortSettings = new SortSettings();
			SortResult Result = new SortResult();
			sortSettings.Option.IntersectionRules = SortingIntersectionRulesType.ClosestLength;
			clsInit.cVector5.GetClosedEntitiesByRefPointUsingCrossLines(refPoint, ref copiedEnt, sortSettings, ref SortedEntities, ref Result);
			for (int i = 0; i <= SortedEntities.Count - 1; i++)
			{
				CustomData customData = (CustomData)SortedEntities[i].EntityData;
				if ((customData.OriginalEntityIndex >= 0) & (customData.OriginalEntityIndex <= ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Count - 1))
				{
					ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[customData.OriginalEntityIndex].Selected = true;
				}
			}
			clsInit.appCommand.undoBuffer();
			for (int j = 0; j <= SortedEntities.Count - 1; j++)
			{
				ccVars.UndoDont = true;
				SortedEntities[j].ColorMethod = colorMethodType.byEntity;
				SortedEntities[j].Color = Color.Lime;
				SortedEntities[j].LineWeightMethod = colorMethodType.byEntity;
				SortedEntities[j].LineWeight = 3f;
			}
			ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Invalidate();
		}
		catch (Exception mSException)
		{
			buLog.addLog("", "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: true, "");
		}
	}

