	public void SelectionAnalyzeAfterSelected(Keys ModifierKeys)
	{
		List<int> list = new List<int>();
		if (!(clsVar.varSelection.SelectInternalEntitiesWhenClick || ModifierKeys == Keys.Shift))
		{
			return;
		}
		for (int i = 0; i <= ccVars.SelectionOP.Selections.Count - 1; i++)
		{
			bool flag = false;
			List<Point3D> Points = new List<Point3D>();
			clsInit.cVector5.EntitiesToPointsWithCamDirection(ccVars.SelectionOP.Selections[i].SelectedLinearPaths, 0.05, ref Points);
			if (Points.Count >= 2 && buCompare5.EQ(Points[0], Points[Points.Count - 1]))
			{
				flag = true;
			}
			if (!flag)
			{
				continue;
			}
			for (int j = 0; j <= ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Count - 1; j++)
			{
				Entity entity = ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[j];
				if (!(!ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[j].Selected & ((ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[j] is ICurve) | (ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[j] is Text))))
				{
					continue;
				}
				if (entity.Vertices == null)
				{
					entity.Regen(0.05);
				}
				if (entity.Vertices.Length > 10)
				{
					int num = entity.Vertices.Length / 10;
					for (int k = 0; k <= entity.Vertices.Length - 1; k += num)
					{
						if (clsInit.cVector5.IsPointInsidePolygon(Points, entity.Vertices[k]))
						{
							list.Add(j);
							k = entity.Vertices.Length;
						}
					}
					continue;
				}
				for (int l = 0; l <= entity.Vertices.Length - 1; l++)
				{
					if (clsInit.cVector5.IsPointInsidePolygon(Points, entity.Vertices[l]))
					{
						list.Add(j);
						l = entity.Vertices.Length;
					}
				}
			}
		}
		if (list.Count > 0)
		{
			SelectedToSelectionAdd(list);
		}
		ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Invalidate();
	}

	public void GetChainEntities(Point3D RefPoint, List<Entity> refEntities, bool AddToSelection)
	{
		List<Entity> SortedEntities = new List<Entity>();
		List<int> SortedEntitesIndex = new List<int>();
		GetChainEntities(RefPoint, refEntities, AddToSelection, ref SortedEntities, ref SortedEntitesIndex);
		SortedEntities.Clear();
		SortedEntitesIndex.Clear();
		SortedEntities = null;
		SortedEntitesIndex = null;
	}

	public void GetChainEntities(Point3D RefPoint, List<Entity> refEntities, bool AddToSelection, ref List<Entity> SortedEntities, ref List<int> SortedEntitesIndex)
	{
		try
		{
			int Sequence = -1;
			Point3D pntFound = new Point3D();
			StartEndType FoundLocation = StartEndType.Start;
			SortSettings settings = new SortSettings();
			clsInit.cVector5.MostClosestPoint(RefPoint, refEntities, settings, ref Sequence, ref pntFound, ref FoundLocation);
			SortedEntitesIndex.Clear();
			List<Entity> copiedEnt = new List<Entity>();
			buVector5.CopyEntities(refEntities, ref copiedEnt);
			bool flag = false;
			if (Sequence < 0)
			{
				return;
			}
			new Point3D();
			for (int i = 0; i <= copiedEnt.Count - 1; i++)
			{
				for (int j = 0; j <= refEntities.Count - 1; j++)
				{
					if (!((refEntities[j] is ICurve) & refEntities[j].Selectable))
					{
						continue;
					}
					ICurve curve = (ICurve)refEntities[j];
					if (!buCompare5.EQ(pntFound, curve.StartPoint, buSystem.resolutionSorting))
					{
						if (!buCompare5.EQ(pntFound, curve.EndPoint, buSystem.resolutionSorting))
						{
							if (!(curve is CompositeCurve))
							{
								continue;
							}
							CompositeCurve compositeCurve = curve as CompositeCurve;
							for (int k = 0; k <= compositeCurve.CurveList.Count - 1; k++)
							{
								ICurve curve2 = compositeCurve.CurveList[k];
								if (!buCompare5.EQ(pntFound, curve2.StartPoint, buSystem.resolutionSorting))
								{
									if (buCompare5.EQ(pntFound, curve2.EndPoint, buSystem.resolutionSorting) && !clsInit.cVector.IsIndexNumberAvailableAtList(SortedEntitesIndex, j))
									{
										SortedEntitesIndex.Add(j);
										Entity refEntity = buVector5.CopyEntities(refEntities[j]);
										clsInit.cVector5.SetSortDirection(entitySortDirection.Reverse, ref refEntity);
										SortedEntities.Add(refEntity);
										if (AddToSelection)
										{
											SelectionEntity S = null;
											SelectionFromEntity(RefPoint, j, entitySortDirection.Normal, ref S);
											ccVars.SelectionOP.Selections.Add(S);
										}
										pntFound = buVector5.ToPoint3D(curve2.StartPoint);
										refEntities[j].Selected = true;
										j = refEntities.Count;
										flag = true;
									}
								}
								else if (!clsInit.cVector.IsIndexNumberAvailableAtList(SortedEntitesIndex, j))
								{
									SortedEntitesIndex.Add(j);
									Entity refEntity2 = buVector5.CopyEntities(refEntities[j]);
									clsInit.cVector5.SetSortDirection(entitySortDirection.Normal, ref refEntity2);
									SortedEntities.Add(refEntity2);
									if (AddToSelection)
									{
										SelectionEntity S2 = null;
										SelectionFromEntity(RefPoint, j, entitySortDirection.Normal, ref S2);
										ccVars.SelectionOP.Selections.Add(S2);
									}
									pntFound = buVector5.ToPoint3D(curve2.EndPoint);
									refEntities[j].Selected = true;
									j = refEntities.Count;
									flag = true;
								}
							}
						}
						else if (!clsInit.cVector.IsIndexNumberAvailableAtList(SortedEntitesIndex, j))
						{
							SortedEntitesIndex.Add(j);
							Entity refEntity3 = buVector5.CopyEntities(refEntities[j]);
							clsInit.cVector5.SetSortDirection(entitySortDirection.Reverse, ref refEntity3);
							SortedEntities.Add(refEntity3);
							if (AddToSelection)
							{
								SelectionEntity S3 = null;
								SelectionFromEntity(RefPoint, j, entitySortDirection.Normal, ref S3);
								ccVars.SelectionOP.Selections.Add(S3);
							}
							pntFound = buVector5.ToPoint3D(curve.StartPoint);
							refEntities[j].Selected = true;
							j = refEntities.Count;
							flag = true;
						}
					}
					else if (!clsInit.cVector.IsIndexNumberAvailableAtList(SortedEntitesIndex, j))
					{
						SortedEntitesIndex.Add(j);
						Entity refEntity4 = buVector5.CopyEntities(refEntities[j]);
						clsInit.cVector5.SetSortDirection(entitySortDirection.Normal, ref refEntity4);
						SortedEntities.Add(refEntity4);
						if (AddToSelection)
						{
							SelectionEntity S4 = null;
							SelectionFromEntity(RefPoint, j, entitySortDirection.Normal, ref S4);
							ccVars.SelectionOP.Selections.Add(S4);
						}
						pntFound = buVector5.ToPoint3D(curve.EndPoint);
						refEntities[j].Selected = true;
						j = refEntities.Count;
						flag = true;
					}
				}
			}
			if (flag && AddToSelection)
			{
				ccVars.SelectionOP.ClickList.Add(buVector5.ToPoint3D(RefPoint));
			}
		}
		catch (Exception mSException)
		{
			string text = "";
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
		}
	}

	public void MeasureCommands(object Data)
	{
		if (Data == null)
		{
			return;
		}
		if (Data.ToString() == "face")
		{
			cmdSelectDynamicFace();
		}
		if (Data.ToString() == "edge")
		{
			cmdSelectDynamicEdge();
		}
		if (Data.ToString() == "entity")
		{
			cmdSelectDynamicEntity();
		}
		if (Data.ToString() == "vertex")
		{
			cmdSelectDynamicVertex();
		}
		if (Data.ToString() == "point")
		{
			cmdSelectDynamicPoint();
		}
		if (Data.ToString() == "min")
		{
			clsVar.varSelection.DynamicSelectionDistanceType = MinMaxType.Min;
			if (ccVars.LastMeasured >= 0)
			{
				MeasureShow(ccVars.LastMeasured);
			}
		}
		if (Data.ToString() == "max")
		{
			clsVar.varSelection.DynamicSelectionDistanceType = MinMaxType.Max;
			if (ccVars.LastMeasured >= 0)
			{
				MeasureShow(ccVars.LastMeasured);
			}
		}
		if (Data.ToString() == "xenable")
		{
			clsVar.varInterface.DynamicSelectionX = true;
			if (ccVars.LastMeasured >= 0)
			{
				MeasureShow(ccVars.LastMeasured);
			}
		}
		if (Data.ToString() == "xdisable")
		{
			clsVar.varInterface.DynamicSelectionX = false;
			if (ccVars.LastMeasured >= 0)
			{
				MeasureShow(ccVars.LastMeasured);
			}
		}
		if (Data.ToString() == "yenable")
		{
			clsVar.varInterface.DynamicSelectionY = true;
			if (ccVars.LastMeasured >= 0)
			{
				MeasureShow(ccVars.LastMeasured);
			}
		}
		if (Data.ToString() == "ydisable")
		{
			clsVar.varInterface.DynamicSelectionY = false;
			if (ccVars.LastMeasured >= 0)
			{
				MeasureShow(ccVars.LastMeasured);
			}
		}
		if (Data.ToString() == "zenable")
		{
			clsVar.varInterface.DynamicSelectionZ = true;
			if (ccVars.LastMeasured >= 0)
			{
				MeasureShow(ccVars.LastMeasured);
			}
		}
		if (Data.ToString() == "zdisable")
		{
			clsVar.varInterface.DynamicSelectionZ = false;
			if (ccVars.LastMeasured >= 0)
			{
				MeasureShow(ccVars.LastMeasured);
			}
		}
		if (Data.ToString() == "clearlast")
		{
			ccVars.MeasureObjects.Clear();
			clsItem.FrmMeasure.lbl_selected.Text = "";
			for (int i = 0; i <= ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Count - 1; i++)
			{
				if (ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[i] is Brep)
				{
					((Brep)ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[i]).ClearEdgesSelection(null);
					((Brep)ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[i]).ClearFacesSelection();
					((Brep)ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[i]).ClearVerticesSelection(null);
				}
			}
		}
		if (Data.ToString() == "clearall" && clsItem.FrmMeasure != null)
		{
			for (int j = 0; j <= ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Count - 1; j++)
			{
				if (ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[j] is Brep)
				{
					((Brep)ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[j]).ClearEdgesSelection(null);
					((Brep)ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[j]).ClearFacesSelection();
					((Brep)ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[j]).ClearVerticesSelection(null);
				}
			}
			clsItem.FrmMeasure.tree_item.Nodes.Clear();
			ccVars.SelectedMeasureObjects.Clear();
			ccVars.pntDrawDynamicMeasure.Clear();
			ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Invalidate();
		}
		if (Data.ToString() == "clear" && clsItem.FrmMeasure != null)
		{
			for (int k = 0; k <= ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Count - 1; k++)
			{
				if (ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[k] is Brep)
				{
					((Brep)ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[k]).ClearEdgesSelection(null);
					((Brep)ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[k]).ClearFacesSelection();
					((Brep)ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[k]).ClearVerticesSelection(null);
				}
			}
			clsItem.FrmMeasure.txt_explanation.Text = "";
			ccVars.pntDrawDynamicMeasure.Clear();
			if ((ccVars.LastMeasured >= 0) & (ccVars.LastMeasured <= ccVars.SelectedMeasureObjects.Count - 1))
			{
				ccVars.SelectedMeasureObjects.RemoveAt(ccVars.LastMeasured);
				MeasureFill();
				if (ccVars.SelectedMeasureObjects.Count <= 0)
				{
					ccVars.LastMeasured = -1;
				}
				else
				{
					if (ccVars.LastMeasured > ccVars.SelectedMeasureObjects.Count - 1)
					{
						ccVars.LastMeasured = 0;
					}
					MeasureShow(ccVars.LastMeasured);
				}
			}
			ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Invalidate();
		}
		if (formUpdate_0 != null)
		{
			formUpdate_0(MenuUpdate: false, SettingUpdate: true, ControlsUpdate: false);
		}
	}

	public void MeasureUpdate(MeasureItem item)
	{
		try
		{
			if (item == null)
			{
				return;
			}
			string text = "";
			if (item.Type != selectionFilterType.Face)
			{
				if (item.Type != selectionFilterType.Edge)
				{
					if (item.Type != selectionFilterType.Entity)
					{
						if (item.Type == selectionFilterType.Vertex)
						{
							text = "Vertex" + ccVars.MeasureObjects.Count + "- ";
							if (item.Object is Brep.Vertex)
							{
								text = text + " - Position ( X: " + ((Point3D)item.Object).X.ToString("f3");
								text = text + " , Y: " + ((Point3D)item.Object).Y.ToString("f3");
								text = text + " , Z: " + ((Point3D)item.Object).Z.ToString("f3") + " )";
							}
						}
					}
					else
					{
						text += " ";
						Entity entity = (Entity)item.Object;
						if (entity is devDept.Eyeshot.Entities.Point)
						{
							devDept.Eyeshot.Entities.Point point = (devDept.Eyeshot.Entities.Point)entity;
							text += " Point ";
							text = text + " - ( X: " + point.StartPoint.X.ToString("f3");
							text = text + " , Y: " + point.StartPoint.Y.ToString("f3");
							text = text + " , Z: " + point.StartPoint.Z.ToString("f3") + " )";
						}
						if (entity is Line)
						{
							Line line = (Line)entity;
							text = text + " Line - Length: " + line.Length().ToString("f3");
							text = text + " - ( dX: " + (line.BoxMax.X - line.BoxMin.X).ToString("f3");
							text = text + " , dY: " + (line.BoxMax.Y - line.BoxMin.Y).ToString("f3");
							text = text + " , dZ: " + (line.BoxMax.Z - line.BoxMin.Z).ToString("f3") + " )";
						}
						if (entity is Arc)
						{
							Arc arc = (Arc)entity;
							arc.Regen(0.01);
							text = text + "Arc - Radius : " + Math.Round(arc.Radius, 3).ToString("f3");
							text = text + " - ( dX: " + (arc.BoxMax.X - arc.BoxMin.X).ToString("f3");
							text = text + " , dY: " + (arc.BoxMax.Y - arc.BoxMin.Y).ToString("f3");
							text = text + " , dZ: " + (arc.BoxMax.Z - arc.BoxMin.Z).ToString("f3") + " )";
						}
						if (entity is Curve)
						{
							Curve curve = (Curve)entity;
							curve.Regen(0.01);
							text = text + "Curve - Length : " + Math.Round(curve.Length(), 3).ToString("f3");
							text = text + " - ( dX: " + (curve.BoxMax.X - curve.BoxMin.X).ToString("f3");
							text = text + " , dY: " + (curve.BoxMax.Y - curve.BoxMin.Y).ToString("f3");
							text = text + " , dZ: " + (curve.BoxMax.Z - curve.BoxMin.Z).ToString("f3") + " )";
						}
						if (entity is LinearPath)
						{
							LinearPath linearPath = (LinearPath)entity;
							text = text + "LinearPath - Length : " + Math.Round(linearPath.Length(), 3).ToString("f3");
							text = text + " - ( dX: " + (linearPath.BoxMax.X - linearPath.BoxMin.X).ToString("f3");
							text = text + " , dY: " + (linearPath.BoxMax.Y - linearPath.BoxMin.Y).ToString("f3");
							text = text + " , dZ: " + (linearPath.BoxMax.Z - linearPath.BoxMin.Z).ToString("f3") + " )";
						}
					}
				}
				else
				{
					text = "Edge " + ccVars.MeasureObjects.Count + "- ";
					if (item.Object is Brep.Edge)
					{
						text += " ";
						Brep.Edge edge = (Brep.Edge)item.Object;
						if (edge.Curve is Line)
						{
							Line line2 = (Line)edge.Curve;
							text = text + " buLine - Length: " + line2.Length().ToString("f3");
							text = text + " - ( dX: " + (line2.BoxMax.X - line2.BoxMin.X).ToString("f3");
							text = text + " , dY: " + (line2.BoxMax.Y - line2.BoxMin.Y).ToString("f3");
							text = text + " , dZ: " + (line2.BoxMax.Z - line2.BoxMin.Z).ToString("f3") + " )";
						}
						if (edge.Curve is Arc)
						{
							Arc arc2 = (Arc)edge.Curve;
							arc2.Regen(0.01);
							text = text + "Arc - Radius : " + Math.Round(arc2.Radius, 3).ToString("f3");
							text = text + " - ( dX: " + (arc2.BoxMax.X - arc2.BoxMin.X).ToString("f3");
							text = text + " , dY: " + (arc2.BoxMax.Y - arc2.BoxMin.Y).ToString("f3");
							text = text + " , dZ: " + (arc2.BoxMax.Z - arc2.BoxMin.Z).ToString("f3") + " )";
						}
						if (edge.Curve is Curve)
						{
							Curve curve2 = (Curve)edge.Curve;
							curve2.Regen(0.01);
							text = text + "Curve - Length : " + Math.Round(curve2.Length(), 3).ToString("f3");
							text = text + " - ( dX: " + (curve2.BoxMax.X - curve2.BoxMin.X).ToString("f3");
							text = text + " , dY: " + (curve2.BoxMax.Y - curve2.BoxMin.Y).ToString("f3");
							text = text + " , dZ: " + (curve2.BoxMax.Z - curve2.BoxMin.Z).ToString("f3") + " )";
						}
						if (edge.Curve is LinearPath)
						{
							LinearPath linearPath2 = (LinearPath)edge.Curve;
							text = text + "LinearPath - Length : " + Math.Round(linearPath2.Length(), 3).ToString("f3");
							text = text + " - ( dX: " + (linearPath2.BoxMax.X - linearPath2.BoxMin.X).ToString("f3");
							text = text + " , dY: " + (linearPath2.BoxMax.Y - linearPath2.BoxMin.Y).ToString("f3");
							text = text + " , dZ: " + (linearPath2.BoxMax.Z - linearPath2.BoxMin.Z).ToString("f3") + " )";
						}
					}
				}
			}
			else
			{
				text = "Face" + ccVars.MeasureObjects.Count + "- ";
				if (item.Object is Brep.Face)
				{
					Brep.Face face = (Brep.Face)item.Object;
					if (face.Parametric == null)
					{
					}
				}
			}
			item.Explanation = text;
			ccVars.MeasureObjects.Add(item);
			if (ccVars.MeasureObjects.Count >= 2)
			{
				MeasureAdd();
			}
			else
			{
				clsItem.FrmMeasure.lbl_selected.Text = text;
			}
		}
		catch (Exception)
		{
			throw;
		}
	}

	public void MeasureAdd()
	{
		int count = ccVars.SelectedMeasureObjects.Count;
		TreeNodeSettings treeNodeSettings = new TreeNodeSettings("Group" + count);
		treeNodeSettings.ClassIndex = count;
		TreeNodeSettings treeNodeSettings2 = new TreeNodeSettings(ccVars.MeasureObjects[0].Explanation);
		treeNodeSettings2.ClassIndex = count;
		treeNodeSettings.Nodes.Add(treeNodeSettings2);
		treeNodeSettings2 = new TreeNodeSettings(ccVars.MeasureObjects[1].Explanation);
		treeNodeSettings2.ClassIndex = count;
		treeNodeSettings.Nodes.Add(treeNodeSettings2);
		clsItem.FrmMeasure.tree_item.Nodes.Add(treeNodeSettings);
		clsItem.FrmMeasure.tree_item.ExpandAll();
		clsItem.FrmMeasure.lbl_selected.Text = "";
		ccVars.SelectedMeasureObjects.Add(ccVars.MeasureObjects);
		ccVars.MeasureObjects = new List<MeasureItem>();
		MeasureShow(ccVars.SelectedMeasureObjects.Count - 1);
		for (int i = 0; i <= ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Count - 1; i++)
		{
			if (ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[i] is Brep)
			{
				((Brep)ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[i]).ClearEdgesSelection(null);
				((Brep)ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[i]).ClearFacesSelection();
				((Brep)ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[i]).ClearVerticesSelection(null);
			}
		}
	}

	public void MeasureFill()
	{
		clsItem.FrmMeasure.tree_item.Nodes.Clear();
		for (int i = 0; i <= ccVars.SelectedMeasureObjects.Count - 1; i++)
		{
			int classIndex = i;
			TreeNodeSettings treeNodeSettings = new TreeNodeSettings("Group" + classIndex);
			treeNodeSettings.ClassIndex = classIndex;
			TreeNodeSettings treeNodeSettings2 = new TreeNodeSettings(ccVars.SelectedMeasureObjects[i][0].Explanation);
			treeNodeSettings2.ClassIndex = classIndex;
			treeNodeSettings.Nodes.Add(treeNodeSettings2);
			treeNodeSettings2 = new TreeNodeSettings(ccVars.SelectedMeasureObjects[i][1].Explanation);
			treeNodeSettings2.ClassIndex = classIndex;
			treeNodeSettings.Nodes.Add(treeNodeSettings2);
			clsItem.FrmMeasure.tree_item.Nodes.Add(treeNodeSettings);
		}
		clsItem.FrmMeasure.tree_item.ExpandAll();
	}

	public void MeasureShow(int MeasureIndex)
	{
		ccVars.LastMeasured = MeasureIndex;
		string text = "";
		DistanceData Distance = new DistanceData();
		Point3D FirstFoundPoints = new Point3D();
		Point3D SecondFoundPoints = new Point3D();
		Entity entity = null;
		Entity entity2 = null;
		if (!(ccVars.SelectedMeasureObjects[MeasureIndex][0].Object is Brep.Edge))
		{
			if (!(ccVars.SelectedMeasureObjects[MeasureIndex][0].Object is Brep.Face))
			{
				if (!(ccVars.SelectedMeasureObjects[MeasureIndex][0].Object is Brep.Vertex))
				{
					if (ccVars.SelectedMeasureObjects[MeasureIndex][0].Object is Entity)
					{
						entity = (Entity)((Entity)ccVars.SelectedMeasureObjects[MeasureIndex][0].Object).Clone();
					}
				}
				else
				{
					Point3D point3D = (Point3D)ccVars.SelectedMeasureObjects[MeasureIndex][0].Object;
					entity = new devDept.Eyeshot.Entities.Point(point3D.X, point3D.Y, point3D.Z);
				}
			}
			else
			{
				Brep.Face face = (Brep.Face)ccVars.SelectedMeasureObjects[MeasureIndex][0].Object;
				if (face.Parametric != null && face.Parametric.Length == 0)
				{
				}
			}
		}
		else
		{
			Brep.Edge edge = (Brep.Edge)ccVars.SelectedMeasureObjects[MeasureIndex][0].Object;
			entity = (Entity)edge.Curve;
		}
		if (!(ccVars.SelectedMeasureObjects[MeasureIndex][1].Object is Brep.Edge))
		{
			if (!(ccVars.SelectedMeasureObjects[MeasureIndex][1].Object is Brep.Face))
			{
				if (!(ccVars.SelectedMeasureObjects[MeasureIndex][1].Object is Brep.Vertex))
				{
					if (ccVars.SelectedMeasureObjects[MeasureIndex][0].Object is Entity)
					{
						entity2 = (Entity)((Entity)ccVars.SelectedMeasureObjects[MeasureIndex][1].Object).Clone();
					}
				}
				else
				{
					Point3D point3D2 = (Point3D)ccVars.SelectedMeasureObjects[MeasureIndex][1].Object;
					entity2 = new devDept.Eyeshot.Entities.Point(point3D2.X, point3D2.Y, point3D2.Z);
				}
			}
			else
			{
				Brep.Face face2 = (Brep.Face)ccVars.SelectedMeasureObjects[MeasureIndex][1].Object;
				if (face2.Parametric != null && face2.Parametric.Length == 0)
				{
				}
			}
		}
		else
		{
			Brep.Edge edge2 = (Brep.Edge)ccVars.SelectedMeasureObjects[MeasureIndex][1].Object;
			entity2 = (Entity)edge2.Curve;
		}
		if (entity != null && entity2 != null)
		{
			if (clsVar.varSelection.DynamicSelectionDistanceType == MinMaxType.Min)
			{
				clsInit.cVector5.GetClosestPointsOfTwoEntity(entity, entity2, ref FirstFoundPoints, ref SecondFoundPoints);
			}
			if (clsVar.varSelection.DynamicSelectionDistanceType == MinMaxType.Max)
			{
				clsInit.cVector5.GetLongestPointsOfTwoEntity(entity, entity2, ref FirstFoundPoints, ref SecondFoundPoints);
			}
			clsInit.cVector5.GetInformationBetweenTwoPoints(FirstFoundPoints, SecondFoundPoints, ref Distance);
			text = " L =  " + Distance.Length.ToString("f3") + Environment.NewLine;
			text = text + " dx =  " + Distance.dX.ToString("f3") + Environment.NewLine;
			text = text + " dy =  " + Distance.dY.ToString("f3") + Environment.NewLine;
			text = text + " dz =  " + Distance.dZ.ToString("f3");
			double num = 0.0;
			ccVars.pntDrawDynamicMeasure.Clear();
			MeasureData measureData = new MeasureData();
			measureData.Points.Add(FirstFoundPoints);
			measureData.Points.Add(SecondFoundPoints);
			measureData.Text = "L = ";
			measureData.Length = Math.Round(Point3D.Distance(FirstFoundPoints, SecondFoundPoints), 3);
			measureData.PntText = Point3D.MidPoint(FirstFoundPoints, SecondFoundPoints);
			num = measureData.Length;
			ccVars.pntDrawDynamicMeasure.Add(measureData);
			measureData = new MeasureData();
			Point3D point3D3 = new Point3D(FirstFoundPoints.X, FirstFoundPoints.Y, FirstFoundPoints.Z);
			Point3D point3D4 = new Point3D(SecondFoundPoints.X, FirstFoundPoints.Y, FirstFoundPoints.Z);
			measureData.Points.Add(point3D3);
			measureData.Points.Add(point3D4);
			measureData.Length = Math.Round(Point3D.Distance(point3D3, point3D4), 3);
			measureData.PntText = Point3D.MidPoint(point3D3, point3D4);
			measureData.Text = "dX = ";
			if (buCompare.EQ(num, measureData.Length, 0.001))
			{
				measureData.Length = 0.0;
			}
			if (!clsVar.varInterface.DynamicSelectionX)
			{
				measureData.Length = 0.0;
				measureData.Points.Clear();
			}
			if (buCompare.EQ(measureData.Length, 0.0, 0.001))
			{
				measureData.Text = "";
			}
			ccVars.pntDrawDynamicMeasure.Add(measureData);
			measureData = new MeasureData();
			point3D3 = new Point3D(FirstFoundPoints.X, FirstFoundPoints.Y, FirstFoundPoints.Z);
			point3D4 = new Point3D(FirstFoundPoints.X, SecondFoundPoints.Y, FirstFoundPoints.Z);
			measureData.Points.Add(point3D3);
			measureData.Points.Add(point3D4);
			measureData.Length = Math.Round(Point3D.Distance(point3D3, point3D4), 3);
			measureData.PntText = Point3D.MidPoint(point3D3, point3D4);
			measureData.Text = "dY = ";
			if (buCompare.EQ(num, measureData.Length, 0.001))
			{
				measureData.Length = 0.0;
			}
			if (!clsVar.varInterface.DynamicSelectionY)
			{
				measureData.Length = 0.0;
				measureData.Points.Clear();
			}
			if (buCompare.EQ(measureData.Length, 0.0, 0.001))
			{
				measureData.Text = "";
			}
			ccVars.pntDrawDynamicMeasure.Add(measureData);
			measureData = new MeasureData();
			point3D3 = new Point3D(FirstFoundPoints.X, FirstFoundPoints.Y, FirstFoundPoints.Z);
			point3D4 = new Point3D(FirstFoundPoints.X, FirstFoundPoints.Y, SecondFoundPoints.Z);
			measureData.Points.Add(point3D3);
			measureData.Points.Add(point3D4);
			measureData.Length = Point3D.Distance(point3D3, point3D4);
			measureData.PntText = Point3D.MidPoint(point3D3, point3D4);
			measureData.Text = "dZ = ";
			if (buCompare.EQ(num, measureData.Length, 0.001))
			{
				measureData.Length = 0.0;
			}
			if (!clsVar.varInterface.DynamicSelectionZ)
			{
				measureData.Length = 0.0;
				measureData.Points.Clear();
			}
			if (buCompare.EQ(measureData.Length, 0.0, 0.001))
			{
				measureData.Text = "";
			}
			ccVars.pntDrawDynamicMeasure.Add(measureData);
		}
		clsItem.FrmMeasure.txt_explanation.Text = text;
		ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Invalidate();
	}

	public void Measure_AfterSelect(object sender, TreeViewEventArgs e)
	{
		TreeView treeView = (TreeView)sender;
		TreeNodeSettings treeNodeSettings = (TreeNodeSettings)treeView.SelectedNode;
		if (treeNodeSettings.ClassIndex >= 0)
		{
			int classIndex = treeNodeSettings.ClassIndex;
			if (classIndex <= ccVars.SelectedMeasureObjects.Count - 1)
			{
				MeasureShow(classIndex);
			}
		}
	}

	public void OsnapCalculationByThread()
	{
		clsVar.threadCalculations = new Thread(clsInit.appCommand.ThreadCalculationLoop);
		ThreadCommands.OsnapCalculationAll = true;
		clsVar.threadCalculations.Start();
	}

	public void OsnapEnableDisableByLayerAndEntityVisiblityThread()
	{
		if (!ThreadCommands.OsnapEnableDisableByLayerVisible)
		{
			clsVar.threadCalculations = new Thread(clsInit.appCommand.ThreadCalculationLoop);
			ThreadCommands.OsnapEnableDisableByLayerVisible = true;
			clsVar.threadCalculations.Start();
		}
	}

	public void OsnapEnableDisableByLayerAndEntityVisiblity()
	{
		try
		{
			if (ccVars.Pages.Count <= 0)
			{
				return;
			}
			for (int num = ccVars.Pages[ccVars.PageIndex].OsnapPoints.Count - 1; num >= 0; num--)
			{
				bool flag = true;
				bool flag2 = true;
				for (int i = 0; i <= ccVars.Pages[ccVars.PageIndex].Layers.Count - 1; i++)
				{
					if (ccVars.Pages[ccVars.PageIndex].OsnapPoints[num].LayerName == ccVars.Pages[ccVars.PageIndex].Layers[i].Name)
					{
						flag = ccVars.Pages[ccVars.PageIndex].Layers[i].Enable;
						i = ccVars.Pages[ccVars.PageIndex].Layers.Count;
					}
				}
				for (int j = 0; j <= ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Count - 1; j++)
				{
					if (j < ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Count - 1)
					{
						string entityName = clsInit.cVector5.GetEntityName(ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[j]);
						if ((ccVars.Pages[ccVars.PageIndex].OsnapPoints[num].EntName == entityName) & (entityName.Length > 0))
						{
							flag2 = ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[j].Visible;
						}
					}
				}
				ccVars.Pages[ccVars.PageIndex].OsnapPoints[num].Enable = flag && flag2;
			}
		}
		catch (Exception)
		{
		}
	}

	public void OsnapDelete()
	{
		for (int i = 0; i <= clsVar.OsnapDeleteList.Count - 1; i++)
		{
			OsnapDeleteByEntityName(clsVar.OsnapDeleteList[i]);
		}
		clsVar.OsnapDeleteList.Clear();
	}

	public void OsnapCalculationAll()
	{
		try
		{
			if (ccVars.Pages.Count <= 0)
			{
				return;
			}
			ccVars.Pages[ccVars.PageIndex].OsnapPoints.Clear();
			if (ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities != null)
			{
				for (int i = 0; i <= ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Count - 1; i++)
				{
					clsInit.appCommand.OsnapCalculation(ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[i], i + 1);
				}
			}
		}
		catch (Exception)
		{
		}
	}

	public void OsnapCalculation(Entity refEnt)
	{
		OsnapCalculation(refEnt, 0);
	}

	public void OsnapCalculation(Entity refEnt, int ListStartIndex)
	{
		try
		{
			if (ccVars.OsnapDont || !clsVar.varProgram.OsnapCalculation)
			{
				return;
			}
			if (!(refEnt is devDept.Eyeshot.Entities.Point))
			{
				if (!(refEnt is Line))
				{
					if (!(refEnt is LinearPath))
					{
						if (!(refEnt is CompositeCurve))
						{
							if (!(refEnt is Arc))
							{
								if (!(refEnt is Circle))
								{
									if (!(refEnt is Curve))
									{
										if (!(refEnt is EllipticalArc))
										{
											if (!(refEnt is Ellipse))
											{
												if (!(refEnt is Picture))
												{
													if (!(refEnt is Text))
													{
														if (!(refEnt is Mesh))
														{
															if (!(refEnt is Brep))
															{
																if (!(refEnt is Surface))
																{
																	return;
																}
																Surface surface = (Surface)refEnt;
																if (clsVar.varMouse.Osnap.OsnapBoxSize)
																{
																	if (surface.BoxMax == null)
																	{
																		surface.Regen(0.01);
																	}
																	Point3D point3D = clsInit.cVector5.MiddlePointOfLine(surface.BoxMin, surface.BoxMax);
																	ccVars.Pages[ccVars.PageIndex].OsnapPoints.Add(new OsnapPoint(new Point3D(surface.BoxMin.X, surface.BoxMin.Y, surface.BoxMin.Z), osnapType.Point, clsInit.cVector5.GetEntityCustomData(refEnt).EntityName, surface.LayerName, ""));
																	ccVars.Pages[ccVars.PageIndex].OsnapPoints.Add(new OsnapPoint(new Point3D(surface.BoxMax.X, surface.BoxMax.Y, surface.BoxMin.Z), osnapType.Point, clsInit.cVector5.GetEntityCustomData(refEnt).EntityName, surface.LayerName, ""));
																	ccVars.Pages[ccVars.PageIndex].OsnapPoints.Add(new OsnapPoint(new Point3D(surface.BoxMin.X, surface.BoxMax.Y, surface.BoxMin.Z), osnapType.Point, clsInit.cVector5.GetEntityCustomData(refEnt).EntityName, surface.LayerName, ""));
																	ccVars.Pages[ccVars.PageIndex].OsnapPoints.Add(new OsnapPoint(new Point3D(surface.BoxMax.X, surface.BoxMin.Y, surface.BoxMin.Z), osnapType.Point, clsInit.cVector5.GetEntityCustomData(refEnt).EntityName, surface.LayerName, ""));
																	ccVars.Pages[ccVars.PageIndex].OsnapPoints.Add(new OsnapPoint(new Point3D(point3D.X, point3D.Y, surface.BoxMin.Z), osnapType.Point, clsInit.cVector5.GetEntityCustomData(refEnt).EntityName, surface.LayerName, ""));
																	ccVars.Pages[ccVars.PageIndex].OsnapPoints.Add(new OsnapPoint(new Point3D(surface.BoxMin.X, surface.BoxMin.Y, surface.BoxMax.Z), osnapType.Point, clsInit.cVector5.GetEntityCustomData(refEnt).EntityName, surface.LayerName, ""));
																	ccVars.Pages[ccVars.PageIndex].OsnapPoints.Add(new OsnapPoint(new Point3D(surface.BoxMax.X, surface.BoxMax.Y, surface.BoxMax.Z), osnapType.Point, clsInit.cVector5.GetEntityCustomData(refEnt).EntityName, surface.LayerName, ""));
																	ccVars.Pages[ccVars.PageIndex].OsnapPoints.Add(new OsnapPoint(new Point3D(surface.BoxMin.X, surface.BoxMax.Y, surface.BoxMax.Z), osnapType.Point, clsInit.cVector5.GetEntityCustomData(refEnt).EntityName, surface.LayerName, ""));
																	ccVars.Pages[ccVars.PageIndex].OsnapPoints.Add(new OsnapPoint(new Point3D(surface.BoxMax.X, surface.BoxMin.Y, surface.BoxMax.Z), osnapType.Point, clsInit.cVector5.GetEntityCustomData(refEnt).EntityName, surface.LayerName, ""));
																	ccVars.Pages[ccVars.PageIndex].OsnapPoints.Add(new OsnapPoint(new Point3D(point3D.X, point3D.Y, surface.BoxMax.Z), osnapType.Point, clsInit.cVector5.GetEntityCustomData(refEnt).EntityName, surface.LayerName, ""));
																}
																if (clsVar.varMouse.Osnap.OsnapPoint)
																{
																	if (surface.Vertices == null)
																	{
																		surface.Regen(0.01);
																	}
																	for (int i = 0; i <= surface.Vertices.Length - 1; i++)
																	{
																		ccVars.Pages[ccVars.PageIndex].OsnapPoints.Add(new OsnapPoint(surface.Vertices[i], osnapType.Point, clsInit.cVector5.GetEntityCustomData(refEnt).EntityName, surface.LayerName, ""));
																	}
																}
																return;
															}
															Brep brep = (Brep)refEnt;
															if (clsVar.varMouse.Osnap.OsnapBoxSize)
															{
																if (brep.BoxMax == null)
																{
																	brep.Regen(0.01);
																}
																Point3D point3D2 = clsInit.cVector5.MiddlePointOfLine(brep.BoxMin, brep.BoxMax);
																ccVars.Pages[ccVars.PageIndex].OsnapPoints.Add(new OsnapPoint(new Point3D(brep.BoxMin.X, brep.BoxMin.Y, brep.BoxMin.Z), osnapType.Point, clsInit.cVector5.GetEntityCustomData(refEnt).EntityName, brep.LayerName, ""));
																ccVars.Pages[ccVars.PageIndex].OsnapPoints.Add(new OsnapPoint(new Point3D(brep.BoxMax.X, brep.BoxMax.Y, brep.BoxMin.Z), osnapType.Point, clsInit.cVector5.GetEntityCustomData(refEnt).EntityName, brep.LayerName, ""));
																ccVars.Pages[ccVars.PageIndex].OsnapPoints.Add(new OsnapPoint(new Point3D(brep.BoxMin.X, brep.BoxMax.Y, brep.BoxMin.Z), osnapType.Point, clsInit.cVector5.GetEntityCustomData(refEnt).EntityName, brep.LayerName, ""));
																ccVars.Pages[ccVars.PageIndex].OsnapPoints.Add(new OsnapPoint(new Point3D(brep.BoxMax.X, brep.BoxMin.Y, brep.BoxMin.Z), osnapType.Point, clsInit.cVector5.GetEntityCustomData(refEnt).EntityName, brep.LayerName, ""));
																ccVars.Pages[ccVars.PageIndex].OsnapPoints.Add(new OsnapPoint(new Point3D(point3D2.X, point3D2.Y, brep.BoxMin.Z), osnapType.Point, clsInit.cVector5.GetEntityCustomData(refEnt).EntityName, brep.LayerName, ""));
																ccVars.Pages[ccVars.PageIndex].OsnapPoints.Add(new OsnapPoint(new Point3D(brep.BoxMin.X, brep.BoxMin.Y, brep.BoxMax.Z), osnapType.Point, clsInit.cVector5.GetEntityCustomData(refEnt).EntityName, brep.LayerName, ""));
																ccVars.Pages[ccVars.PageIndex].OsnapPoints.Add(new OsnapPoint(new Point3D(brep.BoxMax.X, brep.BoxMax.Y, brep.BoxMax.Z), osnapType.Point, clsInit.cVector5.GetEntityCustomData(refEnt).EntityName, brep.LayerName, ""));
																ccVars.Pages[ccVars.PageIndex].OsnapPoints.Add(new OsnapPoint(new Point3D(brep.BoxMin.X, brep.BoxMax.Y, brep.BoxMax.Z), osnapType.Point, clsInit.cVector5.GetEntityCustomData(refEnt).EntityName, brep.LayerName, ""));
																ccVars.Pages[ccVars.PageIndex].OsnapPoints.Add(new OsnapPoint(new Point3D(brep.BoxMax.X, brep.BoxMin.Y, brep.BoxMax.Z), osnapType.Point, clsInit.cVector5.GetEntityCustomData(refEnt).EntityName, brep.LayerName, ""));
																ccVars.Pages[ccVars.PageIndex].OsnapPoints.Add(new OsnapPoint(new Point3D(point3D2.X, point3D2.Y, brep.BoxMax.Z), osnapType.Point, clsInit.cVector5.GetEntityCustomData(refEnt).EntityName, brep.LayerName, ""));
															}
															for (int j = 0; j <= brep.Edges.Length - 1; j++)
															{
																if (brep.Edges[j].Curve is Arc && clsVar.varMouse.Osnap.OsnapCenter)
																{
																	Arc arc = (Arc)brep.Edges[j].Curve;
																	ccVars.Pages[ccVars.PageIndex].OsnapPoints.Add(new OsnapPoint(arc.Center, osnapType.Center, clsInit.cVector5.GetEntityCustomData(refEnt).EntityName, refEnt.LayerName, ""));
																}
																if (brep.Edges[j].Curve is Circle && clsVar.varMouse.Osnap.OsnapCenter)
																{
																	Circle circle = (Circle)brep.Edges[j].Curve;
																	ccVars.Pages[ccVars.PageIndex].OsnapPoints.Add(new OsnapPoint(circle.Center, osnapType.Center, clsInit.cVector5.GetEntityCustomData(refEnt).EntityName, refEnt.LayerName, ""));
																}
															}
															if (clsVar.varMouse.Osnap.OsnapPoint)
															{
																if (brep.Vertices == null)
																{
																	brep.Regen(0.01);
																}
																for (int k = 0; k <= brep.Vertices.Length - 1; k++)
																{
																	ccVars.Pages[ccVars.PageIndex].OsnapPoints.Add(new OsnapPoint(brep.Vertices[k], osnapType.Point, clsInit.cVector5.GetEntityCustomData(refEnt).EntityName, brep.LayerName, ""));
																}
															}
															return;
														}
														Mesh mesh = (Mesh)refEnt;
														if (clsVar.varMouse.Osnap.OsnapBoxSize)
														{
															if (mesh.BoxMax == null)
															{
																mesh.Regen(0.01);
															}
															Point3D point3D3 = clsInit.cVector5.MiddlePointOfLine(mesh.BoxMin, mesh.BoxMax);
															ccVars.Pages[ccVars.PageIndex].OsnapPoints.Add(new OsnapPoint(new Point3D(mesh.BoxMin.X, mesh.BoxMin.Y, mesh.BoxMin.Z), osnapType.Point, clsInit.cVector5.GetEntityCustomData(refEnt).EntityName, mesh.LayerName, ""));
															ccVars.Pages[ccVars.PageIndex].OsnapPoints.Add(new OsnapPoint(new Point3D(mesh.BoxMax.X, mesh.BoxMax.Y, mesh.BoxMin.Z), osnapType.Point, clsInit.cVector5.GetEntityCustomData(refEnt).EntityName, mesh.LayerName, ""));
															ccVars.Pages[ccVars.PageIndex].OsnapPoints.Add(new OsnapPoint(new Point3D(mesh.BoxMin.X, mesh.BoxMax.Y, mesh.BoxMin.Z), osnapType.Point, clsInit.cVector5.GetEntityCustomData(refEnt).EntityName, mesh.LayerName, ""));
															ccVars.Pages[ccVars.PageIndex].OsnapPoints.Add(new OsnapPoint(new Point3D(mesh.BoxMax.X, mesh.BoxMin.Y, mesh.BoxMin.Z), osnapType.Point, clsInit.cVector5.GetEntityCustomData(refEnt).EntityName, mesh.LayerName, ""));
