	public void OsnapDeleteByEntityName(string EntName)
	{
		for (int num = ccVars.Pages[ccVars.PageIndex].OsnapPoints.Count - 1; num >= 0; num--)
		{
			if (!(ccVars.Pages[ccVars.PageIndex].OsnapPoints[num].EntName == EntName))
			{
				if (num <= ccVars.Pages[ccVars.PageIndex].OsnapPoints.Count - 1 && ccVars.Pages[ccVars.PageIndex].OsnapPoints[num].OtherEntName == EntName)
				{
					ccVars.Pages[ccVars.PageIndex].OsnapPoints.RemoveAt(num);
					num = 0;
				}
			}
			else
			{
				ccVars.Pages[ccVars.PageIndex].OsnapPoints.RemoveAt(num);
				num = 0;
			}
		}
	}

	public void CoordinateCalculation(Point3D refPoint)
	{
		if (refPoint == null)
		{
			return;
		}
		ccVars.OsnapCatchPoint.Found = false;
		ccVars.OsnapCatchPoint.OrthoFound = false;
		ccVars.OsnapCatchPoint.OverFound = false;
		ccVars.OsnapCatchPoint.SnapFound = false;
		ccVars.OsnapCatchPoint.TrackFound = false;
		ccVars.OsnapCatchPoint.OsnapFound = false;
		if (clsVar.varMouse.Osnap.Snap)
		{
			ccVars.OsnapCatchPoint.Point = buConversion5.Pnt3DToPoint3D(clsInit.cVector.SnapFunction(buConversion5.Point3DToPnt3D(refPoint), clsVar.varMouse.Osnap.SnapDistance, buVector5.PlaneToWorkPlane(ccVars.planeActive)));
			ccVars.OsnapCatchPoint.SnapFound = true;
			ccVars.pntActive = buVector5.ToPoint3D(ccVars.OsnapCatchPoint.Point);
			ccVars.OsnapCatchPoint.Type = osnapType.None;
			ccVars.OsnapCatchPoint.Method = osnapMethodType.Snap;
		}
		if ((ccVars.Action != actionTypeBU.None) & clsVar.varMouse.Osnap.OrthoAuto & !ccVars.selectionProcess)
		{
			double num = clsInit.cVector5.PointAngle(refPoint, ccVars.pntBase, ccVars.planeActive);
			double num2 = Math.Abs(num % 90.0);
			double num3 = Math.Abs(num2 - 90.0);
			if ((num2 <= clsVar.varMouse.Osnap.OrthoAutoAngle) | (num3 <= clsVar.varMouse.Osnap.OrthoAutoAngle))
			{
				int OrthoDir = 0;
				Pnt3D OrthoPnt = new Pnt3D();
				clsInit.cVector.OrthoFunction(buConversion5.Point3DToPnt3D(refPoint), buConversion5.Point3DToPnt3D(ccVars.pntBase), buVector5.PlaneToWorkPlane(ccVars.planeActive), ref OrthoPnt, ref OrthoDir);
				ccVars.OsnapCatchPoint.Point = buConversion5.Pnt3DToPoint3D(OrthoPnt);
				ccVars.OsnapCatchPoint.OrthoFound = true;
				ccVars.OsnapCatchPoint.Found = false;
				ccVars.pntActive = buVector5.ToPoint3D(ccVars.OsnapCatchPoint.Point);
			}
		}
		if (clsVar.varMouse.Osnap.Ortho & !ccVars.OsnapCatchPoint.Found & !ccVars.disableOrtho & !ccVars.selectionProcess & (ccVars.stpDrawing > 1))
		{
			int OrthoDir2 = 0;
			ccVars.planeActive.Project(ccVars.pntBase);
			ccVars.planeActive.Project(ccVars.pntActive);
			new Vector3D(ccVars.pntBase.X - ccVars.pntActive.X, ccVars.pntBase.Y - ccVars.pntActive.Y, ccVars.pntBase.Z - ccVars.pntActive.Z);
			Pnt3D OrthoPnt2 = new Pnt3D();
			clsInit.cVector.OrthoFunction(buConversion5.Point3DToPnt3D(ccVars.pntActive), buConversion5.Point3DToPnt3D(ccVars.pntBase), buVector5.PlaneToWorkPlane(ccVars.planeActive), ref OrthoPnt2, ref OrthoDir2);
			ccVars.OsnapCatchPoint.Point = buConversion5.Pnt3DToPoint3D(OrthoPnt2);
			ccVars.OsnapCatchPoint.OrthoFound = true;
			ccVars.OsnapCatchPoint.Found = false;
			ccVars.pntActive = buVector5.ToPoint3D(ccVars.OsnapCatchPoint.Point);
		}
		if ((clsVar.varMouse.Osnap.Osnap & clsVar.varMouse.Osnap.OsnapZeroPoint) && clsInit.cVector.IsPointInsideWindow(buConversion5.Point3DToPnt3D(refPoint), new Pnt3D(), clsVar.varMouse.Osnap.CatchResolution * ccVars.Pages[ccVars.PageIndex].Form.viewportcad.ZoomRatio, buVector5.PlaneToWorkPlane(ccVars.planeActive)))
		{
			ccVars.OsnapCatchPoint.Found = true;
			ccVars.OsnapCatchPoint.Point = new Point3D();
			ccVars.OsnapCatchPoint.Type = osnapType.Point;
			ccVars.OsnapCatchPoint.Method = osnapMethodType.Osnap;
			ccVars.pntActive = new Point3D();
		}
		if (clsVar.varMouse.Osnap.Over & !ccVars.OsnapCatchPoint.Found & (ccVars.OsnapCatchPoint.UnderEntityIndex >= 0))
		{
			ccVars.OsnapCatchPoint.OverFound = true;
			ccVars.pntActive = buVector5.ToPoint3D(ccVars.OsnapCatchPoint.EntityPoint);
			ccVars.OsnapCatchPoint.Found = false;
		}
		if (clsVar.varMouse.Osnap.Osnap & !ccVars.OsnapCatchPoint.Found & ((ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Count > 0) | (ccVars.Pages[ccVars.PageIndex].OsnapTempPoints.Count > 0)))
		{
			OsnapPoint foundPoint = new OsnapPoint();
			if (clsVar.varMouse.Osnap.OsnapEntities)
			{
				ccVars.OsnapCatchPoint.Found = ccVars.Pages[ccVars.PageIndex].Form.viewportcad.FindClosestPointForOsnap(new List<OsnapPoint>(), ref foundPoint);
			}
			if (!ccVars.OsnapCatchPoint.Found)
			{
				foundPoint = new OsnapPoint();
				ccVars.OsnapCatchPoint.Found = ccVars.Pages[ccVars.PageIndex].Form.viewportcad.FindClosestPointForOsnap(ccVars.Pages[ccVars.PageIndex].OsnapTempPoints, ref foundPoint);
				if (!ccVars.OsnapCatchPoint.Found)
				{
					foundPoint = new OsnapPoint();
					ccVars.OsnapCatchPoint.Found = ccVars.Pages[ccVars.PageIndex].Form.viewportcad.FindClosestPointForOsnap(ccVars.Pages[ccVars.PageIndex].OsnapOtherPoints, ref foundPoint);
					if (ccVars.OsnapCatchPoint.Found)
					{
						ccVars.OsnapCatchPoint.Point = buVector5.ToPoint3D(foundPoint);
						ccVars.OsnapCatchPoint.Type = foundPoint.Type;
						ccVars.pntActive = new Point3D(foundPoint.X, foundPoint.Y, foundPoint.Z);
					}
				}
				else
				{
					ccVars.OsnapCatchPoint.Point = buVector5.ToPoint3D(foundPoint);
					ccVars.OsnapCatchPoint.Type = foundPoint.Type;
					ccVars.pntActive = new Point3D(foundPoint.X, foundPoint.Y, foundPoint.Z);
				}
			}
			else
			{
				ccVars.OsnapCatchPoint.Point = buVector5.ToPoint3D(foundPoint);
				ccVars.OsnapCatchPoint.Type = foundPoint.Type;
				ccVars.pntActive = new Point3D(foundPoint.X, foundPoint.Y, foundPoint.Z);
			}
		}
		if (clsVar.varInterface.ConstantDistanceEnable)
		{
			if (buVector5.isPlaneXYorYX(ccVars.planeActive))
			{
				ccVars.pntActive.Z = clsVar.varInterface.ConstantDistanceValue;
			}
			if (buVector5.isPlaneXZorZX(ccVars.planeActive))
			{
				ccVars.pntActive.Y = clsVar.varInterface.ConstantDistanceValue;
			}
			if (buVector5.isPlaneYZorZY(ccVars.planeActive))
			{
				ccVars.pntActive.X = clsVar.varInterface.ConstantDistanceValue;
			}
		}
	}

	public void GetLayerFromEntitiesColor(ref List<LayerBase5> Layers, ref List<Entity> calcEntities)
	{
		calcEntities.Clear();
		calcEntities = new List<Entity>();
		for (int i = 0; i <= ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Count - 1; i++)
		{
			string text = "";
			bool flag = false;
			Entity entity = (Entity)ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[i].Clone();
			for (int j = 0; j <= clsVar.Cf2Properties.Count - 1; j++)
			{
				Color color = ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[i].Color;
				if (ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[i].ColorMethod == colorMethodType.byLayer)
				{
					color = ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Layers[ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[i].LayerName].Color;
				}
				if (color.ToArgb() != clsVar.Cf2Properties[j].MatchColor.ToArgb())
				{
					continue;
				}
				flag = true;
				entity.Color = clsVar.Cf2Properties[j].Color;
				text = clsVar.Cf2Properties[j].CodeType.ToString() + "-" + clsVar.Cf2Properties[j].PtRealValue + " Pt";
				if (Layers.Count != 0)
				{
					bool flag2 = false;
					for (int k = 0; k <= Layers.Count - 1; k++)
					{
						if (Layers[k].Name == text)
						{
							flag2 = true;
						}
					}
					if (!flag2)
					{
						LayerBase5 layerBase = new LayerBase5();
						layerBase.Diemaker = new LayerDiemakerProps();
						layerBase.Diemaker.Pt = clsVar.Cf2Properties[j].PtRealValue;
						layerBase.Diemaker.Type = clsVar.Cf2Properties[j].CodeType;
						layerBase.LayerColor = clsVar.Cf2Properties[j].Color;
						layerBase.LayerThickness = (float)clsVar.Cf2Properties[j].Thickness;
						layerBase.Name = text;
						Layers.Add(layerBase);
					}
				}
				else
				{
					LayerBase5 layerBase2 = new LayerBase5();
					layerBase2.Diemaker = new LayerDiemakerProps();
					layerBase2.Diemaker.Pt = clsVar.Cf2Properties[j].PtRealValue;
					layerBase2.Diemaker.Type = clsVar.Cf2Properties[j].CodeType;
					layerBase2.LayerColor = clsVar.Cf2Properties[j].Color;
					layerBase2.LayerThickness = (float)clsVar.Cf2Properties[j].Thickness;
					layerBase2.Name = text;
					Layers.Add(layerBase2);
				}
			}
			if (!flag)
			{
				entity.ColorMethod = colorMethodType.byEntity;
				entity.LineTypeMethod = colorMethodType.byEntity;
				entity.LineWeightMethod = colorMethodType.byEntity;
			}
			else
			{
				entity.ColorMethod = colorMethodType.byLayer;
				entity.LineTypeMethod = colorMethodType.byLayer;
				entity.LineWeightMethod = colorMethodType.byLayer;
			}
			entity.LayerName = text;
			calcEntities.Add(entity);
		}
	}

