	public void ShowViewportButtons(bool OkButton, bool CancelButton, bool UndoButton)
	{
		int num = 0;
		int left = 0;
		ccVars.Pages[ccVars.PageIndex].Form.btn_ok.Visible = OkButton;
		ccVars.Pages[ccVars.PageIndex].Form.btn_cancel.Visible = CancelButton;
		ccVars.Pages[ccVars.PageIndex].Form.btn_undo.Visible = UndoButton;
		ccVars.Pages[ccVars.PageIndex].Form.pnl_buttons.Visible = OkButton || CancelButton || UndoButton;
		if (OkButton)
		{
			left = ccVars.Pages[ccVars.PageIndex].Form.btn_ok.Left + ccVars.Pages[ccVars.PageIndex].Form.btn_ok.Width;
			num++;
		}
		if (CancelButton)
		{
			ccVars.Pages[ccVars.PageIndex].Form.btn_cancel.Left = left;
			left = ccVars.Pages[ccVars.PageIndex].Form.btn_cancel.Left + ccVars.Pages[ccVars.PageIndex].Form.btn_cancel.Width;
			num++;
		}
		if (UndoButton)
		{
			ccVars.Pages[ccVars.PageIndex].Form.btn_undo.Left = left;
			left = ccVars.Pages[ccVars.PageIndex].Form.btn_undo.Left + ccVars.Pages[ccVars.PageIndex].Form.btn_undo.Width;
			num++;
		}
		if (num == 1)
		{
			ccVars.Pages[ccVars.PageIndex].Form.pnl_buttons.Width = 40;
		}
		if (num == 2)
		{
			ccVars.Pages[ccVars.PageIndex].Form.pnl_buttons.Width = 80;
		}
		if (num == 3)
		{
			ccVars.Pages[ccVars.PageIndex].Form.pnl_buttons.Width = 120;
		}
	}

