	public void GetDrawingInfo(Point3D pntBase, Point3D pntActive, bool Len, bool Ang, bool dx, bool dy, bool dz)
	{
		dynamicInfo.Len = Point3D.Distance(ccVars.pntActive, ccVars.pntBase);
		dynamicInfo.Ang = clsInit.cVector.PointAngle(buConversion5.Point3DToPnt3D(ccVars.pntActive), buConversion5.Point3DToPnt3D(ccVars.pntBase), buVector5.PlaneToWorkPlane(ccVars.planeActive));
		dynamicInfo.dX = clsInit.cVector5.DeltaX(ccVars.pntActive, ccVars.pntBase);
		dynamicInfo.dY = clsInit.cVector5.DeltaY(ccVars.pntActive, ccVars.pntBase);
		dynamicInfo.dZ = clsInit.cVector5.DeltaZ(ccVars.pntActive, ccVars.pntBase);
		dynamicInfo.Command = AppLanguage.CadCamCommand[1];
		dynamicInfo.Info = AppLanguage.CadCamDynamic[0] + ": " + dynamicInfo.Len.ToString("f" + clsVar.varProgram.DecimalVisiblePoint) + " - " + AppLanguage.CadCamDynamic[2] + ": " + dynamicInfo.Ang.ToString("f" + clsVar.varProgram.DecimalVisiblePoint) + "º";
		if (clsVar.varView.ShowDxDyDzValuesDynamicText)
		{
			dynamicInfo.Info = dynamicInfo.Info + " dx: " + dynamicInfo.dX.ToString("f" + clsVar.varProgram.DecimalVisiblePoint) + " dy: " + dynamicInfo.dY.ToString("f" + clsVar.varProgram.DecimalVisiblePoint) + " dz: " + dynamicInfo.dZ.ToString("f" + clsVar.varProgram.DecimalVisiblePoint);
		}
	}

	public void ShowPreview(List<Entity> Entities, BlockKeyedCollection Blocks, LayerKeyedCollection Layers)
	{
		if (clsItem.FrmPreview == null)
		{
			clsItem.FrmPreview = new F_Preview();
			CreateModelProperties createModelProperties = new CreateModelProperties();
			createModelProperties.CoordinateSystemIconVisible = false;
			createModelProperties.ViewCubeIconVisible = false;
			createModelProperties.OrigineCaptionVisible = false;
			createModelProperties.ToolBorVisible = false;
			clsInit.cVector5.CreateModelControl(ref clsItem.FrmPreview.viewportLayout, clsVar.UnlockKey, createModelProperties);
		}
		clsItem.FrmPreview.viewportLayout.Entities.Clear();
		clsItem.FrmPreview.viewportLayout.Layers = buConversion5.CopyEyeLayerToEyeLayer(Layers);
		for (int num = clsItem.FrmPreview.viewportLayout.Blocks.Count - 1; num >= 1; num--)
		{
			clsItem.FrmPreview.viewportLayout.Blocks.RemoveAt(num);
		}
		clsItem.FrmPreview.viewportLayout.Blocks.AddRange(clsInit.cVector5.CopyEyeBlockToEyeBlock(clsItem.FrmPreview.viewportLayout.Blocks, Blocks));
		for (int i = 0; i <= Entities.Count - 1; i++)
		{
			Entity item = (Entity)Entities[i].Clone();
			clsItem.FrmPreview.viewportLayout.Entities.Add(item);
		}
		clsItem.FrmPreview.viewportLayout.SetView(viewType.Trimetric, fit: true, animate: false);
		clsItem.FrmPreview.Init();
		clsItem.FrmPreview.Show();
	}

