	public void ClassViewValueChanged(object sender, object value, cParameter Parameter)
	{
		if (ccVars.Action == actionTypeBU.drawVectorText && clsItem.FrmActionData.buClassViewer1.ClassObject != null && clsItem.FrmActionData.buClassViewer1.ClassObject is TextVectorRuntimeData)
		{
			ccVars.VectorTextRunVar.Alignment = ((TextVectorRuntimeData)clsItem.FrmActionData.buClassViewer1.ClassObject).Alignment;
			ccVars.VectorTextRunVar.Height = ((TextVectorRuntimeData)clsItem.FrmActionData.buClassViewer1.ClassObject).Height;
			ccVars.VectorTextRunVar.Text = ((TextVectorRuntimeData)clsItem.FrmActionData.buClassViewer1.ClassObject).Text;
			ccVars.VectorTextRunVar.DrawAsCurve = ((TextVectorRuntimeData)clsItem.FrmActionData.buClassViewer1.ClassObject).DrawAsCurve;
			clsInit.appCommand.VectorTextCreate(ccVars.VectorTextRunVar.Text, clsVar.varInterface.VectorTextVar.Font, ccVars.VectorTextRunVar.Height, ccVars.VectorTextRunVar.Alignment, ccVars.planeActive, ref ccVars.ContourPoints);
			clsVar.varInterface.VectorTextVar.Alignment = ccVars.VectorTextRunVar.Alignment;
			clsVar.varInterface.VectorTextVar.DrawAsCurve = ccVars.VectorTextRunVar.DrawAsCurve;
			clsVar.varInterface.VectorTextVar.Height = ccVars.VectorTextRunVar.Height;
			clsVar.varInterface.VectorTextVar.Text = ccVars.VectorTextRunVar.Text;
		}
		if (ccVars.Action == actionTypeBU.drawCustomText && clsItem.FrmActionData.buClassViewer1.ClassObject != null && clsItem.FrmActionData.buClassViewer1.ClassObject is TextCustomRuntimeData)
		{
			ccVars.CustomTextRunVar.Alignment = ((TextCustomRuntimeData)clsItem.FrmActionData.buClassViewer1.ClassObject).Alignment;
			ccVars.CustomTextRunVar.Height = ((TextCustomRuntimeData)clsItem.FrmActionData.buClassViewer1.ClassObject).Height;
			ccVars.CustomTextRunVar.Text = ((TextCustomRuntimeData)clsItem.FrmActionData.buClassViewer1.ClassObject).Text;
			ccVars.CustomTextRunVar.CharSpace = ((TextCustomRuntimeData)clsItem.FrmActionData.buClassViewer1.ClassObject).CharSpace;
			ccVars.CustomTextRunVar.SpaceValue = ((TextCustomRuntimeData)clsItem.FrmActionData.buClassViewer1.ClassObject).SpaceValue;
			clsInit.appCommand.CustomTextCreate(ccVars.CustomTextRunVar.Text, ccVars.CustomTextRunVar.CharSpace, ccVars.CustomTextRunVar.SpaceValue, ccVars.CustomTextRunVar.Height, ccVars.CustomTextRunVar.Alignment, ccVars.planeActive, ref ccVars.ContourPoints5);
			clsVar.varInterface.CustomTextVar.Alignment = ccVars.CustomTextRunVar.Alignment;
			clsVar.varInterface.CustomTextVar.CharSpace = ccVars.CustomTextRunVar.CharSpace;
			clsVar.varInterface.CustomTextVar.Height = ccVars.CustomTextRunVar.Height;
			clsVar.varInterface.CustomTextVar.Text = ccVars.CustomTextRunVar.Text;
			clsVar.varInterface.CustomTextVar.SpaceValue = ccVars.CustomTextRunVar.SpaceValue;
		}
		if (ccVars.Action == actionTypeBU.eventLineerArray)
		{
			viewportMouseMove(ccVars.pntActive, null, new MouseEventArgs(MouseButtons.Left, 0, 0, 0, 0));
			ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Invalidate();
		}
		if (ccVars.Action == actionTypeBU.eventPolarArray)
		{
			viewportMouseMove(ccVars.pntActive, null, new MouseEventArgs(MouseButtons.Left, 0, 0, 0, 0));
			ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Invalidate();
		}
		if (ccVars.Action == actionTypeBU.eventScale)
		{
			if (!clsVar.varInterface.ScaleVar.KeepTheRatio)
			{
				clsInit.appCommand.SpinPropsSet(1, ContentAlignment.MiddleCenter, Visible: false, Focus: true, SelectAll: true, AppLanguage.CadCamDynamic[15]);
				clsInit.appCommand.SpinPropsSet(2, ContentAlignment.MiddleCenter, Visible: false, Focus: true, SelectAll: true, AppLanguage.CadCamDynamic[16]);
				if (ccVars.stpDrawing >= 2)
				{
					ccVars.Spin1Prop.Visible = true;
					ccVars.Spin2Prop.Visible = true;
				}
			}
			else
			{
				clsInit.appCommand.SpinPropsSet(1, ContentAlignment.MiddleCenter, Visible: false, Focus: true, SelectAll: true, AppLanguage.CadCamDynamic[83]);
				if (ccVars.stpDrawing >= 2)
				{
					ccVars.Spin1Prop.Visible = true;
				}
			}
		}
		clsFiles.SaveParameter();
	}

	public void GetEntityInfo(Entity Ent, ref string sInfo)
	{
		if (!(Ent is devDept.Eyeshot.Entities.Point))
		{
			if (!(Ent is Line))
			{
				if (!(Ent is Arc))
				{
					if (!(Ent is Circle))
					{
						if (!(Ent is LinearPath) || Ent.Vertices == null || Ent.Vertices.Length == 0)
						{
							if (!(Ent is Ellipse))
							{
								if (!(Ent is EllipticalArc))
								{
									if (!(Ent is Picture))
									{
										if (!(Ent is Text))
										{
											if (!(Ent is CompositeCurve))
											{
												if (!(Ent is Curve))
												{
													if (!(Ent is PlanarSurface))
													{
														if (!(Ent is TabulatedSurface))
														{
															if (!(Ent is CylindricalSurface))
															{
																if (!(Ent is ConicalSurface))
																{
																	if (!(Ent is SphericalSurface))
																	{
																		if (!(Ent is RevolvedSurface))
																		{
																			if (!(Ent is ToroidalSurface))
																			{
																				if (!(Ent is Brep))
																				{
																					return;
																				}
																				sInfo = AppLanguage.CadCamDynamic[56] + Environment.NewLine;
																				if (ViewportCC.UnderMouseEdge == null)
																				{
																					if (ViewportCC.UnderMouseFace == null)
																					{
																						if (!(ViewportCC.UnderMouseVertice != null))
																						{
																							sInfo = Ent.GetType().Name.ToString() + Environment.NewLine;
																							sInfo = sInfo + AppLanguage.CadCamDynamic[67] + " = (" + ((Brep)Ent).BoxMin.X.ToString("f3") + " , " + ((Brep)Ent).BoxMin.Y.ToString("f3") + " , " + ((Brep)Ent).BoxMin.Z.ToString("f3") + ")" + Environment.NewLine;
