	public void MacroExecute(List<MacroBase> macroList)
	{
		try
		{
			for (int i = 0; i <= macroList.Count - 1; i++)
			{
				MacroBase macroBase = new MacroBase(macroList[i]);
				if (macroBase.Command.Length > 0 && runCommands_0 != null)
				{
					runCommands_0(macroBase.Command, macroBase.Args);
				}
			}
			buLog.addLog("Macro Executed", "Ok", MethodBase.GetCurrentMethod().Name);
		}
		catch (Exception mSException)
		{
			buLog.addLog("", "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: true, "");
		}
	}

	public void DebugExecute(object sender, DebugCommandEventArg e)
	{
		MacroBase macroBase = new MacroBase();
		macroBase = buGeneral.DecodeMacro(e.DebugCommand);
		bool flag = false;
		if (runCommands_0 != null)
		{
			flag = runCommands_0(macroBase.Command, macroBase.Args);
		}
		string text = e.DebugCommand;
		if (e.PasswordChar)
		{
			text = "**************";
		}
		if (!flag)
		{
			clsItem.FrmDebug.lst_commands.Items.Add(text + " - [ Error ]");
		}
		else
		{
			clsItem.FrmDebug.lst_commands.Items.Add(text + " - [ Ok ]");
		}
		clsItem.FrmDebug.txt_command.Text = "";
	}

	public void RunSyCmd(string C)
	{
		string[] array = null;
		array = C.Split(';');
		if (array == null)
		{
			return;
		}
		if (array.Length != 2)
		{
			if (array.Length <= 7)
			{
				return;
			}
			array[0].ToLower().Trim();
			string text = array[1].ToLower().Trim();
			array[2].ToLower().Trim();
			string text2 = array[3].ToLower().Trim();
			string text3 = array[4].ToLower().Trim();
			array[5].ToLower().Trim();
			array[6].ToLower().Trim();
			array[7].ToLower().Trim();
			string text4 = array[8].ToLower().Trim();
			if (!(array[0].ToLower().Trim() == "bucadcam"))
			{
				return;
			}
			if (!((text3.ToLower() == "sendinfo") & ((text.Length == 0) | (text == "0") | (text == clsVar.appDefination.CustomerID.ToString())) & ((text2.Length == 0) | (text2 == "0") | (text2 == clsVar.appDefination.ProgramCode))))
			{
				if (!((text3.ToLower() == "blockallcustomerprogram") & (text == clsVar.appDefination.CustomerID.ToString()) & ((text2.Length == 0) | (text2 == "0") | (text2 == clsVar.appDefination.ProgramCode))))
				{
