	public void CalculationInProgressCmd(CalculationEventArg e)
	{
		if (calculationEventHandler_0 != null && e.ShowOnMainForm)
		{
			calculationEventHandler_0(e);
		}
		if (!e.ShowForm)
		{
			return;
		}
		if (clsItem.FrmProgress == null)
		{
			clsItem.FrmProgress = new F_ProgressCalculation();
		}
		if (clsItem.FrmProgress != null)
		{
			if (!clsItem.FrmProgress.Visible)
			{
				clsItem.FrmProgress.TopMost = true;
				clsItem.FrmProgress.Show();
			}
			if (clsItem.FrmProgress.Visible)
			{
				clsItem.FrmProgress.Init(e.ActiveProgressPercentage, e.OverallProgressPercentage, e.Job);
				clsItem.FrmProgress.Refresh();
			}
		}
	}

	public void CalculationInProgressReset(CalculationEventArg e)
	{
		if (calculationEventHandler_1 != null)
		{
			calculationEventHandler_1(e);
		}
	}

